    secondaryColor: '#0f172a',
    academicYear: '2026'
  });

  useEffect(() => {
    const unsubConfig = onSnapshot(doc(db, 'system_settings', 'main_config'), (docSnap) => {
      if (docSnap.exists()) {
        const data = docSnap.data();
        if (data.schoolConfig) setSchoolConfig(prev => ({ ...prev, ...data.schoolConfig }));
      }
      setLoading(false);
    });

    const unsubStaff = onSnapshot(query(collection(db, 'users'), where('role', 'in', ['diretor', 'vice_diretor', 'coordenador', 'secretaria', 'professor', 'apoio', 'ti'])), (snap) => {
      const data = snap.docs.map(d => ({ id: d.id, ...d.data() }));
      setStaff(data.filter(u => u.uid !== 'root_user_id'));
    });

    const unsubLogs = onSnapshot(query(collection(db, 'system_logs'), orderBy('timestamp', 'desc'), limit(8)), (snap) => {
      setGovernanceLogs(snap.docs.map(d => ({ id: d.id, ...d.data() })));
    });

    return () => { unsubConfig(); unsubStaff(); unsubLogs(); };
  }, []);

  const handleFileUpload = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (file) {
      if (file.size > 500000) { // 500KB limit for base64 optimization
        alert("A imagem é muito grande. Por favor, escolha uma imagem menor que 500KB.");
        return;
      }
      const reader = new FileReader();
      reader.onloadend = () => {
        setMemberForm({ ...memberForm, fotoUrl: reader.result as string });
      };
      reader.readAsDataURL(file);
    }
  };

  const addFormacao = () => {
    setMemberForm({ ...memberForm, formacoes: [...memberForm.formacoes, { curso: '', instituicao: '', ano: '' }] });
  };

  const removeFormacao = (index: number) => {
    const newF = [...memberForm.formacoes];
    newF.splice(index, 1);
    setMemberForm({ ...memberForm, formacoes: newF });
  };

  const addExperiencia = () => {
    setMemberForm({ ...memberForm, experiencias: [...memberForm.experiencias, { cargo: '', empresa: '', periodo: '' }] });
  };

  const removeExperiencia = (index: number) => {
    const newE = [...memberForm.experiencias];
    newE.splice(index, 1);
    setMemberForm({ ...memberForm, experiencias: newE });
  };

  const handleSaveMember = async (e: React.FormEvent) => {
    e.preventDefault();
    setIsSaving(true);
    try {
      const payload = {
        nome: memberForm.nome,
        displayName: memberForm.nome,
        email: memberForm.email,
        documento: memberForm.documento,
        telefone: memberForm.telefone,
        role: memberForm.cargo,
        status: memberForm.status,
        photoURL: memberForm.fotoUrl,
        endereco: memberForm.endereco,
        formacoes: memberForm.formacoes,
        experiencias: memberForm.experiencias,
        biografia: memberForm.biografia,
        password: memberForm.password, // Em produção, isso seria tratado por uma Cloud Function para criar o user no Auth
        updatedAt: serverTimestamp()
      };

      if (selectedMember) {
        await updateDoc(doc(db, 'users', selectedMember.id), payload);
      } else {
        const staffId = `STF-${Date.now().toString().slice(-6)}`;
        await addDoc(collection(db, 'users'), {
          ...payload,
          staffId,
          createdAt: serverTimestamp()
        });
      }

      setIsMemberModalOpen(false);
      setSelectedMember(null);
      alert("Cadastro processado com sucesso!");
    } catch (err) {
      console.error(err);
      alert("Erro ao salvar no banco de dados.");
    } finally {
      setIsSaving(false);
    }
  };

  if (loading) return <div className="h-screen flex items-center justify-center bg-slate-50"><div className="animate-spin rounded-full h-8 w-8 border-b-2 border-indigo-600"></div></div>;

  return (
