            { id: 'geral', label: 'Institucional', icon: <Building size={16}/> },
            { id: 'equipe', label: 'Membros da Equipe', icon: <Users size={16}/> },
            { id: 'seguranca', label: 'Segurança', icon: <Shield size={16}/> },
            { id: 'infra', label: 'Logs', icon: <Activity size={16}/> }
