          </div>

          <div className="bg-white rounded-2xl border border-slate-200 overflow-hidden shadow-sm">
            <table className="w-full text-left border-collapse">
              <thead>
                <tr className="bg-slate-50 border-b border-slate-100">
                  <th className="px-6 py-4 text-[10px] font-bold uppercase text-slate-400">Membro</th>
                  <th className="px-6 py-4 text-[10px] font-bold uppercase text-slate-400">Cargo</th>
                  <th className="px-6 py-4 text-[10px] font-bold uppercase text-slate-400">Contato</th>
                  <th className="px-6 py-4 text-[10px] font-bold uppercase text-slate-400">Status</th>
                  <th className="px-6 py-4 text-[10px] font-bold uppercase text-slate-400 text-right">Ações</th>
