                          className="p-2 text-slate-400 hover:text-amber-600 transition-all"
                        >
                          <Edit3 size={18}/>
                        </button>
                        <button onClick={() => handleDeleteMember(m.id, m.nome)} className="p-2 text-slate-400 hover:text-rose-600 transition-all"><Trash2 size={18}/></button>
                      </div>
                    </td>
                  </tr>
                ))}
              </tbody>
            </table>
          </div>
        </div>
