              <div className="flex items-center gap-3">
                <div className="p-2 bg-indigo-600 text-white rounded-lg"><Users size={20}/></div>
                <h2 className="text-lg font-bold text-slate-900">{selectedMember ? 'Editar Profissional' : 'Credenciar Novo Membro'}</h2>
              </div>
              <button onClick={() => setIsMemberModalOpen(false)} className="p-2 hover:bg-rose-50 text-slate-400 hover:text-rose-600 rounded-full transition-all"><X size={20}/></button>
