            <form onSubmit={handleSaveMember} className="flex-1 overflow-y-auto p-8 custom-scrollbar space-y-10">

              {/* SEÇÃO 1: DADOS BÁSICOS & FOTO */}
              <div className="grid grid-cols-1 lg:grid-cols-4 gap-8">
                <div className="lg:col-span-1 flex flex-col items-center gap-4">
                  <div 
                    onClick={() => fileInputRef.current?.click()}
                    className="w-40 h-40 rounded-3xl bg-slate-100 border-2 border-dashed border-slate-300 flex items-center justify-center overflow-hidden cursor-pointer hover:border-indigo-400 hover:bg-indigo-50 transition-all group relative"
                  >
                    {memberForm.fotoUrl ? (
                      <img src={memberForm.fotoUrl} className="w-full h-full object-cover" />
                    ) : (
                      <div className="text-center">
                        <Camera size={32} className="mx-auto text-slate-300" />
                        <span className="text-[8px] font-bold text-slate-400 uppercase mt-2 block">Foto do Perfil</span>
                      </div>
                    )}
                    <div className="absolute inset-0 bg-black/40 opacity-0 group-hover:opacity-100 flex items-center justify-center transition-opacity">
                      <Upload size={24} className="text-white" />
                    </div>
                  </div>
                  <input type="file" ref={fileInputRef} className="hidden" accept="image/*" onChange={handleFileUpload} />
                  <p className="text-[10px] text-slate-400 text-center">JPG ou PNG (Máx 500KB)</p>
                </div>

                <div className="lg:col-span-3 grid grid-cols-1 sm:grid-cols-2 gap-4">
                  <div className="space-y-1">
                    <label className="text-[10px] font-bold text-slate-400 uppercase ml-1">Nome Completo</label>
                    <input required value={memberForm.nome} onChange={e => setMemberForm({...memberForm, nome: e.target.value})} className="w-full p-2.5 bg-slate-50 border border-slate-200 rounded-xl text-sm outline-none focus:ring-2 focus:ring-indigo-500 transition-all" />
                  </div>
                  <div className="space-y-1">
                    <label className="text-[10px] font-bold text-slate-400 uppercase ml-1">Cargo / Função</label>
                    <select value={memberForm.cargo} onChange={e => setMemberForm({...memberForm, cargo: e.target.value as RoleClassification})} className="w-full p-2.5 bg-slate-50 border border-slate-200 rounded-xl text-sm outline-none focus:ring-2 focus:ring-indigo-500 transition-all">
                      <option value="professor">Professor</option>
                      <option value="coordenador">Coordenador</option>
                      <option value="secretaria">Secretária</option>
                      <option value="diretor">Diretor</option>
                      <option value="ti">Suporte TI</option>
                    </select>
                  </div>
                  <div className="space-y-1">
                    <label className="text-[10px] font-bold text-slate-400 uppercase ml-1">E-mail (Login)</label>
                    <input type="email" required value={memberForm.email} onChange={e => setMemberForm({...memberForm, email: e.target.value})} className="w-full p-2.5 bg-slate-50 border border-slate-200 rounded-xl text-sm outline-none focus:ring-2 focus:ring-indigo-500 transition-all" />
                  </div>
                  <div className="space-y-1">
                    <label className="text-[10px] font-bold text-slate-400 uppercase ml-1">Senha Provisória</label>
                    <input type="password" required={!selectedMember} value={memberForm.password} onChange={e => setMemberForm({...memberForm, password: e.target.value})} className="w-full p-2.5 bg-slate-50 border border-slate-200 rounded-xl text-sm outline-none focus:ring-2 focus:ring-indigo-500 transition-all" placeholder={selectedMember ? 'Deixe em branco para manter' : ''} />
                  </div>
                  <div className="space-y-1">
                    <label className="text-[10px] font-bold text-slate-400 uppercase ml-1">Documento (CPF/RG)</label>
                    <input required value={memberForm.documento} onChange={e => setMemberForm({...memberForm, documento: e.target.value})} className="w-full p-2.5 bg-slate-50 border border-slate-200 rounded-xl text-sm outline-none focus:ring-2 focus:ring-indigo-500 transition-all" />
                  </div>
                  <div className="space-y-1">
                    <label className="text-[10px] font-bold text-slate-400 uppercase ml-1">Telefone / WhatsApp</label>
                    <input required value={memberForm.telefone} onChange={e => setMemberForm({...memberForm, telefone: e.target.value})} className="w-full p-2.5 bg-slate-50 border border-slate-200 rounded-xl text-sm outline-none focus:ring-2 focus:ring-indigo-500 transition-all" />
                  </div>
                </div>
              </div>

