                    <input value={memberForm.endereco.cidade} onChange={e => setMemberForm({...memberForm, endereco: {...memberForm.endereco, cidade: e.target.value}})} className="w-full p-2.5 bg-slate-50 border border-slate-200 rounded-xl text-sm" />
