                      <input className="sm:col-span-4 p-2 bg-white border border-slate-200 rounded-lg text-xs" placeholder="Empresa/Instituição" value={e.empresa} onChange={ev => { const n = [...memberForm.experiencias]; n[i].empresa = ev.target.value; setMemberForm({...memberForm, experiencias: n}) }} />
                      <input className="sm:col-span-3 p-2 bg-white border border-slate-200 rounded-lg text-xs" placeholder="Período" value={e.periodo} onChange={ev => { const n = [...memberForm.experiencias]; n[i].periodo = ev.target.value; setMemberForm({...memberForm, experiencias: n}) }} />
                      <button type="button" onClick={() => removeExperiencia(i)} className="sm:col-span-1 p-2 text-rose-500 hover:bg-rose-50 rounded-lg"><MinusCircle size={18}/></button>
                    </div>
                  ))}
                  {memberForm.experiencias.length === 0 && <p className="text-center text-[10px] text-slate-400 italic py-4">Nenhuma experiência cadastrada.</p>}
                </div>
              </div>

              {/* SEÇÃO 5: BIOGRAFIA */}
