                <div className="flex items-center gap-2 border-b border-slate-100 pb-2">
                  <Award size={16} className="text-indigo-600" />
                  <h4 className="text-xs font-bold text-slate-900 uppercase">Resumo Biográfico</h4>
                </div>
                <textarea 
                  value={memberForm.biografia} 
                  onChange={e => setMemberForm({...memberForm, biografia: e.target.value})}
                  className="w-full p-4 bg-slate-50 border border-slate-200 rounded-2xl h-32 text-xs font-medium italic outline-none focus:ring-2 focus:ring-indigo-500"
                  placeholder="Escreva um breve resumo sobre o profissional..."
                />
              </div>

            </form>

            <footer className="p-6 border-t border-slate-100 bg-slate-50/50 flex justify-end gap-3">
              <button onClick={() => setIsMemberModalOpen(false)} className="px-6 py-2.5 text-slate-500 font-bold text-xs uppercase hover:bg-slate-200 rounded-xl transition-all">Cancelar</button>
              <button 
                onClick={handleSaveMember}
                disabled={isSaving}
                className="bg-slate-900 text-white px-10 py-2.5 rounded-xl text-xs font-bold uppercase shadow-xl hover:bg-indigo-600 transition-all disabled:opacity-50"
              >
                {isSaving ? 'Gravando...' : 'Efetivar Cadastro'}
              </button>
            </footer>
          </div>
        </div>
      )}

      {/* VIEW MODAL - EXIBIÇÃO SIMPLIFICADA */}
      {isViewModalOpen && selectedMember && (
        <div className="fixed inset-0 z-[2000] bg-slate-900/60 backdrop-blur-sm flex items-center justify-center p-4">
          <div className="bg-white w-full max-w-2xl max-h-[90vh] rounded-[2rem] shadow-2xl overflow-y-auto custom-scrollbar animate-in slide-in-from-bottom-4">
            <header className="sticky top-0 bg-white border-b border-slate-100 p-6 flex justify-between items-center z-10">
              <h2 className="font-bold text-slate-900 uppercase text-sm tracking-widest">Dossiê do Profissional</h2>
              <button onClick={() => setIsViewModalOpen(false)} className="p-2 hover:bg-rose-50 text-slate-400 rounded-full"><X size={20}/></button>
            </header>
            <div className="p-8 space-y-8">
              <div className="flex items-center gap-6">
                <div className="w-24 h-24 rounded-3xl bg-slate-100 overflow-hidden border-2 border-slate-50 shadow-md">
                   {selectedMember.photoURL ? <img src={selectedMember.photoURL} className="w-full h-full object-cover" /> : <UserIcon className="m-auto text-slate-200 mt-6" size={48}/>}
                </div>
                <div>
                   <span className="text-[10px] font-bold text-indigo-600 uppercase bg-indigo-50 px-2 py-0.5 rounded">{selectedMember.role}</span>
                   <h1 className="text-2xl font-bold text-slate-900 mt-1">{selectedMember.nome}</h1>
                   <p className="text-xs text-slate-500 italic">{selectedMember.email}</p>
                </div>
              </div>

              <div className="grid grid-cols-2 gap-6 pt-4 border-t border-slate-50">
                <div className="space-y-1">
                  <p className="text-[10px] font-bold text-slate-400 uppercase">WhatsApp</p>
                  <p className="text-sm font-medium">{selectedMember.telefone || '---'}</p>
                </div>
                <div className="space-y-1">
                  <p className="text-[10px] font-bold text-slate-400 uppercase">CPF/RG</p>
                  <p className="text-sm font-medium">{selectedMember.documento || '---'}</p>
                </div>
              </div>

              <div className="space-y-4 pt-4 border-t border-slate-50">
                 <h4 className="text-xs font-bold text-slate-900 uppercase">Formação Acadêmica</h4>
                 <div className="space-y-2">
                    {selectedMember.formacoes?.map((f: any, i: number) => (
                      <div key={i} className="p-3 bg-slate-50 rounded-xl border border-slate-100">
                        <p className="text-xs font-bold text-slate-800">{f.curso}</p>
                        <p className="text-[10px] text-slate-500">{f.instituicao} • {f.ano}</p>
                      </div>
                    ))}
                    {(!selectedMember.formacoes || selectedMember.formacoes.length === 0) && <p className="text-xs text-slate-400 italic">Nenhuma formação registrada.</p>}
                 </div>
              </div>

              <div className="space-y-4 pt-4 border-t border-slate-50">
                 <h4 className="text-xs font-bold text-slate-900 uppercase">Trajetória Profissional</h4>
                 <div className="space-y-2">
                    {selectedMember.experiencias?.map((e: any, i: number) => (
                      <div key={i} className="p-3 bg-slate-50 rounded-xl border border-slate-100">
                        <p className="text-xs font-bold text-slate-800">{e.cargo}</p>
                        <p className="text-[10px] text-slate-500">{e.empresa} • {e.periodo}</p>
                      </div>
                    ))}
                    {(!selectedMember.experiencias || selectedMember.experiencias.length === 0) && <p className="text-xs text-slate-400 italic">Nenhuma experiência registrada.</p>}
                 </div>
              </div>

              {selectedMember.biografia && (
                <div className="space-y-2 pt-4 border-t border-slate-50">
                  <h4 className="text-xs font-bold text-slate-900 uppercase">Resumo Biográfico</h4>
                  <p className="text-xs text-slate-600 leading-relaxed italic">{selectedMember.biografia}</p>
                </div>
              )}
            </div>
          </div>
        </div>
      )}

      {/* ABA DE LOGS/INFRAESTRUTURA */}
      {activeTab === 'infra' && (
        <div className="bg-white p-6 rounded-2xl border border-slate-200 shadow-sm space-y-6 animate-in fade-in">
           <h3 className="font-bold text-slate-900">Auditoria de Governança</h3>
           <div className="space-y-3">
              {governanceLogs.map(log => (
                <div key={log.id} className="flex items-center justify-between p-3 bg-slate-50 rounded-xl border border-slate-100">
                   <div className="flex items-center gap-3">
                      <div className="p-2 bg-white rounded-lg border border-slate-200"><Activity size={14} className="text-indigo-600"/></div>
                      <div>
                        <p className="text-xs font-bold text-slate-800">{log.action}</p>
                        <p className="text-[9px] text-slate-400 uppercase">{log.user}</p>
                      </div>
                   </div>
                   <span className="text-[9px] font-mono text-slate-400">{log.timestamp?.seconds ? new Date(log.timestamp.seconds * 1000).toLocaleString() : 'Recent'}</span>
                </div>
              ))}
           </div>
        </div>
      )}
    </div>
  );
};

export default SettingsView;

import React, { useState, useEffect, useRef } from 'react';
import { 
  doc, updateDoc, getDoc, collection, onSnapshot, query, where, 
  addDoc, deleteDoc, serverTimestamp, orderBy, limit, setDoc
} from "https://www.gstatic.com/firebasejs/10.7.1/firebase-firestore.js";
import { db, auth } from '../firebase';
import { 
  Users, Shield, Building, Save, Activity, 
  Plus, Trash2, Mail, CheckCircle2, UserCheck,
  Calendar, HardDrive, Key, X, Camera, GraduationCap,
  Eye, Edit3, ShieldAlert, Award, MapPin, User as UserIcon, Upload, 
  Briefcase, PlusCircle, MinusCircle, Smartphone, Fingerprint
} from 'lucide-react';
import SignaturePad from '../components/SignaturePad';

type SettingsTab = 'geral' | 'equipe' | 'seguranca' | 'infra';
type RoleClassification = 'diretor' | 'vice_diretor' | 'coordenador' | 'secretaria' | 'professor' | 'apoio' | 'ti';

interface Formacao {
  curso: string;
  instituicao: string;
  ano: string;
}

interface Experiencia {
  cargo: string;
  empresa: string;
  periodo: string;
}

const SettingsView: React.FC = () => {
  const [activeTab, setActiveTab] = useState<SettingsTab>('geral');
  const [isSignModalOpen, setIsSignModalOpen] = useState(false);
  const [signingUserId, setSigningUserId] = useState<string | null>(null);
  const [loading, setLoading] = useState(true);
  const [isSaving, setIsSaving] = useState(false);
  const fileInputRef = useRef<HTMLInputElement>(null);

  const [staff, setStaff] = useState<any[]>([]);
  const [isMemberModalOpen, setIsMemberModalOpen] = useState(false);
  const [isViewModalOpen, setIsViewModalOpen] = useState(false);
  const [selectedMember, setSelectedMember] = useState<any>(null);

  // Formulário de Membro Otimizado
  const [memberForm, setMemberForm] = useState({
    nome: '',
    email: '',
    documento: '',
    telefone: '',
    cargo: 'professor' as RoleClassification,
    status: 'ativo',
    fotoUrl: '',
    password: '', // Senha temporária
    endereco: {
      cep: '',
      rua: '',
      numero: '',
      bairro: '',
      cidade: '',
      uf: ''
    },
    formacoes: [] as Formacao[],
    experiencias: [] as Experiencia[],
    biografia: ''
  });

  const [governanceLogs, setGovernanceLogs] = useState<any[]>([]);
  const [schoolConfig, setSchoolConfig] = useState({
    schoolName: 'Escola Bíblica EAD',
    primaryColor: '#4f46e5',
    secondaryColor: '#0f172a',
    academicYear: '2026'
  });

  useEffect(() => {
    const unsubConfig = onSnapshot(doc(db, 'system_settings', 'main_config'), (docSnap) => {
      if (docSnap.exists()) {
        const data = docSnap.data();
        if (data.schoolConfig) setSchoolConfig(prev => ({ ...prev, ...data.schoolConfig }));
      }
      setLoading(false);
    });

    const unsubStaff = onSnapshot(query(collection(db, 'users'), where('role', 'in', ['diretor', 'vice_diretor', 'coordenador', 'secretaria', 'professor', 'apoio', 'ti'])), (snap) => {
      const data = snap.docs.map(d => ({ id: d.id, ...d.data() }));
      setStaff(data.filter(u => u.uid !== 'root_user_id'));
    });

    const unsubLogs = onSnapshot(query(collection(db, 'system_logs'), orderBy('timestamp', 'desc'), limit(8)), (snap) => {
      setGovernanceLogs(snap.docs.map(d => ({ id: d.id, ...d.data() })));
    });

    return () => { unsubConfig(); unsubStaff(); unsubLogs(); };
  }, []);

  const handleFileUpload = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (file) {
      if (file.size > 500000) { // 500KB limit for base64 optimization
        alert("A imagem é muito grande. Por favor, escolha uma imagem menor que 500KB.");
        return;
      }
      const reader = new FileReader();
      reader.onloadend = () => {
        setMemberForm({ ...memberForm, fotoUrl: reader.result as string });
      };
      reader.readAsDataURL(file);
    }
  };

  const addFormacao = () => {
    setMemberForm({ ...memberForm, formacoes: [...memberForm.formacoes, { curso: '', instituicao: '', ano: '' }] });
  };

  const removeFormacao = (index: number) => {
    const newF = [...memberForm.formacoes];
    newF.splice(index, 1);
    setMemberForm({ ...memberForm, formacoes: newF });
  };

  const addExperiencia = () => {
    setMemberForm({ ...memberForm, experiencias: [...memberForm.experiencias, { cargo: '', empresa: '', periodo: '' }] });
  };

  const removeExperiencia = (index: number) => {
    const newE = [...memberForm.experiencias];
    newE.splice(index, 1);
    setMemberForm({ ...memberForm, experiencias: newE });
  };

  // Added missing handleDeleteMember function
  const handleDeleteMember = async (id: string, name: string) => {
    if (confirm(`Deseja remover ${name} da equipe permanentemente?`)) {
      try {
        await deleteDoc(doc(db, 'users', id));
        // Log action
        await addDoc(collection(db, 'system_logs'), {
          action: `Remoção de Membro: ${name}`,
          user: auth.currentUser?.email || 'Administrador',
          timestamp: serverTimestamp()
        });
      } catch (err) {
        console.error(err);
        alert("Erro ao remover membro.");
      }
    }
  };

  const handleSaveMember = async (e: React.FormEvent) => {
    e.preventDefault();
    setIsSaving(true);
    try {
      const payload = {
        nome: memberForm.nome,
        displayName: memberForm.nome,
        email: memberForm.email,
        documento: memberForm.documento,
        telefone: memberForm.telefone,
        role: memberForm.cargo,
        status: memberForm.status,
        photoURL: memberForm.fotoUrl,
        endereco: memberForm.endereco,
        formacoes: memberForm.formacoes,
        experiencias: memberForm.experiencias,
        biografia: memberForm.biografia,
        password: memberForm.password, // Em produção, isso seria tratado por uma Cloud Function para criar o user no Auth
        updatedAt: serverTimestamp()
      };

      if (selectedMember) {
        await updateDoc(doc(db, 'users', selectedMember.id), payload);
      } else {
        const staffId = `STF-${Date.now().toString().slice(-6)}`;
        await addDoc(collection(db, 'users'), {
          ...payload,
          staffId,
          createdAt: serverTimestamp()
        });
      }

      setIsMemberModalOpen(false);
      setSelectedMember(null);
      alert("Cadastro processado com sucesso!");
    } catch (err) {
      console.error(err);
      alert("Erro ao salvar no banco de dados.");
    } finally {
      setIsSaving(false);
    }
  };

  if (loading) return <div className="h-screen flex items-center justify-center bg-slate-50"><div className="animate-spin rounded-full h-8 w-8 border-b-2 border-indigo-600"></div></div>;

  return (
    <div className="max-w-7xl mx-auto space-y-6 pb-20">
      <header className="flex flex-col md:flex-row md:items-center justify-between gap-4">
        <div>
          <h1 className="text-2xl font-bold text-slate-900 tracking-tight">Configurações do Sistema</h1>
          <p className="text-slate-500 text-sm">Gerencie a equipe, segurança e identidade da escola.</p>
        </div>
        <div className="flex bg-white p-1 rounded-xl border border-slate-200 shadow-sm overflow-x-auto">
          {[
            { id: 'geral', label: 'Institucional', icon: <Building size={16}/> },
            { id: 'equipe', label: 'Membros da Equipe', icon: <Users size={16}/> },
            { id: 'seguranca', label: 'Segurança', icon: <Shield size={16}/> },
            { id: 'infra', label: 'Logs', icon: <Activity size={16}/> }
          ].map(tab => (
            <button
              key={tab.id}
              onClick={() => setActiveTab(tab.id as SettingsTab)}
              className={`flex items-center gap-2 px-4 py-2 rounded-lg text-xs font-bold transition-all whitespace-nowrap ${
                activeTab === tab.id ? 'bg-slate-900 text-white shadow-md' : 'text-slate-500 hover:text-slate-900'
              }`}
            >
              {tab.icon} {tab.label}
            </button>
          ))}
        </div>
      </header>

      {/* ABA EQUIPE - LISTAGEM SIMPLIFICADA */}
      {activeTab === 'equipe' && (
        <div className="space-y-4 animate-in fade-in">
          <div className="bg-white p-4 rounded-2xl border border-slate-200 flex justify-between items-center shadow-sm">
            <h3 className="font-bold text-slate-800">Equipe Administrativa e Docente</h3>
            <button 
              onClick={() => {
                setSelectedMember(null);
                setMemberForm({
                  nome: '', email: '', documento: '', telefone: '', cargo: 'professor', status: 'ativo', fotoUrl: '', password: '',
                  endereco: { cep: '', rua: '', numero: '', bairro: '', cidade: '', uf: '' },
                  formacoes: [], experiencias: [], biografia: ''
                });
                setIsMemberModalOpen(true);
              }}
              className="bg-indigo-600 text-white px-4 py-2 rounded-xl text-xs font-bold flex items-center gap-2 hover:bg-indigo-700 transition-all"
            >
              <Plus size={16}/> Novo Membro
            </button>
          </div>

          <div className="bg-white rounded-2xl border border-slate-200 overflow-hidden shadow-sm">
            <table className="w-full text-left border-collapse">
              <thead>
                <tr className="bg-slate-50 border-b border-slate-100">
                  <th className="px-6 py-4 text-[10px] font-bold uppercase text-slate-400">Membro</th>
                  <th className="px-6 py-4 text-[10px] font-bold uppercase text-slate-400">Cargo</th>
                  <th className="px-6 py-4 text-[10px] font-bold uppercase text-slate-400">Contato</th>
                  <th className="px-6 py-4 text-[10px] font-bold uppercase text-slate-400">Status</th>
                  <th className="px-6 py-4 text-[10px] font-bold uppercase text-slate-400 text-right">Ações</th>
                </tr>
              </thead>
              <tbody className="divide-y divide-slate-50">
                {staff.map(m => (
                  <tr key={m.id} className="hover:bg-slate-50/50 transition-colors">
                    <td className="px-6 py-4">
                      <div className="flex items-center gap-3">
                        <div className="w-10 h-10 rounded-full bg-slate-100 overflow-hidden border border-slate-200">
                          {m.photoURL ? <img src={m.photoURL} className="w-full h-full object-cover" /> : <UserIcon className="m-auto text-slate-300 mt-2" size={24}/>}
                        </div>
                        <div>
                          <p className="text-sm font-bold text-slate-900">{m.nome}</p>
                          <p className="text-[10px] text-slate-400 font-mono">{m.staffId}</p>
                        </div>
                      </div>
                    </td>
                    <td className="px-6 py-4">
                      <span className="text-[10px] font-bold uppercase bg-slate-100 px-2 py-1 rounded text-slate-600 border border-slate-200">{m.role?.replace('_', ' ')}</span>
                    </td>
                    <td className="px-6 py-4">
                      <p className="text-xs text-slate-600">{m.email}</p>
                      <p className="text-[10px] text-slate-400">{m.telefone}</p>
                    </td>
                    <td className="px-6 py-4">
                      <span className={`w-2 h-2 rounded-full inline-block mr-2 ${m.status === 'ativo' ? 'bg-emerald-500' : 'bg-rose-500'}`}></span>
                      <span className="text-xs font-medium text-slate-600">{m.status === 'ativo' ? 'Ativo' : 'Inativo'}</span>
                    </td>
                    <td className="px-6 py-4 text-right">
                      <div className="flex justify-end gap-2">
                        <button onClick={() => { setSelectedMember(m); setIsViewModalOpen(true); }} className="p-2 text-slate-400 hover:text-indigo-600 transition-all"><Eye size={18}/></button>
                        <button 
                          onClick={() => {
                            setSelectedMember(m);
                            setMemberForm({
                              nome: m.nome || '', email: m.email || '', documento: m.documento || '', telefone: m.telefone || '',
                              cargo: m.role || 'professor', status: m.status || 'ativo', fotoUrl: m.photoURL || '', password: m.password || '',
                              endereco: m.endereco || { cep: '', rua: '', numero: '', bairro: '', cidade: '', uf: '' },
                              formacoes: m.formacoes || [], experiencias: m.experiencias || [], biografia: m.biografia || ''
                            });
                            setIsMemberModalOpen(true);
                          }} 
                          className="p-2 text-slate-400 hover:text-amber-600 transition-all"
                        >
                          <Edit3 size={18}/>
                        </button>
                        <button onClick={() => handleDeleteMember(m.id, m.nome)} className="p-2 text-slate-400 hover:text-rose-600 transition-all"><Trash2 size={18}/></button>
                      </div>
                    </td>
                  </tr>
                ))}
              </tbody>
            </table>
          </div>
        </div>
      )}

      {/* ABA INSTITUCIONAL SIMPLIFICADA */}
      {activeTab === 'geral' && (
        <div className="grid grid-cols-1 md:grid-cols-3 gap-6 animate-in fade-in">
          <div className="md:col-span-2 bg-white p-6 rounded-2xl border border-slate-200 shadow-sm space-y-6">
            <h3 className="font-bold text-slate-900 border-b pb-4">Dados da Instituição</h3>
            <div className="grid grid-cols-1 sm:grid-cols-2 gap-4">
              <div className="space-y-1">
                <label className="text-[10px] font-bold text-slate-400 uppercase">Nome da Escola</label>
                <input value={schoolConfig.schoolName} onChange={e => setSchoolConfig({...schoolConfig, schoolName: e.target.value})} className="w-full p-2.5 bg-slate-50 border border-slate-200 rounded-lg text-sm font-bold" />
              </div>
              <div className="space-y-1">
                <label className="text-[10px] font-bold text-slate-400 uppercase">Ano Letivo Ativo</label>
                <input value={schoolConfig.academicYear} onChange={e => setSchoolConfig({...schoolConfig, academicYear: e.target.value})} className="w-full p-2.5 bg-slate-50 border border-slate-200 rounded-lg text-sm font-bold" />
              </div>
            </div>
            <button className="bg-slate-900 text-white px-4 py-2 rounded-lg text-xs font-bold hover:bg-slate-800 transition-all">Salvar Alterações</button>
          </div>
          <div className="bg-white p-6 rounded-2xl border border-slate-200 shadow-sm">
            <h3 className="font-bold text-slate-900 mb-4">Cores do Sistema</h3>
            <div className="space-y-4">
              <div className="flex items-center justify-between">
                <span className="text-xs font-medium text-slate-600">Cor Primária</span>
                <input type="color" value={schoolConfig.primaryColor} className="h-8 w-12 rounded-lg border-none cursor-pointer" />
              </div>
              <div className="flex items-center justify-between">
                <span className="text-xs font-medium text-slate-600">Cor Secundária</span>
                <input type="color" value={schoolConfig.secondaryColor} className="h-8 w-12 rounded-lg border-none cursor-pointer" />
              </div>
            </div>
          </div>
        </div>
      )}

      {/* MODAL DE CADASTRO - NOVO DESIGN FUNCIONAL */}
      {isMemberModalOpen && (
        <div className="fixed inset-0 z-[1000] bg-slate-900/60 backdrop-blur-sm flex items-center justify-center p-4">
          <div className="bg-white w-full max-w-5xl h-[90vh] rounded-[2rem] shadow-2xl flex flex-col overflow-hidden animate-in zoom-in-95">
            <header className="p-6 border-b border-slate-100 flex justify-between items-center bg-slate-50/50">
              <div className="flex items-center gap-3">
                <div className="p-2 bg-indigo-600 text-white rounded-lg"><Users size={20}/></div>
                <h2 className="text-lg font-bold text-slate-900">{selectedMember ? 'Editar Profissional' : 'Credenciar Novo Membro'}</h2>
              </div>
              <button onClick={() => setIsMemberModalOpen(false)} className="p-2 hover:bg-rose-50 text-slate-400 hover:text-rose-600 rounded-full transition-all"><X size={20}/></button>
            </header>

            <form onSubmit={handleSaveMember} className="flex-1 overflow-y-auto p-8 custom-scrollbar space-y-10">

              {/* SEÇÃO 1: DADOS BÁSICOS & FOTO */}
              <div className="grid grid-cols-1 lg:grid-cols-4 gap-8">
                <div className="lg:col-span-1 flex flex-col items-center gap-4">
                  <div 
                    onClick={() => fileInputRef.current?.click()}
                    className="w-40 h-40 rounded-3xl bg-slate-100 border-2 border-dashed border-slate-300 flex items-center justify-center overflow-hidden cursor-pointer hover:border-indigo-400 hover:bg-indigo-50 transition-all group relative"
                  >
                    {memberForm.fotoUrl ? (
