                  <MapPin size={16} className="text-indigo-600" />
                  <h4 className="text-xs font-bold text-slate-900 uppercase">Endereço Residencial</h4>
                </div>
                <div className="grid grid-cols-1 sm:grid-cols-4 gap-4">
                  <div className="space-y-1 sm:col-span-1">
                    <label className="text-[10px] font-bold text-slate-400 uppercase">CEP</label>
                    <input value={memberForm.endereco.cep} onChange={e => setMemberForm({...memberForm, endereco: {...memberForm.endereco, cep: e.target.value}})} className="w-full p-2.5 bg-slate-50 border border-slate-200 rounded-xl text-sm" />
