                  </div>
                  <div className="space-y-1 sm:col-span-1">
                    <label className="text-[10px] font-bold text-slate-400 uppercase">Número</label>
                    <input value={memberForm.endereco.numero} onChange={e => setMemberForm({...memberForm, endereco: {...memberForm.endereco, numero: e.target.value}})} className="w-full p-2.5 bg-slate-50 border border-slate-200 rounded-xl text-sm" />
