                      <input className="sm:col-span-4 p-2 bg-white border border-slate-200 rounded-lg text-xs" placeholder="Instituição" value={f.instituicao} onChange={e => { const n = [...memberForm.formacoes]; n[i].instituicao = e.target.value; setMemberForm({...memberForm, formacoes: n}) }} />
