              {/* SEÇÃO 4: EXPERIÊNCIA PROFISSIONAL DINÂMICA */}
              <div className="space-y-4">
                <div className="flex items-center justify-between border-b border-slate-100 pb-2">
                  <div className="flex items-center gap-2">
