                    <h4 className="text-xs font-bold text-slate-900 uppercase">Experiência Profissional</h4>
                  </div>
                  <button type="button" onClick={addExperiencia} className="text-indigo-600 hover:text-indigo-700 flex items-center gap-1 text-[10px] font-bold uppercase"><PlusCircle size={14}/> Adicionar</button>
                </div>
                <div className="space-y-3">
                  {memberForm.experiencias.map((e, i) => (
                    <div key={i} className="grid grid-cols-1 sm:grid-cols-12 gap-3 bg-slate-50 p-3 rounded-2xl border border-slate-200">
                      <input className="sm:col-span-4 p-2 bg-white border border-slate-200 rounded-lg text-xs" placeholder="Cargo" value={e.cargo} onChange={ev => { const n = [...memberForm.experiencias]; n[i].cargo = ev.target.value; setMemberForm({...memberForm, experiencias: n}) }} />
                      <input className="sm:col-span-4 p-2 bg-white border border-slate-200 rounded-lg text-xs" placeholder="Empresa/Instituição" value={e.empresa} onChange={ev => { const n = [...memberForm.experiencias]; n[i].empresa = ev.target.value; setMemberForm({...memberForm, experiencias: n}) }} />
                      <input className="sm:col-span-3 p-2 bg-white border border-slate-200 rounded-lg text-xs" placeholder="Período" value={e.periodo} onChange={ev => { const n = [...memberForm.experiencias]; n[i].periodo = ev.target.value; setMemberForm({...memberForm, experiencias: n}) }} />
                      <button type="button" onClick={() => removeExperiencia(i)} className="sm:col-span-1 p-2 text-rose-500 hover:bg-rose-50 rounded-lg"><MinusCircle size={18}/></button>
                    </div>
                  ))}
                  {memberForm.experiencias.length === 0 && <p className="text-center text-[10px] text-slate-400 italic py-4">Nenhuma experiência cadastrada.</p>}
                </div>
              </div>

              {/* SEÇÃO 5: BIOGRAFIA */}
              <div className="space-y-4">
                <div className="flex items-center gap-2 border-b border-slate-100 pb-2">
                  <Award size={16} className="text-indigo-600" />
                  <h4 className="text-xs font-bold text-slate-900 uppercase">Resumo Biográfico</h4>
                </div>
                <textarea 
                  value={memberForm.biografia} 
                  onChange={e => setMemberForm({...memberForm, biografia: e.target.value})}
                  className="w-full p-4 bg-slate-50 border border-slate-200 rounded-2xl h-32 text-xs font-medium italic outline-none focus:ring-2 focus:ring-indigo-500"
                  placeholder="Escreva um breve resumo sobre the profissional..."
                />
              </div>

            </form>

            <footer className="p-6 border-t border-slate-100 bg-slate-50/50 flex justify-end gap-3">
              <button onClick={() => setIsMemberModalOpen(false)} className="px-6 py-2.5 text-slate-500 font-bold text-xs uppercase hover:bg-slate-200 rounded-xl transition-all">Cancelar</button>
              <button 
                onClick={handleSaveMember}
                disabled={isSaving}
                className="bg-slate-900 text-white px-10 py-2.5 rounded-xl text-xs font-bold uppercase shadow-xl hover:bg-indigo-600 transition-all disabled:opacity-50"
              >
                {isSaving ? 'Gravando...' : 'Efetivar Cadastro'}
              </button>
            </footer>
          </div>
        </div>
      )}

      {/* VIEW MODAL - EXIBIÇÃO SIMPLIFICADA */}
      {isViewModalOpen && selectedMember && (
        <div className="fixed inset-0 z-[2000] bg-slate-900/60 backdrop-blur-sm flex items-center justify-center p-4">
          <div className="bg-white w-full max-w-2xl max-h-[90vh] rounded-[2rem] shadow-2xl overflow-y-auto custom-scrollbar animate-in slide-in-from-bottom-4">
            <header className="sticky top-0 bg-white border-b border-slate-100 p-6 flex justify-between items-center z-10">
              <h2 className="font-bold text-slate-900 uppercase text-sm tracking-widest">Dossiê do Profissional</h2>
              <button onClick={() => setIsViewModalOpen(false)} className="p-2 hover:bg-rose-50 text-slate-400 rounded-full"><X size={20}/></button>
            </header>
            <div className="p-8 space-y-8">
              <div className="flex items-center gap-6">
                <div className="w-24 h-24 rounded-3xl bg-slate-100 overflow-hidden border-2 border-slate-50 shadow-md">
                   {selectedMember.photoURL ? <img src={selectedMember.photoURL} className="w-full h-full object-cover" /> : <UserIcon className="m-auto text-slate-200 mt-6" size={48}/>}
                </div>
                <div>
                   <span className="text-[10px] font-bold text-indigo-600 uppercase bg-indigo-50 px-2 py-0.5 rounded">{selectedMember.role}</span>
                   <h1 className="text-2xl font-bold text-slate-900 mt-1">{selectedMember.nome}</h1>
                   <p className="text-xs text-slate-500 italic">{selectedMember.email}</p>
                </div>
              </div>

              <div className="grid grid-cols-2 gap-6 pt-4 border-t border-slate-50">
                <div className="space-y-1">
                  <p className="text-[10px] font-bold text-slate-400 uppercase">WhatsApp</p>
                  <p className="text-sm font-medium">{selectedMember.telefone || '---'}</p>
                </div>
                <div className="space-y-1">
                  <p className="text-[10px] font-bold text-slate-400 uppercase">CPF/RG</p>
                  <p className="text-sm font-medium">{selectedMember.documento || '---'}</p>
                </div>
              </div>

              <div className="space-y-4 pt-4 border-t border-slate-50">
                 <h4 className="text-xs font-bold text-slate-900 uppercase">Formação Acadêmica</h4>
                 <div className="space-y-2">
                    {selectedMember.formacoes?.map((f: any, i: number) => (
                      <div key={i} className="p-3 bg-slate-50 rounded-xl border border-slate-100">
                        <p className="text-xs font-bold text-slate-800">{f.curso}</p>
                        <p className="text-[10px] text-slate-500">{f.instituicao} • {f.ano}</p>
                      </div>
                    ))}
                    {(!selectedMember.formacoes || selectedMember.formacoes.length === 0) && <p className="text-xs text-slate-400 italic">Nenhuma formação registrada.</p>}
                 </div>
              </div>

              <div className="space-y-4 pt-4 border-t border-slate-50">
                 <h4 className="text-xs font-bold text-slate-900 uppercase">Trajetória Profissional</h4>
                 <div className="space-y-2">
                    {selectedMember.experiencias?.map((e: any, i: number) => (
                      <div key={i} className="p-3 bg-slate-50 rounded-xl border border-slate-100">
                        <p className="text-xs font-bold text-slate-800">{e.cargo}</p>
                        <p className="text-[10px] text-slate-500">{e.empresa} • {e.periodo}</p>
                      </div>
                    ))}
                    {(!selectedMember.experiencias || selectedMember.experiencias.length === 0) && <p className="text-xs text-slate-400 italic">Nenhuma experiência registrada.</p>}
                 </div>
              </div>

              {selectedMember.biografia && (
                <div className="space-y-2 pt-4 border-t border-slate-50">
                  <h4 className="text-xs font-bold text-slate-900 uppercase">Resumo Biográfico</h4>
                  <p className="text-xs text-slate-600 leading-relaxed italic">{selectedMember.biografia}</p>
                </div>
              )}
            </div>
          </div>
        </div>
      )}

      {/* ABA DE LOGS/INFRAESTRUTURA */}
      {activeTab === 'infra' && (
        <div className="bg-white p-6 rounded-2xl border border-slate-200 shadow-sm space-y-6 animate-in fade-in">
           <h3 className="font-bold text-slate-900">Auditoria de Governança</h3>
           <div className="space-y-3">
              {governanceLogs.map(log => (
                <div key={log.id} className="flex items-center justify-between p-3 bg-slate-50 rounded-xl border border-slate-100">
                   <div className="flex items-center gap-3">
                      <div className="p-2 bg-white rounded-lg border border-slate-200"><Activity size={14} className="text-indigo-600"/></div>
                      <div>
                        <p className="text-xs font-bold text-slate-800">{log.action}</p>
                        <p className="text-[9px] text-slate-400 uppercase">{log.user}</p>
                      </div>
                   </div>
                   <span className="text-[9px] font-mono text-slate-400">{log.timestamp?.seconds ? new Date(log.timestamp.seconds * 1000).toLocaleString() : 'Recent'}</span>
                </div>
              ))}
           </div>
        </div>
      )}
    </div>
  );
};

export default SettingsView;

import React, { useState, useEffect, useRef } from 'react';
import { 
  doc, updateDoc, getDoc, collection, onSnapshot, query, where, 
  addDoc, deleteDoc, serverTimestamp, orderBy, limit, setDoc
} from "https://www.gstatic.com/firebasejs/10.7.1/firebase-firestore.js";
import { db, auth } from '../firebase';
import { 
  Users, Shield, Building, Save, Activity, 
  Plus, Trash2, Mail, CheckCircle2, UserCheck,
  Calendar, HardDrive, Key, X, Camera, GraduationCap,
  Eye, Edit3, Award, MapPin, User as UserIcon, Upload, 
  Briefcase, PlusCircle, MinusCircle, Smartphone, Fingerprint, RefreshCw
} from 'lucide-react';

type SettingsTab = 'geral' | 'equipe' | 'seguranca' | 'infra';
type RoleClassification = 'diretor' | 'vice_diretor' | 'coordenador' | 'secretaria' | 'professor' | 'apoio' | 'ti';

interface Formacao { curso: string; instituicao: string; ano: string; }
interface Experiencia { cargo: string; empresa: string; periodo: string; }

const SettingsView: React.FC = () => {
  const [activeTab, setActiveTab] = useState<SettingsTab>('geral');
  const [loading, setLoading] = useState(true);
  const [isSaving, setIsSaving] = useState(false);
  const fileInputRef = useRef<HTMLInputElement>(null);

  const [staff, setStaff] = useState<any[]>([]);
  const [isMemberModalOpen, setIsMemberModalOpen] = useState(false);
  const [isViewModalOpen, setIsViewModalOpen] = useState(false);
  const [selectedMember, setSelectedMember] = useState<any>(null);

  const [memberForm, setMemberForm] = useState({
    nome: '', email: '', documento: '', telefone: '',
    cargo: 'professor' as RoleClassification,
    status: 'ativo', fotoUrl: '', password: '',
    endereco: { cep: '', rua: '', numero: '', bairro: '', cidade: '', uf: '' },
    formacoes: [] as Formacao[],
    experiencias: [] as Experiencia[],
    biografia: ''
  });

  const [governanceLogs, setGovernanceLogs] = useState<any[]>([]);
  const [schoolConfig, setSchoolConfig] = useState({
    schoolName: 'Escola Bíblica EAD',
    primaryColor: '#4f46e5',
    secondaryColor: '#0f172a',
    academicYear: '2026'
  });

  useEffect(() => {
    const unsubConfig = onSnapshot(doc(db, 'system_settings', 'main_config'), (docSnap) => {
      if (docSnap.exists()) {
        const data = docSnap.data();
        if (data.schoolConfig) setSchoolConfig(prev => ({ ...prev, ...data.schoolConfig }));
      }
      setLoading(false);
    });

    const unsubStaff = onSnapshot(query(collection(db, 'users'), where('role', 'in', ['diretor', 'vice_diretor', 'coordenador', 'secretaria', 'professor', 'apoio', 'ti'])), (snap) => {
      setStaff(snap.docs.map(d => ({ id: d.id, ...d.data() })));
    });

    const unsubLogs = onSnapshot(query(collection(db, 'system_logs'), orderBy('timestamp', 'desc'), limit(10)), (snap) => {
      setGovernanceLogs(snap.docs.map(d => ({ id: d.id, ...d.data() })));
    });

    return () => { unsubConfig(); unsubStaff(); unsubLogs(); };
  }, []);

  const compressImage = (base64: string): Promise<string> => {
    return new Promise((resolve) => {
      const img = new Image();
      img.src = base64;
      img.onload = () => {
        const canvas = document.createElement('canvas');
        const MAX_WIDTH = 300;
        const scale = MAX_WIDTH / img.width;
        canvas.width = MAX_WIDTH;
        canvas.height = img.height * scale;
        const ctx = canvas.getContext('2d');
        ctx?.drawImage(img, 0, 0, canvas.width, canvas.height);
        resolve(canvas.toDataURL('image/jpeg', 0.7));
      };
    });
  };

  const handleFileUpload = async (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (file) {
      const reader = new FileReader();
      reader.onloadend = async () => {
        const compressed = await compressImage(reader.result as string);
        setMemberForm({ ...memberForm, fotoUrl: compressed });
      };
      reader.readAsDataURL(file);
    }
  };

  const handleSaveSystemConfig = async () => {
    setIsSaving(true);
    try {
      await setDoc(doc(db, 'system_settings', 'main_config'), {
        schoolConfig,
        updatedAt: serverTimestamp()
      }, { merge: true });
      alert("Configurações institucionais atualizadas!");
    } catch (err) {
      alert("Erro ao salvar configurações.");
    } finally {
      setIsSaving(false);
    }
  };

  const handleDeleteMember = async (id: string, name: string) => {
    if (confirm(`Remover permanentemente ${name}?`)) {
      try {
        await deleteDoc(doc(db, 'users', id));
        await addDoc(collection(db, 'system_logs'), {
          action: `Exclusão de Membro: ${name}`,
          user: auth.currentUser?.email || 'Admin',
          timestamp: serverTimestamp()
        });
      } catch (err) { alert("Erro na exclusão."); }
    }
  };

  const handleSaveMember = async (e: React.FormEvent) => {
    e.preventDefault();
    setIsSaving(true);
    try {
      const payload: any = {
        nome: memberForm.nome,
        displayName: memberForm.nome,
        email: memberForm.email.toLowerCase().trim(),
        documento: memberForm.documento,
        telefone: memberForm.telefone,
        role: memberForm.cargo,
        status: memberForm.status,
        photoURL: memberForm.fotoUrl,
        endereco: memberForm.endereco,
        formacoes: memberForm.formacoes,
        experiencias: memberForm.experiencias,
        biografia: memberForm.biografia,
        updatedAt: serverTimestamp()
      };

      if (!selectedMember) {
        payload.createdAt = serverTimestamp();
        payload.staffId = `STF-${Math.random().toString(36).substr(2, 5).toUpperCase()}`;
        // Senha enviada para o banco apenas como referência para a Cloud Function de criação de usuário
        payload.password = memberForm.password; 
        await addDoc(collection(db, 'users'), payload);
      } else {
        if (memberForm.password) payload.password = memberForm.password;
        await updateDoc(doc(db, 'users', selectedMember.id), payload);
      }

      await addDoc(collection(db, 'system_logs'), {
        action: selectedMember ? `Editou membro: ${memberForm.nome}` : `Cadastrou novo membro: ${memberForm.nome}`,
        user: auth.currentUser?.email || 'Admin',
        timestamp: serverTimestamp()
      });

      setIsMemberModalOpen(false);
      setSelectedMember(null);
