                <div className="space-y-1"><p className="text-[9px] font-black text-slate-400 uppercase italic">Identificação</p><p className="text-xs font-bold text-slate-800">{selectedMember.documento || '---'}</p></div>
                <div className="space-y-1"><p className="text-[9px] font-black text-slate-400 uppercase italic">Registro Staff</p><p className="text-xs font-mono font-bold text-indigo-600">{selectedMember.staffId || 'MASTER'}</p></div>
              </div>

              <div className="space-y-4">
                 <h4 className="text-[10px] font-black text-slate-900 uppercase italic flex items-center gap-2 tracking-widest"><GraduationCap size={14} className="text-indigo-600"/> Formação Docente</h4>
                 <div className="grid grid-cols-1 sm:grid-cols-2 gap-3">
                    {selectedMember.formacoes?.map((f: any, i: number) => (
