import React, { useState, useEffect, useMemo } from 'react';
import { 
  collection, query, where, onSnapshot, doc, getDoc, 
  addDoc, serverTimestamp, orderBy 
} from "https://www.gstatic.com/firebasejs/10.7.1/firebase-firestore.js";
import { db, auth } from '../firebase';
import { Course, User, Module, Exam } from '../types';
import { 
  BookOpen, PlayCircle, Award, FileText, CheckCircle2, 
  Clock, ChevronRight, Star, ArrowLeft, Layout, 
  GraduationCap, Zap, Download, MessageSquare, Menu, X
} from 'lucide-react';

interface StudentViewProps {
  user: User;
}

type StudentTab = 'vitrine' | 'meus_cursos' | 'aula' | 'perfil';

const StudentView: React.FC<StudentViewProps> = ({ user }) => {
  const [activeTab, setActiveTab] = useState<StudentTab>(user.role === 'aluno' ? 'meus_cursos' : 'vitrine');
  const [courses, setCourses] = useState<Course[]>([]);
  const [myEnrollments, setMyEnrollments] = useState<any[]>([]);
  const [selectedCourse, setSelectedCourse] = useState<Course | null>(null);
  const [courseModules, setCourseModules] = useState<Module[]>([]);
  const [activeLesson, setActiveLesson] = useState<any>(null);
  const [schoolConfig, setSchoolConfig] = useState<any>(null);
  const [loading, setLoading] = useState(true);

  useEffect(() => {
    // Carregar Configurações Escolares (Cores e Nome)
    const unsubConfig = onSnapshot(doc(db, 'system_settings', 'main_config'), (docSnap) => {
      if (docSnap.exists()) setSchoolConfig(docSnap.data().schoolConfig);
    });

    // Carregar Cursos Públicos
    const unsubCourses = onSnapshot(query(collection(db, 'cursos'), where('status', '==', 'ativo')), (snap) => {
      setCourses(snap.docs.map(d => ({ id: d.id, ...d.data() } as Course)));
      setLoading(false);
    });

    // Se logado, carregar progresso (Simulado via campos no user ou coleção específica)
    // Em um sistema real, haveria uma subcoleção 'enrollments'
    return () => { unsubConfig(); unsubCourses(); };
  }, []);

  const handleStartCourse = async (course: Course) => {
    setLoading(true);
    setSelectedCourse(course);
    const q = query(collection(db, 'modulos'), where('courseId', '==', course.id));
    const snap = await (new Promise<any>((resolve) => onSnapshot(q, resolve)));
