  const [loading, setLoading] = useState(true);

  useEffect(() => {
    // Carregar Configurações Escolares (Cores e Nome)
    const unsubConfig = onSnapshot(doc(db, 'system_settings', 'main_config'), (docSnap) => {
      if (docSnap.exists()) setSchoolConfig(docSnap.data().schoolConfig);
    });

    // Carregar Cursos Públicos
    const unsubCourses = onSnapshot(query(collection(db, 'cursos'), where('status', '==', 'ativo')), (snap) => {
      setCourses(snap.docs.map(d => ({ id: d.id, ...d.data() } as Course)));
      setLoading(false);
    });

    // Se logado, carregar progresso (Simulado via campos no user ou coleção específica)
    // Em um sistema real, haveria uma subcoleção 'enrollments'
    return () => { unsubConfig(); unsubCourses(); };
  }, []);

  const handleStartCourse = async (course: Course) => {
    setLoading(true);
    setSelectedCourse(course);
    const q = query(collection(db, 'modulos'), where('courseId', '==', course.id));
    const snap = await (new Promise<any>((resolve) => onSnapshot(q, resolve)));
    const mods = snap.docs.map((d: any) => ({ id: d.id, ...d.data() })).sort((a: any, b: any) => a.order - b.order);
    setCourseModules(mods);
    setActiveTab('aula');
    if (mods.length > 0 && mods[0].lessons.length > 0) {
      setActiveLesson(mods[0].lessons[0]);
    }
    setLoading(false);
  };

  if (loading) return (
    <div className="h-screen flex flex-col items-center justify-center bg-slate-50">
      <div className="w-12 h-12 border-4 border-indigo-600 border-t-transparent animate-spin rounded-full mb-4"></div>
      <p className="text-[10px] font-black uppercase tracking-widest text-slate-400">Preparando seu Ambiente de Estudo...</p>
    </div>
  );

  return (
