                  <label className="text-[10px] font-black text-slate-400 uppercase tracking-widest ml-4 italic">E-mail Cadastrado</label>
                  <div className="relative">
                    <Mail className="absolute left-5 top-1/2 -translate-y-1/2 text-slate-300" size={18} />
                    <input 
                      type="email"
                      required
                      value={email}
                      onChange={(e) => setEmail(e.target.value)}
                      placeholder="exemplo@escola.edu.br"
                      className="w-full pl-14 pr-6 py-4 bg-slate-50 border-none rounded-2xl outline-none focus:ring-2 focus:ring-indigo-500 transition-all text-sm font-bold shadow-inner"
                    />
                  </div>
                </div>

                <div className="space-y-1.5">
                  <label className="text-[10px] font-black text-slate-400 uppercase tracking-widest ml-4 italic">Senha de Acesso</label>
                  <div className="relative">
                    <Lock className="absolute left-5 top-1/2 -translate-y-1/2 text-slate-300" size={18} />
                    <input 
                      type="password"
                      required
                      value={password}
                      onChange={(e) => setPassword(e.target.value)}
                      placeholder="••••••••"
                      className="w-full pl-14 pr-6 py-4 bg-slate-50 border-none rounded-2xl outline-none focus:ring-2 focus:ring-indigo-500 transition-all text-sm font-bold shadow-inner"
                    />
                  </div>
                </div>

                <button 
                  type="submit"
                  disabled={loading}
                  className={`w-full py-5 rounded-2xl font-black text-[10px] uppercase tracking-[0.2em] shadow-2xl transition-all active:scale-[0.98] mt-4 flex items-center justify-center gap-3 ${
                    loading ? 'bg-slate-200 text-slate-400 cursor-not-allowed' : 
                    loginType === 'admin' ? 'bg-slate-900 text-white hover:bg-slate-800' : 'bg-indigo-600 text-white hover:bg-indigo-700'
                  }`}
                >
                  {loading ? 'Validando Protocolos...' : <>Validar Credenciais <ArrowRight size={16}/></>}
                </button>
              </form>

              <div className="mt-10 pt-8 border-t border-slate-50 text-center">
                 <p className="text-[9px] text-slate-300 font-bold uppercase tracking-[0.3em]">&copy; Escola Bíblica EAD • Sistema Master</p>
              </div>
            </div>
          </div>
        )}
      </div>
      <style>{`
        @keyframes pulse-slow {
          0%, 100% { transform: scale(1.1); }
          50% { transform: scale(1.05); }
        }
        .animate-pulse-slow {
          animation: pulse-slow 15s ease-in-out infinite;
        }
      `}</style>
    </div>
  );
};

