import DashboardView from './views/DashboardView';
import ProfessorView from './views/ProfessorView';
import StudentsView from './views/StudentsView';
import SecretariatView from './views/SecretariatView';
import SettingsView from './views/SettingsView';
import LoginView from './views/LoginView';
import StudentView from './views/StudentView';

const App: React.FC = () => {
  const [currentUser, setCurrentUser] = useState<User | null>(null);
  const [loading, setLoading] = useState(true);
  const [activeView, setActiveView] = useState<MainView>('dashboard');
  const [activeProfessorSubView, setActiveProfessorSubView] = useState<ProfessorSubView>('cursos');
  const [isMobileMenuOpen, setIsMobileMenuOpen] = useState(false);

  useEffect(() => {
    const unsubscribe = onAuthStateChanged(auth, async (user) => {
      if (user) {
        try {
          const userRef = doc(db, 'users', user.uid);
          let userDoc = await getDoc(userRef);

          if (!userDoc.exists()) {
            // Auditoria: Se o usuário logou mas não tem doc no Firestore, tratamos como aluno novo por padrão
            const initialData = {
              nome: user.displayName || 'Novo Aluno',
              role: 'aluno',
              email: user.email,
              createdAt: new Date(),
              status: 'ativo'
            };
            await setDoc(userRef, initialData);
            userDoc = await getDoc(userRef);
          }

          const userData = userDoc.data();
          const role = (userData?.role as UserRole) || 'aluno';

          setCurrentUser({
            uid: user.uid,
            email: user.email,
            displayName: userData?.nome || user.displayName || 'Usuário',
            role: role,
            photoURL: user.photoURL || undefined
          });
        } catch (error) {
          console.error("Erro ao buscar perfil RBAC:", error);
          setCurrentUser(null);
        }
      } else {
        setCurrentUser(null);
      }
      setLoading(false);
    });

    return () => unsubscribe();
  }, []);

  const navigateToSubView = (main: MainView, sub?: ProfessorSubView) => {
    setActiveView(main);
    if (sub) setActiveProfessorSubView(sub);
  };

  if (loading) {
    return (
      <div className="flex h-screen items-center justify-center bg-slate-900">
        <div className="flex flex-col items-center gap-6 animate-pulse">
          <div className="h-12 w-12 animate-spin rounded-full border-4 border-indigo-500 border-t-transparent"></div>
          <div className="text-center">
            <p className="text-white text-xs font-black uppercase tracking-[0.5em] italic">Carregando Ecossistema</p>
            <p className="text-slate-500 text-[8px] font-bold uppercase mt-2">Escola Bíblica EAD Master</p>
          </div>
        </div>
      </div>
    );
  }

  if (!currentUser) return <LoginView />;

  // Fluxo de Aluno: Interface exclusiva, sem Navbar Admin
  if (currentUser.role === 'aluno') {
    return <StudentView user={currentUser} />;
  }

  // Fluxo de Staff (Diretor/Professor/Secretaria)
  const renderView = () => {
    switch (activeView) {
      case 'dashboard': return <DashboardView onNavigate={navigateToSubView} />;
      case 'professor': return <ProfessorView user={currentUser} activeSubView={activeProfessorSubView} />;
      case 'alunos': return <StudentsView />;
      case 'secretaria': return <SecretariatView user={currentUser} />;
      case 'configuracoes': return <SettingsView />;
      default: return <DashboardView onNavigate={navigateToSubView} />;
    }
  };

  return (
    <div className="min-h-screen bg-slate-50 flex flex-col font-sans antialiased text-slate-900">
      <Navbar 
        user={currentUser} 
        activeView={activeView} 
        setActiveView={(v) => { setActiveView(v); setIsMobileMenuOpen(false); }}
        isMobileMenuOpen={isMobileMenuOpen}
        setIsMobileMenuOpen={setIsMobileMenuOpen}
      />

      <div className="flex-1 flex overflow-hidden">
        {(activeView === 'professor') && (
          <Sidebar 
            activeSub={activeProfessorSubView} 
            setActiveSub={setActiveProfessorSubView} 
          />
        )}

        <main className="flex-1 overflow-y-auto overflow-x-hidden">
          <div className="max-w-7xl mx-auto p-4 md:p-6 lg:p-8 h-full">
            {renderView()}
          </div>
        </main>
      </div>
    </div>
  );
};

export default App;

import React, { useState, useEffect } from 'react';
// Correcting imports for Firebase modular SDK
import { onAuthStateChanged } from "https://www.gstatic.com/firebasejs/10.7.1/firebase-auth.js";
import { doc, getDoc, setDoc } from "https://www.gstatic.com/firebasejs/10.7.1/firebase-firestore.js";
import { auth, db } from './firebase';
import { UserRole, MainView, User, ProfessorSubView } from './types';
import Navbar from './components/Navbar';
import Sidebar from './components/Sidebar';
import DashboardView from './views/DashboardView';
import ProfessorView from './views/ProfessorView';
import StudentsView from './views/StudentsView';
import SecretariatView from './views/SecretariatView';
import SettingsView from './views/SettingsView';
import LoginView from './views/LoginView';
import StudentView from './views/StudentView';

const App: React.FC = () => {
  const [currentUser, setCurrentUser] = useState<User | null>(null);
  const [loading, setLoading] = useState(true);
  const [activeView, setActiveView] = useState<MainView>('dashboard');
  const [activeProfessorSubView, setActiveProfessorSubView] = useState<ProfessorSubView>('cursos');
  const [isMobileMenuOpen, setIsMobileMenuOpen] = useState(false);

  useEffect(() => {
    const unsubscribe = onAuthStateChanged(auth, async (user) => {
      setLoading(true);
      if (user) {
        try {
          // Busca o documento do usuário no Firestore (onde o role foi definido administrativamente)
          const userRef = doc(db, 'users', user.uid);
          let userDoc = await getDoc(userRef);

          let role: UserRole = 'aluno';
          let displayName = user.displayName || 'Usuário';

          if (userDoc.exists()) {
            const userData = userDoc.data();
            role = (userData?.role as UserRole) || 'aluno';
            displayName = userData?.nome || userData?.displayName || displayName;
          } else {
            // Se o usuário existe no Auth mas não no Firestore (raro, mas possível em novos registros)
            // Criamos o perfil básico para não travar o acesso
            const initialData = {
              nome: displayName,
              role: 'aluno',
              email: user.email,
              createdAt: new Date(),
              status: 'ativo'
            };
            await setDoc(userRef, initialData);
            role = 'aluno';
          }

          setCurrentUser({
            uid: user.uid,
            email: user.email,
            displayName: displayName,
            role: role,
            photoURL: user.photoURL || undefined
          });
        } catch (error) {
          console.error("Erro crítico na auditoria de perfil:", error);
          setCurrentUser(null);
        }
      } else {
        setCurrentUser(null);
      }
      setLoading(false);
    });

    return () => unsubscribe();
  }, []);

  const navigateToSubView = (main: MainView, sub?: ProfessorSubView) => {
    setActiveView(main);
    if (sub) setActiveProfessorSubView(sub);
  };

  if (loading) {
    return (
      <div className="flex h-screen items-center justify-center bg-slate-950">
        <div className="flex flex-col items-center gap-6 animate-pulse">
          <div className="h-12 w-12 animate-spin rounded-full border-4 border-indigo-500 border-t-transparent shadow-[0_0_20px_rgba(79,70,229,0.4)]"></div>
          <div className="text-center">
            <p className="text-white text-[10px] font-black uppercase tracking-[0.5em] italic">Autenticando Acesso</p>
            <p className="text-slate-500 text-[8px] font-bold uppercase mt-2 italic">Escola Bíblica EAD Master</p>
          </div>
        </div>
      </div>
    );
  }

  if (!currentUser) return <LoginView />;

  // Se o usuário for aluno, renderiza a StudentView aprovada
  if (currentUser.role === 'aluno') {
    return <StudentView user={currentUser} />;
  }

  // Se for staff, renderiza o painel administrativo
  const renderView = () => {
    switch (activeView) {
      case 'dashboard': return <DashboardView onNavigate={navigateToSubView} />;
      case 'professor': return <ProfessorView user={currentUser} activeSubView={activeProfessorSubView} />;
      case 'alunos': return <StudentsView />;
      case 'secretaria': return <SecretariatView user={currentUser} />;
      case 'configuracoes': return <SettingsView />;
      default: return <DashboardView onNavigate={navigateToSubView} />;
    }
  };

  return (
    <div className="min-h-screen bg-slate-50 flex flex-col font-sans antialiased text-slate-900">
      <Navbar 
        user={currentUser} 
        activeView={activeView} 
        setActiveView={(v) => { setActiveView(v); setIsMobileMenuOpen(false); }}
        isMobileMenuOpen={isMobileMenuOpen}
        setIsMobileMenuOpen={setIsMobileMenuOpen}
      />

      <div className="flex-1 flex overflow-hidden">
        {(activeView === 'professor') && (
          <Sidebar 
            activeSub={activeProfessorSubView} 
            setActiveSub={setActiveProfessorSubView} 
          />
        )}

        <main className="flex-1 overflow-y-auto overflow-x-hidden">
          <div className="max-w-7xl mx-auto p-4 md:p-6 lg:p-8 h-full">
            {renderView()}
          </div>
        </main>
      </div>
    </div>
  );
};

export default App;

import React, { useState } from 'react';
import { signInWithEmailAndPassword } from "https://www.gstatic.com/firebasejs/10.7.1/firebase-auth.js";
import { auth } from '../firebase';
import { BookOpen, Lock, Mail, AlertCircle, GraduationCap, ShieldCheck, ArrowRight } from 'lucide-react';

const LoginView: React.FC = () => {
  const [email, setEmail] = useState('');
  const [password, setPassword] = useState('');
  const [error, setError] = useState('');
  const [loading, setLoading] = useState(false);
  const [loginType, setLoginType] = useState<'aluno' | 'admin' | null>(null);

  const handleLogin = async (e: React.FormEvent) => {
    e.preventDefault();
    setLoading(true);
    setError('');

    try {
      // Tenta a autenticação no Firebase
      await signInWithEmailAndPassword(auth, email.trim(), password);
      // O App.tsx cuidará de redirecionar com base no 'role' do Firestore após o login bem sucedido
    } catch (err: any) {
      console.error("Erro no Login:", err.code);
      if (err.code === 'auth/user-not-found' || err.code === 'auth/wrong-password' || err.code === 'auth/invalid-credential') {
        setError('E-mail ou senha incorretos. Verifique suas credenciais acadêmicas.');
      } else if (err.code === 'auth/too-many-requests') {
        setError('Muitas tentativas. Sua conta foi temporariamente bloqueada por segurança.');
      } else {
        setError('Falha na conexão com o servidor de autenticação.');
      }
    } finally {
      setLoading(false);
    }
  };

  return (
    <div className="min-h-screen relative flex items-center justify-center p-6 overflow-hidden">
      {/* Background com Imagem Imersiva */}
      <div 
        className="absolute inset-0 z-0 bg-cover bg-center transition-transform duration-[20s] scale-110 animate-pulse-slow"
        style={{ 
          backgroundImage: 'url(https://images.unsplash.com/photo-1523050853064-8430a680d28d?auto=format&fit=crop&q=80)',
        }}
      />
      <div className="absolute inset-0 z-1 bg-slate-950/70 backdrop-blur-[2px]" />

      <div className="relative z-10 w-full max-w-5xl">
        {!loginType ? (
          <div className="grid grid-cols-1 md:grid-cols-2 gap-8 animate-in fade-in zoom-in-95 duration-500">
            {/* Card Aluno */}
            <button 
              onClick={() => setLoginType('aluno')}
              className="bg-white/95 backdrop-blur-xl p-12 rounded-[3rem] shadow-2xl border border-white/20 group hover:scale-[1.02] transition-all text-left flex flex-col items-center text-center"
            >
              <div className="w-20 h-20 bg-indigo-600 text-white rounded-[2rem] flex items-center justify-center mb-8 shadow-xl shadow-indigo-200 group-hover:rotate-12 transition-transform">
                <GraduationCap size={40} />
              </div>
              <h2 className="text-3xl font-black text-slate-900 uppercase italic tracking-tighter mb-4">Portal do Aluno</h2>
              <p className="text-slate-500 font-medium italic mb-8">Acesse suas aulas, materiais e realize suas provas no ambiente de aprendizado.</p>
              <div className="mt-auto flex items-center gap-2 text-indigo-600 font-black uppercase text-[10px] tracking-widest group-hover:gap-4 transition-all">
                Entrar na Sala de Aula <ArrowRight size={16}/>
              </div>
            </button>

            {/* Card Admin */}
            <button 
              onClick={() => setLoginType('admin')}
              className="bg-slate-900/95 backdrop-blur-xl p-12 rounded-[3rem] shadow-2xl border border-white/5 group hover:scale-[1.02] transition-all text-left flex flex-col items-center text-center"
            >
              <div className="w-20 h-20 bg-slate-700 text-white rounded-[2rem] flex items-center justify-center mb-8 shadow-xl shadow-black/50 group-hover:-rotate-12 transition-transform">
                <ShieldCheck size={40} />
              </div>
              <h2 className="text-3xl font-black text-white uppercase italic tracking-tighter mb-4">Gestão Escolar</h2>
              <p className="text-slate-400 font-medium italic mb-8">Acesso restrito para diretores, secretários e corpo docente da instituição.</p>
              <div className="mt-auto flex items-center gap-2 text-indigo-400 font-black uppercase text-[10px] tracking-widest group-hover:gap-4 transition-all">
                Acessar Controladoria <ArrowRight size={16}/>
              </div>
            </button>
          </div>
        ) : (
          <div className="max-w-md mx-auto animate-in slide-in-from-bottom-8 duration-500">
            <div className={`bg-white p-10 rounded-[3rem] shadow-2xl border ${loginType === 'admin' ? 'border-indigo-500/30' : 'border-slate-100'}`}>
              <div className="text-center mb-8">
                <button 
                  onClick={() => { setLoginType(null); setError(''); }}
                  className="mb-6 text-[9px] font-black uppercase tracking-widest text-slate-400 hover:text-indigo-600 transition-colors flex items-center justify-center gap-2 mx-auto"
                >
                  <ArrowRight size={14} className="rotate-180"/> Voltar para Seleção
                </button>
                <div className={`inline-flex p-4 rounded-[1.5rem] text-white mb-4 shadow-lg ${loginType === 'admin' ? 'bg-slate-900' : 'bg-indigo-600'}`}>
                  {loginType === 'admin' ? <ShieldCheck size={32} /> : <GraduationCap size={32} />}
                </div>
                <h1 className="text-2xl font-black text-slate-900 uppercase italic tracking-tighter">
                  {loginType === 'admin' ? 'Acesso Administrativo' : 'Acesso do Aluno'}
                </h1>
                <p className="text-slate-400 text-[10px] font-bold uppercase tracking-widest mt-1">Identifique-se para prosseguir</p>
              </div>

              {error && (
                <div className="mb-6 p-4 bg-rose-50 border border-rose-100 text-rose-600 rounded-2xl text-[10px] font-bold uppercase italic flex items-center gap-3">
                  <AlertCircle size={18} />
                  {error}
                </div>
              )}

              <form onSubmit={handleLogin} className="space-y-5">
                <div className="space-y-1.5">
                  <label className="text-[10px] font-black text-slate-400 uppercase tracking-widest ml-4 italic">E-mail Cadastrado</label>
                  <div className="relative">
                    <Mail className="absolute left-5 top-1/2 -translate-y-1/2 text-slate-300" size={18} />
                    <input 
                      type="email"
                      required
                      value={email}
                      onChange={(e) => setEmail(e.target.value)}
                      placeholder="exemplo@escola.edu.br"
                      className="w-full pl-14 pr-6 py-4 bg-slate-50 border-none rounded-2xl outline-none focus:ring-2 focus:ring-indigo-500 transition-all text-sm font-bold shadow-inner"
                    />
                  </div>
                </div>

                <div className="space-y-1.5">
                  <label className="text-[10px] font-black text-slate-400 uppercase tracking-widest ml-4 italic">Senha de Acesso</label>
                  <div className="relative">
                    <Lock className="absolute left-5 top-1/2 -translate-y-1/2 text-slate-300" size={18} />
                    <input 
                      type="password"
                      required
                      value={password}
                      onChange={(e) => setPassword(e.target.value)}
                      placeholder="••••••••"
                      className="w-full pl-14 pr-6 py-4 bg-slate-50 border-none rounded-2xl outline-none focus:ring-2 focus:ring-indigo-500 transition-all text-sm font-bold shadow-inner"
                    />
                  </div>
                </div>

                <button 
                  type="submit"
                  disabled={loading}
                  className={`w-full py-5 rounded-2xl font-black text-[10px] uppercase tracking-[0.2em] shadow-2xl transition-all active:scale-[0.98] mt-4 flex items-center justify-center gap-3 ${
                    loading ? 'bg-slate-200 text-slate-400 cursor-not-allowed' : 
                    loginType === 'admin' ? 'bg-slate-900 text-white hover:bg-slate-800' : 'bg-indigo-600 text-white hover:bg-indigo-700'
                  }`}
                >
                  {loading ? 'Validando Protocolos...' : <>Validar Credenciais <ArrowRight size={16}/></>}
                </button>
              </form>

              <div className="mt-10 pt-8 border-t border-slate-50 text-center">
                 <p className="text-[9px] text-slate-300 font-bold uppercase tracking-[0.3em]">&copy; Escola Bíblica EAD • Sistema Master</p>
              </div>
            </div>
          </div>
        )}
      </div>
      <style>{`
        @keyframes pulse-slow {
          0%, 100% { transform: scale(1.1); }
          50% { transform: scale(1.05); }
        }
        .animate-pulse-slow {
          animation: pulse-slow 15s ease-in-out infinite;
        }
      `}</style>
    </div>
  );
};

export default LoginView;

