import React, { useState, useEffect, useMemo } from 'react';
import { 
  collection, query, where, onSnapshot, 
  deleteDoc, serverTimestamp, doc, setDoc, getDocs, writeBatch
} from "https://www.gstatic.com/firebasejs/10.7.1/firebase-firestore.js";
import { db } from '../firebase';
import { User, Course } from '../types';
import { 
  Search, UserPlus, Filter, X, Save, UserCog, Trash2, Download, BookOpen, MapPin, Hash, Lock, ShieldCheck, Calendar, Eye, Edit3, AlertCircle
} from 'lucide-react';

const StudentsView: React.FC = () => {
  const [students, setStudents] = useState<User[]>([]);
  const [courses, setCourses] = useState<Course[]>([]);
  const [loading, setLoading] = useState(true);
  const [searchTerm, setSearchTerm] = useState('');
  const [courseFilter, setCourseFilter] = useState('');

  const [isRegisterModalOpen, setIsRegisterModalOpen] = useState(false);
  const [selectedStudent, setSelectedStudent] = useState<any | null>(null);
  const [actionLoading, setActionLoading] = useState(false);

  const [formData, setFormData] = useState({
    nome: '', email: '', telefone: '', cursoId: '', usuario: '', senha: '', status: 'ativo'
  });

  useEffect(() => {
    const unsubStudents = onSnapshot(query(collection(db, 'users'), where('role', '==', 'aluno')), (snap) => {
      const data = snap.docs.map(d => ({ uid: d.id, ...d.data() } as User));
      setStudents(data.sort((a: any, b: any) => (b.createdAt?.seconds || 0) - (a.createdAt?.seconds || 0)));
      setLoading(false);
    });
    const unsubCourses = onSnapshot(collection(db, 'cursos'), (snap) => {
      setCourses(snap.docs.map(d => ({ id: d.id, ...d.data() } as Course)));
    });
    return () => { unsubStudents(); unsubCourses(); };
  }, []);

  const filtered = useMemo(() => {
    return students.filter(s => {
      const matchSearch = s.displayName?.toLowerCase().includes(searchTerm.toLowerCase()) || 
                          s.email?.toLowerCase().includes(searchTerm.toLowerCase());
      const matchCourse = !courseFilter || (s as any).cursoInicial === courseFilter;
      return matchSearch && matchCourse;
    });
  }, [students, searchTerm, courseFilter]);

  const handleSave = async (e: React.FormEvent) => {
    e.preventDefault();
    setActionLoading(true);
    try {
      // Auditoria: Garantir que UID e Role sejam consistentes
      const uid = selectedStudent?.uid || Math.random().toString(36).substring(2, 15);
      const userRef = doc(db, 'users', uid);

      const payload = {
        displayName: formData.nome,
        nome: formData.nome,
        email: formData.email.toLowerCase().trim(),
        telefone: formData.telefone,
        cursoInicial: formData.cursoId,
        username: formData.usuario,
        password: formData.senha, // Em sistema real usar Auth
        role: 'aluno', // CRITICAL: Para auditoria de acesso
        status: formData.status,
        updatedAt: serverTimestamp(),
        createdAt: selectedStudent?.createdAt || serverTimestamp(),
        academicId: selectedStudent?.academicId || `MAT-${new Date().getFullYear()}-${Math.random().toString(36).substring(2, 6).toUpperCase()}`
      };

      await setDoc(userRef, payload, { merge: true });
      setIsRegisterModalOpen(false);
      setFormData({ nome: '', email: '', telefone: '', cursoId: '', usuario: '', senha: '', status: 'ativo' });
      setSelectedStudent(null);
    } catch (err) {
      alert("Erro ao processar matrícula.");
    } finally {
      setActionLoading(false);
    }
  };

  if (loading) return <div className="p-20 flex justify-center"><div className="w-10 h-10 border-4 border-indigo-600 border-t-transparent animate-spin rounded-full" /></div>;

  return (
    <div className="space-y-8 animate-in fade-in duration-700">
      <header className="flex flex-col md:flex-row md:items-center justify-between gap-6">
        <div>
          <h1 className="text-3xl font-black text-slate-900 uppercase italic tracking-tighter">Matrículas EAD</h1>
          <p className="text-slate-500 text-sm font-medium italic">Gestão de prontuários e acessos discentes.</p>
        </div>
        <button onClick={() => setIsRegisterModalOpen(true)} className="flex items-center gap-3 bg-slate-900 text-white px-8 py-3.5 rounded-2xl text-[10px] font-black uppercase tracking-widest hover:bg-indigo-600 shadow-xl transition-all italic"><UserPlus size={18} /> Nova Matrícula</button>
      </header>

      <div className="bg-white rounded-[3rem] border border-slate-200 shadow-sm overflow-hidden">
        <div className="p-10 border-b border-slate-50 flex flex-col md:flex-row gap-4">
          <div className="relative flex-[2]">
            <Search className="absolute left-5 top-1/2 -translate-y-1/2 text-slate-400" size={18} />
            <input type="text" value={searchTerm} onChange={e => setSearchTerm(e.target.value)} placeholder="Pesquisar por nome ou e-mail..." className="w-full pl-14 pr-6 py-4 bg-slate-50 border-none rounded-2xl text-[10px] font-bold shadow-inner" />
          </div>
          <select value={courseFilter} onChange={e => setCourseFilter(e.target.value)} className="bg-slate-50 border-none rounded-2xl px-6 py-4 text-[9px] font-black uppercase flex-1 shadow-inner">
            <option value="">Filtrar por Disciplina</option>
            {courses.map(c => <option key={c.id} value={c.id}>{c.nome}</option>)}
          </select>
        </div>

        <div className="overflow-x-auto">
          <table className="w-full text-left">
            <thead className="bg-slate-50 text-[9px] font-black text-slate-400 uppercase tracking-widest border-b italic">
              <tr>
                <th className="px-10 py-6">ID Aluno</th>
                <th className="px-10 py-6">Nome / E-mail</th>
                <th className="px-10 py-6">Disciplina</th>
                <th className="px-10 py-6">Status</th>
                <th className="px-10 py-6 text-center">Gestão</th>
              </tr>
            </thead>
            <tbody className="divide-y divide-slate-100 text-[10px]">
              {filtered.map(student => (
                <tr key={student.uid} className="hover:bg-slate-50 transition-all">
                  <td className="px-10 py-6 font-mono font-black text-indigo-600">{(student as any).academicId}</td>
                  <td className="px-10 py-6">
                    <div className="font-black text-slate-900 uppercase italic">{student.displayName}</div>
                    <div className="text-slate-400 font-bold">{student.email}</div>
                  </td>
                  <td className="px-10 py-6 font-black text-indigo-500 italic uppercase">{courses.find(c => c.id === (student as any).cursoInicial)?.nome || 'S/Vínculo'}</td>
                  <td className="px-10 py-6">
                    <span className={`px-4 py-1.5 rounded-full text-[8px] font-black uppercase italic ${student.status === 'ativo' ? 'bg-emerald-50 text-emerald-600' : 'bg-rose-50 text-rose-600'}`}>{student.status}</span>
                  </td>
                  <td className="px-10 py-6 text-center">
                    <div className="flex justify-center gap-2">
                      <button onClick={() => { setSelectedStudent(student); setFormData({ nome: student.displayName, email: student.email || '', telefone: (student as any).telefone || '', cursoId: (student as any).cursoInicial || '', usuario: (student as any).username || '', senha: (student as any).password || '', status: student.status || 'ativo' }); setIsRegisterModalOpen(true); }} className="p-2.5 text-slate-400 hover:text-indigo-600 hover:bg-indigo-50 rounded-xl transition-all shadow-sm border border-slate-100"><Edit3 size={16} /></button>
                      <button onClick={async () => { if(confirm('Remover aluno?')) await deleteDoc(doc(db, 'users', student.uid)); }} className="p-2.5 text-slate-400 hover:text-rose-600 hover:bg-rose-50 rounded-xl transition-all shadow-sm border border-slate-100"><Trash2 size={16} /></button>
                    </div>
                  </td>
                </tr>
              ))}
            </tbody>
          </table>
        </div>
      </div>

      {isRegisterModalOpen && (
        <div className="fixed inset-0 z-[1000] bg-slate-950/90 backdrop-blur-xl flex items-center justify-center p-6">
          <div className="bg-white w-full max-w-2xl rounded-[3rem] overflow-hidden shadow-2xl animate-in zoom-in-95 duration-300">
            <header className="p-8 border-b border-slate-100 flex justify-between items-center bg-slate-50/50">
               <h2 className="text-2xl font-black text-slate-900 uppercase italic tracking-tighter leading-none">{selectedStudent ? 'Atualizar Prontuário' : 'Matrícula Oficial'}</h2>
               <button onClick={() => { setIsRegisterModalOpen(false); setSelectedStudent(null); }} className="p-3 hover:bg-rose-50 text-slate-400 rounded-full transition-all"><X size={20}/></button>
            </header>
            <form onSubmit={handleSave} className="p-10 space-y-6">
               <div className="grid grid-cols-2 gap-6">
                 <div className="space-y-1.5"><label className="text-[9px] font-black uppercase text-slate-400 ml-4 italic">Nome Completo</label><input required value={formData.nome} onChange={e => setFormData({...formData, nome: e.target.value})} className="w-full px-6 py-4 bg-slate-50 border-none rounded-2xl font-bold text-xs shadow-inner" /></div>
                 <div className="space-y-1.5"><label className="text-[9px] font-black uppercase text-slate-400 ml-4 italic">E-mail Acadêmico</label><input type="email" required value={formData.email} onChange={e => setFormData({...formData, email: e.target.value})} className="w-full px-6 py-4 bg-slate-50 border-none rounded-2xl font-bold text-xs shadow-inner" /></div>
                 <div className="space-y-1.5"><label className="text-[9px] font-black uppercase text-slate-400 ml-4 italic">Telefone Celular</label><input required value={formData.telefone} onChange={e => setFormData({...formData, telefone: e.target.value})} className="w-full px-6 py-4 bg-slate-50 border-none rounded-2xl font-bold text-xs shadow-inner" /></div>
                 <div className="space-y-1.5"><label className="text-[9px] font-black uppercase text-slate-400 ml-4 italic">Curso Matriz</label><select required value={formData.cursoId} onChange={e => setFormData({...formData, cursoId: e.target.value})} className="w-full px-6 py-4 bg-slate-50 border-none rounded-2xl font-black text-[10px] uppercase shadow-inner"><option value="">Vincular Curso...</option>{courses.map(c => <option key={c.id} value={c.id}>{c.nome}</option>)}</select></div>
                 <div className="space-y-1.5"><label className="text-[9px] font-black uppercase text-slate-400 ml-4 italic">Login (Usuário)</label><input required value={formData.usuario} onChange={e => setFormData({...formData, usuario: e.target.value})} className="w-full px-6 py-4 bg-slate-50 border-none rounded-2xl font-bold text-xs shadow-inner" /></div>
                 <div className="space-y-1.5"><label className="text-[9px] font-black uppercase text-slate-400 ml-4 italic">Senha de Acesso</label><input required value={formData.senha} onChange={e => setFormData({...formData, senha: e.target.value})} className="w-full px-6 py-4 bg-slate-50 border-none rounded-2xl font-bold text-xs shadow-inner" /></div>
               </div>
               <div className="flex gap-4 pt-8">
                  <button type="button" onClick={() => setIsRegisterModalOpen(false)} className="flex-1 py-5 bg-slate-100 text-slate-400 rounded-2xl text-[10px] font-black uppercase italic tracking-widest">Descartar</button>
                  <button type="submit" disabled={actionLoading} className="flex-1 py-5 bg-slate-900 text-white rounded-2xl text-[10px] font-black uppercase shadow-2xl hover:bg-indigo-600 transition-all italic">{actionLoading ? 'Processando...' : 'Confirmar Matrícula'}</button>
               </div>
            </form>
          </div>
        </div>
      )}
    </div>
  );
};

export default StudentsView;

import React, { useState, useEffect, useRef } from 'react';
import { signInWithEmailAndPassword, createUserWithEmailAndPassword } from "https://www.gstatic.com/firebasejs/10.7.1/firebase-auth.js";
import { collection, query, where, onSnapshot, doc, setDoc, serverTimestamp } from "https://www.gstatic.com/firebasejs/10.7.1/firebase-firestore.js";
import { auth, db } from '../firebase';
import { Lock, Mail, AlertCircle, GraduationCap, ShieldCheck, ArrowRight, BookOpen, Star, Users, CheckCircle, Clock, PlayCircle, Bell, ChevronRight, Target, Award } from 'lucide-react';

type ViewMode = 'landing' | 'login' | 'enroll';

const LoginView: React.FC = () => {
  const [viewMode, setViewMode] = useState<ViewMode>('landing');
  const [email, setEmail] = useState('');
  const [password, setPassword] = useState('');
  const [error, setError] = useState('');
  const [loading, setLoading] = useState(false);
  const [isAdminMode, setIsAdminMode] = useState(false);

  // States para Auto-Matrícula
  const [courses, setCourses] = useState<any[]>([]);
  const [selectedCourse, setSelectedCourse] = useState<any>(null);
  const [enrollData, setEnrollData] = useState({ nome: '', email: '', senha: '', telefone: '' });

  const coursesRef = useRef<HTMLDivElement>(null);

  useEffect(() => {
    const unsub = onSnapshot(query(collection(db, 'cursos'), where('status', '==', 'ativo')), (snap) => {
      setCourses(snap.docs.map(d => ({ id: d.id, ...d.data() })));
    });
    return () => unsub();
  }, []);

  const handleLogin = async (e: React.FormEvent) => {
    e.preventDefault();
    setLoading(true);
    setError('');
    try {
      await signInWithEmailAndPassword(auth, email.trim().toLowerCase(), password);
    } catch (err: any) {
      setError('Acesso negado. Verifique seu e-mail e senha acadêmica.');
    } finally {
      setLoading(false);
    }
  };

  const handleAutoEnroll = async (e: React.FormEvent) => {
    e.preventDefault();
    setLoading(true);
    setError('');
    try {
      const userCredential = await createUserWithEmailAndPassword(auth, enrollData.email.trim(), enrollData.senha);
      const uid = userCredential.user.uid;

      const academicId = `MAT-${new Date().getFullYear()}-${Math.random().toString(36).substring(2, 7).toUpperCase()}`;

      await setDoc(doc(db, 'users', uid), {
        uid,
        displayName: enrollData.nome,
        nome: enrollData.nome,
        email: enrollData.email.toLowerCase(),
        telefone: enrollData.telefone,
        role: 'aluno',
        status: 'ativo',
        cursoInicial: selectedCourse.id,
        academicId,
        createdAt: serverTimestamp(),
        progress: 0
      });
