                <span className="text-[9px] font-bold text-slate-400 uppercase tracking-widest mt-1">Excelência Teológica</span>
              </div>
            </div>
            <div className="flex items-center gap-8">
              <button onClick={() => setViewMode('login')} className="text-[10px] font-black uppercase tracking-widest text-slate-500 hover:text-indigo-600 transition-all border-b-2 border-transparent hover:border-indigo-600 pb-1">Já sou Aluno</button>
