                <div className="flex items-center gap-3">
                   <div className="w-10 h-10 rounded-full bg-indigo-100" />
                   <div><p className="text-[10px] font-black uppercase text-slate-900 leading-none">Pr. Marcos Silva</p><p className="text-[8px] font-bold text-slate-400 uppercase mt-1">Teologia Sistemática</p></div>
                </div>
