              {[
                { label: 'Aulas em 4K', value: '450+', icon: <PlayCircle className="text-indigo-400"/> },
                { label: 'Docentes Master', value: '15', icon: <Users className="text-indigo-400"/> },
                { label: 'Materiais PDF', value: '1.2k', icon: <BookOpen className="text-indigo-400"/> },
                { label: 'Satisfação Alunos', value: '99%', icon: <Award className="text-indigo-400"/> }
              ].map((m, i) => (
