  const [loading, setLoading] = useState(true);
  const [showNotifications, setShowNotifications] = useState(false);
  const [isMobileMenuOpen, setIsMobileMenuOpen] = useState(false);

  useEffect(() => {
    setLoading(true);
    // Carregar cursos onde o aluno está matriculado
    // Auditoria: Em um sistema real buscaríamos pela matrícula, aqui simulamos pela lista global filtrada
    const unsub = onSnapshot(query(collection(db, 'cursos'), where('status', '==', 'ativo')), (snap) => {
      setCourses(snap.docs.map(d => ({ id: d.id, ...d.data() } as Course)));
      setLoading(false);
    });
    return () => unsub();
  }, []);

  const handleStartLesson = async (course: Course) => {
    setLoading(true);
    setSelectedCourse(course);
    const q = query(collection(db, 'modulos'), where('courseId', '==', course.id));
    const snap = await (new Promise<any>((resolve) => onSnapshot(q, resolve)));
    const mods = snap.docs.map((d: any) => ({ id: d.id, ...d.data() })).sort((a: any, b: any) => (a.order || 0) - (b.order || 0));
    setModules(mods);
    setActiveSubView('classroom');
