                          <input required value={enrollForm.nome} onChange={e => setEnrollForm({...enrollForm, nome: e.target.value})} className="w-full px-8 py-5 bg-white border border-slate-200 rounded-3xl font-bold shadow-sm focus:ring-2 focus:ring-indigo-600 outline-none" placeholder="Ex: Luiz Otávio Silva..." />
                       </div>
                       <div className="space-y-2">
                          <label className="text-[10px] font-black text-slate-400 uppercase ml-4 italic flex items-center gap-2"><Mail size={12}/> E-mail Principal (Será seu Login)</label>
                          <input type="email" required value={enrollForm.email} onChange={e => setEnrollForm({...enrollForm, email: e.target.value})} className="w-full px-8 py-5 bg-white border border-slate-200 rounded-3xl font-bold shadow-sm focus:ring-2 focus:ring-indigo-600 outline-none" placeholder="seuemail@provedor.com" />
                       </div>
                       <div className="space-y-2">
