import React, { useState, useEffect, useRef } from 'react';
import { 
  collection, query, where, onSnapshot, doc, getDoc, 
  updateDoc, serverTimestamp, orderBy 
} from "https://www.gstatic.com/firebasejs/10.7.1/firebase-firestore.js";
import { auth, db } from '../firebase';
import { Course, User, Module, Lesson } from '../types';
import { 
  BookOpen, PlayCircle, Award, FileText, CheckCircle2, 
  Clock, ChevronRight, Star, ArrowLeft, Layout, 
  GraduationCap, Zap, Download, MessageSquare, Menu, X, Settings,
  Bell, User as UserIcon, LogOut, Search, Play, FileBadge, Sliders, 
  HelpCircle, ChevronDown, CheckCircle, Smartphone, Database, Video, ShieldAlert
} from 'lucide-react';

interface StudentViewProps {
  user: User;
}

type StudentSubView = 'dashboard' | 'classroom' | 'library' | 'certificates' | 'settings';

const StudentView: React.FC<StudentViewProps> = ({ user }) => {
  const [activeSubView, setActiveSubView] = useState<StudentSubView>('dashboard');
  const [courses, setCourses] = useState<Course[]>([]);
  const [selectedCourse, setSelectedCourse] = useState<Course | null>(null);
  const [modules, setModules] = useState<Module[]>([]);
  const [activeLesson, setActiveLesson] = useState<Lesson | null>(null);
  const [loading, setLoading] = useState(true);
  const [showNotifications, setShowNotifications] = useState(false);
  const [notifications, setNotifications] = useState([
    { id: 1, title: 'Matrícula Recebida', message: 'Sua documentação está em análise pela secretaria.', type: 'pdf', time: 'Agora' }
  ]);

  useEffect(() => {
    setLoading(true);
    const unsub = onSnapshot(query(collection(db, 'cursos'), where('status', '==', 'ativo')), (snap) => {
      const data = snap.docs.map(d => ({ id: d.id, ...d.data() } as Course));
      setCourses(data);
      setLoading(false);
    });
    return () => unsub();
  }, []);

  const handleStartLesson = async (course: Course) => {
    setLoading(true);
    setSelectedCourse(course);
    const q = query(collection(db, 'modulos'), where('courseId', '==', course.id));
    onSnapshot(q, (snap) => {
      const mods = snap.docs.map((d: any) => ({ id: d.id, ...d.data() }))
        .sort((a: any, b: any) => (a.order || 0) - (b.order || 0));
      setModules(mods);
      if (mods.length > 0 && mods[0].lessons && mods[0].lessons.length > 0) {
        setActiveLesson(mods[0].lessons[0]);
      }
      setActiveSubView('classroom');
      setLoading(false);
    });
  };

