import React, { useState, useEffect, useRef } from 'react';
import { signInWithEmailAndPassword, createUserWithEmailAndPassword, signOut } from "https://www.gstatic.com/firebasejs/10.7.1/firebase-auth.js";
import { collection, query, where, onSnapshot, doc, setDoc, getDoc, serverTimestamp } from "https://www.gstatic.com/firebasejs/10.7.1/firebase-firestore.js";
import { auth, db } from '../firebase';
import { Lock, Mail, AlertCircle, GraduationCap, ShieldCheck, ArrowRight, BookOpen, Star, Users, CheckCircle, Clock, PlayCircle, Bell, ChevronRight, Target, Award, Camera, User, MapPin, Calendar, Smartphone, FileText, ChevronLeft, Upload, ShieldAlert, Fingerprint } from 'lucide-react';

type ViewMode = 'landing' | 'login' | 'enroll_form';

const LoginView: React.FC = () => {
  const [viewMode, setViewMode] = useState<ViewMode>('landing');
  const [email, setEmail] = useState('');
  const [password, setPassword] = useState('');
  const [error, setError] = useState('');
  const [loading, setLoading] = useState(false);
  const [isAdminMode, setIsAdminMode] = useState(false);

  const [courses, setCourses] = useState<any[]>([]);
  const [selectedCourse, setSelectedCourse] = useState<any>(null);

  const [enrollForm, setEnrollForm] = useState({
    nome: '', email: '', senha: '', cpf: '', nascimento: '', telefone: '', fotoUrl: '',
    endereco: { cep: '', rua: '', numero: '', bairro: '', cidade: '', uf: '' }
  });

  const coursesRef = useRef<HTMLDivElement>(null);
  const fileInputRef = useRef<HTMLInputElement>(null);

  useEffect(() => {
    const unsub = onSnapshot(query(collection(db, 'cursos'), where('status', '==', 'ativo')), (snap) => {
      setCourses(snap.docs.map(d => ({ id: d.id, ...d.data() })));
    });
    return () => unsub();
  }, []);

  const handleLogin = async (e: React.FormEvent) => {
    e.preventDefault();
    setLoading(true);
    setError('');
    try {
      const userCredential = await signInWithEmailAndPassword(auth, email.trim().toLowerCase(), password);
      const uid = userCredential.user.uid;

      // Validação de Ponto de Entrada (Trava de Segurança)
      const userDoc = await getDoc(doc(db, 'users', uid));
      if (userDoc.exists()) {
        const userData = userDoc.data();
        const role = userData.role;

        if (!isAdminMode && role !== 'aluno') {
          await signOut(auth);
          setError('Acesso negado. Credenciais de gestão detectadas. Utilize o Portal do Gestor.');
          setLoading(false);
          return;
        }

        if (isAdminMode && role === 'aluno') {
          await signOut(auth);
          setError('Acesso negado. Esta área é exclusiva para a administração.');
          setLoading(false);
          return;
        }
      }
    } catch (err: any) {
      setError('Credenciais inválidas ou conta não localizada.');
      setLoading(false);
    }
  };

  const handlePhotoUpload = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (file) {
      const reader = new FileReader();
      reader.onloadend = () => setEnrollForm({ ...enrollForm, fotoUrl: reader.result as string });
      reader.readAsDataURL(file);
    }
  };

  const handleFinalizeEnroll = async (e: React.FormEvent) => {
    e.preventDefault();
    setLoading(true);
    setError('');
    try {
      const userCredential = await createUserWithEmailAndPassword(auth, enrollForm.email.trim(), enrollForm.senha);
      const uid = userCredential.user.uid;
      const academicId = `ALU-${new Date().getFullYear()}-${Math.random().toString(36).substring(2, 7).toUpperCase()}`;

      await setDoc(doc(db, 'users', uid), {
        uid, displayName: enrollForm.nome, nome: enrollForm.nome, email: enrollForm.email.toLowerCase(),
        cpf: enrollForm.cpf, nascimento: enrollForm.nascimento, telefone: enrollForm.telefone,
        photoURL: enrollForm.fotoUrl, endereco: enrollForm.endereco, role: 'aluno',
        status: 'aguardando_validacao', cursoMatriculado: selectedCourse.id, academicId,
        createdAt: serverTimestamp(), progress: 0
      });

      alert("Matrícula realizada com sucesso! Agora realize o login.");
      setViewMode('login');
      setIsAdminMode(false);
      setLoading(false);
    } catch (err: any) {
      setError('Erro ao processar matrícula.');
      setLoading(false);
    }
  };

  if (viewMode === 'enroll_form') {
    return (
      <div className="min-h-screen bg-slate-50 text-slate-900 flex flex-col animate-in fade-in duration-500 overflow-x-hidden">
        <header className="h-20 bg-white border-b border-slate-200 px-8 flex items-center justify-between sticky top-0 z-50">
           <button onClick={() => setViewMode('landing')} className="flex items-center gap-2 text-[10px] font-black uppercase text-slate-400 hover:text-indigo-600 transition-all italic">
              <ChevronLeft size={16}/> Voltar para Vitrine
           </button>
           <div className="flex items-center gap-3">
              <div className="bg-indigo-600 p-2 rounded-xl text-white shadow-lg shadow-indigo-100">
                 <GraduationCap size={20} />
              </div>
              <span className="font-black uppercase italic tracking-tighter text-lg">Matrícula Acadêmica</span>
           </div>
           <div className="px-4 py-1.5 bg-indigo-50 text-indigo-600 rounded-full text-[9px] font-black uppercase italic border border-indigo-100">
              Curso: {selectedCourse?.nome}
           </div>
        </header>

        <main className="max-w-5xl mx-auto w-full p-8 lg:p-16 space-y-16">
           <div className="space-y-4">
              <h1 className="text-5xl font-black uppercase italic tracking-tighter leading-none text-slate-900">Formulário de <br/> <span className="text-indigo-600">Ingresso EAD</span></h1>
              <p className="text-slate-400 text-sm font-medium italic">Preencha seus dados reais para emissão de documentos acadêmicos.</p>
           </div>

           <form onSubmit={handleFinalizeEnroll} className="space-y-20">
              <div className="grid grid-cols-1 lg:grid-cols-4 gap-12 items-start">
                 <div className="lg:col-span-1 space-y-6 flex flex-col items-center">
                    <div onClick={() => fileInputRef.current?.click()} className="w-48 h-48 rounded-[3rem] bg-white border-4 border-dashed border-slate-200 flex items-center justify-center overflow-hidden cursor-pointer hover:border-indigo-400 hover:bg-indigo-50/30 transition-all relative group shadow-xl">
                       {enrollForm.fotoUrl ? (
                         <img src={enrollForm.fotoUrl} className="w-full h-full object-cover" alt="Perfil" />
                       ) : (
                         <div className="text-center opacity-20 group-hover:opacity-100 group-hover:text-indigo-600 transition-all">
                            <Camera size={48} className="mx-auto mb-2" />
