                         </div>
                       )}
                       <div className="absolute inset-0 bg-indigo-600/20 opacity-0 group-hover:opacity-100 flex items-center justify-center transition-all">
                          <Upload size={24} className="text-white" />
                       </div>
                    </div>
                    <input type="file" ref={fileInputRef} className="hidden" accept="image/*" onChange={handlePhotoUpload} />
                 </div>

                 <div className="lg:col-span-3 space-y-10">
                    <div className="grid grid-cols-1 md:grid-cols-2 gap-8">
                       <div className="space-y-2">
                          <label className="text-[10px] font-black text-slate-400 uppercase ml-4 italic flex items-center gap-2"><User size={12}/> Nome Completo</label>
                          <input required value={enrollForm.nome} onChange={e => setEnrollForm({...enrollForm, nome: e.target.value})} className="w-full px-8 py-5 bg-white border border-slate-200 rounded-3xl font-bold shadow-sm focus:ring-2 focus:ring-indigo-600 outline-none" placeholder="Ex: Luiz Otávio Silva..." />
                       </div>
                       <div className="space-y-2">
                          <label className="text-[10px] font-black text-slate-400 uppercase ml-4 italic flex items-center gap-2"><Mail size={12}/> E-mail de Login</label>
                          <input type="email" required value={enrollForm.email} onChange={e => setEnrollForm({...enrollForm, email: e.target.value})} className="w-full px-8 py-5 bg-white border border-slate-200 rounded-3xl font-bold shadow-sm focus:ring-2 focus:ring-indigo-600 outline-none" placeholder="seuemail@provedor.com" />
                       </div>
