export default LoginView;

import React, { useState, useEffect, useRef } from 'react';
import { signInWithEmailAndPassword, createUserWithEmailAndPassword, signOut } from "https://www.gstatic.com/firebasejs/10.7.1/firebase-auth.js";
import { collection, query, where, onSnapshot, doc, setDoc, getDoc, serverTimestamp } from "https://www.gstatic.com/firebasejs/10.7.1/firebase-firestore.js";
import { auth, db } from '../firebase';
import { Lock, Mail, AlertCircle, GraduationCap, ShieldCheck, ArrowRight, BookOpen, Star, Users, CheckCircle, Clock, PlayCircle, Bell, ChevronRight, Target, Award, Camera, User, MapPin, Calendar, Smartphone, FileText, ChevronLeft, Upload, ShieldAlert, Fingerprint, Key } from 'lucide-react';

type ViewMode = 'landing' | 'login' | 'enroll_form';

const LoginView: React.FC = () => {
  const [viewMode, setViewMode] = useState<ViewMode>('landing');
  const [email, setEmail] = useState('');
  const [password, setPassword] = useState('');
  const [error, setError] = useState('');
  const [loading, setLoading] = useState(false);
  const [isAdminMode, setIsAdminMode] = useState(false);

  const [courses, setCourses] = useState<any[]>([]);
  const [selectedCourse, setSelectedCourse] = useState<any>(null);

  const [enrollForm, setEnrollForm] = useState({
    nome: '', email: '', senha: '', cpf: '', nascimento: '', telefone: '', fotoUrl: '',
    endereco: { cep: '', rua: '', numero: '', bairro: '', cidade: '', uf: '' }
  });

  const coursesRef = useRef<HTMLDivElement>(null);
  const fileInputRef = useRef<HTMLInputElement>(null);

  useEffect(() => {
    const unsub = onSnapshot(query(collection(db, 'cursos'), where('status', '==', 'ativo')), (snap) => {
      setCourses(snap.docs.map(d => ({ id: d.id, ...d.data() })));
    });
    return () => unsub();
  }, []);

  const handleLogin = async (e: React.FormEvent) => {
    e.preventDefault();
    setLoading(true);
    setError('');
    try {
      const userCredential = await signInWithEmailAndPassword(auth, email.trim().toLowerCase(), password);
      const uid = userCredential.user.uid;

      const userDoc = await getDoc(doc(db, 'users', uid));
      if (userDoc.exists()) {
        const userData = userDoc.data();
        const role = userData.role;

        // REGRA DE OURO: Diretores (Root) têm acesso total a qualquer portal
        if (role === 'diretor') {
          setLoading(false);
          return; // Deixa o App.tsx decidir o componente baseado no role
        }

        // Restrição para Alunos: Não podem entrar no Portal do Gestor
        if (isAdminMode && role === 'aluno') {
          await signOut(auth);
          setError('Acesso negado. Alunos não possuem autorização para o Portal Administrativo.');
          setLoading(false);
          return;
        }

        // Restrição para Professores/Staff: Devem usar o Portal do Gestor
        if (!isAdminMode && role !== 'aluno') {
          // Embora o Root possa entrar aqui, um professor comum deve ir para o admin
          // Se for professor mas está no login de aluno:
          await signOut(auth);
          setError('Credenciais administrativas detectadas. Utilize o Acesso Restrito à Gestão.');
          setLoading(false);
          return;
        }
      }
    } catch (err: any) {
      setError('Credenciais inválidas ou conta não localizada.');
      setLoading(false);
    }
  };

  const handlePhotoUpload = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (file) {
      const reader = new FileReader();
      reader.onloadend = () => setEnrollForm({ ...enrollForm, fotoUrl: reader.result as string });
      reader.readAsDataURL(file);
    }
  };

  const handleFinalizeEnroll = async (e: React.FormEvent) => {
    e.preventDefault();
    setLoading(true);
    setError('');
    try {
      const userCredential = await createUserWithEmailAndPassword(auth, enrollForm.email.trim(), enrollForm.senha);
      const uid = userCredential.user.uid;
      const academicId = `ALU-${new Date().getFullYear()}-${Math.random().toString(36).substring(2, 7).toUpperCase()}`;

      await setDoc(doc(db, 'users', uid), {
        uid, displayName: enrollForm.nome, nome: enrollForm.nome, email: enrollForm.email.toLowerCase(),
        cpf: enrollForm.cpf, nascimento: enrollForm.nascimento, telefone: enrollForm.telefone,
        photoURL: enrollForm.fotoUrl, endereco: enrollForm.endereco, role: 'aluno',
        status: 'aguardando_validacao', cursoMatriculado: selectedCourse.id, academicId,
        createdAt: serverTimestamp(), progress: 0
      });

      alert("Matrícula realizada com sucesso! Realize o login agora.");
      setViewMode('login');
      setIsAdminMode(false);
      setLoading(false);
    } catch (err: any) {
      setError('Erro ao processar matrícula.');
      setLoading(false);
    }
  };

  if (viewMode === 'enroll_form') {
    return (
      <div className="min-h-screen bg-white text-slate-900 flex flex-col animate-in fade-in duration-500 overflow-x-hidden font-sans">
        <header className="h-20 bg-slate-900 text-white px-8 flex items-center justify-between sticky top-0 z-50 shadow-2xl">
           <button onClick={() => setViewMode('landing')} className="flex items-center gap-2 text-[10px] font-black uppercase text-slate-400 hover:text-indigo-400 transition-all italic">
              <ChevronLeft size={16}/> Cancelar Inscrição
           </button>
           <div className="flex items-center gap-3">
              <div className="bg-indigo-600 p-2 rounded-xl text-white">
                 <GraduationCap size={20} />
              </div>
              <span className="font-black uppercase italic tracking-tighter text-lg">Nova Matrícula Acadêmica</span>
           </div>
           <div className="px-4 py-1.5 bg-indigo-600 text-white rounded-full text-[9px] font-black uppercase italic border border-indigo-500 shadow-lg">
              Disciplina: {selectedCourse?.nome}
           </div>
        </header>

        <main className="max-w-6xl mx-auto w-full p-8 lg:p-20 space-y-24 pb-40">
           <div className="space-y-4 text-center">
              <h1 className="text-5xl lg:text-7xl font-black uppercase italic tracking-tighter leading-none text-slate-900">Finalize sua <br/> <span className="text-indigo-600">Matrícula EAD</span></h1>
              <p className="text-slate-400 text-sm font-medium italic">Organize seus dados para emissão do contrato e credenciais de acesso.</p>
           </div>

           <form onSubmit={handleFinalizeEnroll} className="space-y-32">
              {/* BLOCO 1: DADOS PESSOAIS */}
              <section className="space-y-12">
                 <div className="flex items-center gap-4 border-b border-slate-100 pb-6">
                    <div className="w-12 h-12 bg-indigo-50 rounded-2xl flex items-center justify-center text-indigo-600 shadow-inner"><User size={24}/></div>
                    <div>
                       <h3 className="text-2xl font-black uppercase italic tracking-tighter">Identificação Pessoal</h3>
                       <p className="text-[10px] font-bold text-slate-400 uppercase tracking-widest">Documentação básica e biometria</p>
                    </div>
                 </div>

