      const userDoc = await getDoc(doc(db, 'users', uid));
      if (userDoc.exists()) {
        const userData = userDoc.data();
        const role = userData.role;
        if (role === 'diretor') { setLoading(false); return; }
        if (isAdminMode && role === 'aluno') { await signOut(auth); setError('Acesso negado ao Portal Administrativo.'); setLoading(false); return; }
        if (!isAdminMode && role !== 'aluno') { await signOut(auth); setError('Utilize o Acesso Restrito à Gestão.'); setLoading(false); return; }
      }
    } catch (err: any) {
      setError('Credenciais inválidas.');
      setLoading(false);
    }
  };

