                    <div className="space-y-2"><label className="text-[10px] font-black text-slate-400 uppercase ml-4 italic">E-mail</label><div className="relative"><Mail className="absolute left-6 top-1/2 -translate-y-1/2 text-slate-300" size={18} /><input type="email" required value={email} onChange={e => setEmail(e.target.value)} className="w-full pl-16 pr-6 py-5 bg-slate-50 border-none rounded-[1.5rem] outline-none font-bold text-sm shadow-inner" /></div></div>
                    <div className="space-y-2"><label className="text-[10px] font-black text-slate-400 uppercase ml-4 italic">Senha</label><div className="relative"><Lock className="absolute left-6 top-1/2 -translate-y-1/2 text-slate-300" size={18} /><input type="password" required value={password} onChange={e => setPassword(e.target.value)} className="w-full pl-16 pr-6 py-5 bg-slate-50 border-none rounded-[1.5rem] outline-none font-bold text-sm shadow-inner" /></div></div>
                  </div>
                  <button type="submit" disabled={loading} className={`w-full py-6 rounded-[2rem] text-[11px] font-black uppercase tracking-[0.3em] shadow-2xl transition-all active:scale-[0.98] mt-4 flex items-center justify-center gap-3 text-white ${isAdminMode ? 'bg-slate-900 hover:bg-slate-800' : 'bg-indigo-600 hover:bg-indigo-700'}`}>{loading ? 'Validando...' : 'Entrar no Sistema'}</button>
                </form>
                <div className="mt-12 pt-8 border-t border-slate-50 flex flex-col items-center gap-6">
                  {!isAdminMode && <button onClick={() => coursesRef.current?.scrollIntoView({ behavior: 'smooth' })} className="text-[9px] font-black uppercase text-indigo-600 hover:text-indigo-700 transition-all italic tracking-widest flex items-center gap-2">Iniciar Matrícula <ArrowRight size={12}/></button>}
                  <button onClick={() => { setIsAdminMode(!isAdminMode); setError(''); }} className="text-[10px] font-black uppercase text-slate-300 hover:text-slate-600 transition-all tracking-widest italic border-b border-transparent hover:border-slate-200">{isAdminMode ? 'Alternar para Aluno' : 'Acesso Restrito à Gestão'}</button>
                </div>
             </div>
          </div>
        </div>
      </div>
    </div>
  );
};

export default LoginView;

import React, { useState, useEffect, useRef } from 'react';
import { signInWithEmailAndPassword, createUserWithEmailAndPassword, signOut } from "https://www.gstatic.com/firebasejs/10.7.1/firebase-auth.js";
import { collection, query, where, onSnapshot, doc, setDoc, getDoc, serverTimestamp } from "https://www.gstatic.com/firebasejs/10.7.1/firebase-firestore.js";
import { auth, db } from '../firebase';
import { Lock, Mail, AlertCircle, GraduationCap, ShieldCheck, ArrowRight, BookOpen, Star, Users, CheckCircle, Clock, PlayCircle, Bell, ChevronRight, Target, Award, Camera, User, MapPin, Calendar, Smartphone, FileText, ChevronLeft, Upload, ShieldAlert, Fingerprint, Key, Quote, BarChart3 } from 'lucide-react';

type ViewMode = 'landing' | 'login' | 'enroll_form';

const LoginView: React.FC = () => {
  const [viewMode, setViewMode] = useState<ViewMode>('landing');
  const [email, setEmail] = useState('');
  const [password, setPassword] = useState('');
  const [error, setError] = useState('');
  const [loading, setLoading] = useState(false);
  const [isAdminMode, setIsAdminMode] = useState(false);

  const [courses, setCourses] = useState<any[]>([]);
  const [selectedCourse, setSelectedCourse] = useState<any>(null);

  const [enrollForm, setEnrollForm] = useState({
    nome: '', email: '', senha: '', cpf: '', nascimento: '', telefone: '', fotoUrl: '',
    endereco: { cep: '', rua: '', numero: '', bairro: '', cidade: '', uf: '' }
  });

  const coursesRef = useRef<HTMLDivElement>(null);
  const fileInputRef = useRef<HTMLInputElement>(null);

  useEffect(() => {
    const unsub = onSnapshot(query(collection(db, 'cursos'), where('status', '==', 'ativo')), (snap) => {
      setCourses(snap.docs.map(d => ({ id: d.id, ...d.data() })));
    });
    return () => unsub();
  }, []);

  // Busca Automática de CEP
  useEffect(() => {
    const cep = enrollForm.endereco.cep.replace(/\D/g, '');
    if (cep.length === 8) {
      fetch(`https://viacep.com.br/ws/${cep}/json/`)
        .then(res => res.json())
        .then(data => {
          if (!data.erro) {
            setEnrollForm(prev => ({
              ...prev,
              endereco: {
                ...prev.endereco,
                rua: data.logradouro,
                bairro: data.bairro,
                cidade: data.localidade,
                uf: data.uf
              }
            }));
          }
        });
    }
  }, [enrollForm.endereco.cep]);

  const handleLogin = async (e: React.FormEvent) => {
    e.preventDefault();
    setLoading(true);
    setError('');
    try {
      const userCredential = await signInWithEmailAndPassword(auth, email.trim().toLowerCase(), password);
      const uid = userCredential.user.uid;
      const userDoc = await getDoc(doc(db, 'users', uid));
      if (userDoc.exists()) {
        const userData = userDoc.data();
        const role = userData.role;

        // Regra de Privilégio: Diretores (Root) acessam qualquer portal
        if (role === 'diretor') {
          setLoading(false);
          return;
        }

        // Bloqueio de Segurança para Alunos no Admin
        if (isAdminMode && role === 'aluno') {
          await signOut(auth);
          setError('Acesso restrito. Sua conta não possui privilégios administrativos.');
          setLoading(false);
          return;
        }

        // Orientação para Docentes no portal de alunos
        if (!isAdminMode && role !== 'aluno') {
          await signOut(auth);
          setError('Identidade docente localizada. Utilize o Acesso Restrito à Gestão.');
          setLoading(false);
          return;
        }
      }
    } catch (err: any) {
      setError('Credenciais inválidas ou conta não localizada.');
      setLoading(false);
    }
  };

  const handlePhotoUpload = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (file) {
      const reader = new FileReader();
      reader.onloadend = () => setEnrollForm({ ...enrollForm, fotoUrl: reader.result as string });
      reader.readAsDataURL(file);
    }
  };

  const handleFinalizeEnroll = async (e: React.FormEvent) => {
    e.preventDefault();
    setLoading(true);
    try {
      const userCredential = await createUserWithEmailAndPassword(auth, enrollForm.email.trim(), enrollForm.senha);
      const uid = userCredential.user.uid;
      const academicId = `ALU-${new Date().getFullYear()}-${Math.random().toString(36).substring(2, 7).toUpperCase()}`;

      // FIX: Padronização de campos para exibição no painel administrativo
      await setDoc(doc(db, 'users', uid), {
        uid, 
        displayName: enrollForm.nome, // Essencial para listagem
        nome: enrollForm.nome, 
        email: enrollForm.email.toLowerCase(),
        cpf: enrollForm.cpf, 
        nascimento: enrollForm.nascimento, 
        telefone: enrollForm.telefone,
        photoURL: enrollForm.fotoUrl, 
        endereco: enrollForm.endereco, 
        role: 'aluno', // Auditoria de role
        status: 'aguardando_validacao', 
        cursoInicial: selectedCourse.id, // Campo usado no filtro do StudentsView
        academicId,
        createdAt: serverTimestamp(), 
        progress: 0
      });

      alert("Matrícula realizada com sucesso! Aguarde a validação administrativa.");
      setViewMode('login');
      setIsAdminMode(false);
      setLoading(false);
