                    <div className="p-10 flex flex-col flex-1 space-y-6">
                      <h3 className="text-2xl font-black text-slate-900 uppercase italic tracking-tighter leading-none">{c.nome}</h3>
                      <button onClick={() => { setSelectedCourse(c); setViewMode('enroll_form'); }} className="w-full py-5 bg-slate-900 text-white rounded-[1.5rem] text-[10px] font-black uppercase tracking-widest italic hover:bg-indigo-600 transition-all flex items-center justify-center gap-3 shadow-xl">Matricular-se Agora <ChevronRight size={16}/></button>
