                <div className="bg-slate-900 p-2 rounded-xl text-white"><BookOpen size={20} /></div>
                <span className="font-black uppercase italic tracking-tighter text-lg">EB-EAD MASTER</span>
              </div>
              <button onClick={() => { setViewMode('login'); setIsAdminMode(true); }} className="text-[9px] font-black uppercase text-slate-300 hover:text-indigo-600 transition-all italic tracking-widest">Acesso Restrito à Gestão</button>
           </div>
        </footer>
      </div>
    );
  }

  return (
    <div className="min-h-screen relative flex items-center justify-center p-6 overflow-hidden font-sans">
      <div className="absolute inset-0 z-0 bg-cover bg-center transition-transform duration-[30s] scale-110 animate-pulse-slow" style={{ backgroundImage: 'url(https://images.unsplash.com/photo-1524995997946-a1c2e315a42f?auto=format&fit=crop&q=80)' }} />
      <div className="absolute inset-0 z-[1] bg-slate-950/90 backdrop-blur-[6px]" />
      <div className="relative z-10 w-full max-w-5xl animate-in fade-in slide-in-from-bottom-8 duration-700">
        <div className="bg-white rounded-[4rem] shadow-2xl border border-white/10 overflow-hidden flex flex-col lg:flex-row min-h-[550px]">
          <div className={`lg:w-2/5 p-12 lg:p-16 flex flex-col justify-between transition-colors duration-500 ${isAdminMode ? 'bg-slate-900 text-white' : 'bg-indigo-600 text-white'}`}>
             <div>
                <button onClick={() => setViewMode('landing')} className="mb-12 text-[10px] font-black uppercase opacity-60 hover:opacity-100 flex items-center gap-2 transition-all"><ArrowRight className="rotate-180" size={14}/> Início</button>
                <div className="w-20 h-20 bg-white/10 rounded-[2.5rem] flex items-center justify-center mb-8 shadow-2xl">{isAdminMode ? <ShieldCheck size={40}/> : <GraduationCap size={40}/>}</div>
                <h1 className="text-4xl font-black uppercase italic tracking-tighter leading-none mb-4">{isAdminMode ? 'Portal do Gestor' : 'Acesso do Aluno'}</h1>
                <p className="text-[10px] font-black uppercase tracking-[0.3em] opacity-60 italic leading-relaxed">{isAdminMode ? 'Acesso restrito à diretoria e corpo docente.' : 'Sua sala de aula master e histórico acadêmico.'}</p>
             </div>
             <div className="pt-12"><div className="flex items-center gap-4 p-5 bg-white/5 rounded-3xl border border-white/10"><Fingerprint size={24} className="opacity-40" /><div><p className="text-[8px] font-black uppercase tracking-widest opacity-40">Segurança Master</p><p className="text-[10px] font-bold italic">Conexão monitorada em tempo real.</p></div></div></div>
          </div>
          <div className="flex-1 p-12 lg:p-20 bg-white flex flex-col justify-center">
             <div className="max-w-md mx-auto w-full">
                <h2 className="text-xl font-black text-slate-900 uppercase italic tracking-tighter mb-2">Credenciais Acadêmicas</h2>
                <p className="text-[10px] font-bold text-slate-400 uppercase tracking-widest mb-10 italic border-b pb-4">Informe seus dados para autenticação biométrica</p>
                {error && <div className="mb-8 p-5 bg-rose-50 text-rose-600 rounded-2xl text-[11px] font-black uppercase flex items-center gap-3 italic animate-in shake duration-500"><AlertCircle size={20} /> {error}</div>}
                <form onSubmit={handleLogin} className="space-y-6">
                  <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
                    <div className="space-y-2"><label className="text-[10px] font-black text-slate-400 uppercase ml-4 italic">E-mail</label><div className="relative"><Mail className="absolute left-6 top-1/2 -translate-y-1/2 text-slate-300" size={18} /><input type="email" required value={email} onChange={e => setEmail(e.target.value)} className="w-full pl-16 pr-6 py-5 bg-slate-50 border-none rounded-[1.5rem] outline-none font-bold text-sm shadow-inner" /></div></div>
                    <div className="space-y-2"><label className="text-[10px] font-black text-slate-400 uppercase ml-4 italic">Senha</label><div className="relative"><Lock className="absolute left-6 top-1/2 -translate-y-1/2 text-slate-300" size={18} /><input type="password" required value={password} onChange={e => setPassword(e.target.value)} className="w-full pl-16 pr-6 py-5 bg-slate-50 border-none rounded-[1.5rem] outline-none font-bold text-sm shadow-inner" /></div></div>
                  </div>
                  <button type="submit" disabled={loading} className={`w-full py-7 rounded-[2.5rem] text-[11px] font-black uppercase tracking-[0.3em] shadow-2xl transition-all active:scale-[0.98] mt-4 flex items-center justify-center gap-3 text-white ${isAdminMode ? 'bg-slate-900 hover:bg-slate-800' : 'bg-indigo-600 hover:bg-indigo-700 shadow-indigo-100'}`}>{loading ? 'Validando...' : 'Autenticar no Sistema'}</button>
                </form>
                <div className="mt-16 pt-8 border-t border-slate-50 flex flex-col items-center gap-6">
                  {!isAdminMode && <button onClick={() => coursesRef.current?.scrollIntoView({ behavior: 'smooth' })} className="text-[9px] font-black uppercase text-indigo-600 hover:text-indigo-700 transition-all italic tracking-widest flex items-center gap-2">Não é aluno? Inicie sua matrícula <ArrowRight size={12}/></button>}
                  <button onClick={() => { setIsAdminMode(!isAdminMode); setError(''); }} className="text-[10px] font-black uppercase text-slate-300 hover:text-slate-600 transition-all tracking-widest italic border-b border-transparent hover:border-slate-200">{isAdminMode ? 'Portal Sala de Aula (Aluno)' : 'Acesso Restrito à Gestão'}</button>
                </div>
             </div>
          </div>
        </div>
      </div>
      <style>{`
        @keyframes pulse-slow { 0%, 100% { transform: scale(1.1); } 50% { transform: scale(1.05); } }
        .animate-pulse-slow { animation: pulse-slow 20s ease-in-out infinite; }
        @keyframes shake { 0%, 100% { transform: translateX(0); } 25% { transform: translateX(-5px); } 75% { transform: translateX(5px); } }
        .shake { animation: shake 0.4s ease-in-out; }
      `}</style>
    </div>
  );
};

export default LoginView;

import React, { useState, useEffect, useRef } from 'react';
import { signInWithEmailAndPassword, createUserWithEmailAndPassword, signOut } from "https://www.gstatic.com/firebasejs/10.7.1/firebase-auth.js";
import { collection, query, where, onSnapshot, doc, setDoc, getDoc, serverTimestamp } from "https://www.gstatic.com/firebasejs/10.7.1/firebase-firestore.js";
import { auth, db } from '../firebase';
// Added missing Database icon import
import { Lock, Mail, AlertCircle, GraduationCap, ShieldCheck, ArrowRight, BookOpen, Star, Users, CheckCircle, Clock, PlayCircle, Bell, ChevronRight, Target, Award, Camera, User, MapPin, Calendar, Smartphone, FileText, ChevronLeft, Upload, ShieldAlert, Fingerprint, Key, Quote, BarChart3, Database } from 'lucide-react';

type ViewMode = 'landing' | 'login' | 'enroll_form';

const LoginView: React.FC = () => {
  const [viewMode, setViewMode] = useState<ViewMode>('landing');
  const [email, setEmail] = useState('');
  const [password, setPassword] = useState('');
  const [error, setError] = useState('');
  const [loading, setLoading] = useState(false);
  const [isAdminMode, setIsAdminMode] = useState(false);

  const [courses, setCourses] = useState<any[]>([]);
  const [selectedCourse, setSelectedCourse] = useState<any>(null);

  const [enrollForm, setEnrollForm] = useState({
    nome: '', email: '', senha: '', cpf: '', nascimento: '', telefone: '', fotoUrl: '',
    endereco: { cep: '', rua: '', numero: '', bairro: '', cidade: '', uf: '' }
  });

  const coursesRef = useRef<HTMLDivElement>(null);
  const fileInputRef = useRef<HTMLInputElement>(null);

  useEffect(() => {
    const unsub = onSnapshot(query(collection(db, 'cursos'), where('status', '==', 'ativo')), (snap) => {
      setCourses(snap.docs.map(d => ({ id: d.id, ...d.data() })));
    });
    return () => unsub();
  }, []);

  // Busca Automática de CEP
  useEffect(() => {
    const cep = enrollForm.endereco.cep.replace(/\D/g, '');
    if (cep.length === 8) {
      fetch(`https://viacep.com.br/ws/${cep}/json/`)
        .then(res => res.json())
        .then(data => {
          if (!data.erro) {
            setEnrollForm(prev => ({
              ...prev,
              endereco: {
                ...prev.endereco,
                rua: data.logradouro,
                bairro: data.bairro,
                cidade: data.localidade,
                uf: data.uf
              }
            }));
          }
        });
    }
  }, [enrollForm.endereco.cep]);

  const handleLogin = async (e: React.FormEvent) => {
    e.preventDefault();
    setLoading(true);
    setError('');
    try {
      const userCredential = await signInWithEmailAndPassword(auth, email.trim().toLowerCase(), password);
      const uid = userCredential.user.uid;
      const userDoc = await getDoc(doc(db, 'users', uid));
      if (userDoc.exists()) {
        const userData = userDoc.data();
        const role = userData.role;

        // Regra de Privilégio: Diretores (Root) acessam qualquer portal
        if (role === 'diretor') {
          setLoading(false);
          return;
        }

        // Bloqueio de Segurança para Alunos no Admin
        if (isAdminMode && role === 'aluno') {
          await signOut(auth);
          setError('Acesso restrito. Sua conta não possui privilégios administrativos.');
          setLoading(false);
          return;
        }

        // Orientação para Docentes no portal de alunos
        if (!isAdminMode && role !== 'aluno') {
          await signOut(auth);
          setError('Identidade docente localizada. Utilize o Acesso Restrito à Gestão.');
          setLoading(false);
          return;
        }
      }
    } catch (err: any) {
      setError('Credenciais inválidas ou conta não localizada.');
      setLoading(false);
    }
  };

  const handlePhotoUpload = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (file) {
      const reader = new FileReader();
      reader.onloadend = () => setEnrollForm({ ...enrollForm, fotoUrl: reader.result as string });
      reader.readAsDataURL(file);
    }
  };

  const handleFinalizeEnroll = async (e: React.FormEvent) => {
    e.preventDefault();
    setLoading(true);
    try {
      const userCredential = await createUserWithEmailAndPassword(auth, enrollForm.email.trim(), enrollForm.senha);
      const uid = userCredential.user.uid;
      const academicId = `ALU-${new Date().getFullYear()}-${Math.random().toString(36).substring(2, 7).toUpperCase()}`;

      // FIX: Padronização de campos para exibição no painel administrativo
      await setDoc(doc(db, 'users', uid), {
        uid, 
        displayName: enrollForm.nome, // Essencial para listagem
        nome: enrollForm.nome, 
        email: enrollForm.email.toLowerCase(),
        cpf: enrollForm.cpf, 
        nascimento: enrollForm.nascimento, 
        telefone: enrollForm.telefone,
        photoURL: enrollForm.fotoUrl, 
        endereco: enrollForm.endereco, 
        role: 'aluno', // Auditoria de role
        status: 'aguardando_validacao', 
        cursoInicial: selectedCourse.id, // Campo usado no filtro do StudentsView
        academicId,
        createdAt: serverTimestamp(), 
        progress: 0
      });

      alert("Matrícula realizada com sucesso! Aguarde a validação administrativa.");
      setViewMode('login');
      setIsAdminMode(false);
      setLoading(false);
    } catch (err: any) {
      setError('Erro ao processar matrícula.');
      setLoading(false);
    }
  };

  if (viewMode === 'enroll_form') {
    return (
      <div className="min-h-screen bg-white text-slate-900 flex flex-col animate-in fade-in duration-500 overflow-x-hidden font-sans">
        <header className="h-20 bg-slate-900 text-white px-8 flex items-center justify-between sticky top-0 z-50 shadow-2xl">
           <button onClick={() => setViewMode('landing')} className="flex items-center gap-2 text-[10px] font-black uppercase text-slate-400 hover:text-indigo-400 transition-all italic">
              <ChevronLeft size={16}/> Cancelar Inscrição
           </button>
           <div className="flex items-center gap-3">
              <div className="bg-indigo-600 p-2 rounded-xl text-white">
                 <GraduationCap size={20} />
              </div>
              <span className="font-black uppercase italic tracking-tighter text-lg">Inscrição Acadêmica Digital</span>
           </div>
           <div className="px-4 py-1.5 bg-indigo-600 text-white rounded-full text-[9px] font-black uppercase italic border border-indigo-500">
              Curso: {selectedCourse?.nome}
           </div>
        </header>

        <main className="max-w-5xl mx-auto w-full p-8 lg:p-20 space-y-24 pb-40">
           <div className="space-y-4 text-center">
              <h1 className="text-4xl lg:text-5xl font-black uppercase italic tracking-tighter leading-none text-slate-900">Formulário de <span className="text-indigo-600">Ingresso Master</span></h1>
              <p className="text-slate-400 text-sm font-medium italic">Sua jornada começa com a organização segura dos seus dados.</p>
           </div>

           <form onSubmit={handleFinalizeEnroll} className="space-y-24">
              {/* BLOCO 1: IDENTIFICAÇÃO PESSOAL */}
              <section className="space-y-10">
                 <div className="flex items-center gap-4 border-b border-slate-100 pb-6">
                    <div className="w-12 h-12 bg-indigo-50 rounded-2xl flex items-center justify-center text-indigo-600 shadow-inner"><User size={24}/></div>
                    <h3 className="text-2xl font-black uppercase italic tracking-tighter">1. Identificação Pessoal</h3>
                 </div>

                 <div className="grid grid-cols-1 lg:grid-cols-4 gap-12 items-center">
                    <div className="lg:col-span-1 flex flex-col items-center gap-4">
                       <div onClick={() => fileInputRef.current?.click()} className="w-44 h-44 rounded-[4rem] bg-slate-50 border-4 border-dashed border-slate-200 flex items-center justify-center overflow-hidden cursor-pointer hover:border-indigo-400 transition-all relative group shadow-xl">
                          {enrollForm.fotoUrl ? (
                            <img src={enrollForm.fotoUrl} className="w-full h-full object-cover" alt="Perfil" />
                          ) : (
                            <div className="text-center opacity-30 group-hover:opacity-100 group-hover:text-indigo-600 transition-all">
                               <Camera size={48} className="mx-auto mb-2" />
                               <span className="text-[9px] font-black uppercase block">Foto Perfil</span>
                            </div>
                          )}
                       </div>
                       <input type="file" ref={fileInputRef} className="hidden" accept="image/*" onChange={handlePhotoUpload} />
                    </div>

                    <div className="lg:col-span-3 grid grid-cols-1 md:grid-cols-2 gap-8">
                       <div className="space-y-2">
                          <label className="text-[10px] font-black text-slate-400 uppercase ml-4 italic">Nome Completo</label>
                          <input required value={enrollForm.nome} onChange={e => setEnrollForm({...enrollForm, nome: e.target.value})} className="w-full px-8 py-5 bg-slate-50 border-none rounded-3xl font-bold shadow-inner focus:ring-2 focus:ring-indigo-600 outline-none" placeholder="Para emissão de certificados..." />
                       </div>
                       <div className="space-y-2">
                          <label className="text-[10px] font-black text-slate-400 uppercase ml-4 italic">CPF</label>
                          <input required value={enrollForm.cpf} onChange={e => setEnrollForm({...enrollForm, cpf: e.target.value})} className="w-full px-8 py-5 bg-slate-50 border-none rounded-3xl font-bold shadow-inner focus:ring-2 focus:ring-indigo-600 outline-none" placeholder="000.000.000-00" />
                       </div>
                       <div className="space-y-2">
                          <label className="text-[10px] font-black text-slate-400 uppercase ml-4 italic">Data de Nascimento</label>
                          <input type="date" required value={enrollForm.nascimento} onChange={e => setEnrollForm({...enrollForm, nascimento: e.target.value})} className="w-full px-8 py-5 bg-slate-50 border-none rounded-3xl font-bold shadow-inner focus:ring-2 focus:ring-indigo-600 outline-none" />
                       </div>
                       <div className="space-y-2">
                          <label className="text-[10px] font-black text-slate-400 uppercase ml-4 italic">WhatsApp</label>
                          <input required value={enrollForm.telefone} onChange={e => setEnrollForm({...enrollForm, telefone: e.target.value})} className="w-full px-8 py-5 bg-slate-50 border-none rounded-3xl font-bold shadow-inner focus:ring-2 focus:ring-indigo-600 outline-none" placeholder="(00) 00000-0000" />
                       </div>
                    </div>
                 </div>
              </section>

              {/* BLOCO 2: LOCALIZAÇÃO RESIDENCIAL */}
              <section className="space-y-10">
                 <div className="flex items-center gap-4 border-b border-slate-100 pb-6">
                    <div className="w-12 h-12 bg-indigo-50 rounded-2xl flex items-center justify-center text-indigo-600 shadow-inner"><MapPin size={24}/></div>
                    <div>
                       <h3 className="text-2xl font-black uppercase italic tracking-tighter">2. Localização Residencial</h3>
                       <p className="text-[9px] font-bold text-slate-400 uppercase tracking-widest">Busca automática por CEP</p>
                    </div>
                 </div>

                 <div className="grid grid-cols-1 md:grid-cols-6 gap-8">
                    <div className="md:col-span-2 space-y-2">
                       <label className="text-[10px] font-black text-slate-400 uppercase ml-4">CEP</label>
                       <input required value={enrollForm.endereco.cep} onChange={e => setEnrollForm({...enrollForm, endereco: {...enrollForm.endereco, cep: e.target.value}})} className="w-full px-8 py-5 bg-slate-50 border-none rounded-3xl font-bold shadow-inner" placeholder="00000000" />
                    </div>
                    <div className="md:col-span-3 space-y-2">
                       <label className="text-[10px] font-black text-slate-400 uppercase ml-4">Rua / Logradouro</label>
                       <input required value={enrollForm.endereco.rua} onChange={e => setEnrollForm({...enrollForm, endereco: {...enrollForm.endereco, rua: e.target.value}})} className="w-full px-8 py-5 bg-slate-50 border-none rounded-3xl font-bold shadow-inner" placeholder="Nome da via..." />
                    </div>
                    <div className="md:col-span-1 space-y-2">
                       <label className="text-[10px] font-black text-slate-400 uppercase text-center block">Nº</label>
                       <input required value={enrollForm.endereco.numero} onChange={e => setEnrollForm({...enrollForm, endereco: {...enrollForm.endereco, numero: e.target.value}})} className="w-full px-8 py-5 bg-slate-50 border-none rounded-3xl font-bold shadow-inner text-center" />
                    </div>
                    <div className="md:col-span-2 space-y-2">
                       <label className="text-[10px] font-black text-slate-400 uppercase ml-4">Bairro</label>
                       <input required value={enrollForm.endereco.bairro} onChange={e => setEnrollForm({...enrollForm, endereco: {...enrollForm.endereco, bairro: e.target.value}})} className="w-full px-8 py-5 bg-slate-50 border-none rounded-3xl font-bold shadow-inner" />
                    </div>
                    <div className="md:col-span-3 space-y-2">
                       <label className="text-[10px] font-black text-slate-400 uppercase ml-4">Cidade</label>
                       <input required value={enrollForm.endereco.cidade} onChange={e => setEnrollForm({...enrollForm, endereco: {...enrollForm.endereco, cidade: e.target.value}})} className="w-full px-8 py-5 bg-slate-50 border-none rounded-3xl font-bold shadow-inner" />
                    </div>
                    <div className="md:col-span-1 space-y-2">
                       <label className="text-[10px] font-black text-slate-400 uppercase text-center block">UF</label>
                       <input required maxLength={2} value={enrollForm.endereco.uf} onChange={e => setEnrollForm({...enrollForm, endereco: {...enrollForm.endereco, uf: e.target.value.toUpperCase()}})} className="w-full px-8 py-5 bg-slate-50 border-none rounded-3xl font-bold shadow-inner text-center uppercase" placeholder="SP" />
                    </div>
                 </div>
              </section>

              {/* BLOCO 3: ACESSO AO SISTEMA */}
              <section className="space-y-10">
                 <div className="flex items-center gap-4 border-b border-slate-100 pb-6">
                    <div className="w-12 h-12 bg-indigo-50 rounded-2xl flex items-center justify-center text-indigo-600 shadow-inner"><Key size={24}/></div>
