import React, { useState, useEffect } from 'react';
import { 
  LayoutDashboard, 
  BookOpen, 
  GraduationCap, 
  MessageSquare, 
  Settings, 
  LogOut,
  Menu,
  X,
  Bell,
  User as UserIcon,
  AlertCircle
} from 'lucide-react';
import { MainView, User } from '../types';
import { auth, db } from '../firebase';
import { collection, query, where, onSnapshot } from "https://www.gstatic.com/firebasejs/10.7.1/firebase-firestore.js";

interface NavbarProps {
  user: User;
  activeView: MainView;
  setActiveView: (view: MainView) => void;
  isMobileMenuOpen: boolean;
  setIsMobileMenuOpen: (open: boolean) => void;
}

const Navbar: React.FC<NavbarProps> = ({ user, activeView, setActiveView, isMobileMenuOpen, setIsMobileMenuOpen }) => {
  const [pendingCount, setPendingCount] = useState(0);
  const [showNotifications, setShowNotifications] = useState(false);

  useEffect(() => {
    // Monitora novos alunos aguardando validação para alertar o administrativo
    const q = query(collection(db, 'users'), where('status', '==', 'aguardando_validacao'));
    const unsub = onSnapshot(q, (snap) => {
      setPendingCount(snap.size);
    });
    return () => unsub();
  }, []);

  const navItems = [
    { id: 'dashboard', label: 'Dashboard', icon: <LayoutDashboard size={18} /> },
    { id: 'professor', label: 'Área do Professor', icon: <BookOpen size={18} /> },
    { id: 'alunos', label: 'Alunos', icon: <GraduationCap size={18} /> },
    { id: 'secretaria', label: 'Secretaria', icon: <MessageSquare size={18} /> },
    { id: 'configuracoes', label: 'Configurações', icon: <Settings size={18} /> },
  ];

  return (
    <nav className="sticky top-0 z-[100] bg-slate-900 text-slate-300 h-16 shadow-2xl border-b border-slate-800">
      <div className="max-w-[1440px] mx-auto px-4 lg:px-6 h-full flex items-center justify-between">
        <div className="flex items-center gap-3">
          <div className="bg-indigo-600 text-white p-1.5 rounded-lg shadow-lg shadow-indigo-600/20">
            <BookOpen size={20} />
          </div>
          <div className="flex flex-col">
            <span className="font-black text-white text-sm tracking-tight leading-none uppercase italic">EB-EAD</span>
            <span className="text-[9px] font-bold text-indigo-400 tracking-[0.2em] uppercase leading-none mt-0.5">Gestão Master</span>
          </div>
        </div>

        <div className="hidden md:flex items-center gap-0.5">
          {navItems.map((item) => (
            <button
              key={item.id}
              onClick={() => setActiveView(item.id as MainView)}
              className={`flex items-center gap-2.5 px-4 py-2 rounded-lg text-xs font-bold transition-all ${
                activeView === item.id 
                  ? 'bg-indigo-600 text-white shadow-lg shadow-indigo-600/20' 
                  : 'hover:bg-slate-800 hover:text-slate-100'
              }`}
            >
              <span className={activeView === item.id ? 'text-white' : 'text-slate-500'}>{item.icon}</span>
              {item.label}
            </button>
          ))}
        </div>

        <div className="flex items-center gap-4">
          {/* Central de Alertas Operacionais */}
          <div className="relative">
            <button 
              onClick={() => { setShowNotifications(!showNotifications); if(pendingCount > 0) setActiveView('secretaria'); }}
              className={`p-2.5 rounded-xl transition-all relative ${pendingCount > 0 ? 'bg-indigo-600/10 text-indigo-400 animate-pulse' : 'text-slate-500 hover:bg-slate-800'}`}
            >
              <Bell size={20} />
              {pendingCount > 0 && (
                <span className="absolute -top-1 -right-1 w-5 h-5 bg-rose-600 text-white text-[10px] font-black flex items-center justify-center rounded-full border-2 border-slate-900 shadow-lg">
                  {pendingCount}
                </span>
              )}
            </button>

            {showNotifications && pendingCount > 0 && (
              <div className="absolute top-14 right-0 w-72 bg-white rounded-2xl shadow-2xl border border-slate-200 p-5 animate-in slide-in-from-top-2 text-slate-900">
                <h4 className="text-[10px] font-black uppercase text-indigo-600 mb-3 italic flex items-center gap-2">
                  <AlertCircle size={14}/> Novas Matrículas ({pendingCount})
                </h4>
                <p className="text-[11px] font-medium text-slate-500 leading-relaxed italic">
                  Existem novos alunos aguardando validação documental na Secretaria Master.
                </p>
                <button 
                  onClick={() => { setShowNotifications(false); setActiveView('secretaria'); }}
                  className="w-full mt-4 py-2 bg-slate-900 text-white rounded-lg text-[9px] font-black uppercase italic hover:bg-indigo-600 transition-all"
                >
                  Ir para Validação
                </button>
              </div>
            )}
          </div>

          <div className="hidden sm:flex flex-col items-end pr-4 border-r border-slate-800">
            <span className="text-xs font-bold text-white leading-none uppercase italic">{user.displayName}</span>
            <span className="text-[10px] font-bold uppercase text-indigo-500 tracking-wider mt-0.5">{user.role}</span>
          </div>

          <button 
            onClick={() => auth.signOut()}
            className="p-2.5 hover:bg-red-500/10 hover:text-red-500 rounded-xl transition-all text-slate-400"
          >
            <LogOut size={18} />
          </button>

          <button 
            className="md:hidden p-2 text-slate-300 hover:text-white"
            onClick={() => setIsMobileMenuOpen(!isMobileMenuOpen)}
          >
            {isMobileMenuOpen ? <X size={24} /> : <Menu size={24} />}
          </button>
        </div>
      </div>

      {isMobileMenuOpen && (
        <div className="absolute top-16 left-0 w-full bg-slate-900 border-t border-slate-800 md:hidden animate-in slide-in-from-top duration-300">
          <div className="flex flex-col p-4 gap-1.5">
            {navItems.map((item) => (
              <button
                key={item.id}
                onClick={() => { setActiveView(item.id as MainView); setIsMobileMenuOpen(false); }}
                className={`flex items-center gap-4 w-full px-5 py-4 rounded-xl text-sm font-bold transition-all ${
                  activeView === item.id ? 'bg-indigo-600 text-white shadow-lg shadow-indigo-600/20' : 'hover:bg-slate-800'
                }`}
              >
                {item.icon}
                {item.label}
              </button>
            ))}
          </div>
        </div>
      )}
    </nav>
  );
};

