import React, { useState, useEffect } from 'react';
import { 
  collection, query, where, onSnapshot, doc, getDoc, 
  updateDoc, serverTimestamp, orderBy 
} from "https://www.gstatic.com/firebasejs/10.7.1/firebase-firestore.js";
import { auth, db } from '../firebase';
import { Course, User, Module, Lesson } from '../types';
import { 
  BookOpen, PlayCircle, Award, FileText, CheckCircle2, 
  Clock, ChevronRight, Star, ArrowLeft, Layout, 
  GraduationCap, Zap, Download, MessageSquare, Menu, X, Settings,
  Bell, User as UserIcon, LogOut, Search, Play, FileBadge, Sliders, 
  HelpCircle, ChevronDown, CheckCircle, Smartphone, Database, Video, ShieldAlert,
  Home, LifeBuoy, ScrollText
} from 'lucide-react';

interface StudentViewProps {
  user: User;
}

type StudentSubView = 'dashboard' | 'classroom' | 'library' | 'certificates' | 'support';

const StudentView: React.FC<StudentViewProps> = ({ user }) => {
  const [activeSubView, setActiveSubView] = useState<StudentSubView>('dashboard');
  const [enrolledCourse, setEnrolledCourse] = useState<Course | null>(null);
  const [modules, setModules] = useState<Module[]>([]);
  const [activeLesson, setActiveLesson] = useState<Lesson | null>(null);
  const [loading, setLoading] = useState(true);
  const [isSidebarOpen, setIsSidebarOpen] = useState(true);

  useEffect(() => {
    const fetchEnrolledCourse = async () => {
      setLoading(true);
      const userDoc = await getDoc(doc(db, 'users', user.uid));
      if (userDoc.exists()) {
        const userData = userDoc.data();
        const courseId = userData.cursoInicial;
        if (courseId) {
          const courseDoc = await getDoc(doc(db, 'cursos', courseId));
          if (courseDoc.exists()) {
            setEnrolledCourse({ id: courseDoc.id, ...courseDoc.data() } as Course);
          }
        }
      }
      setLoading(false);
    };
    fetchEnrolledCourse();
  }, [user.uid]);

  const handleStartLesson = async () => {
    if (!enrolledCourse) return;
    setLoading(true);
    const q = query(collection(db, 'modulos'), where('courseId', '==', enrolledCourse.id));
    onSnapshot(q, (snap) => {
      const mods = snap.docs.map((d: any) => ({ id: d.id, ...d.data() }))
        .sort((a: any, b: any) => (a.order || 0) - (b.order || 0));
      setModules(mods);
      if (mods.length > 0 && mods[0].lessons && mods[0].lessons.length > 0) {
        setActiveLesson(mods[0].lessons[0]);
      }
      setActiveSubView('classroom');
      setLoading(false);
    });
  };

  if (loading) return (
    <div className="h-screen flex flex-col items-center justify-center bg-slate-950">
      <div className="w-16 h-16 border-4 border-indigo-600 border-t-transparent animate-spin rounded-full mb-8 shadow-2xl"></div>
      <p className="text-[10px] font-black uppercase tracking-[0.6em] text-white italic animate-pulse">Autenticando Matrícula...</p>
    </div>
  );

  const sidebarItems = [
    { id: 'dashboard', label: 'Home Page', icon: <Home size={20}/> },
    { id: 'library', label: 'Biblioteca', icon: <BookOpen size={20}/> },
    { id: 'certificates', label: 'Meus Diplomas', icon: <Award size={20}/> },
    { id: 'support', label: 'Suporte & Ajuda', icon: <LifeBuoy size={20}/> },
  ];

  return (
    <div className="min-h-screen bg-slate-50 text-slate-900 font-sans flex overflow-hidden">

      {/* SIDEBAR MASTER ALUNO */}
      <aside className={`bg-slate-900 text-slate-400 w-72 flex flex-col transition-all duration-300 z-[300] ${isSidebarOpen ? 'ml-0' : '-ml-72'}`}>
        <div className="p-8 flex items-center gap-3 border-b border-white/5">
          <div className="bg-indigo-600 p-2 rounded-xl text-white shadow-lg shadow-indigo-600/20"><GraduationCap size={24}/></div>
          <div className="flex flex-col">
            <span className="font-black text-white uppercase italic tracking-tighter text-lg leading-none">EB-EAD</span>
            <span className="text-[8px] font-bold text-indigo-400 uppercase tracking-widest mt-1">Sala de Aula Master</span>
          </div>
        </div>

        <nav className="flex-1 p-4 space-y-2 mt-6">
          {sidebarItems.map(item => (
            <button 
              key={item.id}
              onClick={() => setActiveSubView(item.id as StudentSubView)}
              className={`w-full flex items-center gap-4 px-6 py-4 rounded-2xl text-[11px] font-black uppercase tracking-widest transition-all ${activeSubView === item.id ? 'bg-indigo-600 text-white shadow-2xl' : 'hover:bg-white/5 hover:text-white'}`}
            >
              {item.icon} {item.label}
            </button>
          ))}
        </nav>

        <div className="p-6 border-t border-white/5 bg-black/20">
           <div className="flex items-center gap-4 p-4 bg-white/5 rounded-2xl border border-white/5">
              <div className="w-10 h-10 rounded-xl overflow-hidden shadow-lg shrink-0">
                 {user.photoURL ? <img src={user.photoURL} className="w-full h-full object-cover" /> : <div className="w-full h-full bg-indigo-600 flex items-center justify-center text-white font-black text-xs">{(user.displayName||'U').charAt(0)}</div>}
              </div>
              <div className="flex-1 overflow-hidden">
                 <p className="text-[10px] font-black text-white uppercase italic truncate leading-none">{user.displayName.split(' ')[0]}</p>
                 <p className="text-[8px] font-bold text-slate-500 uppercase mt-1 truncate">{user.academicId || 'Pendente'}</p>
              </div>
              <button onClick={() => auth.signOut()} className="text-rose-500 hover:scale-110 transition-transform"><LogOut size={18}/></button>
           </div>
        </div>
      </aside>

