              <div className="flex items-center gap-2 px-4 py-2 bg-indigo-50 text-indigo-600 rounded-full border border-indigo-100"><Zap size={14} fill="currentColor"/><span className="text-[9px] font-black uppercase italic tracking-widest">Plano Master Ativo</span></div>
              <div className="relative">
