        </div>
        <button onClick={() => setIsRegisterModalOpen(true)} className="flex items-center gap-3 bg-slate-900 text-white px-8 py-4 rounded-2xl text-[10px] font-black uppercase tracking-widest hover:bg-indigo-600 shadow-2xl transition-all italic active:scale-95"><UserPlus size={18} /> Nova Matrícula Master</button>
      </header>

      <div className="bg-white rounded-[3rem] border border-slate-200 shadow-sm overflow-hidden">
        <div className="p-10 border-b border-slate-50 flex flex-col md:flex-row gap-4">
          <div className="relative flex-[2]">
            <Search className="absolute left-5 top-1/2 -translate-y-1/2 text-slate-400" size={18} />
            <input type="text" value={searchTerm} onChange={e => setSearchTerm(e.target.value)} placeholder="Pesquisar por nome ou e-mail..." className="w-full pl-14 pr-6 py-4 bg-slate-50 border-none rounded-2xl text-[10px] font-bold shadow-inner" />
          </div>
          <select value={courseFilter} onChange={e => setCourseFilter(e.target.value)} className="bg-slate-50 border-none rounded-2xl px-6 py-4 text-[9px] font-black uppercase flex-1 shadow-inner outline-none">
            <option value="">Filtrar por Disciplina</option>
            {courses.map(c => <option key={c.id} value={c.id}>{c.nome}</option>)}
          </select>
        </div>

        <div className="overflow-x-auto">
          <table className="w-full text-left">
            <thead className="bg-slate-50 text-[9px] font-black text-slate-400 uppercase tracking-widest border-b italic">
              <tr>
                <th className="px-10 py-6">Identidade Digital</th>
                <th className="px-10 py-6">Nome / E-mail</th>
                <th className="px-10 py-6">Cadeira Acadêmica</th>
                <th className="px-10 py-6">Status</th>
                <th className="px-10 py-6 text-center">Gestão</th>
              </tr>
            </thead>
            <tbody className="divide-y divide-slate-100 text-[10px]">
              {filtered.map(student => (
                <tr key={student.uid} className="hover:bg-slate-50/80 transition-all group">
                  <td className="px-10 py-6">
                    <div className="flex items-center gap-4">
                      <div className="w-12 h-12 rounded-xl overflow-hidden border-2 border-white shadow-md bg-slate-100 shrink-0">
                         {(student as any).photoURL ? <img src={(student as any).photoURL} className="w-full h-full object-cover" /> : <div className="w-full h-full flex items-center justify-center text-slate-300 font-black italic">{(student.displayName||'U').charAt(0)}</div>}
                      </div>
                      <span className="font-mono font-black text-indigo-600 text-[11px]">{(student as any).academicId}</span>
                    </div>
                  </td>
                  <td className="px-10 py-6">
                    <div className="font-black text-slate-900 uppercase italic text-xs tracking-tight">{student.displayName}</div>
                    <div className="text-slate-400 font-bold mt-1">{student.email}</div>
                  </td>
                  <td className="px-10 py-6">
                    <span className="font-black text-indigo-600 italic uppercase text-[10px] bg-indigo-50 px-3 py-1 rounded-lg border border-indigo-100">{courses.find(c => c.id === (student as any).cursoInicial)?.nome || 'S/Vínculo'}</span>
                  </td>
                  <td className="px-10 py-6">
                    <span className={`px-4 py-1.5 rounded-full text-[8px] font-black uppercase italic border ${student.status === 'ativo' ? 'bg-emerald-50 text-emerald-600 border-emerald-100' : 'bg-rose-50 text-rose-600 border-rose-100'}`}>{student.status}</span>
                  </td>
                  <td className="px-10 py-6 text-center">
                    <div className="flex justify-center gap-2 opacity-0 group-hover:opacity-100 transition-opacity">
                      <button onClick={() => { setSelectedStudent(student); setFormData({ nome: student.displayName, email: student.email || '', telefone: (student as any).telefone || '', cursoId: (student as any).cursoInicial || '', usuario: (student as any).username || '', senha: (student as any).password || '', status: student.status || 'ativo', cpf: (student as any).cpf || '', nascimento: (student as any).nascimento || '', fotoUrl: (student as any).photoURL || '', endereco: (student as any).endereco || { cep: '', rua: '', numero: '', bairro: '', cidade: '', uf: '' } }); setIsRegisterModalOpen(true); }} className="p-3 text-slate-400 hover:text-indigo-600 hover:bg-white rounded-xl transition-all shadow-sm border border-slate-100"><Edit3 size={18} /></button>
                      <button onClick={async () => { if(confirm('Remover aluno permanentemente?')) await deleteDoc(doc(db, 'users', student.uid)); }} className="p-3 text-slate-400 hover:text-rose-600 hover:bg-white rounded-xl transition-all shadow-sm border border-slate-100"><Trash2 size={18} /></button>
                    </div>
