                       <div className="space-y-1.5"><label className="text-[9px] font-black text-slate-400 uppercase ml-4 italic">CPF</label><input required value={formData.cpf} onChange={e => setFormData({...formData, cpf: e.target.value})} placeholder="000.000.000-00" className="w-full px-8 py-5 bg-slate-50 border-none rounded-3xl font-bold text-xs shadow-inner" /></div>
                       <div className="space-y-1.5"><label className="text-[9px] font-black text-slate-400 uppercase ml-4 italic">E-mail Acadêmico</label><div className="relative"><Mail className="absolute left-6 top-1/2 -translate-y-1/2 text-slate-300" size={16}/><input required type="email" value={formData.email} onChange={e => setFormData({...formData, email: e.target.value})} className="w-full pl-14 pr-8 py-5 bg-slate-50 border-none rounded-3xl font-bold text-xs shadow-inner" /></div></div>
                       <div className="space-y-1.5"><label className="text-[9px] font-black text-slate-400 uppercase ml-4 italic">WhatsApp</label><div className="relative"><Smartphone className="absolute left-6 top-1/2 -translate-y-1/2 text-slate-300" size={16}/><input required value={formData.telefone} onChange={e => setFormData({...formData, telefone: e.target.value})} className="w-full pl-14 pr-8 py-5 bg-slate-50 border-none rounded-3xl font-bold text-xs shadow-inner" /></div></div>
                    </div>
                  </div>
               </section>

               {/* 2. VÍNCULO ACADÊMICO */}
               <section className="space-y-10">
                  <div className="flex items-center gap-4 border-b border-slate-100 pb-4">
                     <span className="w-1.5 h-6 bg-indigo-600 rounded-full"></span>
                     <h3 className="font-black text-slate-900 uppercase italic text-sm">2. Matriz e Credenciais</h3>
                  </div>
                  <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-6">
                    <div className="space-y-1.5"><label className="text-[9px] font-black text-slate-400 uppercase ml-4 italic">Cadeira Acadêmica</label><select required value={formData.cursoId} onChange={e => setFormData({...formData, cursoId: e.target.value})} className="w-full px-8 py-5 bg-slate-50 border-none rounded-3xl font-black text-[10px] uppercase shadow-inner outline-none focus:ring-1 focus:ring-indigo-600"><option value="">Vincular Curso...</option>{courses.map(c => <option key={c.id} value={c.id}>{c.nome}</option>)}</select></div>
                    <div className="space-y-1.5"><label className="text-[9px] font-black text-slate-400 uppercase ml-4 italic">Usuário Login</label><input required value={formData.usuario} onChange={e => setFormData({...formData, usuario: e.target.value})} className="w-full px-8 py-5 bg-slate-900 text-white border-none rounded-3xl font-bold text-xs shadow-2xl" /></div>
                    <div className="space-y-1.5"><label className="text-[9px] font-black text-slate-400 uppercase ml-4 italic">Senha Secreta</label><input required type="password" value={formData.senha} onChange={e => setFormData({...formData, senha: e.target.value})} className="w-full px-8 py-5 bg-slate-900 text-white border-none rounded-3xl font-bold text-xs shadow-2xl" /></div>
                  </div>
               </section>

               <div className="flex gap-4 pt-10">
                  <button type="button" onClick={() => setIsRegisterModalOpen(false)} className="flex-1 py-6 bg-slate-100 text-slate-400 rounded-3xl text-[11px] font-black uppercase italic tracking-widest hover:bg-rose-50 hover:text-rose-600 transition-all">Descartar Alterações</button>
                  <button type="submit" disabled={actionLoading} className="flex-[2] py-6 bg-indigo-600 text-white rounded-3xl text-[11px] font-black uppercase shadow-2xl shadow-indigo-200 hover:bg-indigo-700 transition-all italic flex items-center justify-center gap-4">{actionLoading ? 'Processando ERP...' : <><Save size={20}/> Efetivar Matrícula no Banco</>}</button>
               </div>
            </form>
          </div>
        </div>
      )}
    </div>
  );
};

export default StudentsView;

import React, { useState, useEffect, useMemo, useRef } from 'react';
import { 
  collection, query, where, onSnapshot, 
  deleteDoc, serverTimestamp, doc, setDoc, getDoc
} from "https://www.gstatic.com/firebasejs/10.7.1/firebase-firestore.js";
import { db } from '../firebase';
import { User, Course } from '../types';
import { 
  Search, UserPlus, X, Save, UserCog, Trash2, Edit3, Camera, Smartphone, Mail, User as UserIcon, Eye, MapPin, Hash, ShieldCheck
} from 'lucide-react';

const StudentsView: React.FC = () => {
  const [students, setStudents] = useState<User[]>([]);
  const [courses, setCourses] = useState<Course[]>([]);
  const [loading, setLoading] = useState(true);
  const [searchTerm, setSearchTerm] = useState('');
  const [courseFilter, setCourseFilter] = useState('');

  const [isRegisterModalOpen, setIsRegisterModalOpen] = useState(false);
  const [isViewModalOpen, setIsViewModalOpen] = useState(false);
  const [selectedStudent, setSelectedStudent] = useState<any | null>(null);
  const [actionLoading, setActionLoading] = useState(false);
  const fileInputRef = useRef<HTMLInputElement>(null);

  const [formData, setFormData] = useState({
    nome: '', email: '', telefone: '', cursoId: '', usuario: '', senha: '', status: 'ativo',
    cpf: '', nascimento: '', fotoUrl: '',
    endereco: { cep: '', rua: '', numero: '', bairro: '', cidade: '', uf: '' }
  });

  useEffect(() => {
    const unsubStudents = onSnapshot(query(collection(db, 'users'), where('role', '==', 'aluno')), (snap) => {
      const data = snap.docs.map(d => ({ uid: d.id, ...d.data() } as User));
      setStudents(data.sort((a: any, b: any) => (b.createdAt?.seconds || 0) - (a.createdAt?.seconds || 0)));
      setLoading(false);
    });
    const unsubCourses = onSnapshot(collection(db, 'cursos'), (snap) => {
      setCourses(snap.docs.map(d => ({ id: d.id, ...d.data() } as Course)));
    });
    return () => { unsubStudents(); unsubCourses(); };
  }, []);

  const filtered = useMemo(() => {
    return students.filter(s => {
      const name = s.displayName || (s as any).nome || '';
      const email = s.email || '';
      const aid = (s as any).academicId || '';
      const matchSearch = name.toLowerCase().includes(searchTerm.toLowerCase()) || 
                          email.toLowerCase().includes(searchTerm.toLowerCase()) ||
                          aid.toLowerCase().includes(searchTerm.toLowerCase());
      const matchCourse = !courseFilter || (s as any).cursoInicial === courseFilter;
      return matchSearch && matchCourse;
    });
  }, [students, searchTerm, courseFilter]);

  const handlePhotoUpload = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (file) {
      const reader = new FileReader();
      reader.onloadend = () => setFormData({ ...formData, fotoUrl: reader.result as string });
      reader.readAsDataURL(file);
    }
  };

  const handleSave = async (e: React.FormEvent) => {
    e.preventDefault();
    setActionLoading(true);
    try {
      const uid = selectedStudent?.uid || Math.random().toString(36).substring(2, 15);
      const userRef = doc(db, 'users', uid);

      const payload = {
        uid,
        displayName: formData.nome,
        nome: formData.nome,
        email: formData.email.toLowerCase().trim(),
        telefone: formData.telefone,
        cpf: formData.cpf,
        nascimento: formData.nascimento,
        photoURL: formData.fotoUrl,
        endereco: formData.endereco,
        cursoInicial: formData.cursoId,
        username: formData.usuario,
        password: formData.senha, 
        role: 'aluno', 
        status: formData.status,
        updatedAt: serverTimestamp(),
        createdAt: selectedStudent?.createdAt || serverTimestamp(),
        academicId: selectedStudent?.academicId || `MAT-${new Date().getFullYear()}-${Math.random().toString(36).substring(2, 7).toUpperCase()}`
      };

      await setDoc(userRef, payload, { merge: true });
      setIsRegisterModalOpen(false);
      setSelectedStudent(null);
    } catch (err) {
      alert("Erro ao processar matrícula.");
    } finally {
      setActionLoading(false);
    }
  };

  if (loading) return <div className="p-20 flex justify-center"><div className="w-10 h-10 border-4 border-indigo-600 border-t-transparent animate-spin rounded-full" /></div>;

  return (
    <div className="space-y-8 animate-in fade-in duration-700">
      <header className="flex flex-col md:flex-row md:items-center justify-between gap-6">
        <div>
          <h1 className="text-3xl font-black text-slate-900 uppercase italic tracking-tighter leading-none">Gestão de Alunos</h1>
          <p className="text-slate-500 text-sm font-medium italic mt-2">Prontuário Acadêmico Centralizado.</p>
        </div>
        <button onClick={() => { 
          setFormData({ nome: '', email: '', telefone: '', cursoId: '', usuario: '', senha: '', status: 'ativo', cpf: '', nascimento: '', fotoUrl: '', endereco: { cep: '', rua: '', numero: '', bairro: '', cidade: '', uf: '' } });
          setSelectedStudent(null);
          setIsRegisterModalOpen(true); 
        }} className="flex items-center gap-3 bg-slate-900 text-white px-8 py-4 rounded-2xl text-[10px] font-black uppercase tracking-widest hover:bg-indigo-600 shadow-2xl transition-all italic"><UserPlus size={18} /> Cadastrar Aluno</button>
      </header>

      <div className="bg-white rounded-[3rem] border border-slate-200 shadow-sm overflow-hidden">
        <div className="p-10 border-b border-slate-50 flex flex-col md:flex-row gap-4">
          <div className="relative flex-[2]">
            <Search className="absolute left-5 top-1/2 -translate-y-1/2 text-slate-400" size={18} />
            <input type="text" value={searchTerm} onChange={e => setSearchTerm(e.target.value)} placeholder="Pesquisar por Matrícula, Nome ou E-mail..." className="w-full pl-14 pr-6 py-4 bg-slate-50 border-none rounded-2xl text-[10px] font-bold shadow-inner" />
          </div>
          <select value={courseFilter} onChange={e => setCourseFilter(e.target.value)} className="bg-slate-50 border-none rounded-2xl px-6 py-4 text-[9px] font-black uppercase flex-1 shadow-inner outline-none">
            <option value="">Todas as Disciplinas</option>
            {courses.map(c => <option key={c.id} value={c.id}>{c.nome}</option>)}
          </select>
        </div>

        <div className="overflow-x-auto">
          <table className="w-full text-left">
            <thead className="bg-slate-50 text-[9px] font-black text-slate-400 uppercase tracking-widest border-b italic">
              <tr>
                <th className="px-10 py-6">Matrícula</th>
                <th className="px-10 py-6">Aluno</th>
                <th className="px-10 py-6">Cadeira / Curso</th>
                <th className="px-10 py-6">Status</th>
                <th className="px-10 py-6 text-center">Ações</th>
              </tr>
            </thead>
            <tbody className="divide-y divide-slate-100 text-[10px]">
              {filtered.map(student => (
                <tr key={student.uid} className="hover:bg-slate-50/80 transition-all group">
                  <td className="px-10 py-6 font-mono font-black text-indigo-600 text-xs">{(student as any).academicId || 'S/ID'}</td>
                  <td className="px-10 py-6">
                    <div className="flex items-center gap-4">
                      <div className="w-10 h-10 rounded-xl overflow-hidden bg-slate-100 border border-slate-200">
                        {(student as any).photoURL ? <img src={(student as any).photoURL} className="w-full h-full object-cover" /> : <div className="w-full h-full flex items-center justify-center text-slate-300 font-black italic">{(student.displayName||'U').charAt(0)}</div>}
                      </div>
                      <div>
                        <div className="font-black text-slate-900 uppercase italic text-xs leading-none">{student.displayName || (student as any).nome}</div>
                        <div className="text-slate-400 font-bold mt-1.5">{student.email}</div>
                      </div>
                    </div>
                  </td>
                  <td className="px-10 py-6">
                    <span className="font-black text-indigo-600 italic uppercase text-[9px] bg-indigo-50 px-3 py-1.5 rounded-lg border border-indigo-100">{courses.find(c => c.id === (student as any).cursoInicial)?.nome || 'Lead / Pendente'}</span>
                  </td>
                  <td className="px-10 py-6">
                    <span className={`px-4 py-1.5 rounded-full text-[8px] font-black uppercase italic border ${student.status === 'ativo' ? 'bg-emerald-50 text-emerald-600 border-emerald-100' : 'bg-rose-50 text-rose-600 border-rose-100'}`}>{student.status?.replace('_', ' ')}</span>
                  </td>
                  <td className="px-10 py-6 text-center">
                    <div className="flex justify-center gap-2">
                      <button onClick={() => { setSelectedStudent(student); setIsViewModalOpen(true); }} className="p-3 text-slate-400 hover:text-indigo-600 hover:bg-white rounded-xl transition-all shadow-sm border border-slate-100" title="Ver Ficha"><Eye size={16} /></button>
                      <button onClick={() => { setSelectedStudent(student); setFormData({ nome: student.displayName || (student as any).nome, email: student.email || '', telefone: (student as any).telefone || '', cursoId: (student as any).cursoInicial || '', usuario: (student as any).username || '', senha: (student as any).password || '', status: student.status || 'ativo', cpf: (student as any).cpf || '', nascimento: (student as any).nascimento || '', fotoUrl: (student as any).photoURL || '', endereco: (student as any).endereco || { cep: '', rua: '', numero: '', bairro: '', cidade: '', uf: '' } }); setIsRegisterModalOpen(true); }} className="p-3 text-slate-400 hover:text-amber-600 hover:bg-white rounded-xl transition-all shadow-sm border border-slate-100" title="Editar"><Edit3 size={16} /></button>
                      <button onClick={async () => { if(confirm('Remover permanentemente?')) await deleteDoc(doc(db, 'users', student.uid)); }} className="p-3 text-slate-400 hover:text-rose-600 hover:bg-white rounded-xl transition-all shadow-sm border border-slate-100" title="Excluir"><Trash2 size={16} /></button>
                    </div>
                  </td>
                </tr>
              ))}
            </tbody>
          </table>
        </div>
      </div>

      {/* MODAL DE CADASTRO/EDIÇÃO */}
      {isRegisterModalOpen && (
        <div className="fixed inset-0 z-[1000] bg-slate-950/90 backdrop-blur-xl flex items-center justify-center p-6">
          <div className="bg-white w-full max-w-5xl h-[90vh] rounded-[3.5rem] overflow-hidden shadow-2xl animate-in zoom-in-95 flex flex-col">
            <header className="p-8 border-b border-slate-100 flex justify-between items-center bg-slate-50/50 shrink-0">
               <div className="flex items-center gap-4">
                  <div className="p-3 bg-slate-900 text-white rounded-2xl shadow-xl"><UserCog size={22}/></div>
                  <h2 className="text-2xl font-black text-slate-900 uppercase italic tracking-tighter">Prontuário Discente</h2>
               </div>
               <button onClick={() => setIsRegisterModalOpen(false)} className="p-4 hover:bg-rose-50 text-slate-400 rounded-full transition-all"><X size={24}/></button>
            </header>

            <form onSubmit={handleSave} className="flex-1 overflow-y-auto p-12 custom-scrollbar space-y-16">
               <section className="grid grid-cols-1 lg:grid-cols-4 gap-12">
                  <div className="lg:col-span-1 flex flex-col items-center gap-4">
                     <div onClick={() => fileInputRef.current?.click()} className="w-44 h-44 rounded-[3.5rem] bg-slate-50 border-4 border-dashed border-slate-200 flex items-center justify-center overflow-hidden cursor-pointer hover:border-indigo-400 transition-all relative group shadow-xl">
                        {formData.fotoUrl ? <img src={formData.fotoUrl} className="w-full h-full object-cover" /> : <div className="text-center opacity-30"><Camera size={48} className="mx-auto"/><span className="text-[9px] font-black uppercase mt-2 block">Foto do Aluno</span></div>}
                     </div>
                     <input type="file" ref={fileInputRef} className="hidden" accept="image/*" onChange={handlePhotoUpload} />
                  </div>
                  <div className="lg:col-span-3 grid grid-cols-1 md:grid-cols-2 gap-6">
                     <div className="space-y-1.5"><label className="text-[9px] font-black text-slate-400 uppercase ml-4 italic">Nome Completo</label><input required value={formData.nome} onChange={e => setFormData({...formData, nome: e.target.value})} className="w-full px-8 py-5 bg-slate-50 border-none rounded-3xl font-bold text-xs shadow-inner" /></div>
                     <div className="space-y-1.5"><label className="text-[9px] font-black text-slate-400 uppercase ml-4 italic">CPF</label><input required value={formData.cpf} onChange={e => setFormData({...formData, cpf: e.target.value})} className="w-full px-8 py-5 bg-slate-50 border-none rounded-3xl font-bold text-xs shadow-inner" /></div>
                     <div className="space-y-1.5"><label className="text-[9px] font-black text-slate-400 uppercase ml-4 italic">E-mail Acadêmico</label><input required type="email" value={formData.email} onChange={e => setFormData({...formData, email: e.target.value})} className="w-full px-8 py-5 bg-slate-50 border-none rounded-3xl font-bold text-xs shadow-inner" /></div>
                     <div className="space-y-1.5"><label className="text-[9px] font-black text-slate-400 uppercase ml-4 italic">WhatsApp</label><input required value={formData.telefone} onChange={e => setFormData({...formData, telefone: e.target.value})} className="w-full px-8 py-5 bg-slate-50 border-none rounded-3xl font-bold text-xs shadow-inner" /></div>
                  </div>
               </section>

               <section className="space-y-10">
                  <div className="flex items-center gap-4 border-b border-slate-100 pb-4">
                     <MapPin size={18} className="text-indigo-600"/>
                     <h3 className="font-black text-slate-900 uppercase italic text-sm">Endereço Residencial</h3>
                  </div>
                  <div className="grid grid-cols-1 md:grid-cols-6 gap-6">
                    <div className="md:col-span-2 space-y-1.5"><label className="text-[9px] font-black text-slate-400 uppercase ml-4">CEP</label><input value={formData.endereco.cep} onChange={e => setFormData({...formData, endereco: {...formData.endereco, cep: e.target.value}})} className="w-full px-8 py-4 bg-slate-50 border-none rounded-2xl font-bold text-xs shadow-inner" /></div>
                    <div className="md:col-span-3 space-y-1.5"><label className="text-[9px] font-black text-slate-400 uppercase ml-4">Rua</label><input value={formData.endereco.rua} onChange={e => setFormData({...formData, endereco: {...formData.endereco, rua: e.target.value}})} className="w-full px-8 py-4 bg-slate-50 border-none rounded-2xl font-bold text-xs shadow-inner" /></div>
                    <div className="md:col-span-1 space-y-1.5"><label className="text-[9px] font-black text-slate-400 uppercase ml-4">Nº</label><input value={formData.endereco.numero} onChange={e => setFormData({...formData, endereco: {...formData.endereco, numero: e.target.value}})} className="w-full px-8 py-4 bg-slate-50 border-none rounded-2xl font-bold text-xs shadow-inner" /></div>
                  </div>
               </section>

               <section className="grid grid-cols-1 md:grid-cols-3 gap-6">
                  <div className="space-y-1.5"><label className="text-[9px] font-black text-slate-400 uppercase ml-4 italic">Curso Vinculado</label><select required value={formData.cursoId} onChange={e => setFormData({...formData, cursoId: e.target.value})} className="w-full px-8 py-5 bg-slate-50 border-none rounded-3xl font-black text-[10px] uppercase shadow-inner outline-none"><option value="">Vincular...</option>{courses.map(c => <option key={c.id} value={c.id}>{c.nome}</option>)}</select></div>
                  <div className="space-y-1.5"><label className="text-[9px] font-black text-slate-400 uppercase ml-4 italic">Usuário Login</label><input required value={formData.usuario} onChange={e => setFormData({...formData, usuario: e.target.value})} className="w-full px-8 py-5 bg-slate-900 text-white border-none rounded-3xl font-bold text-xs" /></div>
                  <div className="space-y-1.5"><label className="text-[9px] font-black text-slate-400 uppercase ml-4 italic">Senha</label><input required type="password" value={formData.senha} onChange={e => setFormData({...formData, senha: e.target.value})} className="w-full px-8 py-5 bg-slate-900 text-white border-none rounded-3xl font-bold text-xs" /></div>
               </section>

               <div className="flex gap-4">
                  <button type="button" onClick={() => setIsRegisterModalOpen(false)} className="flex-1 py-6 bg-slate-100 text-slate-400 rounded-3xl text-[10px] font-black uppercase italic hover:bg-rose-50 transition-all">Cancelar</button>
                  <button type="submit" disabled={actionLoading} className="flex-[2] py-6 bg-indigo-600 text-white rounded-3xl text-[10px] font-black uppercase shadow-2xl hover:bg-indigo-700 transition-all italic flex items-center justify-center gap-4">{actionLoading ? 'Gravando...' : <><Save size={20}/> Efetivar Matrícula</>}</button>
               </div>
            </form>
          </div>
        </div>
      )}

      {/* MODAL DE VISUALIZAÇÃO DE FICHA */}
      {isViewModalOpen && selectedStudent && (
        <div className="fixed inset-0 z-[1000] bg-slate-950/90 backdrop-blur-xl flex items-center justify-center p-6">
          <div className="bg-white w-full max-w-3xl rounded-[3.5rem] overflow-hidden shadow-2xl animate-in slide-in-from-bottom-5 flex flex-col">
            <header className="p-8 border-b flex justify-between items-center">
              <h2 className="text-xl font-black text-slate-900 uppercase italic tracking-tighter">Ficha Cadastral Discente</h2>
              <button onClick={() => setIsViewModalOpen(false)} className="p-3 hover:bg-rose-50 text-slate-400 rounded-full transition-all"><X size={20}/></button>
            </header>
            <div className="p-10 space-y-10 overflow-y-auto custom-scrollbar">
              <div className="flex items-center gap-8">
                <div className="w-32 h-32 rounded-[2rem] bg-slate-100 overflow-hidden border-4 border-slate-50 shadow-xl">
                  {(selectedStudent as any).photoURL ? <img src={(selectedStudent as any).photoURL} className="w-full h-full object-cover" /> : <UserIcon className="m-auto mt-8 text-slate-200" size={60}/>}
                </div>
                <div>
                  <span className="text-[10px] font-black text-indigo-600 uppercase bg-indigo-50 px-3 py-1 rounded-full italic tracking-widest">Matrícula: {(selectedStudent as any).academicId || 'PENDENTE'}</span>
                  <h1 className="text-3xl font-black text-slate-900 uppercase italic tracking-tighter mt-2">{selectedStudent.displayName || (selectedStudent as any).nome}</h1>
                  <p className="text-sm font-bold text-slate-400 tracking-tight">{selectedStudent.email}</p>
                </div>
              </div>
              <div className="grid grid-cols-2 md:grid-cols-3 gap-6 pt-10 border-t">
                 <div className="space-y-1"><p className="text-[8px] font-black text-slate-400 uppercase italic">WhatsApp</p><p className="text-xs font-bold text-slate-900">{(selectedStudent as any).telefone || '---'}</p></div>
                 <div className="space-y-1"><p className="text-[8px] font-black text-slate-400 uppercase italic">Documento CPF</p><p className="text-xs font-bold text-slate-900">{(selectedStudent as any).cpf || '---'}</p></div>
                 <div className="space-y-1"><p className="text-[8px] font-black text-slate-400 uppercase italic">Nascimento</p><p className="text-xs font-bold text-slate-900">{(selectedStudent as any).nascimento || '---'}</p></div>
              </div>
              <div className="p-6 bg-slate-50 rounded-3xl border border-slate-100">
                <h4 className="text-[10px] font-black text-indigo-600 uppercase italic mb-4 flex items-center gap-2"><MapPin size={14}/> Endereço Completo</h4>
                <p className="text-xs font-bold text-slate-600 leading-relaxed italic">
                  {(selectedStudent as any).endereco?.rua ? `${(selectedStudent as any).endereco.rua}, ${(selectedStudent as any).endereco.numero} - ${(selectedStudent as any).endereco.bairro}, ${(selectedStudent as any).endereco.cidade}/${(selectedStudent as any).endereco.uf} - CEP: ${(selectedStudent as any).endereco.cep}` : 'Endereço não cadastrado.'}
                </p>
              </div>
            </div>
            <footer className="p-8 bg-slate-50 border-t flex justify-end"><button onClick={() => setIsViewModalOpen(false)} className="px-10 py-3.5 bg-slate-900 text-white rounded-xl text-[10px] font-black uppercase italic hover:bg-indigo-600 transition-all">Fechar Ficha</button></footer>
          </div>
        </div>
      )}
    </div>
  );
};

