      content: pdfDataUri, 
      uploader: user.displayName, 
      createdAt: serverTimestamp(), 
      size: 15000, 
      type: 'application/pdf', 
      verificationCode: vCode,
      academicId: selectedStudentForDecl.academicId || ''
