                              </div>
                           </td>
                        </tr>
                      ))}
                   </tbody>
                </table>
             </div>
          </div>
        );
      case 'transferencia':
        return (
          <div className="bg-white p-10 rounded-[2.5rem] border border-slate-200 shadow-xl max-w-2xl mx-auto space-y-8 animate-in zoom-in-95">
