                       {chatHistory.map((m, i) => (
                         <div key={i} className={`flex flex-col ${m.sender === 'Secretaria' ? 'items-end' : 'items-start'}`}>
                            <div className={`max-w-[80%] p-5 rounded-[1.5rem] shadow-sm ${m.sender === 'Secretaria' ? 'bg-slate-900 text-white rounded-tr-none' : 'bg-white border border-slate-100 text-slate-700 rounded-tl-none'}`}>
                                <p className="text-xs font-medium italic leading-relaxed">{m.text}</p>
                            </div>
                         </div>
                       ))}
                       <div ref={chatEndRef} />
                    </div>
                    <div className="p-6 border-t bg-white flex gap-3"><input value={chatMessage} onChange={e => setChatMessage(e.target.value)} onKeyDown={e => e.key === 'Enter' && handleSendMessage()} placeholder="RESPOSTA ACADÊMICA..." className="flex-1 bg-slate-50 border-none rounded-2xl px-6 py-4 text-[10px] font-black uppercase tracking-widest shadow-inner outline-none focus:ring-1 focus:ring-indigo-600" /><button onClick={handleSendMessage} className="p-4 bg-slate-900 text-white rounded-2xl hover:bg-indigo-600 transition-all shadow-md"><Send size={20}/></button></div>
                  </>
                ) : <div className="flex-1 flex flex-col items-center justify-center opacity-20 p-20 text-center gap-5"><MessageSquare size={100}/><p className="text-[11px] font-black uppercase tracking-[0.6em] italic text-slate-400">Canal de Atendimento Master</p></div>}
             </div>
          </div>
        )}

        {(activeTab === 'atendimento' || activeTab === 'arquivos') && (
           <div className="bg-white p-20 rounded-[3rem] border-4 border-dashed border-slate-100 text-center space-y-4 animate-in fade-in"><FolderOpen size={60} className="mx-auto text-slate-200"/><h2 className="text-lg font-black uppercase italic text-slate-400 tracking-widest">Navegação Master Restrita</h2><p className="text-slate-300 text-[10px] font-bold uppercase tracking-[0.2em] italic">Utilize o menu operacional para gerenciar os prontuários ativos.</p></div>
        )}
      </main>

      {isSignModalOpen && <SignaturePad title="Assinatura Digital Secretário" onCancel={() => setIsSignModalOpen(false)} onSave={async (b) => { await updateDoc(doc(db, 'users', user.uid), {signatureUrl: b}); setSecSignature(b); setIsSignModalOpen(false); alert("Identidade Digital Atualizada!"); }} />}
    </div>
  );
};

export default SecretariatView;

