import { Lock, Mail, AlertCircle, GraduationCap, ShieldCheck, ArrowRight, BookOpen, Star, ChevronRight, CheckCircle, Camera, User, MapPin, Key, Quote, BarChart3, Database, ChevronLeft } from 'lucide-react';

type ViewMode = 'landing' | 'login' | 'enroll_form';

const LoginView: React.FC = () => {
  const [viewMode, setViewMode] = useState<ViewMode>('landing');
  const [email, setEmail] = useState('');
  const [password, setPassword] = useState('');
  const [error, setError] = useState('');
  const [loading, setLoading] = useState(false);
  const [isAdminMode, setIsAdminMode] = useState(false);

  const [courses, setCourses] = useState<any[]>([]);
  const [selectedCourse, setSelectedCourse] = useState<any>(null);

  const [enrollForm, setEnrollForm] = useState({
    nome: '', email: '', senha: '', cpf: '', nascimento: '', telefone: '', fotoUrl: '',
    endereco: { cep: '', rua: '', numero: '', bairro: '', cidade: '', uf: '' }
  });

  const coursesRef = useRef<HTMLDivElement>(null);
  const fileInputRef = useRef<HTMLInputElement>(null);

  useEffect(() => {
    const unsub = onSnapshot(query(collection(db, 'cursos'), where('status', '==', 'ativo')), (snap) => {
      setCourses(snap.docs.map(d => ({ id: d.id, ...d.data() })));
    });
    return () => unsub();
  }, []);

  useEffect(() => {
    const cep = enrollForm.endereco.cep.replace(/\D/g, '');
    if (cep.length === 8) {
      fetch(`https://viacep.com.br/ws/${cep}/json/`)
        .then(res => res.json())
        .then(data => {
          if (!data.erro) {
            setEnrollForm(prev => ({
              ...prev,
              endereco: { ...prev.endereco, rua: data.logradouro, bairro: data.bairro, cidade: data.localidade, uf: data.uf }
            }));
          }
        });
    }
  }, [enrollForm.endereco.cep]);

  const handleLogin = async (e: React.FormEvent) => {
    e.preventDefault();
    setLoading(true);
    setError('');
    try {
      const userCredential = await signInWithEmailAndPassword(auth, email.trim().toLowerCase(), password);
      const userDoc = await getDoc(doc(db, 'users', userCredential.user.uid));
      if (userDoc.exists()) {
        const userData = userDoc.data();
        if (isAdminMode && userData.role === 'aluno') {
          await signOut(auth);
          setError('Acesso negado. Utilize o portal do aluno.');
          setLoading(false);
          return;
        }
      }
    } catch (err: any) {
      setError('Credenciais inválidas.');
      setLoading(false);
    }
  };

  const handleFinalizeEnroll = async (e: React.FormEvent) => {
    e.preventDefault();
    setLoading(true);
    try {
      const userCredential = await createUserWithEmailAndPassword(auth, enrollForm.email.trim(), enrollForm.senha);
      const uid = userCredential.user.uid;
      const academicId = `MAT-${new Date().getFullYear()}-${Math.random().toString(36).substring(2, 7).toUpperCase()}`;

      const payload = {
        uid,
        displayName: enrollForm.nome,
        nome: enrollForm.nome,
        email: enrollForm.email.toLowerCase(),
        cpf: enrollForm.cpf,
        nascimento: enrollForm.nascimento,
        telefone: enrollForm.telefone,
        photoURL: enrollForm.fotoUrl,
        endereco: enrollForm.endereco,
        role: 'aluno',
        status: 'aguardando_validacao',
        cursoInicial: selectedCourse.id,
        academicId,
        createdAt: serverTimestamp(),
        progress: 0
      };

      await setDoc(doc(db, 'users', uid), payload);
      alert("Matrícula enviada! Aguarde a aprovação da secretaria.");
      setViewMode('login');
      setLoading(false);
    } catch (err: any) {
      setError('Erro no cadastro.');
      setLoading(false);
    }
  };

  if (viewMode === 'enroll_form') {
    return (
      <div className="min-h-screen bg-white text-slate-900 flex flex-col animate-in fade-in duration-500 font-sans">
        <header className="h-20 bg-slate-900 text-white px-8 flex items-center justify-between sticky top-0 z-50">
           <button onClick={() => setViewMode('landing')} className="flex items-center gap-2 text-[10px] font-black uppercase text-slate-400 italic"><ChevronLeft size={16}/> Voltar</button>
           <div className="flex items-center gap-3">
              <div className="bg-indigo-600 p-2 rounded-xl text-white"><GraduationCap size={20} /></div>
              <span className="font-black uppercase italic text-lg tracking-tighter">Matrícula EB-EAD</span>
           </div>
           <div className="px-4 py-1.5 bg-indigo-600 rounded-full text-[9px] font-black uppercase italic">{selectedCourse?.nome}</div>
        </header>

        <main className="max-w-4xl mx-auto w-full p-8 lg:p-20 space-y-16">
           <form onSubmit={handleFinalizeEnroll} className="space-y-12">
              <section className="space-y-8">
                 <div className="flex items-center gap-4 border-b border-slate-100 pb-4">
                    <User size={20} className="text-indigo-600"/>
                    <h3 className="text-xl font-black uppercase italic">Dados Pessoais</h3>
                 </div>
                 <div className="grid grid-cols-1 md:grid-cols-4 gap-6 items-center">
                    <div className="md:col-span-1">
                       <div onClick={() => fileInputRef.current?.click()} className="w-32 h-32 mx-auto rounded-[2rem] bg-slate-50 border-2 border-dashed border-slate-200 flex items-center justify-center overflow-hidden cursor-pointer hover:border-indigo-600 transition-all relative group shadow-inner">
                          {enrollForm.fotoUrl ? <img src={enrollForm.fotoUrl} className="w-full h-full object-cover" /> : <Camera size={32} className="text-slate-300"/>}
                       </div>
                       <input type="file" ref={fileInputRef} className="hidden" accept="image/*" onChange={e => { const f=e.target.files?.[0]; if(f){ const r=new FileReader(); r.onload=ev=>setEnrollForm({...enrollForm, fotoUrl: ev.target?.result as string}); r.readAsDataURL(f); } }} />
                    </div>
                    <div className="md:col-span-3 grid grid-cols-1 md:grid-cols-2 gap-4">
                       <input required placeholder="Nome Completo" value={enrollForm.nome} onChange={e => setEnrollForm({...enrollForm, nome: e.target.value})} className="w-full p-4 bg-slate-50 rounded-2xl font-bold text-xs shadow-inner outline-none" />
                       <input required placeholder="CPF" value={enrollForm.cpf} onChange={e => setEnrollForm({...enrollForm, cpf: e.target.value})} className="w-full p-4 bg-slate-50 rounded-2xl font-bold text-xs shadow-inner outline-none" />
                       <input required type="date" value={enrollForm.nascimento} onChange={e => setEnrollForm({...enrollForm, nascimento: e.target.value})} className="w-full p-4 bg-slate-50 rounded-2xl font-bold text-xs shadow-inner outline-none" />
                       <input required placeholder="WhatsApp" value={enrollForm.telefone} onChange={e => setEnrollForm({...enrollForm, telefone: e.target.value})} className="w-full p-4 bg-slate-50 rounded-2xl font-bold text-xs shadow-inner outline-none" />
                    </div>
                 </div>
              </section>

              <section className="space-y-8">
                 <div className="flex items-center gap-4 border-b border-slate-100 pb-4">
                    <MapPin size={20} className="text-indigo-600"/>
                    <h3 className="text-xl font-black uppercase italic">Endereço Residencial</h3>
                 </div>
                 <div className="grid grid-cols-1 md:grid-cols-6 gap-4">
                    <input placeholder="CEP" value={enrollForm.endereco.cep} onChange={e => setEnrollForm({...enrollForm, endereco: {...enrollForm.endereco, cep: e.target.value}})} className="md:col-span-2 p-4 bg-slate-50 rounded-2xl font-bold text-xs shadow-inner outline-none" />
                    <input placeholder="Rua" value={enrollForm.endereco.rua} onChange={e => setEnrollForm({...enrollForm, endereco: {...enrollForm.endereco, rua: e.target.value}})} className="md:col-span-3 p-4 bg-slate-50 rounded-2xl font-bold text-xs shadow-inner outline-none" />
                    <input placeholder="Nº" value={enrollForm.endereco.numero} onChange={e => setEnrollForm({...enrollForm, endereco: {...enrollForm.endereco, numero: e.target.value}})} className="md:col-span-1 p-4 bg-slate-50 rounded-2xl font-bold text-xs shadow-inner outline-none" />
                 </div>
              </section>

              <section className="space-y-8">
                 <div className="flex items-center gap-4 border-b border-slate-100 pb-4">
                    <Key size={20} className="text-indigo-600"/>
                    <h3 className="text-xl font-black uppercase italic">Acesso Acadêmico</h3>
                 </div>
                 <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
                    <input required type="email" placeholder="E-mail de Login" value={enrollForm.email} onChange={e => setEnrollForm({...enrollForm, email: e.target.value})} className="w-full p-5 bg-slate-900 text-white rounded-2xl font-bold text-xs outline-none" />
                    <input required type="password" placeholder="Sua Senha" value={enrollForm.senha} onChange={e => setEnrollForm({...enrollForm, senha: e.target.value})} className="w-full p-5 bg-slate-900 text-white rounded-2xl font-bold text-xs outline-none" />
                 </div>
              </section>

              <button type="submit" disabled={loading} className="w-full py-6 bg-indigo-600 text-white rounded-[2rem] text-xs font-black uppercase tracking-widest shadow-2xl hover:bg-indigo-700 transition-all italic">
                {loading ? 'Processando...' : 'Confirmar Matrícula Master'}
              </button>
           </form>
        </main>
      </div>
    );
  }

  // Seção de Landing e Login seguem padrão original corrigido para redirecionar conforme role
  return (
    <div className="min-h-screen bg-white text-slate-900 font-sans flex items-center justify-center p-6">
       <div className="max-w-md w-full bg-white rounded-[3rem] p-10 border border-slate-100 shadow-2xl space-y-8 text-center animate-in zoom-in-95">
          <div className="w-20 h-20 bg-indigo-600 text-white rounded-[2rem] flex items-center justify-center mx-auto shadow-xl"><GraduationCap size={40}/></div>
          <h2 className="text-2xl font-black uppercase italic tracking-tighter">Entrar no Sistema</h2>
          {error && <p className="text-[10px] font-black uppercase text-rose-600 bg-rose-50 p-4 rounded-xl">{error}</p>}
          <form onSubmit={handleLogin} className="space-y-4">
             <input type="email" required placeholder="E-mail" value={email} onChange={e => setEmail(e.target.value)} className="w-full p-4 bg-slate-50 rounded-2xl text-xs font-bold shadow-inner border-none" />
             <input type="password" required placeholder="Senha" value={password} onChange={e => setPassword(e.target.value)} className="w-full p-4 bg-slate-50 rounded-2xl text-xs font-bold shadow-inner border-none" />
             <button type="submit" className="w-full py-5 bg-slate-900 text-white rounded-2xl text-[10px] font-black uppercase italic tracking-widest">Acessar Painel</button>
          </form>
          <div className="pt-6 border-t border-slate-50 flex flex-col gap-3">
             <button onClick={() => setViewMode('landing')} className="text-[9px] font-black uppercase text-slate-300 hover:text-indigo-600 transition-colors italic">Início</button>
             <button onClick={() => setIsAdminMode(!isAdminMode)} className="text-[9px] font-black uppercase text-slate-400 italic underline">{isAdminMode ? 'Voltar para Aluno' : 'Acesso à Gestão Master'}</button>
          </div>
       </div>
    </div>
  );
};

