import React, { useState, useEffect, useMemo, useRef } from 'react';
import { 
  collection, query, onSnapshot, addDoc, updateDoc, 
  doc, serverTimestamp, orderBy, where, deleteDoc, getDocs, getDoc
} from "https://www.gstatic.com/firebasejs/10.7.1/firebase-firestore.js";
import { db, auth } from '../firebase';
import { User } from '../types';
import { 
  Ticket as TicketIcon, AlertCircle, Clock, MessageSquare, Search, Plus, X, FolderOpen, FileText, Download, UserCheck, ShieldAlert, FileSignature, Save, PenTool, UserX, Check, ArrowRightLeft, RefreshCw, Fingerprint, Star, Eye
} from 'lucide-react';
import SignaturePad from '../components/SignaturePad';

interface SecretariatViewProps { user: User; }
type SecretariatTab = 'atendimento' | 'chat' | 'arquivos' | 'operacional';
type OperationalSubView = 'main' | 'declaracao' | 'validacao' | 'transferencia' | 'inadimplencia' | 'assinatura';

const SecretariatView: React.FC<SecretariatViewProps> = ({ user }) => {
  const [activeTab, setActiveTab] = useState<SecretariatTab>('atendimento');
  const [opSubView, setOpSubView] = useState<OperationalSubView>('main');
  const [tickets, setTickets] = useState<any[]>([]);
  const [files, setFiles] = useState<any[]>([]);
  const [students, setStudents] = useState<any[]>([]);
  const [courses, setCourses] = useState<any[]>([]);
  const [searchTerm, setSearchTerm] = useState('');
  const [isSignModalOpen, setIsSignModalOpen] = useState(false);
  const [secSignature, setSecSignature] = useState<string | null>(null);
  const [selectedTicketId, setSelectedTicketId] = useState<string | null>(null);

  const [transferData, setTransferData] = useState({ studentId: '', courseId: '' });
  const [selectedStudentForDecl, setSelectedStudentForDecl] = useState<any | null>(null);
  const [declContent, setDeclContent] = useState('Declaramos que o aluno(a) encontra-se regularmente matriculado nesta instituição.');

  useEffect(() => {
    const unsubT = onSnapshot(query(collection(db, 'tickets'), orderBy('createdAt', 'desc')), s => setTickets(s.docs.map(d => ({ id: d.id, ...d.data() }))));
    const unsubF = onSnapshot(collection(db, 'secretaria_arquivos'), s => setFiles(s.docs.map(d => ({ id: d.id, ...d.data() }))));
    const unsubS = onSnapshot(query(collection(db, 'users'), where('role', '==', 'aluno')), s => setStudents(s.docs.map(d => ({ uid: d.id, ...d.data() }))));
    const unsubC = onSnapshot(collection(db, 'cursos'), s => setCourses(s.docs.map(d => ({ id: d.id, ...d.data() }))));
    getDoc(doc(db, 'users', user.uid)).then(d => d.exists() && setSecSignature(d.data().signatureUrl));
    return () => { unsubT(); unsubF(); unsubS(); unsubC(); };
  }, [user.uid]);

  const stats = useMemo(() => {
    const pendingEnrollments = students.filter(s => s.status === 'aguardando_validacao').length;
    return {
      pendentes: tickets.filter(t => t.status === 'Pendente').length + pendingEnrollments,
      emAtendimento: tickets.filter(t => t.status === 'Em Atendimento').length,
      ged: files.length,
      countPending: pendingEnrollments
    };
  }, [tickets, students, files]);

  const renderOperationalContent = () => {
    switch(opSubView) {
      case 'validacao':
        const pending = students.filter(s => s.status === 'aguardando_validacao' || s.status === 'pendente');
        return (
          <div className="bg-white rounded-[2.5rem] border border-slate-200 shadow-xl overflow-hidden animate-in zoom-in-95">
             <div className="p-8 border-b bg-slate-50/50 flex justify-between items-center">
                <div className="flex items-center gap-4"><div className="p-3 bg-indigo-600 text-white rounded-xl shadow-lg shadow-indigo-100"><UserCheck size={20}/></div><h3 className="text-xl font-black uppercase italic">Validação de Matrículas</h3></div>
                <button onClick={() => setOpSubView('main')} className="p-2 hover:bg-rose-50 rounded-full"><X size={20}/></button>
             </div>
             <table className="w-full text-left">
                <thead className="bg-slate-50 text-[9px] font-black uppercase italic border-b">
                   <tr><th className="px-8 py-5">Solicitante</th><th className="px-8 py-5">Identificador</th><th className="px-8 py-5">Ações</th></tr>
                </thead>
                <tbody className="divide-y divide-slate-100 text-xs">
                   {pending.length === 0 ? <tr><td colSpan={3} className="p-20 text-center text-slate-300 font-black uppercase italic">Sem pendências</td></tr> : pending.map(s => (
                     <tr key={s.uid} className="hover:bg-indigo-50/10">
                        <td className="px-8 py-6 font-black uppercase italic text-slate-900">{s.displayName || s.nome}</td>
                        <td className="px-8 py-6 font-mono text-indigo-600 font-bold">{s.academicId || 'S/ID'}</td>
                        <td className="px-8 py-6 flex gap-2">
                           <button onClick={async () => { if(confirm('Aprovar?')) await updateDoc(doc(db, 'users', s.uid), {status: 'ativo'}); }} className="px-5 py-2 bg-emerald-600 text-white rounded-lg text-[9px] font-black uppercase italic">Aprovar</button>
                           <button onClick={async () => { if(confirm('Excluir?')) await deleteDoc(doc(db, 'users', s.uid)); }} className="p-2 text-rose-500 hover:bg-rose-50 rounded-lg"><UserX size={16}/></button>
                        </td>
                     </tr>
                   ))}
                </tbody>
             </table>
          </div>
        );
      case 'transferencia':
        return (
          <div className="bg-white p-10 rounded-[2.5rem] border border-slate-200 shadow-xl max-w-xl mx-auto space-y-6 animate-in zoom-in-95">
             <h3 className="text-xl font-black uppercase italic border-b pb-4 flex items-center gap-3"><ArrowRightLeft className="text-indigo-600"/> Transferência</h3>
             <select value={transferData.studentId} onChange={e => setTransferData({...transferData, studentId: e.target.value})} className="w-full p-4 bg-slate-50 rounded-2xl font-bold text-xs outline-none">
                <option value="">Selecionar Aluno...</option>
                {students.map(s => <option key={s.uid} value={s.uid}>{s.displayName} ({s.academicId})</option>)}
             </select>
             <select value={transferData.courseId} onChange={e => setTransferData({...transferData, courseId: e.target.value})} className="w-full p-4 bg-slate-50 rounded-2xl font-bold text-xs outline-none">
                <option value="">Disciplina de Destino...</option>
                {courses.map(c => <option key={c.id} value={c.id}>{c.nome}</option>)}
             </select>
             <div className="flex gap-3">
                <button onClick={() => setOpSubView('main')} className="flex-1 py-4 bg-slate-100 text-slate-400 rounded-xl font-black uppercase italic text-[10px]">Cancelar</button>
                <button onClick={async () => { if(transferData.studentId && transferData.courseId) { await updateDoc(doc(db, 'users', transferData.studentId), {cursoInicial: transferData.courseId}); alert('Sucesso!'); setOpSubView('main'); } }} className="flex-1 py-4 bg-indigo-600 text-white rounded-xl font-black uppercase italic text-[10px] shadow-lg">Efetivar</button>
             </div>
          </div>
        );
      case 'assinatura':
        return (
          <div className="bg-white p-10 rounded-[2.5rem] border border-slate-200 shadow-xl max-w-lg mx-auto text-center space-y-6 animate-in zoom-in-95">
             <div className="w-16 h-16 bg-indigo-50 rounded-2xl flex items-center justify-center mx-auto text-indigo-600 shadow-inner"><Fingerprint size={32}/></div>
             <h3 className="text-xl font-black uppercase italic tracking-tighter">Assinatura Digital</h3>
             <div className="p-6 bg-slate-50 border border-dashed rounded-3xl min-h-[100px] flex items-center justify-center">
                {secSignature ? <img src={secSignature} className="max-h-20 grayscale" /> : <p className="text-[10px] font-black uppercase text-slate-300">Nenhuma assinatura</p>}
             </div>
             <button onClick={() => setIsSignModalOpen(true)} className="w-full py-4 bg-indigo-600 text-white rounded-xl text-[10px] font-black uppercase italic shadow-xl">Nova Assinatura</button>
             <button onClick={() => setOpSubView('main')} className="text-[9px] font-black uppercase text-slate-400 underline italic">Voltar</button>
          </div>
        );
      default:
        return (
          <div className="grid grid-cols-2 md:grid-cols-5 gap-4 animate-in fade-in">
             {[
               { id: 'validacao', label: 'Validação', icon: <UserCheck/>, color: 'text-emerald-600', note: stats.countPending > 0 ? `${stats.countPending} Pendentes` : null },
               { id: 'declaracao', label: 'Declarações', icon: <FileText/>, color: 'text-indigo-600' },
               { id: 'transferencia', label: 'Transferências', icon: <ArrowRightLeft/>, color: 'text-amber-600' },
               { id: 'inadimplencia', label: 'Financeiro', icon: <ShieldAlert/>, color: 'text-rose-600' },
               { id: 'assinatura', label: 'Assinatura', icon: <Fingerprint/>, color: 'text-slate-900' }
             ].map(btn => (
               <button key={btn.id} onClick={() => setOpSubView(btn.id as any)} className="p-8 bg-white border border-slate-200 rounded-[2.5rem] flex flex-col items-center gap-4 hover:shadow-2xl hover:border-indigo-400 transition-all relative">
                  <div className={`w-14 h-14 rounded-2xl flex items-center justify-center bg-slate-50 ${btn.color}`}>{btn.icon}</div>
                  <span className="text-[10px] font-black uppercase italic text-slate-900">{btn.label}</span>
                  {btn.note && <span className="absolute top-4 right-4 bg-rose-600 text-white text-[7px] font-black px-2 py-0.5 rounded-full animate-bounce">{btn.note}</span>}
               </button>
             ))}
          </div>
        );
    }
  };

  return (
    <div className="space-y-6 pb-20 h-full">
      <header className="flex justify-between items-center">
        <div><h1 className="text-xl font-black uppercase italic tracking-tighter leading-none">Secretaria Master</h1><p className="text-[10px] text-slate-400 font-bold uppercase mt-1">Gestão de Documentos e Fluxos</p></div>
        <div className="bg-white p-1 rounded-xl border flex shadow-sm">
           {(['atendimento', 'chat', 'arquivos', 'operacional'] as any).map((t:any) => (
             <button key={t} onClick={() => { setActiveTab(t); setOpSubView('main'); }} className={`px-5 py-2 rounded-lg text-[9px] font-black uppercase italic tracking-widest ${activeTab === t ? 'bg-slate-900 text-white' : 'text-slate-400 hover:text-slate-900'}`}>{t}</button>
           ))}
        </div>
      </header>

      <main className="flex-1 min-h-[450px]">
         {activeTab === 'operacional' && renderOperationalContent()}
         {activeTab === 'atendimento' && (
           <div className="bg-white p-20 rounded-[3rem] border border-dashed border-slate-200 text-center space-y-4">
              <FolderOpen size={60} className="mx-auto text-slate-200"/>
              <h2 className="text-lg font-black uppercase italic text-slate-400">Ambiente de Gestão Restrito</h2>
              <p className="text-[9px] font-bold text-slate-300 uppercase tracking-widest italic">Acesse as notificações no topo ou use o menu operacional.</p>
           </div>
         )}
         {activeTab === 'chat' && <div className="p-10 text-center text-slate-300 font-black uppercase italic">Selecione um protocolo na lista administrativa.</div>}
      </main>

      {isSignModalOpen && <SignaturePad title="Minha Assinatura Digital" onCancel={() => setIsSignModalOpen(false)} onSave={async b => { await updateDoc(doc(db, 'users', user.uid), {signatureUrl: b}); setSecSignature(b); setIsSignModalOpen(false); alert('Assinatura Atualizada!'); }} />}
    </div>
  );
};

