        <div><h1 className="text-3xl font-black uppercase italic tracking-tighter">Gestão de Alunos</h1><p className="text-slate-500 text-sm font-medium italic">Prontuário Discente Unificado</p></div>
        <button onClick={() => { setFormData({nome:'', email:'', telefone:'', cursoId:'', status:'ativo', cpf:'', nascimento:'', fotoUrl:'', endereco:{cep:'', rua:'', numero:'', bairro:'', cidade:'', uf:''}}); setSelectedStudent(null); setIsRegisterModalOpen(true); }} className="px-8 py-4 bg-slate-900 text-white rounded-2xl text-[10px] font-black uppercase shadow-2xl hover:bg-indigo-600 transition-all italic"><UserPlus size={18} /> Novo Aluno</button>
      </header>

      <div className="bg-white rounded-[3rem] border border-slate-200 overflow-hidden shadow-sm">
        <div className="p-8 border-b bg-slate-50/30 flex items-center gap-4">
           <Search size={20} className="text-slate-400"/><input value={searchTerm} onChange={e => setSearchTerm(e.target.value)} placeholder="Pesquisar por Matrícula, Nome ou E-mail..." className="flex-1 bg-transparent border-none outline-none font-bold text-xs" />
        </div>
        <table className="w-full text-left">
          <thead className="bg-slate-50 text-[9px] font-black uppercase italic text-slate-400 border-b">
             <tr><th className="px-10 py-6">Matrícula</th><th className="px-10 py-6">Identidade Digital</th><th className="px-10 py-6">Status</th><th className="px-10 py-6 text-center">Ações</th></tr>
          </thead>
          <tbody className="divide-y divide-slate-100 text-xs">
             {filtered.map(s => (
               <tr key={s.uid} className="hover:bg-indigo-50/10 group">
                  <td className="px-10 py-6 font-mono font-black text-indigo-600">{(s as any).academicId || 'S/ID'}</td>
                  <td className="px-10 py-6">
                     <div className="flex items-center gap-4">
                        <div className="w-10 h-10 rounded-xl overflow-hidden bg-slate-100 border border-slate-200 shrink-0">
                           {(s as any).photoURL ? <img src={(s as any).photoURL} className="w-full h-full object-cover" /> : <UserIcon className="m-auto mt-2 text-slate-300" size={24}/>}
                        </div>
                        <div><p className="font-black uppercase italic text-slate-900">{s.displayName || (s as any).nome}</p><p className="text-[10px] font-bold text-slate-400">{s.email}</p></div>
                     </div>
                  </td>
                  <td className="px-10 py-6"><span className={`px-4 py-1 rounded-full text-[8px] font-black uppercase italic border ${s.status === 'ativo' ? 'bg-emerald-50 text-emerald-600 border-emerald-100' : 'bg-rose-50 text-rose-600 border-rose-100'}`}>{s.status?.replace('_', ' ')}</span></td>
                  <td className="px-10 py-6 text-center">
                     <div className="flex justify-center gap-2">
                        <button onClick={() => { setSelectedStudent(s); setIsViewModalOpen(true); }} className="p-3 text-slate-400 hover:text-indigo-600 hover:bg-white rounded-xl shadow-sm border border-slate-100 transition-all"><Eye size={16}/></button>
                        <button onClick={() => { setSelectedStudent(s); setFormData({nome: s.displayName || (s as any).nome, email: s.email || '', telefone: (s as any).telefone || '', cursoId: (s as any).cursoInicial || '', status: s.status || 'ativo', cpf: (s as any).cpf || '', nascimento: (s as any).nascimento || '', fotoUrl: (s as any).photoURL || '', endereco: (s as any).endereco || {cep:'', rua:'', numero:'', bairro:'', cidade:'', uf:''} }); setIsRegisterModalOpen(true); }} className="p-3 text-slate-400 hover:text-amber-600 hover:bg-white rounded-xl shadow-sm border border-slate-100 transition-all"><Edit3 size={16}/></button>
                        <button onClick={async () => { if(confirm('Excluir?')) await deleteDoc(doc(db, 'users', s.uid)); }} className="p-3 text-slate-400 hover:text-rose-600 hover:bg-white rounded-xl shadow-sm border border-slate-100 transition-all"><Trash2 size={16}/></button>
                     </div>
                  </td>
               </tr>
             ))}
          </tbody>
        </table>
      </div>

      {/* MODAL FICHA CADASTRAL */}
      {isViewModalOpen && selectedStudent && (
        <div className="fixed inset-0 z-[2000] bg-slate-950/90 backdrop-blur-xl flex items-center justify-center p-6 animate-in zoom-in-95">
           <div className="bg-white w-full max-w-2xl rounded-[3.5rem] overflow-hidden shadow-2xl flex flex-col">
              <header className="p-8 border-b flex justify-between items-center bg-slate-50/50">
                 <h2 className="text-xl font-black uppercase italic tracking-tighter">Dossiê Discente Digital</h2>
                 <button onClick={() => setIsViewModalOpen(false)} className="p-2 hover:bg-rose-50 rounded-full"><X size={20}/></button>
              </header>
              <div className="p-10 space-y-10 overflow-y-auto custom-scrollbar">
                 <div className="flex items-center gap-8">
                    <div className="w-32 h-32 rounded-[2.5rem] bg-slate-100 overflow-hidden border-4 border-white shadow-xl">
                       {selectedStudent.photoURL ? <img src={selectedStudent.photoURL} className="w-full h-full object-cover" /> : <UserIcon className="m-auto mt-8 text-slate-200" size={60}/>}
                    </div>
                    <div className="space-y-2">
                       <span className="text-[10px] font-black uppercase bg-indigo-600 text-white px-3 py-1 rounded-full italic">MAT: {selectedStudent.academicId || 'S/ID'}</span>
                       <h3 className="text-3xl font-black uppercase italic tracking-tighter text-slate-900">{selectedStudent.displayName || selectedStudent.nome}</h3>
                       <p className="text-sm font-bold text-slate-400">{selectedStudent.email}</p>
                    </div>
                 </div>
                 <div className="grid grid-cols-2 md:grid-cols-3 gap-6 pt-10 border-t border-slate-50">
                    <div className="space-y-1"><p className="text-[8px] font-black uppercase text-slate-400 italic">WhatsApp</p><p className="font-bold">{selectedStudent.telefone || '---'}</p></div>
                    <div className="space-y-1"><p className="text-[8px] font-black uppercase text-slate-400 italic">CPF</p><p className="font-bold">{selectedStudent.cpf || '---'}</p></div>
                    <div className="space-y-1"><p className="text-[8px] font-black uppercase text-slate-400 italic">Cadeira</p><p className="font-bold text-indigo-600 uppercase">{courses.find(c => c.id === selectedStudent.cursoInicial)?.nome || 'Não Vinculado'}</p></div>
                 </div>
                 <div className="p-6 bg-slate-50 rounded-3xl border border-slate-100">
                    <p className="text-[10px] font-black uppercase text-indigo-600 mb-2 italic flex items-center gap-2"><MapPin size={12}/> Localização</p>
                    <p className="text-xs font-bold text-slate-600 leading-relaxed italic">
                       {selectedStudent.endereco?.rua ? `${selectedStudent.endereco.rua}, ${selectedStudent.endereco.numero} - ${selectedStudent.endereco.bairro}, ${selectedStudent.endereco.cidade}/${selectedStudent.endereco.uf} - CEP: ${selectedStudent.endereco.cep}` : 'S/Endereço'}
                    </p>
                 </div>
              </div>
              <footer className="p-8 bg-slate-50 border-t flex justify-end"><button onClick={() => setIsViewModalOpen(false)} className="px-10 py-3.5 bg-slate-900 text-white rounded-xl text-[10px] font-black uppercase italic">Fechar Dossiê</button></footer>
           </div>
        </div>
      )}

      {/* MODAL CADASTRO/EDIÇÃO */}
      {isRegisterModalOpen && (
        <div className="fixed inset-0 z-[1500] bg-slate-950/80 backdrop-blur-xl flex items-center justify-center p-6 animate-in zoom-in-95">
           <div className="bg-white w-full max-w-5xl h-[90vh] rounded-[3.5rem] overflow-hidden shadow-2xl flex flex-col">
              <header className="p-8 border-b bg-slate-50/50 flex justify-between items-center">
                 <div className="flex items-center gap-4"><UserCog className="text-indigo-600"/><h2 className="text-2xl font-black uppercase italic tracking-tighter">Manutenção de Prontuário</h2></div>
                 <button onClick={() => setIsRegisterModalOpen(false)} className="p-3 hover:bg-rose-50 rounded-full"><X size={24}/></button>
