                       <div onClick={() => fileInputRef.current?.click()} className="w-40 h-40 rounded-[3rem] bg-slate-50 border-2 border-dashed border-slate-200 flex items-center justify-center cursor-pointer overflow-hidden shadow-inner group">
                          {formData.fotoUrl ? <img src={formData.fotoUrl} className="w-full h-full object-cover" /> : <Camera size={40} className="text-slate-300"/>}
                       </div>
                       <input type="file" ref={fileInputRef} className="hidden" accept="image/*" onChange={e => { const f=e.target.files?.[0]; if(f){ const r=new FileReader(); r.onload=ev=>setFormData({...formData, fotoUrl: ev.target?.result as string}); r.readAsDataURL(f); } }} />
                    </div>
                    <div className="md:col-span-3 grid grid-cols-1 md:grid-cols-2 gap-6">
                       <div className="space-y-1.5"><label className="text-[9px] font-black uppercase text-slate-400 ml-4 italic">Nome</label><input required value={formData.nome} onChange={e => setFormData({...formData, nome: e.target.value})} className="w-full p-4 bg-slate-50 rounded-2xl font-bold text-xs shadow-inner outline-none focus:ring-1 focus:ring-indigo-600" /></div>
                       <div className="space-y-1.5"><label className="text-[9px] font-black uppercase text-slate-400 ml-4 italic">E-mail</label><input required type="email" value={formData.email} onChange={e => setFormData({...formData, email: e.target.value})} className="w-full p-4 bg-slate-50 rounded-2xl font-bold text-xs shadow-inner outline-none focus:ring-1 focus:ring-indigo-600" /></div>
                       <div className="space-y-1.5"><label className="text-[9px] font-black uppercase text-slate-400 ml-4 italic">CPF</label><input required value={formData.cpf} onChange={e => setFormData({...formData, cpf: e.target.value})} className="w-full p-4 bg-slate-50 rounded-2xl font-bold text-xs shadow-inner outline-none focus:ring-1 focus:ring-indigo-600" /></div>
                       <div className="space-y-1.5"><label className="text-[9px] font-black uppercase text-slate-400 ml-4 italic">WhatsApp</label><input required value={formData.telefone} onChange={e => setFormData({...formData, telefone: e.target.value})} className="w-full p-4 bg-slate-50 rounded-2xl font-bold text-xs shadow-inner outline-none focus:ring-1 focus:ring-indigo-600" /></div>
                    </div>
                 </section>
                 <section className="space-y-8">
                    <div className="flex items-center gap-3 border-b pb-4"><MapPin className="text-indigo-600"/><h3 className="text-sm font-black uppercase italic">Localização</h3></div>
                    <div className="grid grid-cols-1 md:grid-cols-6 gap-6">
                       <input placeholder="CEP" value={formData.endereco.cep} onChange={e => setFormData({...formData, endereco: {...formData.endereco, cep: e.target.value}})} className="md:col-span-2 p-4 bg-slate-50 rounded-2xl font-bold text-xs shadow-inner outline-none" />
                       <input placeholder="Rua" value={formData.endereco.rua} onChange={e => setFormData({...formData, endereco: {...formData.endereco, rua: e.target.value}})} className="md:col-span-3 p-4 bg-slate-50 rounded-2xl font-bold text-xs shadow-inner outline-none" />
                       <input placeholder="Nº" value={formData.endereco.numero} onChange={e => setFormData({...formData, endereco: {...formData.endereco, numero: e.target.value}})} className="md:col-span-1 p-4 bg-slate-50 rounded-2xl font-bold text-xs shadow-inner outline-none" />
                    </div>
                 </section>
                 <section className="grid grid-cols-1 md:grid-cols-2 gap-6">
                    <select required value={formData.cursoId} onChange={e => setFormData({...formData, cursoId: e.target.value})} className="p-4 bg-slate-50 rounded-2xl font-black text-[10px] uppercase shadow-inner outline-none focus:ring-1 focus:ring-indigo-600"><option value="">Cadeira Acadêmica...</option>{courses.map(c => <option key={c.id} value={c.id}>{c.nome}</option>)}</select>
                    <select required value={formData.status} onChange={e => setFormData({...formData, status: e.target.value})} className="p-4 bg-slate-50 rounded-2xl font-black text-[10px] uppercase shadow-inner outline-none focus:ring-1 focus:ring-indigo-600"><option value="ativo">Ativo</option><option value="aguardando_validacao">Aguardando Validação</option><option value="suspenso">Suspenso</option></select>
                 </section>
                 <div className="flex gap-4 pt-10"><button type="button" onClick={() => setIsRegisterModalOpen(false)} className="flex-1 py-6 bg-slate-100 text-slate-400 rounded-3xl font-black uppercase italic text-[10px]">Cancelar</button><button type="submit" className="flex-[2] py-6 bg-indigo-600 text-white rounded-3xl font-black uppercase italic text-[10px] shadow-2xl">Gravar Prontuário</button></div>
              </form>
           </div>
        </div>
      )}
    </div>
  );
};

