import { BookOpen, PlayCircle, Award, ArrowLeft, GraduationCap, Zap, Bell, Menu, X, LogOut, Home, LifeBuoy, ScrollText, Smartphone, ShieldAlert, Star, Play, Settings } from 'lucide-react';

interface StudentViewProps { user: User; }
type StudentSubView = 'dashboard' | 'classroom' | 'library' | 'certificates' | 'support';

const StudentView: React.FC<StudentViewProps> = ({ user }) => {
  const [activeSubView, setActiveSubView] = useState<StudentSubView>('dashboard');
  const [enrolledCourse, setEnrolledCourse] = useState<Course | null>(null);
  const [modules, setModules] = useState<Module[]>([]);
  const [activeLesson, setActiveLesson] = useState<Lesson | null>(null);
  const [loading, setLoading] = useState(true);
  const [isSidebarOpen, setIsSidebarOpen] = useState(true);

  useEffect(() => {
    const fetchProfile = async () => {
      setLoading(true);
      const userDoc = await getDoc(doc(db, 'users', user.uid));
      if (userDoc.exists()) {
        const cId = userDoc.data().cursoInicial;
        if (cId) {
          const courseDoc = await getDoc(doc(db, 'cursos', cId));
          if (courseDoc.exists()) setEnrolledCourse({ id: courseDoc.id, ...courseDoc.data() } as Course);
        }
      }
      setLoading(false);
    };
    fetchProfile();
  }, [user.uid]);

  const handleStartLesson = () => {
    if (!enrolledCourse) return;
    onSnapshot(query(collection(db, 'modulos'), where('courseId', '==', enrolledCourse.id)), snap => {
      const mods = snap.docs.map(d => ({ id: d.id, ...d.data() } as Module)).sort((a,b) => (a.order||0)-(b.order||0));
      setModules(mods);
      if (mods.length > 0 && mods[0].lessons?.length > 0) setActiveLesson(mods[0].lessons[0]);
      setActiveSubView('classroom');
    });
  };

  if (loading) return <div className="h-screen bg-slate-950 flex items-center justify-center font-black uppercase italic text-white animate-pulse text-[10px] tracking-[0.5em]">Validando Credenciais de Acesso...</div>;

  return (
    <div className="min-h-screen bg-slate-50 flex overflow-hidden font-sans">
      <aside className={`bg-slate-900 w-72 flex flex-col transition-all duration-300 z-50 ${isSidebarOpen ? 'ml-0' : '-ml-72'}`}>
         <div className="p-8 border-b border-white/5 flex items-center gap-3">
            <div className="p-2 bg-indigo-600 text-white rounded-xl shadow-lg shadow-indigo-600/20"><GraduationCap size={24}/></div>
            <div><p className="font-black text-white uppercase italic text-lg leading-none">EB-EAD</p><p className="text-[8px] font-bold text-indigo-400 uppercase tracking-widest mt-1">Sala de Aula Master</p></div>
         </div>
         <nav className="flex-1 p-4 space-y-2 mt-4">
            {[
              { id: 'dashboard', label: 'Home Page', icon: <Home size={18}/> },
              { id: 'library', label: 'Biblioteca', icon: <BookOpen size={18}/> },
              { id: 'certificates', label: 'Meus Diplomas', icon: <Award size={18}/> },
              { id: 'support', label: 'Suporte & Ajuda', icon: <LifeBuoy size={18}/> }
            ].map(item => (
              <button key={item.id} onClick={() => setActiveSubView(item.id as any)} className={`w-full flex items-center gap-4 px-6 py-4 rounded-2xl text-[11px] font-black uppercase tracking-widest transition-all ${activeSubView === item.id ? 'bg-indigo-600 text-white shadow-xl' : 'text-slate-500 hover:text-white hover:bg-white/5'}`}>{item.icon} {item.label}</button>
            ))}
         </nav>
         <div className="p-6 border-t border-white/5 bg-black/20">
            <div className="flex items-center gap-4 p-4 bg-white/5 rounded-2xl">
               <div className="w-10 h-10 rounded-xl overflow-hidden shadow-lg">
                  {user.photoURL ? <img src={user.photoURL} className="w-full h-full object-cover" /> : <div className="w-full h-full bg-indigo-600 flex items-center justify-center text-white font-black">{(user.displayName||'U').charAt(0)}</div>}
               </div>
               <div className="flex-1 overflow-hidden">
                  <p className="text-[9px] font-black text-white uppercase italic truncate">{(user.displayName||'Aluno').split(' ')[0]}</p>
                  <p className="text-[7px] font-bold text-slate-500 uppercase mt-1 truncate">Academic: Active</p>
               </div>
               <button onClick={() => auth.signOut()} className="text-rose-500"><LogOut size={18}/></button>
            </div>
         </div>
      </aside>

      <div className="flex-1 flex flex-col h-screen overflow-hidden">
         <header className="h-20 bg-white border-b border-slate-100 flex items-center justify-between px-8 shadow-sm">
            <button onClick={() => setIsSidebarOpen(!isSidebarOpen)} className="p-2.5 bg-slate-50 text-slate-400 rounded-xl"><Menu size={20}/></button>
            <div className="flex items-center gap-4">
               <div className="flex items-center gap-2 px-4 py-2 bg-indigo-50 text-indigo-600 rounded-full border border-indigo-100"><Zap size={14} fill="currentColor"/><span className="text-[9px] font-black uppercase italic">Membro Master Digital</span></div>
               <Bell size={20} className="text-slate-300"/>
            </div>
         </header>

         <main className="flex-1 overflow-y-auto p-12 bg-slate-50">
            {activeSubView === 'dashboard' && (
              <div className="max-w-5xl mx-auto space-y-12 animate-in fade-in">
                 <h1 className="text-5xl font-black text-slate-900 uppercase italic tracking-tighter leading-[0.9]">Sua Formação <br/> <span className="text-indigo-600">Prosseguir Estudos</span></h1>
                 {enrolledCourse ? (
                   <div className="bg-white rounded-[3.5rem] border border-slate-200 shadow-2xl overflow-hidden flex flex-col lg:flex-row group transition-all hover:scale-[1.01]">
                      <div className="lg:w-1/2 h-80 lg:h-auto overflow-hidden relative">
                         <img src={enrolledCourse.capaUrl} className="w-full h-full object-cover group-hover:scale-110 transition-transform duration-1000" />
                         <div className="absolute inset-0 bg-gradient-to-t from-slate-950 via-transparent to-transparent opacity-60"></div>
                      </div>
                      <div className="flex-1 p-12 space-y-6 flex flex-col justify-center">
                         <span className="text-[10px] font-black text-indigo-600 uppercase tracking-[0.4em] italic">{enrolledCourse.categoria}</span>
                         <h2 className="text-4xl font-black text-slate-900 uppercase italic tracking-tighter leading-none">{enrolledCourse.nome}</h2>
                         <p className="text-slate-500 italic text-sm leading-relaxed">{enrolledCourse.descricao || 'Excelência em teologia bíblica.'}</p>
                         <div className="pt-4"><div className="h-3 bg-slate-100 rounded-full overflow-hidden p-0.5"><div className="h-full bg-indigo-600 rounded-full" style={{width:'0%'}}></div></div><p className="text-[9px] font-black uppercase text-slate-400 mt-3 italic">Progresso Acadêmico: 0%</p></div>
                         <button onClick={handleStartLesson} className="w-full py-6 bg-slate-900 text-white rounded-[2rem] text-[11px] font-black uppercase italic tracking-[0.3em] shadow-2xl hover:bg-indigo-600 transition-all flex items-center justify-center gap-4">
                            <PlayCircle size={24}/> Ingressar na Aula
                         </button>
                      </div>
                   </div>
                 ) : (
                   <div className="bg-white p-20 rounded-[3rem] text-center space-y-6 border border-slate-100">
                      <ShieldAlert size={40} className="mx-auto text-rose-500 animate-pulse"/>
                      <h3 className="text-xl font-black uppercase italic">Vínculo Acadêmico Pendente</h3>
                      <p className="text-xs text-slate-400 font-medium italic max-w-sm mx-auto">Sua matrícula está em processo de validação. Entre em contato com a secretaria.</p>
                   </div>
                 )}
              </div>
            )}

            {activeSubView === 'classroom' && enrolledCourse && (
               <div className="fixed inset-0 z-[1000] bg-slate-950 flex flex-col text-white animate-in slide-in-from-right duration-500">
                  <header className="h-20 bg-black/40 backdrop-blur-2xl px-8 flex items-center justify-between border-b border-white/5">
                     <button onClick={() => setActiveSubView('dashboard')} className="p-3 bg-white/5 hover:bg-white/10 rounded-2xl transition-all border border-white/5"><ArrowLeft size={20}/></button>
                     <h2 className="text-lg font-black uppercase italic tracking-tighter">{enrolledCourse.nome}</h2>
                     <div className="w-10"></div>
                  </header>
                  <div className="flex-1 flex overflow-hidden">
                     <main className="flex-1 flex flex-col bg-black relative p-6">
                        <div className="w-full h-full max-w-[1400px] mx-auto aspect-video bg-zinc-900 rounded-[2.5rem] shadow-2xl overflow-hidden border border-white/5 flex items-center justify-center">
                           {activeLesson?.videoUrl ? (
                             <iframe src={activeLesson.videoUrl.replace('watch?v=', 'embed/')} className="w-full h-full" allowFullScreen />
                           ) : (
                             <div className="text-center opacity-20"><PlayCircle size={80} className="text-indigo-500 mx-auto" /><p className="mt-4 font-black uppercase italic tracking-widest text-xs">Selecione uma lição</p></div>
                           )}
                        </div>
                        <div className="h-28 bg-black/60 backdrop-blur-3xl p-8 flex items-center justify-between border-t border-white/5 mt-auto">
                           <div><h3 className="text-2xl font-black uppercase italic tracking-tighter leading-none">{activeLesson?.title || 'Inicie seus estudos'}</h3><p className="text-slate-500 text-[10px] italic font-bold uppercase mt-2">Módulo Acadêmico EB-EAD Master</p></div>
                        </div>
                     </main>
                     <aside className="w-[400px] bg-zinc-950 border-l border-white/5 flex flex-col hidden xl:flex">
                        <div className="p-8 border-b border-white/5 bg-black/20 text-[10px] font-black uppercase text-indigo-400 tracking-widest italic">Ementa Curricular</div>
                        <div className="flex-1 overflow-y-auto p-4 space-y-4 custom-scrollbar">
                           {modules.map((m, idx) => (
                             <div key={m.id} className="bg-white/5 rounded-3xl border border-white/5 overflow-hidden">
                                <div className="px-6 py-4 bg-black/40 text-[9px] font-black uppercase italic text-slate-300">#{idx+1} {m.title}</div>
                                <div className="p-2 space-y-1">
                                   {m.lessons?.map((l, lIdx) => (
                                     <button key={l.id} onClick={() => setActiveLesson(l)} className={`w-full flex items-center gap-4 p-4 rounded-2xl transition-all text-left group ${activeLesson?.id === l.id ? 'bg-indigo-600/20 border border-indigo-500/30' : 'hover:bg-white/5'}`}>
                                        <div className={`w-9 h-9 rounded-xl flex items-center justify-center font-black text-xs shrink-0 ${activeLesson?.id === l.id ? 'bg-indigo-600 text-white' : 'bg-zinc-900 text-white/10'}`}>{lIdx+1}</div>
                                        <h4 className={`text-[10px] font-black uppercase italic leading-tight ${activeLesson?.id === l.id ? 'text-white' : 'text-slate-400'}`}>{l.title}</h4>
                                     </button>
                                   ))}
                                </div>
                             </div>
                           ))}
                        </div>
                     </aside>
                  </div>
               </div>
            )}
         </main>
      </div>
    </div>
  );
};

export default StudentView;

import React, { useState, useEffect, useMemo, useRef } from 'react';
import { collection, query, where, onSnapshot, deleteDoc, serverTimestamp, doc, setDoc, getDoc } from "https://www.gstatic.com/firebasejs/10.7.1/firebase-firestore.js";
import { db } from '../firebase';
import { User, Course } from '../types';
import { Search, UserPlus, X, Save, UserCog, Trash2, Edit3, Camera, Mail, User as UserIcon, Eye, MapPin, Smartphone, GraduationCap, BarChart3, Clock, CheckCircle2 } from 'lucide-react';

const StudentsView: React.FC = () => {
  const [students, setStudents] = useState<User[]>([]);
  const [courses, setCourses] = useState<Course[]>([]);
  const [loading, setLoading] = useState(true);
  const [searchTerm, setSearchTerm] = useState('');
  const [courseFilter, setCourseFilter] = useState('');

  const [isRegisterModalOpen, setIsRegisterModalOpen] = useState(false);
  const [isProntuarioOpen, setIsProntuarioOpen] = useState(false);
  const [selectedStudent, setSelectedStudent] = useState<any>(null);
  const [actionLoading, setActionLoading] = useState(false);
  const fileInputRef = useRef<HTMLInputElement>(null);

  const [formData, setFormData] = useState({
    nome: '', email: '', telefone: '', cursoId: '', status: 'ativo', cpf: '', nascimento: '', fotoUrl: '',
    endereco: { cep: '', rua: '', numero: '', bairro: '', cidade: '', uf: '' }
  });

  useEffect(() => {
    const unsubS = onSnapshot(query(collection(db, 'users'), where('role', '==', 'aluno')), s => {
      setStudents(s.docs.map(d => ({ uid: d.id, ...d.data() } as User)).sort((a:any, b:any) => (b.createdAt?.seconds || 0) - (a.createdAt?.seconds || 0)));
      setLoading(false);
    });
    const unsubC = onSnapshot(collection(db, 'cursos'), s => setCourses(s.docs.map(d => ({ id: d.id, ...d.data() } as Course))));
    return () => { unsubS(); unsubC(); };
  }, []);

  // Busca automática de CEP no Admin
  useEffect(() => {
    const cep = formData.endereco.cep.replace(/\D/g, '');
    if (cep.length === 8) {
      fetch(`https://viacep.com.br/ws/${cep}/json/`)
        .then(res => res.json())
        .then(data => {
          if (!data.erro) {
            setFormData(prev => ({
              ...prev,
              endereco: { 
                ...prev.endereco, 
                rua: data.logradouro, 
                bairro: data.bairro, 
                cidade: data.localidade, 
                uf: data.uf 
              }
            }));
          }
        });
    }
  }, [formData.endereco.cep]);

  const filtered = useMemo(() => students.filter(s => {
    const name = (s.displayName || (s as any).nome || '').toLowerCase();
    const aid = ((s as any).academicId || '').toLowerCase();
    const matchSearch = name.includes(searchTerm.toLowerCase()) || aid.includes(searchTerm.toLowerCase()) || s.email?.toLowerCase().includes(searchTerm.toLowerCase());
    const matchCourse = !courseFilter || (s as any).cursoInicial === courseFilter;
    return matchSearch && matchCourse;
  }), [students, searchTerm, courseFilter]);

  const handleSave = async (e: React.FormEvent) => {
    e.preventDefault();
    setActionLoading(true);
    try {
      const uid = selectedStudent?.uid || Math.random().toString(36).substring(2, 15);
      const academicId = selectedStudent?.academicId || `MAT-${new Date().getFullYear()}-${Math.random().toString(36).substring(2, 7).toUpperCase()}`;

      const payload = {
        uid,
        displayName: formData.nome,
        nome: formData.nome,
        email: formData.email.toLowerCase().trim(),
        telefone: formData.telefone,
        cpf: formData.cpf,
        nascimento: formData.nascimento,
        photoURL: formData.fotoUrl,
        endereco: formData.endereco,
        cursoInicial: formData.cursoId,
        role: 'aluno',
        status: formData.status,
        academicId,
        updatedAt: serverTimestamp(),
        createdAt: selectedStudent?.createdAt || serverTimestamp()
      };

      await setDoc(doc(db, 'users', uid), payload, { merge: true });

      // Fechamento garantido do modal
      setIsRegisterModalOpen(false);
      setSelectedStudent(null);
      setFormData({
        nome: '', email: '', telefone: '', cursoId: '', status: 'ativo', cpf: '', nascimento: '', fotoUrl: '',
        endereco: { cep: '', rua: '', numero: '', bairro: '', cidade: '', uf: '' }
      });
    } catch (err) {
      alert("Erro ao gravar dados.");
    } finally {
      setActionLoading(false);
    }
  };

  if (loading) return <div className="p-20 text-center animate-pulse font-black uppercase text-xs italic text-slate-400 tracking-widest">Acessando Registro Geral de Alunos...</div>;

  return (
    <div className="space-y-6 animate-in fade-in duration-500 max-w-full overflow-x-hidden">
      <header className="flex justify-between items-center bg-white p-6 rounded-3xl border border-slate-200 shadow-sm">
        <div>
          <h1 className="text-2xl font-black uppercase italic tracking-tighter text-slate-900 leading-none">Gestão de Alunos</h1>
          <p className="text-[10px] font-bold text-slate-400 uppercase tracking-widest mt-1">Base de Dados Acadêmica Sincronizada</p>
        </div>
        <button onClick={() => { 
          setSelectedStudent(null); 
          setFormData({nome:'', email:'', telefone:'', cursoId:'', status:'ativo', cpf:'', nascimento:'', fotoUrl:'', endereco:{cep:'', rua:'', numero:'', bairro:'', cidade:'', uf:''}});
          setIsRegisterModalOpen(true); 
        }} className="px-8 py-4 bg-slate-900 text-white rounded-2xl text-[10px] font-black uppercase shadow-2xl hover:bg-indigo-600 transition-all italic flex items-center gap-3"><UserPlus size={18} /> Nova Matrícula</button>
      </header>

      <div className="bg-white rounded-[2.5rem] border border-slate-200 overflow-hidden shadow-sm">
        <div className="p-6 border-b bg-slate-50/50 flex flex-col md:flex-row items-center gap-4">
           <div className="relative flex-1">
              <Search size={18} className="absolute left-5 top-1/2 -translate-y-1/2 text-slate-400"/>
              <input value={searchTerm} onChange={e => setSearchTerm(e.target.value)} placeholder="Pesquisar por Matrícula, Nome ou E-mail..." className="w-full pl-14 pr-6 py-4 bg-white border border-slate-200 rounded-2xl font-bold text-xs outline-none shadow-inner" />
           </div>
           <select value={courseFilter} onChange={e => setCourseFilter(e.target.value)} className="bg-white border border-slate-200 rounded-2xl px-6 py-4 text-[10px] font-black uppercase outline-none shadow-sm min-w-[250px]">
              <option value="">Todas as Disciplinas</option>
              {courses.map(c => <option key={c.id} value={c.id}>{c.nome}</option>)}
           </select>
        </div>

        <div className="overflow-x-auto">
          <table className="w-full text-left">
            <thead className="bg-slate-50 text-[9px] font-black uppercase italic text-slate-400 border-b">
               <tr>
                 <th className="px-8 py-5">Identificação (MAT)</th>
                 <th className="px-8 py-5">Dados do Aluno</th>
                 <th className="px-8 py-5">Disciplina Matriculada</th>
                 <th className="px-8 py-5">Status</th>
                 <th className="px-8 py-5 text-center">Ações</th>
               </tr>
            </thead>
            <tbody className="divide-y divide-slate-100 text-xs">
               {filtered.length === 0 ? (
                 <tr><td colSpan={5} className="p-20 text-center text-slate-300 font-black uppercase italic tracking-[0.4em]">Nenhum aluno localizado no banco</td></tr>
               ) : filtered.map(s => (
                 <tr key={s.uid} className="hover:bg-indigo-50/10 group transition-colors">
                    <td className="px-8 py-6 font-mono font-black text-indigo-600 text-sm">{(s as any).academicId || 'S/ID'}</td>
                    <td className="px-8 py-6">
                       <div className="flex items-center gap-4">
                          <div className="w-12 h-12 rounded-2xl overflow-hidden bg-slate-100 border border-slate-200 shrink-0 shadow-sm">
                             {(s as any).photoURL ? <img src={(s as any).photoURL} className="w-full h-full object-cover" /> : <UserIcon className="m-auto mt-2 text-slate-300" size={28}/>}
                          </div>
                          <div>
                            <p className="font-black uppercase italic text-slate-900 text-sm">{s.displayName || (s as any).nome}</p>
                            <p className="text-[10px] font-bold text-slate-400 mt-0.5">{s.email}</p>
                          </div>
                       </div>
                    </td>
                    <td className="px-8 py-6">
                       <span className="px-4 py-2 bg-indigo-50 text-indigo-700 rounded-xl text-[9px] font-black uppercase italic border border-indigo-100">
                          {courses.find(c => c.id === (s as any).cursoInicial)?.nome || 'Sem Cadeira Vinculada'}
                       </span>
                    </td>
                    <td className="px-8 py-6">
                       <span className={`px-4 py-1.5 rounded-full text-[8px] font-black uppercase italic border ${s.status === 'ativo' ? 'bg-emerald-50 text-emerald-600 border-emerald-100' : 'bg-rose-50 text-rose-600 border-rose-100'}`}>
                          {s.status?.replace('_', ' ')}
                       </span>
                    </td>
                    <td className="px-8 py-6 text-center">
                       <div className="flex justify-center gap-2">
                          <button onClick={() => { setSelectedStudent(s); setIsProntuarioOpen(true); }} className="p-3 text-slate-400 hover:text-indigo-600 hover:bg-white rounded-xl shadow-sm border border-slate-100 transition-all" title="Ver Prontuário Completo"><Eye size={18}/></button>
                          <button onClick={() => { 
                            setSelectedStudent(s); 
                            setFormData({
                              nome: s.displayName || (s as any).nome, 
                              email: s.email || '', 
                              telefone: (s as any).telefone || '', 
                              cursoId: (s as any).cursoInicial || '', 
                              status: s.status || 'ativo', 
                              cpf: (s as any).cpf || '', 
                              nascimento: (s as any).nascimento || '', 
                              fotoUrl: (s as any).photoURL || '', 
                              endereco: (s as any).endereco || {cep:'', rua:'', numero:'', bairro:'', cidade:'', uf:''} 
                            }); 
                            setIsRegisterModalOpen(true); 
                          }} className="p-3 text-slate-400 hover:text-amber-600 hover:bg-white rounded-xl shadow-sm border border-slate-100 transition-all"><Edit3 size={18}/></button>
                          <button onClick={async () => { if(confirm('Remover aluno do banco permanentemente?')) await deleteDoc(doc(db, 'users', s.uid)); }} className="p-3 text-slate-400 hover:text-rose-600 hover:bg-white rounded-xl shadow-sm border border-slate-100 transition-all"><Trash2 size={18}/></button>
                       </div>
                    </td>
                 </tr>
               ))}
            </tbody>
          </table>
        </div>
      </div>

      {/* PRONTUÁRIO TELA CHEIA (OVERLAY TOTAL) */}
      {isProntuarioOpen && selectedStudent && (
        <div className="fixed inset-0 z-[5000] bg-slate-50 flex flex-col animate-in slide-in-from-right duration-500 overflow-hidden">
           <header className="bg-slate-900 text-white px-10 py-6 flex items-center justify-between shadow-2xl">
              <div className="flex items-center gap-6">
                 <button onClick={() => setIsProntuarioOpen(false)} className="p-3 bg-white/10 hover:bg-white/20 rounded-2xl transition-all shadow-inner"><X size={24}/></button>
                 <div>
                    <h2 className="text-2xl font-black uppercase italic tracking-tighter leading-none">Prontuário Acadêmico Digital</h2>
                    <p className="text-[10px] font-bold text-indigo-400 uppercase tracking-[0.4em] mt-2">Dossiê Completo de Identidade e Desempenho</p>
                 </div>
              </div>
              <div className="flex items-center gap-4">
                 <div className="px-6 py-2 bg-indigo-600 rounded-xl text-[10px] font-black uppercase italic shadow-lg">Matrícula: {selectedStudent.academicId || 'S/ID'}</div>
              </div>
           </header>

           <div className="flex-1 overflow-y-auto p-12 lg:p-20 bg-slate-50 custom-scrollbar">
              <div className="max-w-7xl mx-auto grid grid-cols-1 lg:grid-cols-12 gap-12">

                 {/* Coluna Lateral: Identidade */}
                 <div className="lg:col-span-4 space-y-8">
                    <div className="bg-white p-10 rounded-[3rem] border border-slate-200 shadow-xl text-center space-y-6">
                       <div className="w-56 h-56 rounded-[3.5rem] bg-slate-50 mx-auto overflow-hidden border-8 border-white shadow-2xl">
                          {selectedStudent.photoURL ? <img src={selectedStudent.photoURL} className="w-full h-full object-cover" /> : <UserIcon className="m-auto mt-12 text-slate-200" size={100}/>}
                       </div>
                       <div className="space-y-2">
                          <h1 className="text-3xl font-black uppercase italic tracking-tighter text-slate-900">{selectedStudent.displayName || selectedStudent.nome}</h1>
                          <p className="text-sm font-bold text-slate-400">{selectedStudent.email}</p>
                       </div>
                       <div className="pt-4 flex justify-center gap-3">
