                       <div className="space-y-1.5"><label className="text-[9px] font-black uppercase text-slate-400 ml-4 italic">CPF</label><input required value={formData.cpf} onChange={e => setFormData({...formData, cpf: e.target.value})} className="w-full px-8 py-5 bg-slate-50 border-none rounded-3xl font-bold text-xs shadow-inner focus:ring-1 focus:ring-indigo-600 outline-none" /></div>
