                    <div className="grid grid-cols-1 md:grid-cols-6 gap-6">
                       <div className="md:col-span-2 space-y-1.5"><label className="text-[9px] font-black uppercase text-slate-400 ml-4">CEP (Autocompletar)</label><input placeholder="00000-000" value={formData.endereco.cep} onChange={e => setFormData({...formData, endereco: {...formData.endereco, cep: e.target.value}})} className="w-full px-8 py-5 bg-slate-50 border-none rounded-3xl font-bold text-xs shadow-inner outline-none" /></div>
                       <div className="md:col-span-3 space-y-1.5"><label className="text-[9px] font-black uppercase text-slate-400 ml-4">Logradouro / Rua</label><input placeholder="Rua..." value={formData.endereco.rua} onChange={e => setFormData({...formData, endereco: {...formData.endereco, rua: e.target.value}})} className="w-full px-8 py-5 bg-slate-50 border-none rounded-3xl font-bold text-xs shadow-inner outline-none" /></div>
                       <div className="md:col-span-1 space-y-1.5"><label className="text-[9px] font-black uppercase text-slate-400 ml-4">Nº</label><input placeholder="00" value={formData.endereco.numero} onChange={e => setFormData({...formData, endereco: {...formData.endereco, numero: e.target.value}})} className="w-full px-8 py-5 bg-slate-50 border-none rounded-3xl font-bold text-xs shadow-inner outline-none" /></div>
                       <div className="md:col-span-2 space-y-1.5"><label className="text-[9px] font-black uppercase text-slate-400 ml-4">Bairro</label><input placeholder="Bairro..." value={formData.endereco.bairro} onChange={e => setFormData({...formData, endereco: {...formData.endereco, bairro: e.target.value}})} className="w-full px-8 py-5 bg-slate-50 border-none rounded-3xl font-bold text-xs shadow-inner outline-none" /></div>
                       <div className="md:col-span-3 space-y-1.5"><label className="text-[9px] font-black uppercase text-slate-400 ml-4">Cidade</label><input placeholder="Cidade..." value={formData.endereco.cidade} onChange={e => setFormData({...formData, endereco: {...formData.endereco, cidade: e.target.value}})} className="w-full px-8 py-5 bg-slate-50 border-none rounded-3xl font-bold text-xs shadow-inner outline-none" /></div>
                       <div className="md:col-span-1 space-y-1.5"><label className="text-[9px] font-black uppercase text-slate-400 ml-4">UF</label><input placeholder="UF" maxLength={2} value={formData.endereco.uf} onChange={e => setFormData({...formData, endereco: {...formData.endereco, uf: e.target.value.toUpperCase()}})} className="w-full px-8 py-5 bg-slate-50 border-none rounded-3xl font-black text-xs shadow-inner outline-none" /></div>
                    </div>
                 </section>

                 {/* 3. VÍNCULO ACADÊMICO */}
                 <section className="grid grid-cols-1 md:grid-cols-2 gap-8">
                    <div className="space-y-1.5"><label className="text-[9px] font-black uppercase text-slate-400 ml-4 italic">Cadeira Acadêmica</label><select required value={formData.cursoId} onChange={e => setFormData({...formData, cursoId: e.target.value})} className="w-full px-8 py-5 bg-slate-50 border-none rounded-3xl font-black text-[10px] uppercase shadow-inner outline-none focus:ring-1 focus:ring-indigo-600 appearance-none"><option value="">Selecionar Disciplina...</option>{courses.map(c => <option key={c.id} value={c.id}>{c.nome}</option>)}</select></div>
                    <div className="space-y-1.5"><label className="text-[9px] font-black uppercase text-slate-400 ml-4 italic">Situação de Matrícula</label><select required value={formData.status} onChange={e => setFormData({...formData, status: e.target.value})} className="w-full px-8 py-5 bg-slate-50 border-none rounded-3xl font-black text-[10px] uppercase shadow-inner outline-none focus:ring-1 focus:ring-indigo-600 appearance-none"><option value="ativo">Ativo / Regular</option><option value="aguardando_validacao">Aguardando Validação</option><option value="suspenso">Suspenso</option><option value="concluido">Concluído</option></select></div>
                 </section>

                 <div className="flex gap-4 pt-10">
                    <button type="button" onClick={() => { setIsRegisterModalOpen(false); setSelectedStudent(null); }} className="flex-1 py-6 bg-slate-100 text-slate-400 rounded-3xl font-black uppercase italic text-[10px] hover:bg-slate-200 transition-all">Descartar</button>
                    <button type="submit" disabled={actionLoading} className="flex-[2] py-6 bg-indigo-600 text-white rounded-3xl font-black uppercase italic text-[10px] shadow-2xl shadow-indigo-100 hover:bg-indigo-700 transition-all flex items-center justify-center gap-4">{actionLoading ? 'Processando ERP...' : <><Save size={20}/> Gravar Prontuário</>}</button>
