    </div>
  );
};

export default StudentsView;

import React, { useState, useEffect, useMemo, useRef } from 'react';
import { 
  collection, query, onSnapshot, addDoc, updateDoc, 
  doc, serverTimestamp, orderBy, where, deleteDoc, getDoc
} from "https://www.gstatic.com/firebasejs/10.7.1/firebase-firestore.js";
import { db, auth } from '../firebase';
import { User } from '../types';
import { 
  Ticket as TicketIcon, AlertCircle, Clock, MessageSquare, Search, Plus, X, FolderOpen, FileText, Download, UserCheck, ShieldAlert, FileSignature, Save, PenTool, UserX, Check, ArrowRightLeft, Fingerprint, Star, Send, LayoutDashboard, History
} from 'lucide-react';
import SignaturePad from '../components/SignaturePad';

interface SecretariatViewProps { user: User; }
type SecretariatTab = 'atendimento' | 'chat' | 'arquivos' | 'operacional';
type OperationalSubView = 'main' | 'declaracao' | 'validacao' | 'transferencia' | 'inadimplencia' | 'assinatura';

const SecretariatView: React.FC<SecretariatViewProps> = ({ user }) => {
  const [activeTab, setActiveTab] = useState<SecretariatTab>('atendimento');
  const [opSubView, setOpSubView] = useState<OperationalSubView>('main');
  const [tickets, setTickets] = useState<any[]>([]);
  const [files, setFiles] = useState<any[]>([]);
  const [students, setStudents] = useState<any[]>([]);
  const [courses, setCourses] = useState<any[]>([]);
  const [searchTerm, setSearchTerm] = useState('');
  const [selectedTicketId, setSelectedTicketId] = useState<string | null>(null);
  const [chatHistory, setChatHistory] = useState<any[]>([]);
  const [chatMessage, setChatMessage] = useState('');
  const [isSignModalOpen, setIsSignModalOpen] = useState(false);
  const [secSignature, setSecSignature] = useState<string | null>(null);

  const chatEndRef = useRef<HTMLDivElement>(null);

  useEffect(() => {
    const unsubT = onSnapshot(query(collection(db, 'tickets'), orderBy('createdAt', 'desc')), s => setTickets(s.docs.map(d => ({ id: d.id, ...d.data() }))));
    const unsubF = onSnapshot(collection(db, 'secretaria_arquivos'), s => setFiles(s.docs.map(d => ({ id: d.id, ...d.data() }))));
    const unsubS = onSnapshot(query(collection(db, 'users'), where('role', '==', 'aluno')), s => setStudents(s.docs.map(d => ({ uid: d.id, ...d.data() }))));
    const unsubC = onSnapshot(collection(db, 'cursos'), s => setCourses(s.docs.map(d => ({ id: d.id, ...d.data() }))));
    getDoc(doc(db, 'users', user.uid)).then(d => d.exists() && setSecSignature(d.data().signatureUrl));
    return () => { unsubT(); unsubF(); unsubS(); unsubC(); };
  }, [user.uid]);

  useEffect(() => {
    if (!selectedTicketId) return;
    const unsubChat = onSnapshot(query(collection(db, `tickets/${selectedTicketId}/messages`), orderBy('timestamp', 'asc')), (snap) => {
      setChatHistory(snap.docs.map(d => d.data()));
      setTimeout(() => chatEndRef.current?.scrollIntoView({ behavior: 'smooth' }), 100);
    });
    return () => unsubChat();
  }, [selectedTicketId]);

  const stats = useMemo(() => {
    const pendingVal = students.filter(s => s.status === 'aguardando_validacao').length;
    return {
      abertos: tickets.filter(t => t.status === 'Pendente').length,
      emAndamento: tickets.filter(t => t.status === 'Em Atendimento').length,
      finalizados: tickets.filter(t => t.status === 'Finalizado').length,
      pendentesVal: pendingVal,
      totalGed: files.length
    };
  }, [tickets, students, files]);

  const handleSendMessage = async () => {
    if (!selectedTicketId || !chatMessage.trim()) return;
    const msg = { text: chatMessage, sender: 'Secretaria', timestamp: serverTimestamp() };
    await addDoc(collection(db, `tickets/${selectedTicketId}/messages`), msg);
    await updateDoc(doc(db, 'tickets', selectedTicketId), { lastMessage: chatMessage, lastUpdate: serverTimestamp() });
    setChatMessage('');
  };

  const renderOperational = () => {
    switch(opSubView) {
      case 'validacao':
        const pending = students.filter(s => s.status === 'aguardando_validacao' || s.status === 'pendente');
        return (
          <div className="bg-white rounded-[2.5rem] border border-slate-200 shadow-xl overflow-hidden animate-in zoom-in-95">
             <div className="p-8 border-b bg-slate-50/50 flex justify-between items-center">
                <div className="flex items-center gap-4"><UserCheck className="text-indigo-600"/><h3 className="text-xl font-black uppercase italic">Validar Novas Matrículas</h3></div>
                <button onClick={() => setOpSubView('main')} className="p-2 hover:bg-rose-50 rounded-full"><X/></button>
             </div>
             <table className="w-full text-left">
                <thead className="bg-slate-50 text-[9px] font-black uppercase italic text-slate-400 border-b">
                   <tr><th className="px-8 py-5">Solicitante</th><th className="px-8 py-5">Matrícula</th><th className="px-8 py-5">Disciplina</th><th className="px-8 py-5">Ações</th></tr>
                </thead>
                <tbody className="divide-y divide-slate-100">
                   {pending.length === 0 ? <tr><td colSpan={4} className="p-20 text-center text-slate-300 font-black italic uppercase">Sem pendências na fila</td></tr> : pending.map(s => (
                     <tr key={s.uid} className="hover:bg-indigo-50/10">
                        <td className="px-8 py-6 font-black uppercase italic text-slate-900">{s.displayName || s.nome}</td>
                        <td className="px-8 py-6 font-mono text-indigo-600 font-bold">{s.academicId}</td>
                        <td className="px-8 py-6 font-black text-slate-400 uppercase italic">{courses.find(c => c.id === s.cursoInicial)?.nome || 'Lead'}</td>
                        <td className="px-8 py-6 flex gap-2">
                           <button onClick={async () => await updateDoc(doc(db, 'users', s.uid), {status: 'ativo'})} className="px-6 py-2 bg-emerald-600 text-white rounded-xl text-[9px] font-black uppercase italic">Aprovar</button>
                           <button onClick={async () => await deleteDoc(doc(db, 'users', s.uid))} className="p-2 text-rose-500 hover:bg-rose-100 rounded-xl"><UserX size={18}/></button>
                        </td>
                     </tr>
                   ))}
                </tbody>
             </table>
          </div>
        );
      default:
        return (
          <div className="grid grid-cols-1 md:grid-cols-3 lg:grid-cols-5 gap-6 animate-in fade-in">
             {[
               { id: 'validacao', label: 'Validação', icon: <UserCheck/>, color: 'text-emerald-600', note: stats.pendentesVal > 0 ? `${stats.pendentesVal} Pendentes` : null },
               { id: 'declaracao', label: 'Declarações', icon: <FileText/>, color: 'text-indigo-600' },
               { id: 'transferencia', label: 'Transferências', icon: <ArrowRightLeft/>, color: 'text-amber-600' },
               { id: 'inadimplencia', label: 'Financeiro', icon: <ShieldAlert/>, color: 'text-rose-600' },
               { id: 'assinatura', label: 'Assinatura', icon: <Fingerprint/>, color: 'text-slate-900' }
             ].map(btn => (
               <button key={btn.id} onClick={() => setOpSubView(btn.id as any)} className="bg-white p-10 rounded-[3rem] border border-slate-200 shadow-sm flex flex-col items-center gap-4 hover:shadow-2xl hover:border-indigo-400 transition-all group relative">
                  <div className={`w-16 h-16 rounded-2xl flex items-center justify-center bg-slate-50 ${btn.color} shadow-inner group-hover:scale-110 transition-transform`}>{btn.icon}</div>
                  <span className="text-[11px] font-black uppercase italic text-slate-900">{btn.label}</span>
                  {btn.note && <span className="absolute top-6 right-6 bg-rose-600 text-white text-[8px] font-black px-3 py-1 rounded-full animate-bounce shadow-lg">{btn.note}</span>}
               </button>
             ))}
          </div>
        );
    }
  };

  return (
    <div className="space-y-8 pb-20 animate-in fade-in max-w-full">
      <header className="flex justify-between items-center bg-white p-6 rounded-3xl border border-slate-200 shadow-sm">
        <div>
           <h1 className="text-2xl font-black uppercase italic tracking-tighter text-slate-900 leading-none">Secretaria Master Digital</h1>
           <p className="text-[10px] font-bold text-slate-400 uppercase tracking-widest mt-1 italic">Ambiente de Gestão ERP - Root Access</p>
        </div>
        <div className="bg-slate-100 p-1.5 rounded-2xl border flex gap-1 shadow-inner">
           {(['atendimento', 'chat', 'arquivos', 'operacional'] as any).map((t:any) => (
             <button key={t} onClick={() => { setActiveTab(t); setOpSubView('main'); setSelectedTicketId(null); }} className={`px-6 py-3 rounded-xl text-[9px] font-black uppercase italic tracking-widest transition-all ${activeTab === t ? 'bg-slate-900 text-white shadow-xl' : 'text-slate-400 hover:text-slate-900'}`}>{t}</button>
           ))}
        </div>
      </header>

      {/* KPI INDICATORS */}
      <div className="grid grid-cols-2 md:grid-cols-4 gap-4">
         {[
           { label: 'Solicitações Pendentes', value: stats.abertos, color: 'text-amber-600', bg: 'bg-amber-50', icon: <Clock size={16}/> },
           { label: 'Em Atendimento', value: stats.emAndamento, color: 'text-indigo-600', bg: 'bg-indigo-50', icon: <MessageSquare size={16}/> },
           { label: 'Matrículas p/ Validar', value: stats.pendentesVal, color: 'text-emerald-600', bg: 'bg-emerald-50', icon: <UserCheck size={16}/> },
           { label: 'Documentos GED', value: stats.totalGed, color: 'text-slate-600', bg: 'bg-slate-50', icon: <FolderOpen size={16}/> }
         ].map((s, i) => (
           <div key={i} className={`${s.bg} p-6 rounded-[2rem] border border-slate-200 flex items-center gap-5 shadow-sm`}>
              <div className="p-3 bg-white rounded-xl text-slate-400 shadow-sm shrink-0">{s.icon}</div>
              <div><p className="text-[8px] font-black uppercase text-slate-400 mb-0.5 italic">{s.label}</p><p className="text-2xl font-black text-slate-900 tabular-nums">{s.value}</p></div>
           </div>
         ))}
      </div>

      <main className="flex-1 min-h-[600px]">
         {activeTab === 'operacional' && renderOperational()}

         {activeTab === 'atendimento' && (
