                            <td className="px-8 py-6"><span className={`px-4 py-1.5 rounded-full text-[8px] font-black uppercase border ${t.status === 'Pendente' ? 'bg-amber-50 text-amber-600 border-amber-100' : 'bg-indigo-50 text-indigo-600 border-indigo-100'}`}>{t.status}</span></td>
                            <td className="px-8 py-6 text-slate-400 font-medium italic">{t.lastUpdate?.seconds ? new Date(t.lastUpdate.seconds * 1000).toLocaleString() : 'Recent'}</td>
                            <td className="px-8 py-6 text-center"><button onClick={() => { setSelectedTicketId(t.id); setActiveTab('chat'); }} className="p-3 bg-white text-indigo-600 border border-slate-200 rounded-xl shadow-sm hover:bg-indigo-600 hover:text-white transition-all"><MessageSquare size={18}/></button></td>
