              <div className="lg:col-span-4 bg-white rounded-3xl border border-slate-200 overflow-hidden flex flex-col shadow-sm">
                 <div className="p-5 border-b bg-slate-50/50">
                    <h4 className="text-[10px] font-black uppercase text-slate-400 italic">Conversas Acadêmicas</h4>
                 </div>
                 <div className="flex-1 overflow-y-auto p-4 space-y-2 custom-scrollbar">
                    {tickets.map(t => (
                      <div key={t.id} onClick={() => setSelectedTicketId(t.id)} className={`p-5 rounded-2xl border cursor-pointer transition-all ${selectedTicketId === t.id ? 'bg-indigo-600 border-indigo-400 text-white shadow-lg' : 'bg-slate-50 hover:bg-white border-slate-100'}`}>
                         <p className="text-[10px] font-black uppercase italic">{t.user}</p>
                         <p className="text-[8px] font-bold opacity-60 mt-1 uppercase truncate">{t.lastMessage || 'Aguardando Resposta...'}</p>
                      </div>
                    ))}
                 </div>
              </div>
              <div className="lg:col-span-8 bg-white rounded-3xl border border-slate-200 flex flex-col shadow-sm overflow-hidden relative">
                 {selectedTicketId ? (
                   <>
                     <div className="p-6 border-b flex justify-between items-center bg-slate-50/30">
                        <div className="flex items-center gap-4">
                           <div className="w-10 h-10 rounded-xl bg-indigo-600 text-white flex items-center justify-center font-black italic shadow-lg">{(tickets.find(t=>t.id===selectedTicketId)?.user||'U').charAt(0)}</div>
                           <div><h4 className="text-base font-black text-slate-900 uppercase italic leading-none">{tickets.find(t=>t.id===selectedTicketId)?.user}</h4><p className="text-[9px] font-black text-indigo-600 uppercase mt-1 tracking-widest italic">Protocolo: {tickets.find(t=>t.id===selectedTicketId)?.protocolo}</p></div>
                        </div>
                        <button onClick={async () => { if(confirm('Encerrar Ticket?')) { await updateDoc(doc(db, 'tickets', selectedTicketId), {status: 'Finalizado'}); setSelectedTicketId(null); }}} className="px-6 py-2.5 bg-rose-600 text-white rounded-xl text-[9px] font-black uppercase italic shadow-lg">Finalizar Chamado</button>
                     </div>
                     <div className="flex-1 overflow-y-auto p-8 space-y-4 bg-slate-50/50 custom-scrollbar">
                        {chatHistory.map((m, i) => (
                          <div key={i} className={`flex flex-col ${m.sender === 'Secretaria' ? 'items-end' : 'items-start'}`}>
                             <div className={`max-w-[80%] p-5 rounded-[1.5rem] shadow-sm ${m.sender === 'Secretaria' ? 'bg-slate-900 text-white rounded-tr-none' : 'bg-white border border-slate-100 text-slate-700 rounded-tl-none'}`}>
                                 <p className="text-xs font-medium italic leading-relaxed">{m.text}</p>
                             </div>
                             <span className="text-[7px] font-black text-slate-300 uppercase mt-1.5 px-1">{m.sender} • {m.timestamp?.seconds ? new Date(m.timestamp.seconds * 1000).toLocaleTimeString() : 'Agora'}</span>
                          </div>
                        ))}
                        <div ref={chatEndRef} />
                     </div>
                     <div className="p-6 border-t bg-white flex gap-3">
                        <input value={chatMessage} onChange={e => setChatMessage(e.target.value)} onKeyDown={e => e.key === 'Enter' && handleSendMessage()} placeholder="RESPOSTA ACADÊMICA MASTER..." className="flex-1 bg-slate-50 border-none rounded-2xl px-6 py-4.5 text-[10px] font-black uppercase tracking-widest shadow-inner outline-none focus:ring-1 focus:ring-indigo-600" />
                        <button onClick={handleSendMessage} className="p-4 bg-slate-900 text-white rounded-2xl hover:bg-indigo-600 transition-all shadow-md"><Send size={20}/></button>
                     </div>
                   </>
                 ) : (
                   <div className="flex-1 flex flex-col items-center justify-center opacity-20 p-20 text-center gap-5">
                      <MessageSquare size={100}/>
                      <p className="text-[11px] font-black uppercase tracking-[0.6em] italic text-slate-400">Canal de Atendimento Administrativo</p>
                   </div>
                 )}
              </div>
           </div>
         )}

         {activeTab === 'arquivos' && (
            <div className="grid grid-cols-2 md:grid-cols-4 lg:grid-cols-6 gap-5 animate-in zoom-in-95">
               {files.length === 0 ? <div className="col-span-full py-20 text-center text-slate-300 font-black italic uppercase tracking-widest border-4 border-dashed rounded-[3rem]">Nenhum documento emitido pelo sistema</div> : files.map(f => (
                 <div key={f.id} className="bg-white p-6 rounded-3xl border border-slate-100 shadow-sm hover:shadow-xl transition-all group text-center flex flex-col items-center">
                    <div className="w-16 h-16 bg-slate-50 rounded-2xl flex items-center justify-center mb-4 group-hover:bg-indigo-50 transition-colors shadow-inner"><FileText size={32} className="text-indigo-500"/></div>
