                    <button className="w-full py-3 bg-slate-900 text-white rounded-xl text-[9px] font-black uppercase italic flex items-center justify-center gap-2 hover:bg-indigo-600 transition-all"><Download size={12}/> Baixar</button>
                 </div>
               ))}
            </div>
         )}
      </main>

      {isSignModalOpen && <SignaturePad title="Certificação Digital Secretário" onCancel={() => setIsSignModalOpen(false)} onSave={async b => { await updateDoc(doc(db, 'users', user.uid), {signatureUrl: b}); setSecSignature(b); setIsSignModalOpen(false); alert('Assinatura Digital Auditada!'); }} />}
    </div>
  );
};

