      <header className="flex justify-between items-center bg-slate-900 p-4 text-white">
        <h1 className="text-lg font-bold uppercase tracking-tight">Secretaria Virtual > Alunos</h1>
        <button onClick={() => { 
          setSelectedStudent(null); 
          setFormData({nome:'', emailPessoal:'', emailAcademico:'', telefone:'', cursoId:'', status:'ativo', cpf:'', nascimento:'', fotoUrl:'', senhaNova:'', endereco:{cep:'', rua:'', numero:'', bairro:'', cidade:'', uf:''}});
          setIsRegisterModalOpen(true); 
        }} className="bg-white text-slate-900 px-4 py-2 text-[11px] font-bold uppercase hover:bg-slate-200 flex items-center gap-2 shadow-sm"><UserPlus size={14} /> Matricular Aluno</button>
      </header>

      {/* FILTROS SIMPLES */}
      <div className="bg-slate-200 p-3 flex gap-2 border border-slate-300">
        <div className="relative flex-1">
          <input value={searchTerm} onChange={e => setSearchTerm(e.target.value)} placeholder="Pesquisar por Matrícula, Nome ou E-mail..." className="w-full px-4 py-2 border border-slate-400 text-xs outline-none focus:border-slate-900" />
        </div>
        <select value={courseFilter} onChange={e => setCourseFilter(e.target.value)} className="border border-slate-400 px-4 py-2 text-xs outline-none bg-white">
          <option value="">Todos os Cursos</option>
          {courses.map(c => <option key={c.id} value={c.id}>{c.nome}</option>)}
        </select>
      </div>

      {/* TABELA QUADRADA SEM BORDAS ARREDONDADAS */}
      <div className="border border-slate-300 bg-white overflow-x-auto">
        <table className="w-full text-left border-collapse">
          <thead className="bg-slate-100 border-b border-slate-300 text-[10px] font-bold uppercase text-slate-600">
            <tr>
              <th className="px-4 py-3 border-r border-slate-200">Matrícula</th>
              <th className="px-4 py-3 border-r border-slate-200">Nome Completo</th>
              <th className="px-4 py-3 border-r border-slate-200">E-mail Acadêmico (Acesso)</th>
              <th className="px-4 py-3 border-r border-slate-200">Curso Vinculado</th>
              <th className="px-4 py-3 border-r border-slate-200">Status</th>
              <th className="px-4 py-3 text-center">Ações</th>
            </tr>
          </thead>
          <tbody className="text-xs">
            {filtered.map(s => (
              <tr key={s.uid} className="border-b border-slate-200 hover:bg-slate-50 transition-colors">
                <td className="px-4 py-2 border-r border-slate-200 font-mono font-bold text-slate-700">{(s as any).academicId || 'S/ID'}</td>
                <td className="px-4 py-2 border-r border-slate-200 font-bold uppercase">{s.displayName || (s as any).nome}</td>
                <td className="px-4 py-2 border-r border-slate-200 text-slate-600">{s.email}</td>
                <td className="px-4 py-2 border-r border-slate-200 font-bold uppercase text-slate-500">
                  {courses.find(c => c.id === (s as any).cursoInicial)?.nome || 'Pendente'}
                </td>
                <td className="px-4 py-2 border-r border-slate-200 text-center">
                  <span className={`px-2 py-0.5 font-bold uppercase text-[9px] ${s.status === 'ativo' ? 'bg-green-100 text-green-700' : 'bg-red-100 text-red-700'}`}>{s.status}</span>
                </td>
                <td className="px-4 py-2 text-center flex justify-center gap-1">
                  <button onClick={() => { setSelectedStudent(s); setIsProntuarioOpen(true); }} className="p-1.5 border border-slate-300 hover:bg-slate-900 hover:text-white" title="Ver Ficha"><Eye size={14}/></button>
                  <button onClick={() => { 
                    setSelectedStudent(s); 
                    setFormData({
                      nome: s.displayName || (s as any).nome, 
                      emailPessoal: (s as any).emailPessoal || '',
                      emailAcademico: s.email || '',
                      telefone: (s as any).telefone || '', 
                      cursoId: (s as any).cursoInicial || '', 
                      status: s.status || 'ativo', 
                      cpf: (s as any).cpf || '', 
                      nascimento: (s as any).nascimento || '', 
                      fotoUrl: (s as any).photoURL || '', 
                      senhaNova: '',
                      endereco: (s as any).endereco || {cep:'', rua:'', numero:'', bairro:'', cidade:'', uf:''} 
                    }); 
                    setIsRegisterModalOpen(true); 
                  }} className="p-1.5 border border-slate-300 hover:bg-slate-900 hover:text-white" title="Editar"><Edit3 size={14}/></button>
                  <button onClick={async () => { if(confirm('Excluir aluno?')) await deleteDoc(doc(db, 'users', s.uid)); }} className="p-1.5 border border-slate-300 hover:bg-red-600 hover:text-white" title="Excluir"><Trash2 size={14}/></button>
                </td>
              </tr>
            ))}
          </tbody>
        </table>
      </div>

      {/* MODAL DE MATRÍCULA / EDIÇÃO - SIMPLES E RETO */}
      {isRegisterModalOpen && (
        <div className="fixed inset-0 z-[1000] bg-black/50 flex items-center justify-center p-0">
          <div className="bg-white w-full h-full md:w-3/4 md:h-5/6 border border-slate-400 flex flex-col shadow-2xl">
            <header className="bg-slate-900 text-white p-4 flex justify-between items-center">
              <h2 className="text-sm font-bold uppercase italic">Ficha Cadastral do Aluno</h2>
              <button onClick={() => setIsRegisterModalOpen(false)}><X size={20}/></button>
            </header>

            <form onSubmit={handleSave} className="flex-1 overflow-y-auto p-6 space-y-8 bg-slate-50">
              {/* SEÇÃO IDENTIFICAÇÃO */}
