                <h3 className="text-xs font-black uppercase border-b border-slate-300 pb-1 text-slate-500 italic">Identificação e Contato</h3>
                <div className="grid grid-cols-1 md:grid-cols-4 gap-4">
                   <div className="md:col-span-1 flex flex-col items-center gap-2">
                      <div onClick={() => fileInputRef.current?.click()} className="w-32 h-32 bg-white border border-slate-400 flex items-center justify-center cursor-pointer overflow-hidden relative group">
                        {formData.fotoUrl ? <img src={formData.fotoUrl} className="w-full h-full object-cover" /> : <div className="text-center text-[10px] text-slate-400 uppercase font-bold">Foto do Aluno</div>}
                      </div>
                      <input type="file" ref={fileInputRef} className="hidden" accept="image/*" onChange={e => { const f=e.target.files?.[0]; if(f){ const r=new FileReader(); r.onload=ev=>setFormData({...formData, fotoUrl: ev.target?.result as string}); r.readAsDataURL(f); } }} />
                   </div>
                   <div className="md:col-span-3 grid grid-cols-2 gap-4">
                      <div className="flex flex-col gap-1">
                        <span className="text-[9px] font-bold text-slate-500 uppercase">Nome Completo (Obrigatório)</span>
                        <input required value={formData.nome} onChange={e => setFormData({...formData, nome: e.target.value})} className="border border-slate-400 p-2 text-xs" placeholder="Digite o nome completo do aluno..." />
                      </div>
                      <div className="flex flex-col gap-1">
                        <span className="text-[9px] font-bold text-slate-500 uppercase">WhatsApp</span>
                        <input required value={formData.telefone} onChange={e => setFormData({...formData, telefone: e.target.value})} className="border border-slate-400 p-2 text-xs" placeholder="(00) 00000-0000" />
                      </div>
                      <div className="flex flex-col gap-1">
                        <span className="text-[9px] font-bold text-slate-500 uppercase">CPF (Obrigatório)</span>
                        <input required value={formData.cpf} onChange={e => setFormData({...formData, cpf: e.target.value})} className="border border-slate-400 p-2 text-xs" placeholder="000.000.000-00" />
                      </div>
                      <div className="flex flex-col gap-1">
                        <span className="text-[9px] font-bold text-slate-500 uppercase">Nascimento</span>
                        <input required type="date" value={formData.nascimento} onChange={e => setFormData({...formData, nascimento: e.target.value})} className="border border-slate-400 p-2 text-xs" />
                      </div>
                   </div>
                </div>
              </div>

