                   <div className="md:col-span-1 flex flex-col gap-1">
                      <span className="text-[9px] font-bold text-slate-500 uppercase">CEP</span>
                      <input required value={formData.endereco.cep} onChange={e => setFormData({...formData, endereco: {...formData.endereco, cep: e.target.value}})} className="border border-slate-400 p-2 text-xs" placeholder="00000-000" />
                   </div>
                   <div className="md:col-span-3 flex flex-col gap-1">
                      <span className="text-[9px] font-bold text-slate-500 uppercase">Rua/Avenida</span>
                      <input required value={formData.endereco.rua} onChange={e => setFormData({...formData, endereco: {...formData.endereco, rua: e.target.value}})} className="border border-slate-400 p-2 text-xs bg-slate-100" placeholder="Carregamento automático..." />
                   </div>
                   <div className="md:col-span-1 flex flex-col gap-1">
                      <span className="text-[9px] font-bold text-slate-500 uppercase">Número</span>
                      <input required value={formData.endereco.numero} onChange={e => setFormData({...formData, endereco: {...formData.endereco, numero: e.target.value}})} className="border border-slate-400 p-2 text-xs" placeholder="Nº" />
                   </div>
                   <div className="md:col-span-1 flex flex-col gap-1">
                      <span className="text-[9px] font-bold text-slate-500 uppercase">Bairro</span>
                      <input required value={formData.endereco.bairro} onChange={e => setFormData({...formData, endereco: {...formData.endereco, bairro: e.target.value}})} className="border border-slate-400 p-2 text-xs bg-slate-100" placeholder="Bairro..." />
                   </div>
