import React, { useState, useEffect, useMemo, useRef } from 'react';
import { 
  collection, query, onSnapshot, addDoc, updateDoc, 
  doc, serverTimestamp, orderBy, where, deleteDoc, getDoc
} from "https://www.gstatic.com/firebasejs/10.7.1/firebase-firestore.js";
import { db, auth } from '../firebase';
import { User } from '../types';
import { 
  Ticket as TicketIcon, AlertCircle, Clock, MessageSquare, Search, Plus, X, FolderOpen, FileText, Download, UserCheck, ShieldAlert, FileSignature, Save, PenTool, UserX, Check, ArrowRightLeft, Fingerprint, Star, Send
} from 'lucide-react';
import SignaturePad from '../components/SignaturePad';

interface SecretariatViewProps { user: User; }
type SecretariatTab = 'atendimento' | 'chat' | 'arquivos' | 'operacional';
type OperationalSubView = 'main' | 'declaracao' | 'validacao' | 'transferencia' | 'inadimplencia' | 'assinatura';

const SecretariatView: React.FC<SecretariatViewProps> = ({ user }) => {
  const [activeTab, setActiveTab] = useState<SecretariatTab>('atendimento');
  const [opSubView, setOpSubView] = useState<OperationalSubView>('main');
  const [tickets, setTickets] = useState<any[]>([]);
  const [files, setFiles] = useState<any[]>([]);
  const [students, setStudents] = useState<any[]>([]);
  const [courses, setCourses] = useState<any[]>([]);
  const [searchTerm, setSearchTerm] = useState('');
  const [selectedTicketId, setSelectedTicketId] = useState<string | null>(null);
  const [chatHistory, setChatHistory] = useState<any[]>([]);
  const [chatMessage, setChatMessage] = useState('');
  const [isSignModalOpen, setIsSignModalOpen] = useState(false);
  const [secSignature, setSecSignature] = useState<string | null>(null);

  const chatEndRef = useRef<HTMLDivElement>(null);

  useEffect(() => {
    const unsubT = onSnapshot(query(collection(db, 'tickets'), orderBy('createdAt', 'desc')), s => setTickets(s.docs.map(d => ({ id: d.id, ...d.data() }))));
    const unsubF = onSnapshot(collection(db, 'secretaria_arquivos'), s => setFiles(s.docs.map(d => ({ id: d.id, ...d.data() }))));
    const unsubS = onSnapshot(query(collection(db, 'users'), where('role', '==', 'aluno')), s => setStudents(s.docs.map(d => ({ uid: d.id, ...d.data() }))));
    const unsubC = onSnapshot(collection(db, 'cursos'), s => setCourses(s.docs.map(d => ({ id: d.id, ...d.data() }))));
    getDoc(doc(db, 'users', user.uid)).then(d => d.exists() && setSecSignature(d.data().signatureUrl));
    return () => { unsubT(); unsubF(); unsubS(); unsubC(); };
  }, [user.uid]);

  useEffect(() => {
    if (!selectedTicketId) return;
    const unsubChat = onSnapshot(query(collection(db, `tickets/${selectedTicketId}/messages`), orderBy('timestamp', 'asc')), (snap) => {
      setChatHistory(snap.docs.map(d => d.data()));
      setTimeout(() => chatEndRef.current?.scrollIntoView({ behavior: 'smooth' }), 100);
    });
    return () => unsubChat();
  }, [selectedTicketId]);

  const stats = useMemo(() => {
    const pendingVal = students.filter(s => s.status === 'aguardando_validacao').length;
    return {
      abertos: tickets.filter(t => t.status === 'Pendente').length,
      emAndamento: tickets.filter(t => t.status === 'Em Atendimento').length,
      finalizados: tickets.filter(t => t.status === 'Finalizado').length,
      pendentesVal: pendingVal,
      totalGed: files.length
    };
  }, [tickets, students, files]);

  const handleSendMessage = async () => {
    if (!selectedTicketId || !chatMessage.trim()) return;
    const msg = { text: chatMessage, sender: 'Secretaria', timestamp: serverTimestamp() };
    await addDoc(collection(db, `tickets/${selectedTicketId}/messages`), msg);
    await updateDoc(doc(db, 'tickets', selectedTicketId), { lastMessage: chatMessage, lastUpdate: serverTimestamp() });
    setChatMessage('');
  };

  return (
    <div className="space-y-4 animate-in fade-in h-full">
      {/* NAVBAR DA SECRETARIA - SIMPLES */}
      <header className="flex justify-between items-center bg-slate-900 p-4 text-white">
        <div>
           <h1 className="text-lg font-bold uppercase italic">Painel de Secretaria Master</h1>
           <p className="text-[10px] text-slate-400 font-bold uppercase">Gestão de Processos EB-EAD</p>
        </div>
        <div className="flex gap-1">
           {(['atendimento', 'chat', 'arquivos', 'operacional'] as any).map((t:any) => (
             <button key={t} onClick={() => { setActiveTab(t); setOpSubView('main'); setSelectedTicketId(null); }} className={`px-4 py-2 text-[10px] font-bold uppercase border border-slate-700 hover:bg-slate-800 ${activeTab === t ? 'bg-white text-slate-900' : 'text-slate-300'}`}>{t}</button>
           ))}
        </div>
      </header>

      {/* KPI INDICATORS - SIMPLES QUADRADOS */}
      <div className="grid grid-cols-2 md:grid-cols-4 gap-2">
         {[
           { label: 'Chamados em Aberto', value: stats.abertos, bg: 'bg-white border-l-4 border-l-amber-500' },
           { label: 'Em Atendimento', value: stats.emAndamento, bg: 'bg-white border-l-4 border-l-blue-500' },
           { label: 'Matrículas p/ Aprovar', value: stats.pendentesVal, bg: 'bg-white border-l-4 border-l-red-500' },
           { label: 'Documentos Emitidos', value: stats.totalGed, bg: 'bg-white border-l-4 border-l-green-500' }
         ].map((s, i) => (
           <div key={i} className={`${s.bg} p-4 border border-slate-300 shadow-sm`}>
              <p className="text-[9px] font-bold uppercase text-slate-500 mb-1">{s.label}</p>
              <p className="text-2xl font-black text-slate-900 tabular-nums">{s.value}</p>
           </div>
         ))}
      </div>

      <main className="flex-1 min-h-[500px]">
         {activeTab === 'operacional' && (
           <div className="grid grid-cols-2 md:grid-cols-5 gap-2">
              {[
                { id: 'validacao', label: 'Validar Matrículas', icon: <UserCheck/>, color: 'text-red-600', note: stats.pendentesVal > 0 ? `${stats.pendentesVal} Pendentes` : null },
                { id: 'declaracao', label: 'Gerar Declaração', icon: <FileText/>, color: 'text-slate-600' },
                { id: 'transferencia', label: 'Transferência', icon: <ArrowRightLeft/>, color: 'text-slate-600' },
                { id: 'assinatura', label: 'Assinatura Secretário', icon: <Fingerprint/>, color: 'text-slate-600' }
              ].map(btn => (
                <button key={btn.id} onClick={() => setOpSubView(btn.id as any)} className="bg-white p-6 border border-slate-300 flex flex-col items-center gap-3 hover:bg-slate-50 relative">
                   <div className={`${btn.color}`}>{btn.icon}</div>
                   <span className="text-[10px] font-bold uppercase text-slate-900">{btn.label}</span>
                   {btn.note && <span className="absolute top-2 right-2 bg-red-600 text-white text-[8px] px-1.5 py-0.5 font-bold uppercase animate-bounce">{btn.note}</span>}
                </button>
              ))}
           </div>
         )}

         {activeTab === 'atendimento' && (
           <div className="bg-white border border-slate-300 shadow-sm overflow-hidden">
              <div className="p-3 bg-slate-100 border-b border-slate-300 flex justify-between items-center">
                 <h3 className="font-bold uppercase text-xs italic flex items-center gap-2"><TicketIcon size={14}/> Fila de Atendimento Geral</h3>
                 <input value={searchTerm} onChange={e => setSearchTerm(e.target.value)} placeholder="Filtrar por protocolo ou aluno..." className="px-3 py-1.5 border border-slate-300 text-xs w-64 outline-none" />
              </div>
              <table className="w-full text-left border-collapse">
                 <thead className="bg-slate-50 border-b border-slate-300 text-[10px] font-bold uppercase">
                    <tr><th className="px-4 py-2 border-r border-slate-200">Protocolo</th><th className="px-4 py-2 border-r border-slate-200">Aluno</th><th className="px-4 py-2 border-r border-slate-200">Status</th><th className="px-4 py-2">Ação</th></tr>
                 </thead>
                 <tbody className="text-xs">
                    {tickets.length === 0 ? <tr><td colSpan={4} className="p-10 text-center text-slate-400 uppercase italic">Nenhum chamado pendente</td></tr> : tickets.map(t => (
                      <tr key={t.id} className="border-b border-slate-200">
                         <td className="px-4 py-2 border-r border-slate-200 font-mono font-bold">{t.protocolo}</td>
                         <td className="px-4 py-2 border-r border-slate-200 font-bold uppercase">{t.user}</td>
                         <td className="px-4 py-2 border-r border-slate-200">
                            <span className={`px-2 py-0.5 text-[9px] font-bold uppercase ${t.status === 'Pendente' ? 'bg-red-50 text-red-700' : 'bg-blue-50 text-blue-700'}`}>{t.status}</span>
                         </td>
                         <td className="px-4 py-2 text-center"><button onClick={() => { setSelectedTicketId(t.id); setActiveTab('chat'); }} className="text-blue-600 font-bold uppercase text-[10px] underline">Abrir Chat</button></td>
                      </tr>
                    ))}
                 </tbody>
              </table>
           </div>
         )}

         {activeTab === 'chat' && (
           <div className="grid grid-cols-12 gap-2 h-[600px]">
              <div className="col-span-4 border border-slate-300 bg-white flex flex-col">
                 <div className="p-3 bg-slate-900 text-white text-[10px] font-bold uppercase">Conversas Recentes</div>
                 <div className="flex-1 overflow-y-auto">
                    {tickets.map(t => (
                      <div key={t.id} onClick={() => setSelectedTicketId(t.id)} className={`p-4 border-b border-slate-200 cursor-pointer ${selectedTicketId === t.id ? 'bg-slate-200' : 'hover:bg-slate-50'}`}>
                         <p className="text-[11px] font-bold uppercase text-slate-900 leading-none">{t.user}</p>
                         <p className="text-[9px] text-slate-500 mt-1 uppercase truncate italic">{t.lastMessage || 'Aguardando Resposta'}</p>
                      </div>
                    ))}
                 </div>
              </div>
              <div className="col-span-8 border border-slate-300 bg-white flex flex-col relative">
                 {selectedTicketId ? (
                   <>
                     <div className="p-3 bg-slate-100 border-b border-slate-300 flex justify-between items-center">
                        <h4 className="text-xs font-bold uppercase italic">{tickets.find(t=>t.id===selectedTicketId)?.user}</h4>
                        <button onClick={async () => { await updateDoc(doc(db, 'tickets', selectedTicketId), {status: 'Finalizado'}); setSelectedTicketId(null); }} className="text-[9px] font-bold text-red-600 uppercase border border-red-200 px-3 py-1 bg-white hover:bg-red-50">Finalizar Ticket</button>
                     </div>
                     <div className="flex-1 overflow-y-auto p-4 space-y-3 bg-slate-50">
                        {chatHistory.map((m, i) => (
                          <div key={i} className={`flex flex-col ${m.sender === 'Secretaria' ? 'items-end' : 'items-start'}`}>
                             <div className={`max-w-[80%] p-3 border ${m.sender === 'Secretaria' ? 'bg-slate-800 text-white border-slate-900' : 'bg-white border-slate-300 text-slate-900'}`}>
                                 <p className="text-[11px] font-medium leading-relaxed italic">{m.text}</p>
                             </div>
                             <span className="text-[8px] font-bold text-slate-400 uppercase mt-1">{m.sender}</span>
                          </div>
                        ))}
                        <div ref={chatEndRef} />
                     </div>
                     <div className="p-3 border-t border-slate-300 bg-white flex gap-2">
                        <input value={chatMessage} onChange={e => setChatMessage(e.target.value)} onKeyDown={e => e.key === 'Enter' && handleSendMessage()} placeholder="RESPOSTA ADMINISTRATIVA..." className="flex-1 border border-slate-400 px-3 py-2 text-xs font-bold outline-none" />
                        <button onClick={handleSendMessage} className="bg-slate-900 text-white px-6 py-2 text-[10px] font-bold uppercase"><Send size={16}/></button>
                     </div>
                   </>
                 ) : (
                   <div className="flex-1 flex flex-col items-center justify-center opacity-30 text-center gap-2">
                      <MessageSquare size={60}/>
                      <p className="text-[10px] font-bold uppercase">Selecione uma conversa na lista lateral</p>
                   </div>
                 )}
              </div>
           </div>
         )}

         {activeTab === 'arquivos' && (
            <div className="grid grid-cols-4 md:grid-cols-6 lg:grid-cols-8 gap-2">
               {files.map(f => (
                 <div key={f.id} className="bg-white p-3 border border-slate-300 text-center flex flex-col items-center hover:bg-slate-50">
                    <FileText size={24} className="text-slate-500 mb-2"/>
                    <h5 className="text-[9px] font-bold uppercase italic text-slate-900 leading-tight mb-2 h-6 overflow-hidden">{f.title}</h5>
