                 </div>
               ))}
            </div>
         )}
      </main>

      {isSignModalOpen && <SignaturePad title="Assinatura Digital - Secretaria" onCancel={() => setIsSignModalOpen(false)} onSave={async b => { await updateDoc(doc(db, 'users', user.uid), {signatureUrl: b}); setSecSignature(b); setIsSignModalOpen(false); alert('Assinatura Auditada!'); }} />}
    </div>
  );
};

