import { User } from '../types';
import { 
  Ticket as TicketIcon, AlertCircle, Clock, MessageSquare, Search, Plus, X, FolderOpen, FileText, Download, UserCheck, ShieldAlert, FileSignature, Save, PenTool, UserX, Check, ArrowRightLeft, Fingerprint, Star, Send, Folder, Archive, CheckCircle2, ChevronRight, FileDown
} from 'lucide-react';
import SignaturePad from '../components/SignaturePad';

interface SecretariatViewProps { user: User; }
type SecretariatTab = 'atendimento' | 'chat' | 'arquivos' | 'operacional';
type OperationalSubView = 'main' | 'declaracao' | 'validacao' | 'transferencia' | 'assinatura';
type ChatFilter = 'abertos' | 'finalizados' | 'arquivados';

const SecretariatView: React.FC<SecretariatViewProps> = ({ user }) => {
  const [activeTab, setActiveTab] = useState<SecretariatTab>('atendimento');
  const [opSubView, setOpSubView] = useState<OperationalSubView>('main');
  const [chatFilter, setChatFilter] = useState<ChatFilter>('abertos');
  const [tickets, setTickets] = useState<any[]>([]);
  const [files, setFiles] = useState<any[]>([]);
  const [students, setStudents] = useState<any[]>([]);
  const [courses, setCourses] = useState<any[]>([]);
  const [searchTerm, setSearchTerm] = useState('');
  const [selectedTicketId, setSelectedTicketId] = useState<string | null>(null);
  const [chatHistory, setChatHistory] = useState<any[]>([]);
  const [chatMessage, setChatMessage] = useState('');
  const [isSignModalOpen, setIsSignModalOpen] = useState(false);
  const [secSignature, setSecSignature] = useState<string | null>(null);

  const [currentPath, setCurrentPath] = useState<string[]>([]);

  const chatEndRef = useRef<HTMLDivElement>(null);

  useEffect(() => {
    const unsubT = onSnapshot(query(collection(db, 'tickets'), orderBy('createdAt', 'desc')), s => setTickets(s.docs.map(d => ({ id: d.id, ...d.data() }))));
    const unsubF = onSnapshot(collection(db, 'secretaria_arquivos'), s => setFiles(s.docs.map(d => ({ id: d.id, ...d.data() }))));
    const unsubS = onSnapshot(query(collection(db, 'users'), where('role', '==', 'aluno')), s => setStudents(s.docs.map(d => ({ uid: d.id, ...d.data() }))));
    const unsubC = onSnapshot(collection(db, 'cursos'), s => setCourses(s.docs.map(d => ({ id: d.id, ...d.data() }))));
    getDoc(doc(db, 'users', user.uid)).then(d => d.exists() && setSecSignature(d.data().signatureUrl));
    return () => { unsubT(); unsubF(); unsubS(); unsubC(); };
  }, [user.uid]);

  useEffect(() => {
    if (!selectedTicketId) return;
    const unsubChat = onSnapshot(query(collection(db, `tickets/${selectedTicketId}/messages`), orderBy('timestamp', 'asc')), (snap) => {
      setChatHistory(snap.docs.map(d => d.data()));
      setTimeout(() => chatEndRef.current?.scrollIntoView({ behavior: 'smooth' }), 100);
    });
    return () => unsubChat();
  }, [selectedTicketId]);

  const stats = useMemo(() => {
    const pendingVal = students.filter(s => s.status === 'aguardando_validacao').length;
    return {
      abertos: tickets.filter(t => t.status === 'Pendente').length,
      finalizados: tickets.filter(t => t.status === 'Finalizado').length,
      arquivados: tickets.filter(t => t.status === 'Arquivado').length,
      pendentesVal: pendingVal,
      totalGed: files.length
    };
  }, [tickets, students, files]);

  const handleSendMessage = async () => {
    if (!selectedTicketId || !chatMessage.trim()) return;
    const msg = { text: chatMessage, sender: 'Secretaria', timestamp: serverTimestamp() };
    await addDoc(collection(db, `tickets/${selectedTicketId}/messages`), msg);
    await updateDoc(doc(db, 'tickets', selectedTicketId), { lastMessage: chatMessage, lastUpdate: serverTimestamp() });
    setChatMessage('');
  };

  const filteredTickets = tickets.filter(t => {
    const matchSearch = t.protocolo?.toLowerCase().includes(searchTerm.toLowerCase()) || t.user?.toLowerCase().includes(searchTerm.toLowerCase());
    if (activeTab === 'atendimento') return matchSearch && t.status === 'Pendente';
    if (activeTab === 'chat') {
       if (chatFilter === 'abertos') return matchSearch && t.status === 'Em Atendimento';
       if (chatFilter === 'finalizados') return matchSearch && t.status === 'Finalizado';
       if (chatFilter === 'arquivados') return matchSearch && t.status === 'Arquivado';
    }
    return matchSearch;
  });

  const renderOperational = () => {
    switch(opSubView) {
      case 'validacao':
        const pending = students.filter(s => s.status === 'aguardando_validacao');
        return (
          <div className="bg-white border border-slate-300 animate-in zoom-in-98">
             <div className="p-4 bg-slate-900 text-white flex justify-between items-center">
                <h3 className="text-xs font-bold uppercase italic flex items-center gap-2"><UserCheck size={16}/> Validação de Novas Matrículas</h3>
                <button onClick={() => setOpSubView('main')}><X size={18}/></button>
             </div>
             <table className="w-full text-left border-collapse">
                <thead className="bg-slate-50 border-b border-slate-300 text-[10px] font-bold uppercase">
                   <tr><th className="px-4 py-2 border-r border-slate-200">Aluno</th><th className="px-4 py-2 border-r border-slate-200">Curso Escolhido</th><th className="px-4 py-2">Gestão</th></tr>
                </thead>
                <tbody className="text-xs">
                   {pending.length === 0 ? <tr><td colSpan={3} className="p-10 text-center text-slate-400 italic">Sem matrículas pendentes.</td></tr> : pending.map(s => (
                     <tr key={s.uid} className="border-b border-slate-200">
                        <td className="px-4 py-3 border-r border-slate-200 font-bold uppercase">{s.displayName}</td>
                        <td className="px-4 py-3 border-r border-slate-200 font-bold text-indigo-600 uppercase">{courses.find(c=>c.id===s.cursoInicial)?.nome}</td>
                        <td className="px-4 py-3 flex gap-2">
                           <button onClick={async () => await updateDoc(doc(db, 'users', s.uid), {status: 'ativo'})} className="px-4 py-1.5 bg-emerald-600 text-white text-[10px] font-bold uppercase">Aprovar</button>
                           <button onClick={async () => await deleteDoc(doc(db, 'users', s.uid))} className="p-1.5 border border-red-300 text-red-600 hover:bg-red-50"><UserX size={14}/></button>
                        </td>
                     </tr>
                   ))}
                </tbody>
             </table>
          </div>
        );
      case 'assinatura':
        return (
          <div className="max-w-md mx-auto bg-white border border-slate-300 p-8 text-center space-y-6">
             <div className="w-16 h-16 bg-slate-100 rounded-full flex items-center justify-center mx-auto text-slate-400"><Fingerprint size={32}/></div>
             <h3 className="font-bold uppercase italic">Assinatura do Secretário</h3>
             <div className="p-4 border border-dashed border-slate-300 bg-slate-50 min-h-[100px] flex items-center justify-center">
                {secSignature ? <img src={secSignature} className="max-h-20 grayscale" /> : <p className="text-[10px] text-slate-300 uppercase">Não registrada</p>}
             </div>
             <button onClick={() => setIsSignModalOpen(true)} className="w-full py-3 bg-slate-900 text-white text-[10px] font-bold uppercase italic">Coletar Nova Assinatura</button>
             <button onClick={() => setOpSubView('main')} className="text-[10px] text-slate-400 underline uppercase">Voltar</button>
          </div>
        );
      default:
        return (
          <div className="grid grid-cols-2 md:grid-cols-5 gap-2">
             <button onClick={() => alert('Abrir Gerador de Declaração')} className="bg-white p-6 border border-slate-300 flex flex-col items-center gap-3 hover:bg-indigo-50 transition-all group">
                <div className="text-slate-400 group-hover:text-indigo-600 transition-colors"><FileText size={24}/></div>
                <span className="text-[10px] font-bold uppercase text-slate-900">Declaracão</span>
             </button>
             <button onClick={() => setOpSubView('validacao')} className="bg-white p-6 border border-slate-300 flex flex-col items-center gap-3 hover:bg-indigo-50 transition-all group relative">
                <div className="text-slate-400 group-hover:text-indigo-600 transition-colors"><UserCheck size={24}/></div>
                <span className="text-[10px] font-bold uppercase text-slate-900">Validar Aluno</span>
                {stats.pendentesVal > 0 && <span className="absolute top-2 right-2 bg-red-600 text-white text-[8px] px-1.5 py-0.5 font-bold rounded-full">{stats.pendentesVal}</span>}
             </button>
             <button onClick={() => alert('Abrir Ficha Acadêmica')} className="bg-white p-6 border border-slate-300 flex flex-col items-center gap-3 hover:bg-indigo-50 transition-all group">
                <div className="text-slate-400 group-hover:text-indigo-600 transition-colors"><FileSignature size={24}/></div>
                <span className="text-[10px] font-bold uppercase text-slate-900">Ficha Aluno</span>
             </button>
             <button onClick={() => alert('Abrir Transferências')} className="bg-white p-6 border border-slate-300 flex flex-col items-center gap-3 hover:bg-indigo-50 transition-all group">
                <div className="text-slate-400 group-hover:text-indigo-600 transition-colors"><ArrowRightLeft size={24}/></div>
                <span className="text-[10px] font-bold uppercase text-slate-900">Transferências</span>
             </button>
             <button onClick={() => setOpSubView('assinatura')} className="bg-white p-6 border border-slate-300 flex flex-col items-center gap-3 hover:bg-indigo-50 transition-all group">
                <div className="text-slate-400 group-hover:text-indigo-600 transition-colors"><Fingerprint size={24}/></div>
                <span className="text-[10px] font-bold uppercase text-slate-900">Assinatura Sec.</span>
             </button>
          </div>
        );
    }
  };

  return (
    <div className="space-y-4 animate-in fade-in h-full max-w-full overflow-hidden">
      <header className="flex flex-col md:flex-row justify-between items-center bg-slate-900 p-4 text-white gap-4">
        <div>
           <h1 className="text-xl font-black uppercase italic tracking-tighter">Secretaria Virtual - Escola Bíblica AD</h1>
           <p className="text-[9px] text-indigo-400 font-bold uppercase tracking-widest">Painel Administrativo v2.0</p>
        </div>
        <div className="flex bg-slate-800 p-1 rounded-lg">
           {(['atendimento', 'chat', 'arquivos', 'operacional'] as any).map((t:any) => (
             <button key={t} onClick={() => { setActiveTab(t); setOpSubView('main'); setSelectedTicketId(null); }} className={`px-4 py-2 text-[10px] font-bold uppercase transition-all ${activeTab === t ? 'bg-white text-slate-900' : 'text-slate-400 hover:text-white'}`}>{t}</button>
           ))}
        </div>
      </header>

      {/* KPI INDICATORS */}
      <div className="grid grid-cols-2 md:grid-cols-4 gap-2">
         <div className="bg-white border-l-4 border-l-amber-500 p-4 border border-slate-300 shadow-sm"><p className="text-[9px] font-bold text-slate-400 uppercase">Tickets Pendentes</p><p className="text-2xl font-black">{stats.abertos}</p></div>
         <div className="bg-white border-l-4 border-l-indigo-500 p-4 border border-slate-300 shadow-sm"><p className="text-[9px] font-bold text-slate-400 uppercase">Atendimentos Ativos</p><p className="text-2xl font-black">{stats.finalizados}</p></div>
         <div className="bg-white border-l-4 border-l-red-500 p-4 border border-slate-300 shadow-sm"><p className="text-[9px] font-bold text-slate-400 uppercase">Matrículas p/ Aprovar</p><p className="text-2xl font-black">{stats.pendentesVal}</p></div>
         <div className="bg-white border-l-4 border-l-emerald-500 p-4 border border-slate-300 shadow-sm"><p className="text-[9px] font-bold text-slate-400 uppercase">Total de Documentos</p><p className="text-2xl font-black">{stats.totalGed}</p></div>
      </div>

      <main className="flex-1 min-h-[600px] overflow-hidden">
         {activeTab === 'operacional' && renderOperational()}

         {activeTab === 'atendimento' && (
           <div className="bg-white border border-slate-300 overflow-hidden h-full flex flex-col">
              <div className="p-4 bg-slate-50 border-b border-slate-300 flex justify-between items-center">
                 <h3 className="font-bold text-xs uppercase italic flex items-center gap-2"><TicketIcon size={14}/> Fila de Comunicação Geral</h3>
                 <div className="relative"><Search className="absolute left-3 top-1/2 -translate-y-1/2 text-slate-400" size={14}/><input value={searchTerm} onChange={e => setSearchTerm(e.target.value)} placeholder="Filtrar por Protocolo..." className="pl-9 pr-4 py-2 border border-slate-300 text-xs w-64 outline-none focus:border-slate-900" /></div>
              </div>
              <div className="flex-1 overflow-auto">
                 <table className="w-full text-left border-collapse">
                    <thead className="bg-slate-100 border-b border-slate-300 text-[10px] font-bold uppercase sticky top-0 z-10">
                       <tr><th className="px-4 py-3 border-r border-slate-200">Protocolo</th><th className="px-4 py-3 border-r border-slate-200">Aluno / Solicitante</th><th className="px-4 py-3 border-r border-slate-200">Status</th><th className="px-4 py-3">Ações</th></tr>
                    </thead>
                    <tbody className="text-xs">
                       {filteredTickets.length === 0 ? <tr><td colSpan={4} className="p-20 text-center text-slate-400 uppercase italic">Nenhum ticket encontrado.</td></tr> : filteredTickets.map(t => (
                         <tr key={t.id} className="border-b border-slate-200 hover:bg-slate-50">
                            <td className="px-4 py-3 border-r border-slate-200 font-mono font-bold text-indigo-600">{t.protocolo}</td>
                            <td className="px-4 py-3 border-r border-slate-200 font-bold uppercase">{t.user}</td>
                            <td className="px-4 py-3 border-r border-slate-200"><span className="px-2 py-1 bg-amber-50 text-amber-600 text-[9px] font-bold uppercase border border-amber-100">{t.status}</span></td>
                            <td className="px-4 py-3 text-center"><button onClick={async () => { await updateDoc(doc(db, 'tickets', t.id), {status: 'Em Atendimento'}); setSelectedTicketId(t.id); setActiveTab('chat'); setChatFilter('abertos'); }} className="text-indigo-600 font-bold uppercase underline text-[10px]">Iniciar Atendimento</button></td>
                         </tr>
                       ))}
                    </tbody>
                 </table>
              </div>
           </div>
         )}

         {activeTab === 'chat' && (
           <div className="grid grid-cols-12 gap-2 h-[650px] border border-slate-300 bg-slate-200 p-2">
              <div className="col-span-4 bg-white border border-slate-300 flex flex-col">
                 <div className="flex border-b border-slate-300">
                    {['abertos', 'finalizados', 'arquivados'].map((f:any) => (
                      <button key={f} onClick={() => setChatFilter(f)} className={`flex-1 py-2.5 text-[9px] font-bold uppercase transition-all ${chatFilter === f ? 'bg-slate-900 text-white' : 'text-slate-400 hover:bg-slate-50'}`}>{f}</button>
                    ))}
                 </div>
                 <div className="flex-1 overflow-y-auto">
                    {filteredTickets.map(t => (
                      <div key={t.id} onClick={() => setSelectedTicketId(t.id)} className={`p-4 border-b border-slate-200 cursor-pointer ${selectedTicketId === t.id ? 'bg-indigo-50 border-r-4 border-r-indigo-600' : 'hover:bg-slate-50'}`}>
                         <p className="text-[10px] font-bold uppercase text-slate-900 leading-none">{t.user}</p>
                         <p className="text-[9px] text-indigo-600 font-mono mt-1">PROT: {t.protocolo}</p>
                         <p className="text-[8px] text-slate-400 mt-1 uppercase italic truncate">{t.lastMessage || 'Sem mensagens'}</p>
                      </div>
                    ))}
                 </div>
              </div>
              <div className="col-span-8 bg-white border border-slate-300 flex flex-col relative overflow-hidden">
                 {selectedTicketId ? (
                   <>
                     <div className="p-4 bg-slate-50 border-b border-slate-300 flex justify-between items-center">
                        <div className="flex items-center gap-3">
                           <div className="w-10 h-10 bg-indigo-600 text-white rounded flex items-center justify-center font-black italic">{(filteredTickets.find(t=>t.id===selectedTicketId)?.user||'U').charAt(0)}</div>
                           <div>
                              <h4 className="text-xs font-bold uppercase text-slate-900">{filteredTickets.find(t=>t.id===selectedTicketId)?.user}</h4>
                              <p className="text-[9px] text-slate-400 font-mono">Protocolo: {filteredTickets.find(t=>t.id===selectedTicketId)?.protocolo}</p>
                           </div>
                        </div>
                        <div className="flex gap-1">
                           <button onClick={async () => { await updateDoc(doc(db, 'tickets', selectedTicketId), {status: 'Finalizado'}); setSelectedTicketId(null); }} className="px-3 py-1.5 border border-slate-300 text-[9px] font-bold uppercase hover:bg-slate-100">Finalizar</button>
                           <button onClick={async () => { await updateDoc(doc(db, 'tickets', selectedTicketId), {status: 'Arquivado'}); setSelectedTicketId(null); }} className="px-3 py-1.5 bg-slate-900 text-white text-[9px] font-bold uppercase hover:bg-slate-800 flex items-center gap-1"><Archive size={12}/> Arquivar</button>
                        </div>
                     </div>
                     <div className="flex-1 overflow-y-auto p-6 space-y-4 bg-slate-50/50">
                        {chatHistory.map((m, i) => (
                          <div key={i} className={`flex flex-col ${m.sender === 'Secretaria' ? 'items-end' : 'items-start'}`}>
                             <div className={`max-w-[70%] p-3 border ${m.sender === 'Secretaria' ? 'bg-slate-900 text-white border-slate-900 rounded-tr-none' : 'bg-white border-slate-300 text-slate-900 rounded-tl-none'}`}>
                                 <p className="text-[11px] font-medium leading-relaxed italic">{m.text}</p>
                             </div>
                             <span className="text-[7px] font-bold text-slate-400 uppercase mt-1 px-1">{m.sender}</span>
                          </div>
                        ))}
                        <div ref={chatEndRef} />
                     </div>
                     <div className="p-4 border-t border-slate-300 bg-white flex gap-2">
                        <input value={chatMessage} onChange={e => setChatMessage(e.target.value)} onKeyDown={e => e.key === 'Enter' && handleSendMessage()} placeholder="RESPOSTA ADMINISTRATIVA..." className="flex-1 border border-slate-300 px-4 py-3 text-xs font-bold outline-none" />
                        <button onClick={handleSendMessage} className="bg-slate-900 text-white px-8 py-3 text-[10px] font-bold uppercase hover:bg-indigo-600 transition-all flex items-center gap-2"><Send size={14}/> Enviar</button>
                     </div>
                   </>
                 ) : (
                   <div className="flex-1 flex flex-col items-center justify-center opacity-20 text-center gap-2">
                      <MessageSquare size={100}/>
                      <p className="text-[11px] font-bold uppercase tracking-[0.6em]">Selecione uma conversa ativa</p>
                   </div>
                 )}
              </div>
           </div>
         )}

         {activeTab === 'arquivos' && (
            <div className="bg-white border border-slate-300 h-full flex flex-col">
               <div className="p-4 bg-slate-900 text-white flex justify-between items-center">
                  <div className="flex items-center gap-4">
                     <button onClick={() => setCurrentPath([])} className="text-[10px] font-bold uppercase italic hover:underline">Secretaria / Home</button>
                     {currentPath.map((p, i) => (
                       <React.Fragment key={i}><ChevronRight size={14} className="text-slate-500" /><button className="text-[10px] font-bold uppercase italic text-indigo-400">{p}</button></React.Fragment>
                     ))}
                  </div>
                  <button className="px-4 py-2 bg-white text-slate-900 text-[10px] font-bold uppercase flex items-center gap-2 hover:bg-slate-100 transition-all"><Plus size={14}/> Novo Diretório</button>
               </div>
               <div className="p-6 grid grid-cols-2 md:grid-cols-4 lg:grid-cols-6 gap-4">
                  {currentPath.length === 0 ? (
                     <>
                        <button onClick={() => setCurrentPath(['Matrículas'])} className="p-8 border border-slate-300 bg-slate-50 flex flex-col items-center gap-3 hover:bg-indigo-50 transition-all group">
                           <Folder size={40} className="text-slate-300 group-hover:text-indigo-500 transition-colors" />
                           <span className="text-[10px] font-bold uppercase">Matrículas</span>
                        </button>
                        <button onClick={() => setCurrentPath(['Declarações'])} className="p-8 border border-slate-300 bg-slate-50 flex flex-col items-center gap-3 hover:bg-indigo-50 transition-all group">
                           <Folder size={40} className="text-slate-300 group-hover:text-indigo-500 transition-colors" />
                           <span className="text-[10px] font-bold uppercase">Declarações</span>
                        </button>
                        <button onClick={() => setCurrentPath(['Financeiro'])} className="p-8 border border-slate-300 bg-slate-50 flex flex-col items-center gap-3 hover:bg-indigo-50 transition-all group">
                           <Folder size={40} className="text-slate-300 group-hover:text-indigo-500 transition-colors" />
                           <span className="text-[10px] font-bold uppercase">Financeiro</span>
                        </button>
                     </>
                  ) : (
                     files.filter(f => f.folder === currentPath[0]).length === 0 ? (
                        <div className="col-span-full py-20 text-center text-slate-300 italic uppercase font-bold text-xs">Diretório Vazio.</div>
                     ) : files.filter(f => f.folder === currentPath[0]).map(f => (
                        <div key={f.id} className="p-6 border border-slate-300 bg-white flex flex-col items-center gap-3 relative group">
                           <FileText size={32} className="text-indigo-400" />
                           <span className="text-[9px] font-bold uppercase text-slate-900 leading-tight text-center h-8 overflow-hidden">{f.title}</span>
                           <div className="absolute inset-0 bg-indigo-600/90 flex flex-col items-center justify-center opacity-0 group-hover:opacity-100 transition-opacity p-4">
                              <button className="w-full py-2 bg-white text-slate-900 text-[8px] font-bold uppercase flex items-center justify-center gap-1 mb-2"><FileDown size={10}/> Download</button>
                              <button className="w-full py-2 border border-white text-white text-[8px] font-bold uppercase">Deletar</button>
                           </div>
                        </div>
                     ))
                  )}
               </div>
            </div>
         )}
      </main>

      {isSignModalOpen && <SignaturePad title="Certificação Digital do Secretário" onCancel={() => setIsSignModalOpen(false)} onSave={async b => { await updateDoc(doc(db, 'users', user.uid), {signatureUrl: b}); setSecSignature(b); setIsSignModalOpen(false); alert('Assinatura Registrada!'); }} />}
    </div>
  );
};

export default SecretariatView;

import React, { useState, useEffect, useMemo, useRef } from 'react';
import { collection, query, where, onSnapshot, deleteDoc, serverTimestamp, doc, setDoc, getDocs } from "https://www.gstatic.com/firebasejs/10.7.1/firebase-firestore.js";
import { db } from '../firebase';
import { User, Course } from '../types';
import { Search, UserPlus, X, Save, UserCog, Trash2, Edit3, Camera, Eye, MapPin, ChevronLeft, ChevronRight, Filter, MoreHorizontal, Hash } from 'lucide-react';

const StudentsView: React.FC = () => {
  const [students, setStudents] = useState<User[]>([]);
  const [courses, setCourses] = useState<Course[]>([]);
  const [loading, setLoading] = useState(true);
  const [searchTerm, setSearchTerm] = useState('');
  const [courseFilter, setCourseFilter] = useState('');

  // Paginação
  const [currentPage, setCurrentPage] = useState(1);
  const itemsPerPage = 10;

  const [isRegisterModalOpen, setIsRegisterModalOpen] = useState(false);
  const [isProntuarioOpen, setIsProntuarioOpen] = useState(false);
  const [selectedStudent, setSelectedStudent] = useState<any>(null);
  const [actionLoading, setActionLoading] = useState(false);
  const fileInputRef = useRef<HTMLInputElement>(null);

  const [formData, setFormData] = useState({
    nome: '', emailPessoal: '', emailAcademico: '', telefone: '', cursoId: '', status: 'ativo', cpf: '', nascimento: '', fotoUrl: '', senhaNova: '',
    endereco: { cep: '', rua: '', numero: '', bairro: '', cidade: '', uf: '' }
  });

  useEffect(() => {
    const unsubS = onSnapshot(query(collection(db, 'users'), where('role', '==', 'aluno')), s => {
      setStudents(s.docs.map(d => ({ uid: d.id, ...d.data() } as User)).sort((a:any, b:any) => (b.createdAt?.seconds || 0) - (a.createdAt?.seconds || 0)));
      setLoading(false);
    });
    const unsubC = onSnapshot(collection(db, 'cursos'), s => setCourses(s.docs.map(d => ({ id: d.id, ...d.data() } as Course))));
    return () => { unsubS(); unsubC(); };
  }, []);

  useEffect(() => {
    if (formData.nome && !selectedStudent) {
      const names = formData.nome.trim().toLowerCase().split(' ');
      const suggested = names.length > 1 ? `${names[0]}.${names[names.length - 1]}@ebd.com` : `${names[0]}@ebd.com`;
      setFormData(prev => ({ ...prev, emailAcademico: suggested }));
    }
  }, [formData.nome, selectedStudent]);

  useEffect(() => {
    const cep = formData.endereco.cep.replace(/\D/g, '');
    if (cep.length === 8) {
      fetch(`https://viacep.com.br/ws/${cep}/json/`)
        .then(res => res.json())
        .then(data => {
          if (!data.erro) {
            setFormData(prev => ({
              ...prev,
              endereco: { ...prev.endereco, rua: data.logradouro, bairro: data.bairro, cidade: data.localidade, uf: data.uf }
            }));
          }
        });
    }
  }, [formData.endereco.cep]);

  const filtered = useMemo(() => students.filter(s => {
    const name = (s.displayName || (s as any).nome || '').toLowerCase();
    const aid = ((s as any).academicId || '').toLowerCase();
    const matchSearch = name.includes(searchTerm.toLowerCase()) || aid.includes(searchTerm.toLowerCase()) || s.email?.toLowerCase().includes(searchTerm.toLowerCase());
    const matchCourse = !courseFilter || (s as any).cursoInicial === courseFilter;
    return matchSearch && matchCourse;
  }), [students, searchTerm, courseFilter]);

  // Lógica de Paginação
  const totalPages = Math.ceil(filtered.length / itemsPerPage);
  const currentTableData = useMemo(() => {
    const start = (currentPage - 1) * itemsPerPage;
    return filtered.slice(start, start + itemsPerPage);
  }, [filtered, currentPage]);

  const handleSave = async (e: React.FormEvent) => {
    e.preventDefault();
    setActionLoading(true);
    try {
      const uid = selectedStudent?.uid || Math.random().toString(36).substring(2, 15);
      const academicId = selectedStudent?.academicId || `MAT-${new Date().getFullYear()}-${Math.random().toString(36).substring(2, 7).toUpperCase()}`;

      const payload: any = {
        uid,
        displayName: formData.nome,
        nome: formData.nome,
        email: formData.emailAcademico.toLowerCase().trim(),
        emailPessoal: formData.emailPessoal.toLowerCase().trim(),
        telefone: formData.telefone,
        cpf: formData.cpf,
        nascimento: formData.nascimento,
        photoURL: formData.fotoUrl,
        endereco: formData.endereco,
        cursoInicial: formData.cursoId,
        role: 'aluno',
        status: selectedStudent ? formData.status : 'ativo',
        academicId,
        updatedAt: serverTimestamp(),
        createdAt: selectedStudent?.createdAt || serverTimestamp()
      };

      if (formData.senhaNova) payload.password = formData.senhaNova;

      await setDoc(doc(db, 'users', uid), payload, { merge: true });
      setIsRegisterModalOpen(false);
      setSelectedStudent(null);
      setFormData({
        nome: '', emailPessoal: '', emailAcademico: '', telefone: '', cursoId: '', status: 'ativo', cpf: '', nascimento: '', fotoUrl: '', senhaNova: '',
        endereco: { cep: '', rua: '', numero: '', bairro: '', cidade: '', uf: '' }
      });
    } catch (err) {
      alert("Erro ao gravar dados.");
    } finally {
      setActionLoading(false);
    }
  };

  if (loading) return <div className="p-10 font-mono text-[10px] tracking-widest uppercase">Acessando Registro Geral...</div>;

  return (
    <div className="space-y-1 animate-in fade-in duration-300">
      {/* HEADER ELEGANTE E RETO */}
      <header className="flex justify-between items-center bg-white border border-slate-200 p-6 shadow-sm">
        <div>
          <h1 className="text-xl font-black uppercase italic tracking-tighter text-slate-900 leading-none">Gestão de Discentes</h1>
          <p className="text-[10px] font-bold text-slate-400 uppercase tracking-[0.3em] mt-2">Base de Dados Sincronizada EB-AD</p>
        </div>
        <button onClick={() => { 
          setSelectedStudent(null); 
          setFormData({nome:'', emailPessoal:'', emailAcademico:'', telefone:'', cursoId:'', status:'ativo', cpf:'', nascimento:'', fotoUrl:'', senhaNova:'', endereco:{cep:'', rua:'', numero:'', bairro:'', cidade:'', uf:''}});
          setIsRegisterModalOpen(true); 
        }} className="bg-slate-900 text-white px-8 py-3 text-[10px] font-black uppercase italic hover:bg-indigo-600 transition-all flex items-center gap-3 shadow-lg shadow-slate-200"><UserPlus size={16} /> Matricular Aluno</button>
      </header>

      {/* ÁREA DE FILTROS - DESIGN RETO */}
      <div className="bg-white border-x border-slate-200 p-4 flex flex-col md:flex-row items-center gap-4">
        <div className="relative flex-1 w-full">
          <Search size={16} className="absolute left-4 top-1/2 -translate-y-1/2 text-slate-400" />
          <input 
            value={searchTerm} 
            onChange={e => { setSearchTerm(e.target.value); setCurrentPage(1); }} 
            placeholder="Pesquisar por Matrícula, Nome ou E-mail..." 
            className="w-full pl-12 pr-4 py-3 bg-slate-50 border border-slate-200 text-xs font-bold outline-none focus:border-indigo-500 focus:bg-white transition-all" 
          />
        </div>
        <div className="flex gap-2 w-full md:w-auto">
          <div className="relative">
            <Filter size={14} className="absolute left-3 top-1/2 -translate-y-1/2 text-slate-400" />
            <select 
              value={courseFilter} 
              onChange={e => { setCourseFilter(e.target.value); setCurrentPage(1); }} 
              className="pl-10 pr-10 py-3 bg-slate-50 border border-slate-200 text-[10px] font-black uppercase outline-none focus:border-indigo-500 appearance-none min-w-[200px]"
            >
              <option value="">Todas as Disciplinas</option>
              {courses.map(c => <option key={c.id} value={c.id}>{c.nome}</option>)}
            </select>
          </div>
        </div>
      </div>

      {/* TABELA - DESIGN ELEGANTE E RETO */}
      <div className="bg-white border border-slate-200 overflow-hidden shadow-sm">
        <table className="w-full text-left border-collapse">
          <thead className="bg-slate-50 border-b border-slate-200 text-[10px] font-black uppercase text-slate-500 italic tracking-widest">
            <tr>
              <th className="px-6 py-4 border-r border-slate-100"><div className="flex items-center gap-2"><Hash size={12}/> Matrícula</div></th>
              <th className="px-6 py-4 border-r border-slate-100">Nome do Aluno</th>
              <th className="px-6 py-4 border-r border-slate-100">E-mail Acadêmico</th>
              <th className="px-6 py-4 border-r border-slate-100">Disciplina</th>
              <th className="px-6 py-4 border-r border-slate-100 text-center">Status</th>
              <th className="px-6 py-4 text-center">Ações</th>
            </tr>
          </thead>
          <tbody className="text-xs">
            {currentTableData.length === 0 ? (
              <tr><td colSpan={6} className="p-20 text-center text-slate-300 font-black uppercase italic tracking-[0.5em]">Nenhum registro localizado</td></tr>
            ) : currentTableData.map(s => (
              <tr key={s.uid} className="border-b border-slate-100 hover:bg-indigo-50/20 transition-colors group">
                <td className="px-6 py-4 border-r border-slate-50 font-mono font-bold text-indigo-600">{(s as any).academicId || '---'}</td>
                <td className="px-6 py-4 border-r border-slate-50">
                  <div className="flex items-center gap-3">
                    <div className="w-8 h-8 bg-slate-100 border border-slate-200 overflow-hidden shrink-0">
                      {(s as any).photoURL ? <img src={(s as any).photoURL} className="w-full h-full object-cover" /> : <div className="w-full h-full flex items-center justify-center text-[10px] font-bold text-slate-300">{(s.displayName || 'U').charAt(0)}</div>}
                    </div>
                    <span className="font-black uppercase italic text-slate-900 tracking-tight">{s.displayName || (s as any).nome}</span>
                  </div>
                </td>
                <td className="px-6 py-4 border-r border-slate-50 text-slate-500 font-medium">{s.email}</td>
                <td className="px-6 py-4 border-r border-slate-50">
                  <span className="px-3 py-1 bg-slate-100 text-slate-600 text-[9px] font-black uppercase italic border border-slate-200">
                    {courses.find(c => c.id === (s as any).cursoInicial)?.nome || 'Pendente'}
                  </span>
                </td>
                <td className="px-6 py-4 border-r border-slate-50 text-center">
                  <span className={`px-3 py-1 font-black uppercase italic text-[8px] border ${s.status === 'ativo' ? 'bg-emerald-50 text-emerald-700 border-emerald-100' : 'bg-rose-50 text-rose-700 border-rose-100'}`}>{s.status}</span>
                </td>
                <td className="px-6 py-4 text-center">
                  <div className="flex justify-center gap-1 opacity-40 group-hover:opacity-100 transition-opacity">
                    <button onClick={() => { setSelectedStudent(s); setIsProntuarioOpen(true); }} className="p-2 border border-slate-200 hover:bg-slate-900 hover:text-white transition-all"><Eye size={14}/></button>
                    <button onClick={() => { 
                      setSelectedStudent(s); 
                      setFormData({
                        nome: s.displayName || (s as any).nome, 
                        emailPessoal: (s as any).emailPessoal || '',
                        emailAcademico: s.email || '',
                        telefone: (s as any).telefone || '', 
                        cursoId: (s as any).cursoInicial || '', 
                        status: s.status || 'ativo', 
                        cpf: (s as any).cpf || '', 
                        nascimento: (s as any).nascimento || '', 
                        fotoUrl: (s as any).photoURL || '', 
                        senhaNova: '',
                        endereco: (s as any).endereco || {cep:'', rua:'', numero:'', bairro:'', cidade:'', uf:''} 
                      }); 
                      setIsRegisterModalOpen(true); 
                    }} className="p-2 border border-slate-200 hover:bg-slate-900 hover:text-white transition-all"><Edit3 size={14}/></button>
                    <button onClick={async () => { if(confirm('Remover aluno definitivamente?')) await deleteDoc(doc(db, 'users', s.uid)); }} className="p-2 border border-slate-200 hover:bg-rose-600 hover:text-white transition-all"><Trash2 size={14}/></button>
                  </div>
                </td>
              </tr>
            ))}
          </tbody>
        </table>

        {/* PAGINAÇÃO DINÂMICA */}
        <div className="bg-slate-50 px-6 py-4 border-t border-slate-200 flex justify-between items-center">
           <p className="text-[10px] font-bold text-slate-400 uppercase italic">Exibindo {currentTableData.length} de {filtered.length} registros</p>
           <div className="flex gap-1">
              <button 
                disabled={currentPage === 1}
                onClick={() => setCurrentPage(prev => prev - 1)}
                className={`p-2 border border-slate-300 transition-all ${currentPage === 1 ? 'opacity-20 cursor-not-allowed' : 'hover:bg-white active:scale-95'}`}
              ><ChevronLeft size={16}/></button>
              <div className="flex items-center px-4 border border-slate-300 bg-white font-black text-[10px] italic">{currentPage} / {totalPages || 1}</div>
              <button 
                disabled={currentPage === totalPages || totalPages === 0}
                onClick={() => setCurrentPage(prev => prev + 1)}
                className={`p-2 border border-slate-300 transition-all ${currentPage === totalPages || totalPages === 0 ? 'opacity-20 cursor-not-allowed' : 'hover:bg-white active:scale-95'}`}
              ><ChevronRight size={16}/></button>
           </div>
        </div>
      </div>

      {/* MODAL DE CADASTRO/EDIÇÃO - REFINADO E RETO */}
      {isRegisterModalOpen && (
        <div className="fixed inset-0 z-[1000] bg-slate-900/60 backdrop-blur-sm flex items-center justify-center p-0 md:p-10 animate-in fade-in">
          <div className="bg-white w-full h-full md:max-w-5xl md:h-auto border border-slate-300 shadow-2xl flex flex-col">
            <header className="bg-slate-900 text-white p-6 flex justify-between items-center">
              <div className="flex items-center gap-4">
                <div className="p-3 bg-indigo-600 shadow-lg"><UserCog size={20}/></div>
                <div>
                  <h2 className="text-lg font-black uppercase italic tracking-tighter">Prontuário Discente Master</h2>
                  <p className="text-[9px] font-bold text-indigo-400 uppercase tracking-widest">Entrada de Dados Acadêmicos</p>
                </div>
              </div>
              <button onClick={() => setIsRegisterModalOpen(false)} className="hover:rotate-90 transition-transform"><X size={24}/></button>
            </header>

            <form onSubmit={handleSave} className="flex-1 overflow-y-auto p-10 space-y-12 bg-slate-50 custom-scrollbar">
              <section className="space-y-6">
                <h3 className="text-[10px] font-black uppercase border-l-4 border-indigo-600 pl-4 text-slate-800 italic">Identificação e Contato</h3>
                <div className="grid grid-cols-1 md:grid-cols-4 gap-8">
                   <div className="md:col-span-1 flex flex-col items-center gap-3">
                      <div onClick={() => fileInputRef.current?.click()} className="w-40 h-40 bg-white border border-slate-300 flex items-center justify-center cursor-pointer overflow-hidden relative group shadow-inner">
                        {formData.fotoUrl ? <img src={formData.fotoUrl} className="w-full h-full object-cover" /> : <div className="text-center text-[9px] text-slate-400 uppercase font-black px-6 opacity-30"><Camera size={32} className="mx-auto mb-2"/> Upload Foto</div>}
                        <div className="absolute inset-0 bg-slate-900/40 opacity-0 group-hover:opacity-100 transition-all flex items-center justify-center"><Camera size={24} className="text-white"/></div>
                      </div>
                      <input type="file" ref={fileInputRef} className="hidden" accept="image/*" onChange={e => { const f=e.target.files?.[0]; if(f){ const r=new FileReader(); r.onload=ev=>setFormData({...formData, fotoUrl: ev.target?.result as string}); r.readAsDataURL(f); } }} />
                   </div>
                   <div className="md:col-span-3 grid grid-cols-2 gap-5">
                      <div className="flex flex-col gap-1.5"><span className="text-[9px] font-black text-slate-400 uppercase italic ml-2">Nome Completo</span><input required value={formData.nome} onChange={e => setFormData({...formData, nome: e.target.value})} className="border border-slate-200 bg-white p-4 text-xs font-bold outline-none focus:border-indigo-500 shadow-sm" placeholder="Nome do Aluno..." /></div>
                      <div className="flex flex-col gap-1.5"><span className="text-[9px] font-black text-slate-400 uppercase italic ml-2">WhatsApp</span><input required value={formData.telefone} onChange={e => setFormData({...formData, telefone: e.target.value})} className="border border-slate-200 bg-white p-4 text-xs font-bold outline-none focus:border-indigo-500 shadow-sm" placeholder="(00) 00000-0000" /></div>
                      <div className="flex flex-col gap-1.5"><span className="text-[9px] font-black text-slate-400 uppercase italic ml-2">Documento CPF</span><input required value={formData.cpf} onChange={e => setFormData({...formData, cpf: e.target.value})} className="border border-slate-200 bg-white p-4 text-xs font-bold outline-none focus:border-indigo-500 shadow-sm" placeholder="000.000.000-00" /></div>
                      <div className="flex flex-col gap-1.5"><span className="text-[9px] font-black text-slate-400 uppercase italic ml-2">Data Nascimento</span><input required type="date" value={formData.nascimento} onChange={e => setFormData({...formData, nascimento: e.target.value})} className="border border-slate-200 bg-white p-4 text-xs font-bold outline-none focus:border-indigo-500 shadow-sm uppercase" /></div>
                   </div>
                </div>
              </section>

              <section className="space-y-6">
                <h3 className="text-[10px] font-black uppercase border-l-4 border-indigo-600 pl-4 text-slate-800 italic">Endereço de Correspondência</h3>
                <div className="grid grid-cols-1 md:grid-cols-6 gap-4">
                   <div className="md:col-span-1 flex flex-col gap-1.5"><span className="text-[9px] font-black text-slate-400 uppercase italic ml-2">CEP</span><input required value={formData.endereco.cep} onChange={e => setFormData({...formData, endereco: {...formData.endereco, cep: e.target.value}})} className="border border-slate-200 bg-white p-4 text-xs font-bold outline-none focus:border-indigo-500 shadow-sm" placeholder="00000-000" /></div>
                   <div className="md:col-span-4 flex flex-col gap-1.5"><span className="text-[9px] font-black text-slate-400 uppercase italic ml-2">Logradouro / Rua</span><input required value={formData.endereco.rua} onChange={e => setFormData({...formData, endereco: {...formData.endereco, rua: e.target.value}})} className="border border-slate-200 bg-slate-100 p-4 text-xs font-bold outline-none shadow-inner" placeholder="Rua..." /></div>
                   <div className="md:col-span-1 flex flex-col gap-1.5"><span className="text-[9px] font-black text-slate-400 uppercase italic ml-2">Nº</span><input required value={formData.endereco.numero} onChange={e => setFormData({...formData, endereco: {...formData.endereco, numero: e.target.value}})} className="border border-slate-200 bg-white p-4 text-xs font-bold outline-none focus:border-indigo-500 shadow-sm" placeholder="S/N" /></div>
                   <div className="md:col-span-2 flex flex-col gap-1.5"><span className="text-[9px] font-black text-slate-400 uppercase italic ml-2">Bairro</span><input required value={formData.endereco.bairro} onChange={e => setFormData({...formData, endereco: {...formData.endereco, bairro: e.target.value}})} className="border border-slate-200 bg-slate-100 p-4 text-xs font-bold outline-none shadow-inner" /></div>
                   <div className="md:col-span-3 flex flex-col gap-1.5"><span className="text-[9px] font-black text-slate-400 uppercase italic ml-2">Cidade</span><input required value={formData.endereco.cidade} onChange={e => setFormData({...formData, endereco: {...formData.endereco, cidade: e.target.value}})} className="border border-slate-200 bg-slate-100 p-4 text-xs font-bold outline-none shadow-inner" /></div>
                   <div className="md:col-span-1 flex flex-col gap-1.5"><span className="text-[9px] font-black text-slate-400 uppercase italic ml-2">UF</span><input required value={formData.endereco.uf} onChange={e => setFormData({...formData, endereco: {...formData.endereco, uf: e.target.value.toUpperCase()}})} className="border border-slate-200 bg-slate-100 p-4 text-xs font-black outline-none shadow-inner uppercase" maxLength={2} /></div>
                </div>
              </section>

              <section className="space-y-6">
                <h3 className="text-[10px] font-black uppercase border-l-4 border-indigo-600 pl-4 text-slate-800 italic">Gestão de Acesso e Vínculo</h3>
                <div className="grid grid-cols-1 md:grid-cols-2 gap-8">
                   <div className="space-y-4">
                      <div className="flex flex-col gap-1.5"><span className="text-[9px] font-black text-slate-400 uppercase italic ml-2">E-mail Acadêmico (Login)</span><input value={formData.emailAcademico} onChange={e => setFormData({...formData, emailAcademico: e.target.value})} className="border border-slate-200 bg-white p-4 text-xs font-black text-indigo-600 outline-none focus:border-indigo-500 shadow-sm" /></div>
                      <div className="flex flex-col gap-1.5"><span className="text-[9px] font-black text-rose-500 uppercase italic ml-2">Redefinir Senha</span><input type="password" value={formData.senhaNova} onChange={e => setFormData({...formData, senhaNova: e.target.value})} className="border border-rose-100 bg-white p-4 text-xs font-bold outline-none focus:border-rose-500 shadow-sm" placeholder="Nova senha (opcional)..." /></div>
                   </div>
                   <div className="space-y-4">
                      <div className="flex flex-col gap-1.5"><span className="text-[9px] font-black text-slate-400 uppercase italic ml-2">Curso / Disciplina Destino</span><select required value={formData.courseId} onChange={e => setFormData({...formData, cursoId: e.target.value})} className="border border-slate-200 bg-white p-4 text-xs font-black uppercase outline-none focus:border-indigo-500 shadow-sm appearance-none"><option value="">Selecionar Disciplina...</option>{courses.map(c => <option key={c.id} value={c.id}>{c.nome}</option>)}</select></div>
                      <div className="flex flex-col gap-1.5"><span className="text-[9px] font-black text-slate-400 uppercase italic ml-2">E-mail Pessoal</span><input type="email" value={formData.emailPessoal} onChange={e => setFormData({...formData, emailPessoal: e.target.value})} className="border border-slate-200 bg-white p-4 text-xs font-bold outline-none focus:border-indigo-500 shadow-sm" placeholder="exemplo@gmail.com" /></div>
                   </div>
                </div>
              </section>

              <div className="pt-8 border-t border-slate-200 flex gap-4">
                <button type="button" onClick={() => setIsRegisterModalOpen(false)} className="px-10 py-4 border border-slate-300 text-[10px] font-black uppercase italic hover:bg-slate-200 transition-all">Cancelar</button>
                <button type="submit" disabled={actionLoading} className="flex-1 py-4 bg-slate-900 text-white text-[10px] font-black uppercase italic tracking-widest hover:bg-indigo-600 shadow-2xl transition-all flex items-center justify-center gap-4">
                  {actionLoading ? <RefreshCw className="animate-spin" size={16}/> : <><Save size={20}/> Gravar Alterações no Banco</>}
                </button>
              </div>
            </form>
          </div>
        </div>
      )}

      {/* PRONTUÁRIO TELA CHEIA - ELEGANTE */}
      {isProntuarioOpen && selectedStudent && (
        <div className="fixed inset-0 z-[2000] bg-white flex flex-col animate-in slide-in-from-bottom-5">
          <header className="bg-slate-900 text-white p-6 flex justify-between items-center shadow-xl shrink-0">
            <div className="flex items-center gap-6">
               <button onClick={() => setIsProntuarioOpen(false)} className="p-3 bg-white/10 hover:bg-white/20 transition-all border border-white/5"><ArrowLeft size={24}/></button>
               <div>
                  <h2 className="text-xl font-black uppercase italic tracking-tighter leading-none">Dossiê Acadêmico: {selectedStudent.displayName || selectedStudent.nome}</h2>
                  <p className="text-[9px] font-bold text-indigo-400 uppercase tracking-[0.4em] mt-2">Prontuário Digital • Matrícula {selectedStudent.academicId || 'S/ID'}</p>
               </div>
            </div>
            <button onClick={() => setIsProntuarioOpen(false)} className="px-10 py-3 bg-indigo-600 text-white text-[10px] font-black uppercase italic shadow-2xl">Fechar Ficha</button>
          </header>
          <div className="flex-1 overflow-y-auto p-12 bg-slate-50 custom-scrollbar">
             <div className="max-w-6xl mx-auto grid grid-cols-1 lg:grid-cols-12 gap-12">
                <div className="lg:col-span-4 space-y-8">
                   <div className="bg-white border border-slate-200 p-10 text-center space-y-6 shadow-sm">
                      <div className="w-64 h-64 border-8 border-slate-50 shadow-2xl mx-auto overflow-hidden">
                        {selectedStudent.photoURL ? <img src={selectedStudent.photoURL} className="w-full h-full object-cover" /> : <div className="w-full h-full flex items-center justify-center text-slate-200 font-black text-6xl italic">U</div>}
                      </div>
                      <div>
                         <h1 className="text-3xl font-black uppercase italic tracking-tighter text-slate-900 leading-none">{selectedStudent.displayName}</h1>
                         <p className="text-xs font-bold text-slate-400 mt-4">{selectedStudent.email}</p>
                      </div>
                      <div className="pt-4 flex justify-center gap-2">
                         <span className="px-4 py-1.5 bg-indigo-50 text-indigo-600 text-[10px] font-black uppercase italic border border-indigo-100">Status: {selectedStudent.status}</span>
                      </div>
                   </div>
                   <div className="bg-slate-900 text-white p-8 space-y-6 shadow-2xl border border-white/5">
                      <h3 className="text-[10px] font-black uppercase tracking-widest text-indigo-400 italic">Vínculo Acadêmico Ativo</h3>
                      <div className="flex items-center gap-4 border-b border-white/5 pb-6">
                         <div className="p-3 bg-indigo-600"><GraduationCap size={24}/></div>
                         <div>
                            <p className="font-black uppercase italic text-sm">{courses.find(c=>c.id === selectedStudent.cursoInicial)?.nome || 'Não Vinculado'}</p>
                            <p className="text-[9px] text-white/40 font-bold uppercase mt-1">Disciplina Principal</p>
                         </div>
                      </div>
                      <div className="space-y-4">
                         <div className="flex justify-between items-center"><span className="text-[10px] font-bold text-white/40 uppercase">Progresso Real</span><span className="text-xl font-black italic">0%</span></div>
                         <div className="h-2 bg-white/10 overflow-hidden"><div className="h-full bg-indigo-500" style={{width:'0%'}}></div></div>
                      </div>
                   </div>
                </div>
                <div className="lg:col-span-8 space-y-10">
                   <div className="bg-white border border-slate-200 p-12 shadow-sm space-y-12">
                      <div className="grid grid-cols-2 gap-12">
                         <div className="space-y-10">
                            <div className="space-y-2"><p className="text-[10px] font-black text-slate-400 uppercase italic">Identificação CPF</p><p className="text-lg font-black text-slate-900 tracking-tight">{selectedStudent.cpf || '---'}</p></div>
                            <div className="space-y-2"><p className="text-[10px] font-black text-slate-400 uppercase italic">WhatsApp / Fone</p><p className="text-lg font-black text-slate-900 tracking-tight">{selectedStudent.telefone || '---'}</p></div>
                            <div className="space-y-2"><p className="text-[10px] font-black text-slate-400 uppercase italic">Data de Nascimento</p><p className="text-lg font-black text-slate-900 tracking-tight">{selectedStudent.nascimento || '---'}</p></div>
                         </div>
                         <div className="space-y-10 border-l border-slate-100 pl-12">
                            <div className="space-y-2"><p className="text-[10px] font-black text-slate-400 uppercase italic">E-mail Pessoal</p><p className="text-sm font-bold text-slate-700">{selectedStudent.emailPessoal || '---'}</p></div>
                            <div className="space-y-4">
                               <p className="text-[10px] font-black text-indigo-600 uppercase italic flex items-center gap-2"><MapPin size={14}/> Localização Residencial</p>
                               <div className="p-6 bg-slate-50 border border-slate-100 italic leading-relaxed text-sm font-medium text-slate-600">
                                  {selectedStudent.endereco?.rua}, {selectedStudent.endereco?.numero}<br/>
                                  {selectedStudent.endereco?.bairro}<br/>
                                  {selectedStudent.endereco?.cidade} / {selectedStudent.endereco?.uf}<br/>
                                  <span className="text-[10px] font-mono mt-3 block">CEP: {selectedStudent.endereco?.cep}</span>
                               </div>
                            </div>
                         </div>
                      </div>
                      <div className="pt-12 border-t border-slate-100">
                         <h4 className="text-[10px] font-black uppercase text-slate-900 italic tracking-[0.3em] mb-8">Fluxo Acadêmico Permanente</h4>
                         <div className="grid grid-cols-3 gap-6">
                            <div className="p-8 border border-slate-100 text-center space-y-2">
                               <p className="text-4xl font-black text-slate-900">0.0</p>
                               <p className="text-[9px] font-black uppercase text-slate-400 italic">Média Geral</p>
                            </div>
                            <div className="p-8 border border-slate-100 text-center space-y-2">
                               <p className="text-4xl font-black text-slate-900">0</p>
                               <p className="text-[9px] font-black uppercase text-slate-400 italic">Aulas Assistidas</p>
                            </div>
                            <div className="p-8 border border-slate-100 text-center space-y-2">
                               <p className="text-4xl font-black text-slate-900">0</p>
                               <p className="text-[9px] font-black uppercase text-slate-400 italic">Créditos</p>
                            </div>
                         </div>
                      </div>
                   </div>
                </div>
             </div>
          </div>
        </div>
      )}
    </div>
  );
};

export default StudentsView;

import React, { useState, useEffect, useMemo, useRef } from 'react';
import { collection, query, where, onSnapshot, deleteDoc, serverTimestamp, doc, setDoc, getDocs } from "https://www.gstatic.com/firebasejs/10.7.1/firebase-firestore.js";
import { db } from '../firebase';
import { User, Course } from '../types';
// Fix: Added missing icons RefreshCw, ArrowLeft, and GraduationCap to the import list
import { Search, UserPlus, X, Save, UserCog, Trash2, Edit3, Camera, Eye, MapPin, ChevronLeft, ChevronRight, Filter, MoreHorizontal, Hash, RefreshCw, ArrowLeft, GraduationCap } from 'lucide-react';

const StudentsView: React.FC = () => {
  const [students, setStudents] = useState<User[]>([]);
  const [courses, setCourses] = useState<Course[]>([]);
  const [loading, setLoading] = useState(true);
  const [searchTerm, setSearchTerm] = useState('');
  const [courseFilter, setCourseFilter] = useState('');

  // Paginação
  const [currentPage, setCurrentPage] = useState(1);
  const itemsPerPage = 10;

  const [isRegisterModalOpen, setIsRegisterModalOpen] = useState(false);
  const [isProntuarioOpen, setIsProntuarioOpen] = useState(false);
  const [selectedStudent, setSelectedStudent] = useState<any>(null);
  const [actionLoading, setActionLoading] = useState(false);
  const fileInputRef = useRef<HTMLInputElement>(null);

  const [formData, setFormData] = useState({
    nome: '', emailPessoal: '', emailAcademico: '', telefone: '', cursoId: '', status: 'ativo', cpf: '', nascimento: '', fotoUrl: '', senhaNova: '',
    endereco: { cep: '', rua: '', numero: '', bairro: '', cidade: '', uf: '' }
  });

  useEffect(() => {
    const unsubS = onSnapshot(query(collection(db, 'users'), where('role', '==', 'aluno')), s => {
      setStudents(s.docs.map(d => ({ uid: d.id, ...d.data() } as User)).sort((a:any, b:any) => (b.createdAt?.seconds || 0) - (a.createdAt?.seconds || 0)));
      setLoading(false);
    });
    const unsubC = onSnapshot(collection(db, 'cursos'), s => setCourses(s.docs.map(d => ({ id: d.id, ...d.data() } as Course))));
    return () => { unsubS(); unsubC(); };
  }, []);

  useEffect(() => {
    if (formData.nome && !selectedStudent) {
      const names = formData.nome.trim().toLowerCase().split(' ');
      const suggested = names.length > 1 ? `${names[0]}.${names[names.length - 1]}@ebd.com` : `${names[0]}@ebd.com`;
      setFormData(prev => ({ ...prev, emailAcademico: suggested }));
    }
  }, [formData.nome, selectedStudent]);

  useEffect(() => {
    const cep = formData.endereco.cep.replace(/\D/g, '');
    if (cep.length === 8) {
      fetch(`https://viacep.com.br/ws/${cep}/json/`)
        .then(res => res.json())
        .then(data => {
          if (!data.erro) {
            setFormData(prev => ({
              ...prev,
              endereco: { ...prev.endereco, rua: data.logradouro, bairro: data.bairro, cidade: data.localidade, uf: data.uf }
            }));
          }
        });
    }
  }, [formData.endereco.cep]);

  const filtered = useMemo(() => students.filter(s => {
    const name = (s.displayName || (s as any).nome || '').toLowerCase();
    const aid = ((s as any).academicId || '').toLowerCase();
    const matchSearch = name.includes(searchTerm.toLowerCase()) || aid.includes(searchTerm.toLowerCase()) || s.email?.toLowerCase().includes(searchTerm.toLowerCase());
    const matchCourse = !courseFilter || (s as any).cursoInicial === courseFilter;
    return matchSearch && matchCourse;
  }), [students, searchTerm, courseFilter]);

  // Lógica de Paginação
  const totalPages = Math.ceil(filtered.length / itemsPerPage);
  const currentTableData = useMemo(() => {
    const start = (currentPage - 1) * itemsPerPage;
    return filtered.slice(start, start + itemsPerPage);
  }, [filtered, currentPage]);

  const handleSave = async (e: React.FormEvent) => {
    e.preventDefault();
    setActionLoading(true);
    try {
      const uid = selectedStudent?.uid || Math.random().toString(36).substring(2, 15);
      const academicId = selectedStudent?.academicId || `MAT-${new Date().getFullYear()}-${Math.random().toString(36).substring(2, 7).toUpperCase()}`;

      const payload: any = {
        uid,
        displayName: formData.nome,
        nome: formData.nome,
        email: formData.emailAcademico.toLowerCase().trim(),
        emailPessoal: formData.emailPessoal.toLowerCase().trim(),
        telefone: formData.telefone,
        cpf: formData.cpf,
        nascimento: formData.nascimento,
        photoURL: formData.fotoUrl,
        endereco: formData.endereco,
        cursoInicial: formData.cursoId,
        role: 'aluno',
        status: selectedStudent ? formData.status : 'ativo',
        academicId,
        updatedAt: serverTimestamp(),
        createdAt: selectedStudent?.createdAt || serverTimestamp()
      };

      if (formData.senhaNova) payload.password = formData.senhaNova;

      await setDoc(doc(db, 'users', uid), payload, { merge: true });
      setIsRegisterModalOpen(false);
      setSelectedStudent(null);
      setFormData({
        nome: '', emailPessoal: '', emailAcademico: '', telefone: '', cursoId: '', status: 'ativo', cpf: '', nascimento: '', fotoUrl: '', senhaNova: '',
        endereco: { cep: '', rua: '', numero: '', bairro: '', cidade: '', uf: '' }
      });
    } catch (err) {
      alert("Erro ao gravar dados.");
    } finally {
      setActionLoading(false);
    }
  };

  if (loading) return <div className="p-10 font-mono text-[10px] tracking-widest uppercase">Acessando Registro Geral...</div>;

  return (
    <div className="space-y-1 animate-in fade-in duration-300">
      {/* HEADER ELEGANTE E RETO */}
      <header className="flex justify-between items-center bg-white border border-slate-200 p-6 shadow-sm">
        <div>
          <h1 className="text-xl font-black uppercase italic tracking-tighter text-slate-900 leading-none">Gestão de Discentes</h1>
          <p className="text-[10px] font-bold text-slate-400 uppercase tracking-[0.3em] mt-2">Base de Dados Sincronizada EB-AD</p>
        </div>
        <button onClick={() => { 
          setSelectedStudent(null); 
          setFormData({nome:'', emailPessoal:'', emailAcademico:'', telefone:'', cursoId:'', status:'ativo', cpf:'', nascimento:'', fotoUrl:'', senhaNova:'', endereco:{cep:'', rua:'', numero:'', bairro:'', cidade:'', uf:''}});
          setIsRegisterModalOpen(true); 
        }} className="bg-slate-900 text-white px-8 py-3 text-[10px] font-black uppercase italic hover:bg-indigo-600 transition-all flex items-center gap-3 shadow-lg shadow-slate-200"><UserPlus size={16} /> Matricular Aluno</button>
      </header>

      {/* ÁREA DE FILTROS - DESIGN RETO */}
      <div className="bg-white border-x border-slate-200 p-4 flex flex-col md:flex-row items-center gap-4">
        <div className="relative flex-1 w-full">
          <Search size={16} className="absolute left-4 top-1/2 -translate-y-1/2 text-slate-400" />
          <input 
            value={searchTerm} 
            onChange={e => { setSearchTerm(e.target.value); setCurrentPage(1); }} 
            placeholder="Pesquisar por Matrícula, Nome ou E-mail..." 
            className="w-full pl-12 pr-4 py-3 bg-slate-50 border border-slate-200 text-xs font-bold outline-none focus:border-indigo-500 focus:bg-white transition-all" 
          />
        </div>
        <div className="flex gap-2 w-full md:w-auto">
          <div className="relative">
            <Filter size={14} className="absolute left-3 top-1/2 -translate-y-1/2 text-slate-400" />
            <select 
              value={courseFilter} 
              onChange={e => { setCourseFilter(e.target.value); setCurrentPage(1); }} 
              className="pl-10 pr-10 py-3 bg-slate-50 border border-slate-200 text-[10px] font-black uppercase outline-none focus:border-indigo-500 appearance-none min-w-[200px]"
            >
              <option value="">Todas as Disciplinas</option>
              {courses.map(c => <option key={c.id} value={c.id}>{c.nome}</option>)}
            </select>
          </div>
        </div>
      </div>

      {/* TABELA - DESIGN ELEGANTE E RETO */}
      <div className="bg-white border border-slate-200 overflow-hidden shadow-sm">
        <table className="w-full text-left border-collapse">
          <thead className="bg-slate-50 border-b border-slate-200 text-[10px] font-black uppercase text-slate-500 italic tracking-widest">
            <tr>
              <th className="px-6 py-4 border-r border-slate-100"><div className="flex items-center gap-2"><Hash size={12}/> Matrícula</div></th>
              <th className="px-6 py-4 border-r border-slate-100">Nome do Aluno</th>
              <th className="px-6 py-4 border-r border-slate-100">E-mail Acadêmico</th>
              <th className="px-6 py-4 border-r border-slate-100">Disciplina</th>
              <th className="px-6 py-4 border-r border-slate-100 text-center">Status</th>
              <th className="px-6 py-4 text-center">Ações</th>
            </tr>
          </thead>
          <tbody className="text-xs">
            {currentTableData.length === 0 ? (
              <tr><td colSpan={6} className="p-20 text-center text-slate-300 font-black uppercase italic tracking-[0.5em]">Nenhum registro localizado</td></tr>
            ) : currentTableData.map(s => (
              <tr key={s.uid} className="border-b border-slate-100 hover:bg-indigo-50/20 transition-colors group">
                <td className="px-6 py-4 border-r border-slate-50 font-mono font-bold text-indigo-600">{(s as any).academicId || '---'}</td>
                <td className="px-6 py-4 border-r border-slate-50">
                  <div className="flex items-center gap-3">
                    <div className="w-8 h-8 bg-slate-100 border border-slate-200 overflow-hidden shrink-0">
                      {(s as any).photoURL ? <img src={(s as any).photoURL} className="w-full h-full object-cover" /> : <div className="w-full h-full flex items-center justify-center text-[10px] font-bold text-slate-300">{(s.displayName || 'U').charAt(0)}</div>}
                    </div>
                    <span className="font-black uppercase italic text-slate-900 tracking-tight">{s.displayName || (s as any).nome}</span>
                  </div>
                </td>
                <td className="px-6 py-4 border-r border-slate-50 text-slate-500 font-medium">{s.email}</td>
                <td className="px-6 py-4 border-r border-slate-50">
                  <span className="px-3 py-1 bg-slate-100 text-slate-600 text-[9px] font-black uppercase italic border border-slate-200">
                    {courses.find(c => c.id === (s as any).cursoInicial)?.nome || 'Pendente'}
                  </span>
                </td>
                <td className="px-6 py-4 border-r border-slate-50 text-center">
                  <span className={`px-3 py-1 font-black uppercase italic text-[8px] border ${s.status === 'ativo' ? 'bg-emerald-50 text-emerald-700 border-emerald-100' : 'bg-rose-50 text-rose-700 border-rose-100'}`}>{s.status}</span>
                </td>
                <td className="px-6 py-4 text-center">
                  <div className="flex justify-center gap-1 opacity-40 group-hover:opacity-100 transition-opacity">
                    <button onClick={() => { setSelectedStudent(s); setIsProntuarioOpen(true); }} className="p-2 border border-slate-200 hover:bg-slate-900 hover:text-white transition-all"><Eye size={14}/></button>
                    <button onClick={() => { 
                      setSelectedStudent(s); 
                      setFormData({
                        nome: s.displayName || (s as any).nome, 
                        emailPessoal: (s as any).emailPessoal || '',
                        emailAcademico: s.email || '',
                        telefone: (s as any).telefone || '', 
                        cursoId: (s as any).cursoInicial || '', 
                        status: s.status || 'ativo', 
                        cpf: (s as any).cpf || '', 
                        nascimento: (s as any).nascimento || '', 
                        fotoUrl: (s as any).photoURL || '', 
                        senhaNova: '',
                        endereco: (s as any).endereco || {cep:'', rua:'', numero:'', bairro:'', cidade:'', uf:''} 
                      }); 
                      setIsRegisterModalOpen(true); 
                    }} className="p-2 border border-slate-200 hover:bg-slate-900 hover:text-white transition-all"><Edit3 size={14}/></button>
                    <button onClick={async () => { if(confirm('Remover aluno definitivamente?')) await deleteDoc(doc(db, 'users', s.uid)); }} className="p-2 border border-slate-200 hover:bg-rose-600 hover:text-white transition-all"><Trash2 size={14}/></button>
                  </div>
                </td>
              </tr>
            ))}
          </tbody>
        </table>

        {/* PAGINAÇÃO DINÂMICA */}
        <div className="bg-slate-50 px-6 py-4 border-t border-slate-200 flex justify-between items-center">
           <p className="text-[10px] font-bold text-slate-400 uppercase italic">Exibindo {currentTableData.length} de {filtered.length} registros</p>
           <div className="flex gap-1">
              <button 
                disabled={currentPage === 1}
                onClick={() => setCurrentPage(prev => prev - 1)}
                className={`p-2 border border-slate-300 transition-all ${currentPage === 1 ? 'opacity-20 cursor-not-allowed' : 'hover:bg-white active:scale-95'}`}
              ><ChevronLeft size={16}/></button>
              <div className="flex items-center px-4 border border-slate-300 bg-white font-black text-[10px] italic">{currentPage} / {totalPages || 1}</div>
              <button 
                disabled={currentPage === totalPages || totalPages === 0}
                onClick={() => setCurrentPage(prev => prev + 1)}
                className={`p-2 border border-slate-300 transition-all ${currentPage === totalPages || totalPages === 0 ? 'opacity-20 cursor-not-allowed' : 'hover:bg-white active:scale-95'}`}
              ><ChevronRight size={16}/></button>
           </div>
        </div>
      </div>

      {/* MODAL DE CADASTRO/EDIÇÃO - REFINADO E RETO */}
      {isRegisterModalOpen && (
        <div className="fixed inset-0 z-[1000] bg-slate-900/60 backdrop-blur-sm flex items-center justify-center p-0 md:p-10 animate-in fade-in">
          <div className="bg-white w-full h-full md:max-w-5xl md:h-auto border border-slate-300 shadow-2xl flex flex-col">
            <header className="bg-slate-900 text-white p-6 flex justify-between items-center">
              <div className="flex items-center gap-4">
                <div className="p-3 bg-indigo-600 shadow-lg"><UserCog size={20}/></div>
                <div>
                  <h2 className="text-lg font-black uppercase italic tracking-tighter">Prontuário Discente Master</h2>
                  <p className="text-[9px] font-bold text-indigo-400 uppercase tracking-widest">Entrada de Dados Acadêmicos</p>
                </div>
              </div>
              <button onClick={() => setIsRegisterModalOpen(false)} className="hover:rotate-90 transition-transform"><X size={24}/></button>
            </header>

            <form onSubmit={handleSave} className="flex-1 overflow-y-auto p-10 space-y-12 bg-slate-50 custom-scrollbar">
              <section className="space-y-6">
                <h3 className="text-[10px] font-black uppercase border-l-4 border-indigo-600 pl-4 text-slate-800 italic">Identificação e Contato</h3>
                <div className="grid grid-cols-1 md:grid-cols-4 gap-8">
                   <div className="md:col-span-1 flex flex-col items-center gap-3">
                      <div onClick={() => fileInputRef.current?.click()} className="w-40 h-40 bg-white border border-slate-300 flex items-center justify-center cursor-pointer overflow-hidden relative group shadow-inner">
                        {formData.fotoUrl ? <img src={formData.fotoUrl} className="w-full h-full object-cover" /> : <div className="text-center text-[9px] text-slate-400 uppercase font-black px-6 opacity-30"><Camera size={32} className="mx-auto mb-2"/> Upload Foto</div>}
                        <div className="absolute inset-0 bg-slate-900/40 opacity-0 group-hover:opacity-100 transition-all flex items-center justify-center"><Camera size={24} className="text-white"/></div>
                      </div>
                      <input type="file" fileInputRef={fileInputRef} className="hidden" accept="image/*" onChange={e => { const f=e.target.files?.[0]; if(f){ const r=new FileReader(); r.onload=ev=>setFormData({...formData, fotoUrl: ev.target?.result as string}); r.readAsDataURL(f); } }} />
                   </div>
                   <div className="md:col-span-3 grid grid-cols-2 gap-5">
                      <div className="flex flex-col gap-1.5"><span className="text-[9px] font-black text-slate-400 uppercase italic ml-2">Nome Completo</span><input required value={formData.nome} onChange={e => setFormData({...formData, nome: e.target.value})} className="border border-slate-200 bg-white p-4 text-xs font-bold outline-none focus:border-indigo-500 shadow-sm" placeholder="Nome do Aluno..." /></div>
                      <div className="flex flex-col gap-1.5"><span className="text-[9px] font-black text-slate-400 uppercase italic ml-2">WhatsApp</span><input required value={formData.telefone} onChange={e => setFormData({...formData, telefone: e.target.value})} className="border border-slate-200 bg-white p-4 text-xs font-bold outline-none focus:border-indigo-500 shadow-sm" placeholder="(00) 00000-0000" /></div>
                      <div className="flex flex-col gap-1.5"><span className="text-[9px] font-black text-slate-400 uppercase italic ml-2">Documento CPF</span><input required value={formData.cpf} onChange={e => setFormData({...formData, cpf: e.target.value})} className="border border-slate-200 bg-white p-4 text-xs font-bold outline-none focus:border-indigo-500 shadow-sm" placeholder="000.000.000-00" /></div>
                      <div className="flex flex-col gap-1.5"><span className="text-[9px] font-black text-slate-400 uppercase italic ml-2">Data Nascimento</span><input required type="date" value={formData.nascimento} onChange={e => setFormData({...formData, nascimento: e.target.value})} className="border border-slate-200 bg-white p-4 text-xs font-bold outline-none focus:border-indigo-500 shadow-sm uppercase" /></div>
                   </div>
                </div>
              </section>

              <section className="space-y-6">
                <h3 className="text-[10px] font-black uppercase border-l-4 border-indigo-600 pl-4 text-slate-800 italic">Endereço de Correspondência</h3>
                <div className="grid grid-cols-1 md:grid-cols-6 gap-4">
                   <div className="md:col-span-1 flex flex-col gap-1.5"><span className="text-[9px] font-black text-slate-400 uppercase italic ml-2">CEP</span><input required value={formData.endereco.cep} onChange={e => setFormData({...formData, endereco: {...formData.endereco, cep: e.target.value}})} className="border border-slate-200 bg-white p-4 text-xs font-bold outline-none focus:border-indigo-500 shadow-sm" placeholder="00000-000" /></div>
                   <div className="md:col-span-4 flex flex-col gap-1.5"><span className="text-[9px] font-black text-slate-400 uppercase italic ml-2">Logradouro / Rua</span><input required value={formData.endereco.rua} onChange={e => setFormData({...formData, endereco: {...formData.endereco, rua: e.target.value}})} className="border border-slate-200 bg-slate-100 p-4 text-xs font-bold outline-none shadow-inner" placeholder="Rua..." /></div>
                   <div className="md:col-span-1 flex flex-col gap-1.5"><span className="text-[9px] font-black text-slate-400 uppercase italic ml-2">Nº</span><input required value={formData.endereco.numero} onChange={e => setFormData({...formData, endereco: {...formData.endereco, numero: e.target.value}})} className="border border-slate-200 bg-white p-4 text-xs font-bold outline-none focus:border-indigo-500 shadow-sm" placeholder="S/N" /></div>
                   <div className="md:col-span-2 flex flex-col gap-1.5"><span className="text-[9px] font-black text-slate-400 uppercase italic ml-2">Bairro</span><input required value={formData.endereco.bairro} onChange={e => setFormData({...formData, endereco: {...formData.endereco, bairro: e.target.value}})} className="border border-slate-200 bg-slate-100 p-4 text-xs font-bold outline-none shadow-inner" /></div>
