                      <div className="flex flex-col gap-1.5"><span className="text-[9px] font-black text-slate-400 uppercase italic ml-2">E-mail Pessoal</span><input type="email" value={formData.emailPessoal} onChange={e => setFormData({...formData, emailPessoal: e.target.value})} className="border border-slate-200 bg-white p-4 text-xs font-bold outline-none focus:border-indigo-500 shadow-sm" placeholder="exemplo@gmail.com" /></div>
                   </div>
                </div>
              </section>

              <div className="pt-8 border-t border-slate-200 flex gap-4">
