                      </div>
                   </div>
                   <div className="bg-slate-900 text-white p-8 space-y-6 shadow-2xl border border-white/5">
                      <h3 className="text-[10px] font-black uppercase tracking-widest text-indigo-400 italic">Vínculo Acadêmico Ativo</h3>
                      <div className="flex items-center gap-4 border-b border-white/5 pb-6">
                         <div className="p-3 bg-indigo-600"><GraduationCap size={24}/></div>
                         <div>
                            <p className="font-black uppercase italic text-sm">{courses.find(c=>c.id === selectedStudent.cursoInicial)?.nome || 'Não Vinculado'}</p>
                            <p className="text-[9px] text-white/40 font-bold uppercase mt-1">Disciplina Principal</p>
                         </div>
                      </div>
                      <div className="space-y-4">
                         <div className="flex justify-between items-center"><span className="text-[10px] font-bold text-white/40 uppercase">Progresso Real</span><span className="text-xl font-black italic">0%</span></div>
                         <div className="h-2 bg-white/10 overflow-hidden"><div className="h-full bg-indigo-500" style={{width:'0%'}}></div></div>
                      </div>
                   </div>
                </div>
                <div className="lg:col-span-8 space-y-10">
                   <div className="bg-white border border-slate-200 p-12 shadow-sm space-y-12">
                      <div className="grid grid-cols-2 gap-12">
                         <div className="space-y-10">
                            <div className="space-y-2"><p className="text-[10px] font-black text-slate-400 uppercase italic">Identificação CPF</p><p className="text-lg font-black text-slate-900 tracking-tight">{selectedStudent.cpf || '---'}</p></div>
                            <div className="space-y-2"><p className="text-[10px] font-black text-slate-400 uppercase italic">WhatsApp / Fone</p><p className="text-lg font-black text-slate-900 tracking-tight">{selectedStudent.telefone || '---'}</p></div>
                            <div className="space-y-2"><p className="text-[10px] font-black text-slate-400 uppercase italic">Data de Nascimento</p><p className="text-lg font-black text-slate-900 tracking-tight">{selectedStudent.nascimento || '---'}</p></div>
                         </div>
                         <div className="space-y-10 border-l border-slate-100 pl-12">
                            <div className="space-y-2"><p className="text-[10px] font-black text-slate-400 uppercase italic">E-mail Pessoal</p><p className="text-sm font-bold text-slate-700">{selectedStudent.emailPessoal || '---'}</p></div>
                            <div className="space-y-4">
                               <p className="text-[10px] font-black text-indigo-600 uppercase italic flex items-center gap-2"><MapPin size={14}/> Localização Residencial</p>
                               <div className="p-6 bg-slate-50 border border-slate-100 italic leading-relaxed text-sm font-medium text-slate-600">
                                  {selectedStudent.endereco?.rua}, {selectedStudent.endereco?.numero}<br/>
                                  {selectedStudent.endereco?.bairro}<br/>
                                  {selectedStudent.endereco?.cidade} / {selectedStudent.endereco?.uf}<br/>
                                  <span className="text-[10px] font-mono mt-3 block">CEP: {selectedStudent.endereco?.cep}</span>
                               </div>
                            </div>
                         </div>
                      </div>
                      <div className="pt-12 border-t border-slate-100">
                         <h4 className="text-[10px] font-black uppercase text-slate-900 italic tracking-[0.3em] mb-8">Fluxo Acadêmico Permanente</h4>
                         <div className="grid grid-cols-3 gap-6">
                            <div className="p-8 border border-slate-100 text-center space-y-2">
                               <p className="text-4xl font-black text-slate-900">0.0</p>
                               <p className="text-[9px] font-black uppercase text-slate-400 italic">Média Geral</p>
                            </div>
                            <div className="p-8 border border-slate-100 text-center space-y-2">
                               <p className="text-4xl font-black text-slate-900">0</p>
                               <p className="text-[9px] font-black uppercase text-slate-400 italic">Aulas Assistidas</p>
                            </div>
                            <div className="p-8 border border-slate-100 text-center space-y-2">
                               <p className="text-4xl font-black text-slate-900">0</p>
                               <p className="text-[9px] font-black uppercase text-slate-400 italic">Créditos</p>
