                <h2 className="text-xl font-black uppercase italic tracking-tighter leading-none">Matrícula Master de Alunos</h2>
                <p className="text-[10px] font-bold text-indigo-400 uppercase tracking-widest mt-1.5">Módulo de Cadastro Direto v2.5</p>
              </div>
            </div>
            <button 
              onClick={() => setIsRegisterModalOpen(false)} 
              className="flex items-center gap-3 px-6 py-2.5 bg-white/10 hover:bg-rose-600 rounded-xl text-[10px] font-black uppercase italic transition-all border border-white/5"
            >
              <X size={20}/> Cancelar Operação
            </button>
          </header>

          <div className="flex-1 overflow-y-auto bg-slate-50">
            <form onSubmit={handleSave} className="max-w-5xl mx-auto py-16 px-8 space-y-20">
              <section className="space-y-10">
                <h3 className="text-xs font-black uppercase border-l-8 border-indigo-600 pl-6 text-slate-800 italic tracking-widest">01. Identificação Acadêmica</h3>
                <div className="grid grid-cols-1 lg:grid-cols-4 gap-12">
                   <div className="lg:col-span-1 flex flex-col items-center gap-4">
                      <div 
                        onClick={() => fileInputRef.current?.click()} 
                        className="w-48 h-48 bg-white border-4 border-slate-200 flex items-center justify-center cursor-pointer overflow-hidden relative group shadow-2xl rounded-3xl"
                      >
                        {formData.fotoUrl ? (
                          <img src={formData.fotoUrl} className="w-full h-full object-cover" />
                        ) : (
                          <div className="text-center p-6 opacity-30 group-hover:opacity-100 transition-opacity">
                            <Camera size={40} className="mx-auto mb-3 text-indigo-600"/> 
                            <span className="text-[10px] font-black uppercase tracking-widest">Enviar Foto</span>
                          </div>
                        )}
                        <div className="absolute inset-0 bg-indigo-600/60 opacity-0 group-hover:opacity-100 transition-all flex flex-col items-center justify-center text-white">
                          <RefreshCw size={24} className="mb-2"/>
                          <span className="text-[8px] font-black uppercase">Alterar Imagem</span>
                        </div>
                      </div>
                      <input type="file" ref={fileInputRef} className="hidden" accept="image/*" onChange={handleFileChange} />
                   </div>
                   <div className="lg:col-span-3 grid grid-cols-1 sm:grid-cols-2 gap-8">
                      <div className="space-y-2"><label className="text-[9px] font-black text-slate-400 uppercase italic ml-2">Nome Completo do Discente</label><input required value={formData.nome} onChange={e => setFormData({...formData, nome: e.target.value})} className="w-full border-b-2 border-slate-200 bg-transparent py-4 text-sm font-black outline-none focus:border-indigo-600 transition-all" placeholder="Digite o nome..." /></div>
                      <div className="space-y-2"><label className="text-[9px] font-black text-slate-400 uppercase italic ml-2">WhatsApp de Contato</label><input required value={formData.telefone} onChange={e => setFormData({...formData, telefone: e.target.value})} className="w-full border-b-2 border-slate-200 bg-transparent py-4 text-sm font-black outline-none focus:border-indigo-600 transition-all" placeholder="(00) 00000-0000" /></div>
                      <div className="space-y-2"><label className="text-[9px] font-black text-slate-400 uppercase italic ml-2">CPF (Somente Números)</label><input required value={formData.cpf} onChange={e => setFormData({...formData, cpf: e.target.value})} className="w-full border-b-2 border-slate-200 bg-transparent py-4 text-sm font-black outline-none focus:border-indigo-600 transition-all" placeholder="000.000.000-00" /></div>
                      <div className="space-y-2"><label className="text-[9px] font-black text-slate-400 uppercase italic ml-2">Nascimento</label><input required type="date" value={formData.nascimento} onChange={e => setFormData({...formData, nascimento: e.target.value})} className="w-full border-b-2 border-slate-200 bg-transparent py-4 text-sm font-black outline-none focus:border-indigo-600 transition-all uppercase" /></div>
                   </div>
                </div>
              </section>

              <section className="space-y-10">
                <h3 className="text-xs font-black uppercase border-l-8 border-indigo-600 pl-6 text-slate-800 italic tracking-widest">02. Endereço e Localização</h3>
                <div className="grid grid-cols-1 md:grid-cols-6 gap-8">
                   <div className="md:col-span-1 space-y-2"><label className="text-[9px] font-black text-slate-400 uppercase ml-2">CEP</label><input required value={formData.endereco.cep} onChange={e => setFormData({...formData, endereco: {...formData.endereco, cep: e.target.value}})} className="w-full border-b-2 border-slate-200 bg-transparent py-4 text-sm font-black outline-none focus:border-indigo-600 transition-all" placeholder="00000-000" /></div>
                   <div className="md:col-span-4 space-y-2"><label className="text-[9px] font-black text-slate-400 uppercase ml-2">Rua / Avenida</label><input required value={formData.endereco.rua} onChange={e => setFormData({...formData, endereco: {...formData.endereco, rua: e.target.value}})} className="w-full border-b-2 border-slate-200 bg-slate-100/50 py-4 px-4 text-sm font-black outline-none" /></div>
                   <div className="md:col-span-1 space-y-2"><label className="text-[9px] font-black text-slate-400 uppercase ml-2">Nº</label><input required value={formData.endereco.numero} onChange={e => setFormData({...formData, endereco: {...formData.endereco, numero: e.target.value}})} className="w-full border-b-2 border-slate-200 bg-transparent py-4 text-sm font-black outline-none focus:border-indigo-600 transition-all" placeholder="S/N" /></div>
                   <div className="md:col-span-2 space-y-2"><label className="text-[9px] font-black text-slate-400 uppercase ml-2">Bairro</label><input required value={formData.endereco.bairro} onChange={e => setFormData({...formData, endereco: {...formData.endereco, bairro: e.target.value}})} className="w-full border-b-2 border-slate-200 bg-slate-100/50 py-4 px-4 text-sm font-black outline-none" /></div>
                   <div className="md:col-span-3 space-y-2"><label className="text-[9px] font-black text-slate-400 uppercase ml-2">Cidade</label><input required value={formData.endereco.cidade} onChange={e => setFormData({...formData, endereco: {...formData.endereco, cidade: e.target.value}})} className="w-full border-b-2 border-slate-200 bg-slate-100/50 py-4 px-4 text-sm font-black outline-none" /></div>
                   <div className="md:col-span-1 space-y-2"><label className="text-[9px] font-black text-slate-400 uppercase ml-2">UF</label><input required value={formData.endereco.uf} onChange={e => setFormData({...formData, endereco: {...formData.endereco, uf: e.target.value.toUpperCase()}})} maxLength={2} className="w-full border-b-2 border-slate-200 bg-slate-100/50 py-4 px-4 text-sm font-black outline-none uppercase" /></div>
                </div>
              </section>

              <section className="space-y-10">
                <h3 className="text-xs font-black uppercase border-l-8 border-indigo-600 pl-6 text-slate-800 italic tracking-widest">03. Parâmetros de Acesso Master</h3>
                <div className="grid grid-cols-1 lg:grid-cols-2 gap-12">
                   <div className="space-y-6">
                      <div className="space-y-2"><label className="text-[9px] font-black text-indigo-600 uppercase italic ml-2 tracking-widest">E-mail Acadêmico (Login EAD)</label><input value={formData.emailAcademico} onChange={e => setFormData({...formData, emailAcademico: e.target.value})} className="w-full border-2 border-indigo-100 bg-white p-5 text-sm font-black text-indigo-600 outline-none focus:border-indigo-600 shadow-xl" /></div>
                      <div className="space-y-2"><label className="text-[9px] font-black text-rose-500 uppercase italic ml-2 tracking-widest">Redefinir Senha de Acesso</label><input type="password" value={formData.senhaNova} onChange={e => setFormData({...formData, senhaNova: e.target.value})} className="w-full border-2 border-rose-50 bg-white p-5 text-sm font-black outline-none focus:border-rose-500 shadow-xl" placeholder="Nova senha se desejar alterar..." /></div>
                   </div>
                   <div className="space-y-6">
                      <div className="space-y-2"><label className="text-[9px] font-black text-slate-400 uppercase italic ml-2">Disciplina de Ingresso</label><select required value={formData.cursoId} onChange={e => setFormData({...formData, cursoId: e.target.value})} className="w-full border-2 border-slate-100 bg-white p-5 text-sm font-black uppercase outline-none focus:border-indigo-600 shadow-xl appearance-none cursor-pointer"><option value="">Selecionar Disciplina Ativa...</option>{courses.map(c => <option key={c.id} value={c.id}>{c.nome}</option>)}</select></div>
                      <div className="space-y-2"><label className="text-[9px] font-black text-slate-400 uppercase italic ml-2">E-mail Pessoal (Backup)</label><input type="email" value={formData.emailPessoal} onChange={e => setFormData({...formData, emailPessoal: e.target.value})} className="w-full border-2 border-slate-100 bg-white p-5 text-sm font-black outline-none focus:border-indigo-600 shadow-xl" placeholder="exemplo@gmail.com" /></div>
                   </div>
                </div>
              </section>
            </form>
          </div>

          <footer className="p-10 border-t border-slate-200 bg-white shadow-[0_-20px_50px_rgba(0,0,0,0.05)] flex items-center justify-center shrink-0">
             <button 
                onClick={handleSave} 
                disabled={actionLoading} 
                className="w-full max-w-4xl py-6 bg-slate-900 text-white rounded-2xl text-xs font-black uppercase italic tracking-[0.4em] hover:bg-indigo-600 shadow-[0_20px_40px_rgba(0,0,0,0.2)] transition-all flex items-center justify-center gap-6 active:scale-95 disabled:opacity-50"
             >
                {actionLoading ? <RefreshCw className="animate-spin" size={24}/> : <><Save size={24}/> Efetivar Matrícula no Banco de Dados</>}
             </button>
          </footer>
        </div>
      )}

      {/* TELA DE LISTAGEM PADRÃO */}
      <header className="flex justify-between items-center bg-white border border-slate-200 p-6 shadow-sm">
        <div>
          <h1 className="text-xl font-black uppercase italic tracking-tighter text-slate-900 leading-none">Gestão de Discentes</h1>
          <p className="text-[10px] font-bold text-slate-400 uppercase tracking-[0.3em] mt-2">Base de Dados Sincronizada EB-AD</p>
        </div>
        <button onClick={() => { 
          setSelectedStudent(null); 
          setFormData({nome:'', emailPessoal:'', emailAcademico:'', telefone:'', cursoId:'', status:'ativo', cpf:'', nascimento:'', fotoUrl:'', senhaNova:'', endereco:{cep:'', rua:'', numero:'', bairro:'', cidade:'', uf:''}});
          setIsRegisterModalOpen(true); 
        }} className="bg-slate-900 text-white px-8 py-3 text-[10px] font-black uppercase italic hover:bg-indigo-600 transition-all flex items-center gap-3 shadow-lg"><UserPlus size={16} /> Matricular Aluno</button>
      </header>

      <div className="bg-white border-x border-slate-200 p-4 flex flex-col md:flex-row items-center gap-4">
        <div className="relative flex-1 w-full">
          <Search size={16} className="absolute left-4 top-1/2 -translate-y-1/2 text-slate-400" />
          <input value={searchTerm} onChange={e => { setSearchTerm(e.target.value); setCurrentPage(1); }} placeholder="Pesquisar por Matrícula, Nome ou E-mail..." className="w-full pl-12 pr-4 py-3 bg-slate-50 border border-slate-200 text-xs font-bold outline-none focus:border-indigo-500 focus:bg-white transition-all" />
        </div>
        <div className="flex gap-2 w-full md:w-auto">
          <div className="relative">
            <Filter size={14} className="absolute left-3 top-1/2 -translate-y-1/2 text-slate-400" />
            <select value={courseFilter} onChange={e => { setCourseFilter(e.target.value); setCurrentPage(1); }} className="pl-10 pr-10 py-3 bg-slate-50 border border-slate-200 text-[10px] font-black uppercase outline-none min-w-[200px] appearance-none"><option value="">Todas as Disciplinas</option>{courses.map(c => <option key={c.id} value={c.id}>{c.nome}</option>)}</select>
          </div>
        </div>
      </div>

      <div className="bg-white border border-slate-200 overflow-hidden shadow-sm">
        <table className="w-full text-left border-collapse">
          <thead className="bg-slate-50 border-b border-slate-200 text-[10px] font-black uppercase text-slate-500 italic tracking-widest">
            <tr>
              <th className="px-6 py-4 border-r border-slate-100">Matrícula</th>
              <th className="px-6 py-4 border-r border-slate-100">Nome do Aluno</th>
              <th className="px-6 py-4 border-r border-slate-100">E-mail Acadêmico</th>
              <th className="px-6 py-4 border-r border-slate-100 text-center">Status</th>
              <th className="px-6 py-4 text-center">Ações</th>
            </tr>
          </thead>
          <tbody className="text-xs">
            {currentTableData.map(s => (
              <tr key={s.uid} className="border-b border-slate-100 hover:bg-slate-50 transition-colors group">
                <td className="px-6 py-4 border-r border-slate-50 font-mono font-bold text-indigo-600">{(s as any).academicId || '---'}</td>
                <td className="px-6 py-4 border-r border-slate-50 font-black uppercase italic text-slate-900">{(s as any).displayName || (s as any).nome}</td>
                <td className="px-6 py-4 border-r border-slate-50 text-slate-500">{s.email}</td>
                <td className="px-6 py-4 border-r border-slate-50 text-center"><span className={`px-3 py-1 font-black uppercase italic text-[8px] border ${s.status === 'ativo' ? 'bg-emerald-50 text-emerald-700 border-emerald-100' : 'bg-rose-50 text-rose-700 border-rose-100'}`}>{s.status}</span></td>
                <td className="px-6 py-4 text-center">
                  <div className="flex justify-center gap-1 opacity-40 group-hover:opacity-100 transition-opacity">
                    <button onClick={() => { setSelectedStudent(s); setIsProntuarioOpen(true); }} className="p-2 border border-slate-200 hover:bg-slate-900 hover:text-white transition-all"><Eye size={14}/></button>
                    <button onClick={() => { setSelectedStudent(s); setFormData({ nome: s.displayName || (s as any).nome, emailPessoal: (s as any).emailPessoal || '', emailAcademico: s.email || '', telefone: (s as any).telefone || '', cursoId: (s as any).cursoInicial || '', status: s.status || 'ativo', cpf: (s as any).cpf || '', nascimento: (s as any).nascimento || '', fotoUrl: (s as any).photoURL || '', senhaNova: '', endereco: (s as any).endereco || {cep:'', rua:'', numero:'', bairro:'', cidade:'', uf:''} }); setIsRegisterModalOpen(true); }} className="p-2 border border-slate-200 hover:bg-slate-900 hover:text-white transition-all"><Edit3 size={14}/></button>
                    <button onClick={async () => { if(confirm('Remover definitivamente?')) await deleteDoc(doc(db, 'users', s.uid)); }} className="p-2 border border-slate-200 hover:bg-rose-600 hover:text-white transition-all"><Trash2 size={14}/></button>
                  </div>
                </td>
              </tr>
            ))}
          </tbody>
        </table>
        <div className="bg-slate-50 px-6 py-4 border-t border-slate-200 flex justify-between items-center">
           <p className="text-[10px] font-bold text-slate-400 uppercase italic">Exibindo {currentTableData.length} registros</p>
           <div className="flex gap-1">
              <button disabled={currentPage === 1} onClick={() => setCurrentPage(prev => prev - 1)} className="p-2 border border-slate-300 transition-all hover:bg-white disabled:opacity-20"><ChevronLeft size={16}/></button>
              <div className="flex items-center px-4 border border-slate-300 bg-white font-black text-[10px]">{currentPage} / {totalPages || 1}</div>
              <button disabled={currentPage === totalPages} onClick={() => setCurrentPage(prev => prev + 1)} className="p-2 border border-slate-300 transition-all hover:bg-white disabled:opacity-20"><ChevronRight size={16}/></button>
           </div>
        </div>
      </div>

      {/* PRONTUÁRIO TELA CHEIA */}
      {isProntuarioOpen && selectedStudent && (
        <div className="fixed inset-0 z-[6000] bg-white flex flex-col animate-in slide-in-from-bottom-5">
          <header className="bg-slate-900 text-white p-6 flex justify-between items-center shrink-0">
            <div className="flex items-center gap-6">
               <button onClick={() => setIsProntuarioOpen(false)} className="p-3 bg-white/10 hover:bg-white/20 transition-all border border-white/5"><ArrowLeft size={24}/></button>
               <div><h2 className="text-xl font-black uppercase italic tracking-tighter leading-none">Dossiê Acadêmico: {selectedStudent.displayName || selectedStudent.nome}</h2><p className="text-[9px] font-bold text-indigo-400 uppercase tracking-[0.4em] mt-2">Matrícula {selectedStudent.academicId || 'S/ID'}</p></div>
            </div>
            <button onClick={() => setIsProntuarioOpen(false)} className="px-10 py-3 bg-indigo-600 text-white text-[10px] font-black uppercase italic">Fechar Ficha</button>
          </header>
          <div className="flex-1 overflow-y-auto p-12 bg-slate-50">
             <div className="max-w-6xl mx-auto grid grid-cols-1 lg:grid-cols-12 gap-12">
                <div className="lg:col-span-4 space-y-8">
                   <div className="bg-white border border-slate-200 p-10 text-center space-y-6 shadow-sm">
                      <div className="w-64 h-64 border-8 border-slate-50 shadow-2xl mx-auto overflow-hidden">
                        {selectedStudent.photoURL ? <img src={selectedStudent.photoURL} className="w-full h-full object-cover" /> : <div className="w-full h-full flex items-center justify-center text-slate-200 font-black text-6xl">U</div>}
                      </div>
                      <h1 className="text-3xl font-black uppercase italic tracking-tighter text-slate-900">{selectedStudent.displayName}</h1>
                      <span className="px-4 py-1.5 bg-indigo-50 text-indigo-600 text-[10px] font-black uppercase italic border border-indigo-100 block">Status: {selectedStudent.status}</span>
                   </div>
                </div>
                <div className="lg:col-span-8 bg-white border border-slate-200 p-12 shadow-sm space-y-10">
                   <div className="grid grid-cols-2 gap-10">
                      <div className="space-y-6">
                         <div className="space-y-1"><p className="text-[9px] font-black text-slate-400 uppercase italic">CPF</p><p className="text-lg font-black text-slate-900">{selectedStudent.cpf || '---'}</p></div>
                         <div className="space-y-1"><p className="text-[9px] font-black text-slate-400 uppercase italic">WhatsApp</p><p className="text-lg font-black text-slate-900">{selectedStudent.telefone || '---'}</p></div>
                      </div>
                      <div className="space-y-6">
                         <div className="space-y-1"><p className="text-[9px] font-black text-slate-400 uppercase italic">E-mail Pessoal</p><p className="text-sm font-bold text-slate-700">{selectedStudent.emailPessoal || '---'}</p></div>
                         <div className="space-y-1"><p className="text-[9px] font-black text-slate-400 uppercase italic">Residência</p><p className="text-xs text-slate-600 font-bold italic leading-relaxed">{selectedStudent.endereco?.rua}, {selectedStudent.endereco?.numero}<br/>{selectedStudent.endereco?.bairro} - {selectedStudent.endereco?.cidade}/{selectedStudent.endereco?.uf}</p></div>
                      </div>
                   </div>
                </div>
             </div>
          </div>
        </div>
      )}
    </div>
  );
};

export default StudentsView;

import React, { useState, useEffect, useMemo, useRef } from 'react';
import { collection, query, where, onSnapshot, deleteDoc, serverTimestamp, doc, setDoc, getDocs, addDoc } from "https://www.gstatic.com/firebasejs/10.7.1/firebase-firestore.js";
import { db } from '../firebase';
import { User, Course } from '../types';
import { Search, UserPlus, X, Save, UserCog, Trash2, Edit3, Camera, Eye, MapPin, ChevronLeft, ChevronRight, Filter, MoreHorizontal, Hash, RefreshCw, ArrowLeft, GraduationCap, FileText, Printer, Download } from 'lucide-react';

const StudentsView: React.FC = () => {
  const [students, setStudents] = useState<User[]>([]);
  const [courses, setCourses] = useState<Course[]>([]);
  const [loading, setLoading] = useState(true);
  const [searchTerm, setSearchTerm] = useState('');
  const [courseFilter, setCourseFilter] = useState('');

  // Paginação
  const [currentPage, setCurrentPage] = useState(1);
  const itemsPerPage = 10;

  const [isRegisterModalOpen, setIsRegisterModalOpen] = useState(false);
  const [isProntuarioOpen, setIsProntuarioOpen] = useState(false);
  const [selectedStudent, setSelectedStudent] = useState<any>(null);
  const [actionLoading, setActionLoading] = useState(false);
  const fileInputRef = useRef<HTMLInputElement>(null);

  const [formData, setFormData] = useState({
    nome: '', emailPessoal: '', emailAcademico: '', telefone: '', cursoId: '', status: 'ativo', cpf: '', nascimento: '', fotoUrl: '', senhaNova: '',
    endereco: { cep: '', rua: '', numero: '', bairro: '', cidade: '', uf: '' }
  });

  useEffect(() => {
    const unsubS = onSnapshot(query(collection(db, 'users'), where('role', '==', 'aluno')), s => {
      setStudents(s.docs.map(d => ({ uid: d.id, ...d.data() } as User)).sort((a:any, b:any) => (b.createdAt?.seconds || 0) - (a.createdAt?.seconds || 0)));
      setLoading(false);
    });
    const unsubC = onSnapshot(collection(db, 'cursos'), s => setCourses(s.docs.map(d => ({ id: d.id, ...d.data() } as Course))));
    return () => { unsubS(); unsubC(); };
  }, []);

  useEffect(() => {
    if (formData.nome && !selectedStudent) {
      const names = formData.nome.trim().toLowerCase().split(' ');
      const suggested = names.length > 1 ? `${names[0]}.${names[names.length - 1]}@ebd.com` : `${names[0]}@ebd.com`;
      setFormData(prev => ({ ...prev, emailAcademico: suggested }));
    }
  }, [formData.nome, selectedStudent]);

  useEffect(() => {
    const cep = formData.endereco.cep.replace(/\D/g, '');
    if (cep.length === 8) {
      fetch(`https://viacep.com.br/ws/${cep}/json/`)
        .then(res => res.json())
        .then(data => {
          if (!data.erro) {
            setFormData(prev => ({
              ...prev,
              endereco: { ...prev.endereco, rua: data.logradouro, bairro: data.bairro, cidade: data.localidade, uf: data.uf }
            }));
          }
        });
    }
  }, [formData.endereco.cep]);

  const filtered = useMemo(() => students.filter(s => {
    const name = (s.displayName || (s as any).nome || '').toLowerCase();
    const aid = ((s as any).academicId || '').toLowerCase();
    const matchSearch = name.includes(searchTerm.toLowerCase()) || aid.includes(searchTerm.toLowerCase()) || s.email?.toLowerCase().includes(searchTerm.toLowerCase());
    const matchCourse = !courseFilter || (s as any).cursoInicial === courseFilter;
    return matchSearch && matchCourse;
  }), [students, searchTerm, courseFilter]);

  const totalPages = Math.ceil(filtered.length / itemsPerPage);
  const currentTableData = useMemo(() => {
    const start = (currentPage - 1) * itemsPerPage;
    return filtered.slice(start, start + itemsPerPage);
  }, [filtered, currentPage]);

  const generateAcademicFile = async (data: any) => {
    // Simulação de geração de PDF e salvamento na pasta de matrículas
    try {
      await addDoc(collection(db, 'secretaria_arquivos'), {
        title: `Ficha de Matrícula - ${data.displayName}`,
        folder: 'Matrículas',
        studentId: data.academicId,
        createdAt: serverTimestamp(),
        type: 'pdf'
      });
    } catch (e) {
      console.error("Erro ao gerar registro de arquivo", e);
    }
  };

  const handleSave = async (e: React.FormEvent) => {
    e.preventDefault();
    setActionLoading(true);
    try {
      const uid = selectedStudent?.uid || Math.random().toString(36).substring(2, 15);
      const academicId = selectedStudent?.academicId || `MAT-${new Date().getFullYear()}-${Math.random().toString(36).substring(2, 7).toUpperCase()}`;

      const payload: any = {
        uid,
        displayName: formData.nome,
        nome: formData.nome,
        email: formData.emailAcademico.toLowerCase().trim(),
        emailPessoal: formData.emailPessoal.toLowerCase().trim(),
        telefone: formData.telefone,
        cpf: formData.cpf,
        nascimento: formData.nascimento,
        photoURL: formData.fotoUrl,
        endereco: formData.endereco,
        cursoInicial: formData.cursoId,
        role: 'aluno',
        status: selectedStudent ? formData.status : 'ativo',
        academicId,
        updatedAt: serverTimestamp(),
        createdAt: selectedStudent?.createdAt || serverTimestamp()
      };

      if (formData.senhaNova) payload.password = formData.senhaNova;

      await setDoc(doc(db, 'users', uid), payload, { merge: true });
      await generateAcademicFile(payload);

      setIsRegisterModalOpen(false);
      setSelectedStudent(null);
      setFormData({
        nome: '', emailPessoal: '', emailAcademico: '', telefone: '', cursoId: '', status: 'ativo', cpf: '', nascimento: '', fotoUrl: '', senhaNova: '',
        endereco: { cep: '', rua: '', numero: '', bairro: '', cidade: '', uf: '' }
      });
      alert("Operação realizada com sucesso! Ficha acadêmica enviada para o GED.");
    } catch (err) {
      alert("Erro ao gravar dados.");
    } finally {
      setActionLoading(false);
    }
  };

  const handleFileChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (file) {
      const reader = new FileReader();
      reader.onload = (ev) => {
        const base64 = ev.target?.result as string;
        setFormData(prev => ({ ...prev, fotoUrl: base64 }));
      };
      reader.readAsDataURL(file);
    }
  };

