      if (formData.senhaNova) payload.password = formData.senhaNova;

      await setDoc(doc(db, 'users', uid), payload, { merge: true });
      await generateAcademicFile(payload);

      setIsRegisterModalOpen(false);
      setSelectedStudent(null);
      setFormData({
        nome: '', emailPessoal: '', emailAcademico: '', telefone: '', cursoId: '', status: 'ativo', cpf: '', nascimento: '', fotoUrl: '', senhaNova: '',
        endereco: { cep: '', rua: '', numero: '', bairro: '', cidade: '', uf: '' }
      });
      alert("Matrícula efetivada e sincronizada com sucesso!");
    } catch (err: any) {
      console.error("Firestore Save Error:", err);
      if (err.code === 'permission-denied') alert("Erro de permissão no banco de dados.");
      else alert("Erro ao gravar dados. Verifique o tamanho da foto.");
    } finally {
      setActionLoading(false);
    }
  };

  if (loading) return <div className="p-10 font-mono text-[10px] tracking-widest uppercase">Sincronizando Banco de Dados...</div>;

  return (
    <div className="space-y-1 animate-in fade-in duration-300">
