        <div className="fixed inset-0 z-[5000] bg-white flex flex-col animate-in slide-in-from-bottom duration-500 overflow-y-auto overflow-x-hidden">
          <header className="bg-slate-900 text-white px-8 py-8 flex justify-between items-center shrink-0">
            <div className="flex items-center gap-6">
              <div className="p-4 bg-indigo-600 shadow-xl rounded-2xl"><UserCog size={28}/></div>
              <div>
                <h2 className="text-2xl font-black uppercase italic tracking-tighter leading-none">Novo Registro Acadêmico</h2>
                <p className="text-[10px] font-bold text-indigo-400 uppercase tracking-widest mt-2">EB-AD Fluxo de Matrícula Master v3.2</p>
              </div>
            </div>
          </header>

          <div className="bg-white">
            <form onSubmit={handleSave} className="max-w-5xl mx-auto py-16 px-8 space-y-16">
              <section className="space-y-10">
                <h3 className="text-xs font-black uppercase border-l-4 border-indigo-600 pl-5 text-slate-800 italic tracking-[0.2em]">01. Identificação de Prontuário</h3>
                <div className="grid grid-cols-1 lg:grid-cols-4 gap-12">
                   <div className="lg:col-span-1 flex flex-col items-center gap-4">
                      <div 
                        onClick={() => fileInputRef.current?.click()} 
                        className="w-48 h-48 bg-slate-50 border-2 border-dashed border-slate-200 flex items-center justify-center cursor-pointer overflow-hidden relative group rounded-3xl"
                      >
                        {formData.fotoUrl ? (
                          <img src={formData.fotoUrl} className="w-full h-full object-cover" />
