import React, { useState, useEffect, useMemo, useRef } from 'react';
import { collection, query, where, onSnapshot, deleteDoc, serverTimestamp, doc, setDoc, getDocs, addDoc, getDoc } from "https://www.gstatic.com/firebasejs/10.7.1/firebase-firestore.js";
import { db } from '../firebase';
import { User, Course } from '../types';
import { Search, UserPlus, X, Save, UserCog, Trash2, Edit3, Camera, Eye, MapPin, ChevronLeft, ChevronRight, Filter, MoreHorizontal, Hash, RefreshCw, ArrowLeft, GraduationCap, FileText, Printer, Download, ShieldCheck, QrCode } from 'lucide-react';

const StudentsView: React.FC = () => {
  const [students, setStudents] = useState<User[]>([]);
  const [courses, setCourses] = useState<Course[]>([]);
  const [loading, setLoading] = useState(true);
  const [searchTerm, setSearchTerm] = useState('');
  const [courseFilter, setCourseFilter] = useState('');

  const [signatures, setSignatures] = useState<{diretor?: any, secretaria?: any}>({});
  const [currentPage, setCurrentPage] = useState(1);
  const itemsPerPage = 10;

  const [isRegisterModalOpen, setIsRegisterModalOpen] = useState(false);
  const [isProntuarioOpen, setIsProntuarioOpen] = useState(false);
  const [selectedStudent, setSelectedStudent] = useState<any>(null);
  const [actionLoading, setActionLoading] = useState(false);
  const fileInputRef = useRef<HTMLInputElement>(null);

  const [formData, setFormData] = useState({
    nome: '', emailPessoal: '', emailAcademico: '', telefone: '', cursoId: '', status: 'ativo', cpf: '', nascimento: '', fotoUrl: '', senhaNova: '',
    endereco: { cep: '', rua: '', numero: '', bairro: '', cidade: '', uf: '' }
  });

  useEffect(() => {
    const unsubS = onSnapshot(query(collection(db, 'users'), where('role', '==', 'aluno')), s => {
      setStudents(s.docs.map(d => ({ uid: d.id, ...d.data() } as User)).sort((a:any, b:any) => (b.createdAt?.seconds || 0) - (a.createdAt?.seconds || 0)));
      setLoading(false);
    });
    const unsubC = onSnapshot(collection(db, 'cursos'), s => setCourses(s.docs.map(d => ({ id: d.id, ...d.data() } as Course))));

    const fetchSignatures = async () => {
      const qDir = query(collection(db, 'users'), where('role', '==', 'diretor'));
      const qSec = query(collection(db, 'users'), where('role', '==', 'secretaria'));
      const [snapDir, snapSec] = await Promise.all([getDocs(qDir), getDocs(qSec)]);
      setSignatures({
        diretor: snapDir.docs[0]?.data(),
        secretaria: snapSec.docs[0]?.data()
      });
    };
    fetchSignatures();
    return () => { unsubS(); unsubC(); };
  }, []);

  useEffect(() => {
    if (formData.nome && !selectedStudent) {
      const names = formData.nome.trim().toLowerCase().split(' ');
      const firstName = names[0];
      const lastName = names.length > 1 ? names[names.length - 1] : '';
      const existsFirst = students.some(s => s.email?.startsWith(`${firstName}@ead.com`));
      let suggestedEmail = `${firstName}@ead.com`;
      if (existsFirst && lastName) suggestedEmail = `${firstName}.${lastName}@ead.com`;
      setFormData(prev => ({ ...prev, emailAcademico: suggestedEmail }));
    }
  }, [formData.nome, selectedStudent, students]);

  useEffect(() => {
    const cep = formData.endereco.cep.replace(/\D/g, '');
    if (cep.length === 8) {
      fetch(`https://viacep.com.br/ws/${cep}/json/`)
        .then(res => res.json())
        .then(data => {
          if (!data.erro) {
            setFormData(prev => ({
              ...prev,
              endereco: { ...prev.endereco, rua: data.logradouro, bairro: data.bairro, cidade: data.localidade, uf: data.uf }
            }));
          }
        });
    }
  }, [formData.endereco.cep]);

  const filtered = useMemo(() => students.filter(s => {
    const name = (s.displayName || (s as any).nome || '').toLowerCase();
    const aid = ((s as any).academicId || '').toLowerCase();
    const matchSearch = name.includes(searchTerm.toLowerCase()) || aid.includes(searchTerm.toLowerCase()) || s.email?.toLowerCase().includes(searchTerm.toLowerCase());
    const matchCourse = !courseFilter || (s as any).cursoInicial === courseFilter;
    return matchSearch && matchCourse;
  }), [students, searchTerm, courseFilter]);

  const totalPages = Math.ceil(filtered.length / itemsPerPage);
  const currentTableData = useMemo(() => {
    const start = (currentPage - 1) * itemsPerPage;
    return filtered.slice(start, start + itemsPerPage);
  }, [filtered, currentPage]);

  const compressImage = (base64: string): Promise<string> => {
    return new Promise((resolve) => {
      const img = new Image();
      img.src = base64;
      img.onload = () => {
        const canvas = document.createElement('canvas');
        const MAX_WIDTH = 400;
        const scale = MAX_WIDTH / img.width;
        canvas.width = MAX_WIDTH;
        canvas.height = img.height * scale;
        const ctx = canvas.getContext('2d');
        ctx?.drawImage(img, 0, 0, canvas.width, canvas.height);
        resolve(canvas.toDataURL('image/jpeg', 0.7));
      };
    });
  };

  const handleFileChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (file) {
      if (file.size > 2 * 1024 * 1024) {
        alert("Imagem muito grande!");
        return;
      }
      const reader = new FileReader();
      reader.onload = async (ev) => {
        const base64 = ev.target?.result as string;
        const compressed = await compressImage(base64);
        setFormData(prev => ({ ...prev, fotoUrl: compressed }));
      };
      reader.readAsDataURL(file);
    }
  };

  const handleSave = async (e: React.FormEvent) => {
    e.preventDefault();
    setActionLoading(true);
    try {
      const uid = selectedStudent?.uid || Math.random().toString(36).substring(2, 15);
      const academicId = selectedStudent?.academicId || `MAT-${new Date().getFullYear()}-${Math.random().toString(36).substring(2, 7).toUpperCase()}`;
      // Gera um Hash de Autenticidade Único se for novo
      const authHash = selectedStudent?.authHash || Math.random().toString(36).substring(2, 12).toUpperCase() + "-" + Date.now().toString().slice(-4);

      const payload: any = {
        uid,
        displayName: formData.nome,
        nome: formData.nome,
        email: formData.emailAcademico.toLowerCase().trim(),
        emailPessoal: formData.emailPessoal.toLowerCase().trim(),
        telefone: formData.telefone,
        cpf: formData.cpf,
        nascimento: formData.nascimento,
        photoURL: formData.fotoUrl || '',
        endereco: formData.endereco,
        cursoInicial: formData.cursoId,
        role: 'aluno',
        status: selectedStudent ? (selectedStudent.status || 'ativo') : 'ativo',
        academicId,
        authHash, // Código de verificação exclusivo
        updatedAt: serverTimestamp(),
        createdAt: selectedStudent?.createdAt || serverTimestamp()
      };

      if (formData.senhaNova) payload.password = formData.senhaNova;
      await setDoc(doc(db, 'users', uid), payload, { merge: true });
      setIsRegisterModalOpen(false);
      setSelectedStudent(null);
      alert("Matrícula efetivada com sucesso!");
    } catch (err) {
      alert("Erro ao gravar dados.");
    } finally {
      setActionLoading(false);
    }
  };

  if (loading) return <div className="p-10 font-mono text-[10px] tracking-widest uppercase text-slate-400 text-center">Sincronizando Banco de Dados...</div>;

  return (
    <div className="space-y-1 animate-in fade-in duration-300">
      {/* MODO TELA CHEIA PARA CADASTRO */}
      {isRegisterModalOpen && (
        <div className="fixed inset-0 z-[5000] bg-white flex flex-col animate-in slide-in-from-bottom duration-500 overflow-y-auto overflow-x-hidden print:hidden">
          <header className="bg-slate-900 text-white px-8 py-8 flex justify-between items-center shrink-0">
            <div className="flex items-center gap-6">
              <div className="p-4 bg-indigo-600 shadow-xl rounded-2xl"><UserCog size={28}/></div>
              <div><h2 className="text-2xl font-black uppercase italic tracking-tighter leading-none">Matrícula Master de Aluno</h2><p className="text-[10px] font-bold text-indigo-400 uppercase tracking-widest mt-2">EB-AD Fluxo Acadêmico v3.2</p></div>
            </div>
          </header>
          <div className="bg-white">
            <form onSubmit={handleSave} className="max-w-5xl mx-auto py-16 px-8 space-y-16 pb-40">
              <section className="space-y-10">
                <h3 className="text-xs font-black uppercase border-l-4 border-indigo-600 pl-5 text-slate-800 italic tracking-[0.2em]">01. Identificação de Prontuário</h3>
                <div className="grid grid-cols-1 lg:grid-cols-4 gap-12">
                   <div className="lg:col-span-1 flex flex-col items-center gap-4">
                      <div onClick={() => fileInputRef.current?.click()} className="w-48 h-48 bg-slate-50 border-2 border-dashed border-slate-200 flex items-center justify-center cursor-pointer overflow-hidden relative group rounded-3xl">
                        {formData.fotoUrl ? <img src={formData.fotoUrl} className="w-full h-full object-cover" /> : <div className="text-center p-6 opacity-30"><Camera size={40} className="mx-auto mb-2 text-indigo-600"/><span className="text-[9px] font-black uppercase tracking-widest">Enviar Foto</span></div>}
                        <div className="absolute inset-0 bg-indigo-600/40 opacity-0 group-hover:opacity-100 flex items-center justify-center transition-all"><RefreshCw size={24} className="text-white" /></div>
                      </div>
                      <input type="file" ref={fileInputRef} className="hidden" accept="image/*" onChange={handleFileChange} />
                   </div>
                   <div className="lg:col-span-3 grid grid-cols-1 sm:grid-cols-2 gap-x-10 gap-y-6">
                      <div className="space-y-2"><label className="text-[9px] font-black text-slate-400 uppercase italic ml-1">Nome Completo</label><input required value={formData.nome} onChange={e => setFormData({...formData, nome: e.target.value})} className="w-full border-b border-slate-200 bg-transparent py-3 text-sm font-bold outline-none focus:border-indigo-600" placeholder="Nome do Aluno..." /></div>
                      <div className="space-y-2"><label className="text-[9px] font-black text-slate-400 uppercase italic ml-1">WhatsApp</label><input required value={formData.telefone} onChange={e => setFormData({...formData, telefone: e.target.value})} className="w-full border-b border-slate-200 bg-transparent py-3 text-sm font-bold outline-none focus:border-indigo-600" placeholder="(00) 00000-0000" /></div>
                      <div className="space-y-2"><label className="text-[9px] font-black text-slate-400 uppercase italic ml-1">Documento CPF</label><input required value={formData.cpf} onChange={e => setFormData({...formData, cpf: e.target.value})} className="w-full border-b border-slate-200 bg-transparent py-3 text-sm font-bold outline-none focus:border-indigo-600" placeholder="000.000.000-00" /></div>
                      <div className="space-y-2"><label className="text-[9px] font-black text-slate-400 uppercase italic ml-1">Nascimento</label><input required type="date" value={formData.nascimento} onChange={e => setFormData({...formData, nascimento: e.target.value})} className="w-full border-b border-slate-200 bg-transparent py-3 text-sm font-bold outline-none focus:border-indigo-600 uppercase" /></div>
                   </div>
                </div>
              </section>
              <section className="space-y-10">
                <h3 className="text-xs font-black uppercase border-l-4 border-indigo-600 pl-5 text-slate-800 italic tracking-[0.2em]">02. Localidade de Domicílio</h3>
                <div className="grid grid-cols-1 md:grid-cols-6 gap-6">
                   <div className="md:col-span-1 space-y-2"><label className="text-[9px] font-black text-slate-400 uppercase ml-1">CEP</label><input required value={formData.endereco.cep} onChange={e => setFormData({...formData, endereco: {...formData.endereco, cep: e.target.value}})} className="w-full border-b border-slate-200 bg-transparent py-3 text-sm font-bold outline-none" placeholder="00000-000" /></div>
                   <div className="md:col-span-4 space-y-2"><label className="text-[9px] font-black text-slate-400 uppercase ml-1">Rua / Logradouro</label><input required value={formData.endereco.rua} onChange={e => setFormData({...formData, endereco: {...formData.endereco, rua: e.target.value}})} className="w-full border-b border-slate-200 bg-slate-50 py-3 px-4 text-sm font-bold outline-none" /></div>
                   <div className="md:col-span-1 space-y-2"><label className="text-[9px] font-black text-slate-400 uppercase ml-1">Nº</label><input required value={formData.endereco.numero} onChange={e => setFormData({...formData, endereco: {...formData.endereco, numero: e.target.value}})} className="w-full border-b border-slate-200 bg-transparent py-3 text-sm font-bold outline-none" placeholder="S/N" /></div>
                </div>
              </section>
              <section className="space-y-10">
                <h3 className="text-xs font-black uppercase border-l-4 border-indigo-600 pl-5 text-slate-800 italic tracking-[0.2em]">03. Parâmetros Acadêmicos</h3>
                <div className="grid grid-cols-1 lg:grid-cols-2 gap-10">
                   <div className="space-y-6">
                      <div className="space-y-2"><label className="text-[9px] font-black text-indigo-600 uppercase italic ml-1 tracking-widest">Login (Gerado Auto)</label><div className="w-full border border-indigo-100 bg-indigo-50/20 p-4 text-sm font-black text-indigo-600 italic">{formData.emailAcademico || 'Aguardando nome...'}</div></div>
                      <div className="space-y-2"><label className="text-[9px] font-black text-rose-500 uppercase italic ml-1 tracking-widest">{selectedStudent ? 'Mudar Senha' : 'Criar Senha'}</label><input type="password" required={!selectedStudent} value={formData.senhaNova} onChange={e => setFormData({...formData, senhaNova: e.target.value})} className="w-full border border-rose-100 bg-rose-50/10 p-4 text-sm font-bold outline-none" /></div>
                   </div>
                   <div className="space-y-6">
                      <div className="space-y-2"><label className="text-[9px] font-black text-slate-400 uppercase italic ml-1">Matriz de Ingresso</label><select required value={formData.cursoId} onChange={e => setFormData({...formData, cursoId: e.target.value})} className="w-full border border-slate-100 bg-white p-4 text-sm font-black uppercase outline-none appearance-none"><option value="">Selecionar...</option>{courses.map(c => <option key={c.id} value={c.id}>{c.nome}</option>)}</select></div>
                      <div className="space-y-2"><label className="text-[9px] font-black text-slate-400 uppercase italic ml-1">E-mail Pessoal</label><input type="email" value={formData.emailPessoal} onChange={e => setFormData({...formData, emailPessoal: e.target.value})} className="w-full border border-slate-100 bg-white p-4 text-sm font-bold outline-none" placeholder="exemplo@gmail.com" /></div>
                   </div>
                </div>
              </section>
              <div className="flex flex-col md:flex-row items-center justify-center gap-6 border-t border-slate-100 pt-12">
                <button type="button" onClick={() => setIsRegisterModalOpen(false)} className="px-12 py-5 bg-white border border-slate-300 text-slate-400 hover:text-rose-600 rounded-2xl text-[10px] font-black uppercase italic tracking-widest transition-all">Cancelar</button>
                <button type="submit" disabled={actionLoading} className="w-full md:max-w-md px-12 py-5 bg-slate-900 text-white text-[10px] font-black uppercase italic tracking-[0.3em] hover:bg-indigo-600 shadow-2xl transition-all flex items-center justify-center gap-4 rounded-2xl">
                  {actionLoading ? <RefreshCw className="animate-spin" size={20}/> : <><Save size={20}/> Efetivar Matrícula</>}
                </button>
              </div>
            </form>
          </div>
        </div>
      )}

      {/* LISTAGEM PRINCIPAL */}
      {!isRegisterModalOpen && (
        <div className="print:hidden space-y-4">
          <header className="flex justify-between items-center bg-white border border-slate-200 p-6 shadow-sm">
            <div><h1 className="text-xl font-black uppercase italic tracking-tighter text-slate-900 leading-none">Gestão de Alunos</h1><p className="text-[10px] font-bold text-slate-400 uppercase tracking-[0.3em] mt-2">EB-AD Administração Centralizada</p></div>
            <button onClick={() => { setSelectedStudent(null); setFormData({nome:'', emailPessoal:'', emailAcademico:'', telefone:'', cursoId:'', status:'ativo', cpf:'', nascimento:'', fotoUrl:'', senhaNova:'', endereco:{cep:'', rua:'', numero:'', bairro:'', cidade:'', uf:''}}); setIsRegisterModalOpen(true); }} className="bg-slate-900 text-white px-8 py-3 text-[10px] font-black uppercase italic hover:bg-indigo-600 transition-all flex items-center gap-3 shadow-lg shadow-slate-200"><UserPlus size={16} /> Novo Aluno</button>
          </header>
          <div className="bg-white border-x border-slate-200 p-4 flex flex-col md:flex-row items-center gap-4">
            <div className="relative flex-1 w-full"><Search size={16} className="absolute left-4 top-1/2 -translate-y-1/2 text-slate-400" /><input value={searchTerm} onChange={e => { setSearchTerm(e.target.value); setCurrentPage(1); }} placeholder="Pesquisar..." className="w-full pl-12 pr-4 py-3 bg-slate-50 border border-slate-200 text-xs font-bold outline-none focus:border-indigo-500 focus:bg-white transition-all" /></div>
          </div>
          <div className="bg-white border border-slate-200 overflow-hidden shadow-sm">
            <table className="w-full text-left border-collapse">
              <thead className="bg-slate-50 border-b border-slate-200 text-[10px] font-black uppercase text-slate-500 italic tracking-widest">
                <tr><th className="px-6 py-4">Matrícula</th><th className="px-6 py-4">Aluno</th><th className="px-6 py-4">Login</th><th className="px-6 py-4 text-center">Status</th><th className="px-6 py-4 text-center">Gestão</th></tr>
              </thead>
              <tbody className="text-xs">
                {currentTableData.map(s => (
                  <tr key={s.uid} className="border-b border-slate-100 hover:bg-indigo-50/20 transition-all group">
                    <td className="px-6 py-4 font-mono font-bold text-indigo-600">{(s as any).academicId || '---'}</td>
                    <td className="px-6 py-4 font-black uppercase italic text-slate-900">{s.displayName}</td>
                    <td className="px-6 py-4 text-slate-400">{s.email}</td>
                    <td className="px-6 py-4 text-center"><span className={`px-3 py-1 font-black uppercase italic text-[8px] border ${s.status === 'ativo' ? 'bg-emerald-50 text-emerald-700 border-emerald-100' : 'bg-rose-50 text-rose-700 border-rose-100'}`}>{s.status}</span></td>
                    <td className="px-6 py-4 text-center flex justify-center gap-1">
                        <button onClick={() => { setSelectedStudent(s); setIsProntuarioOpen(true); }} className="p-2 border border-slate-200 hover:bg-slate-900 hover:text-white transition-all"><Eye size={14}/></button>
                        <button onClick={() => { setSelectedStudent(s); setFormData({ nome: s.displayName, emailPessoal: (s as any).emailPessoal || '', emailAcademico: s.email || '', telefone: (s as any).telefone || '', cursoId: (s as any).cursoInicial || '', status: s.status || 'ativo', cpf: (s as any).cpf || '', nascimento: (s as any).nascimento || '', fotoUrl: (s as any).photoURL || '', senhaNova: '', endereco: (s as any).endereco || {cep:'', rua:'', numero:'', bairro:'', cidade:'', uf:''} }); setIsRegisterModalOpen(true); }} className="p-2 border border-slate-200 hover:bg-slate-900 hover:text-white transition-all"><Edit3 size={14}/></button>
                        <button onClick={async () => { if(confirm('Remover?')) await deleteDoc(doc(db, 'users', s.uid)); }} className="p-2 border border-slate-200 hover:bg-rose-600 hover:text-white transition-all"><Trash2 size={14}/></button>
                    </td>
                  </tr>
                ))}
              </tbody>
            </table>
          </div>
        </div>
      )}

      {/* FICHA ACADÊMICA A4 SINGLE PAGE */}
      {isProntuarioOpen && selectedStudent && (
        <div className="fixed inset-0 z-[6000] bg-slate-900/60 backdrop-blur-md flex items-center justify-center p-0 md:p-4 animate-in fade-in overflow-y-auto print:bg-white print:p-0 print:block print:relative print:z-auto">
          <div className="bg-white w-full max-w-[820px] shadow-[0_50px_100px_rgba(0,0,0,0.5)] print:shadow-none print:max-w-none print:w-full min-h-[1100px] flex flex-col">
            {/* TOOLBAR */}
            <div className="bg-slate-50 border-b border-slate-200 p-4 flex justify-between items-center sticky top-0 z-10 print:hidden">
               <button onClick={() => setIsProntuarioOpen(false)} className="p-2.5 hover:bg-slate-200 rounded-xl text-slate-600 transition-all"><ArrowLeft size={18}/></button>
               <div className="flex gap-2">
                  <button onClick={() => window.print()} className="px-5 py-2 bg-white border border-slate-200 rounded-lg text-[9px] font-black uppercase flex items-center gap-2 shadow-sm"><Printer size={14}/> Imprimir Página Única</button>
                  <button className="px-5 py-2 bg-slate-900 text-white rounded-lg text-[9px] font-black uppercase flex items-center gap-2 shadow-lg"><Download size={14}/> PDF Master</button>
               </div>
            </div>

            {/* CONTEÚDO A4 */}
            <div id="print-area" className="flex-1 p-10 md:p-12 text-slate-900 font-serif bg-white flex flex-col print:p-8">
               {/* HEADER COMPACTADO */}
               <div className="flex justify-between items-start border-b-2 border-slate-900 pb-6 mb-8">
                  <div className="space-y-1">
                     <h2 className="text-xl font-black uppercase tracking-tighter italic font-sans leading-none">Escola Bíblica AD</h2>
                     <p className="text-[8px] font-bold uppercase tracking-widest text-slate-400 font-sans italic">Ensino Teológico de Alta Performance</p>
                     <div className="mt-4 text-[9px] font-sans font-bold text-slate-500 uppercase space-y-0.5">
                        <p>Matrícula: {selectedStudent.academicId || 'S/REF'}</p>
                        <p>Emissão: {new Date().toLocaleDateString('pt-BR')}</p>
                     </div>
                  </div>
                  <div className="flex items-start gap-4">
                     <div className="text-right">
                        <p className="text-[7px] font-black uppercase font-sans text-slate-300 tracking-[0.2em] mb-1">Código de Verificação</p>
                        <p className="text-[10px] font-mono font-bold text-indigo-600 bg-indigo-50 px-2 py-1 border border-indigo-100 rounded tracking-tighter">{selectedStudent.authHash || 'GEN-PENDING'}</p>
                     </div>
                     <div className="w-24 h-32 border border-slate-200 bg-slate-50 flex items-center justify-center p-1 shadow-sm overflow-hidden">
                        {selectedStudent.photoURL ? <img src={selectedStudent.photoURL} className="w-full h-full object-cover grayscale" /> : <div className="text-[8px] font-sans font-black text-slate-200 uppercase text-center">FOTO</div>}
                     </div>
                  </div>
               </div>

               {/* TÍTULO */}
               <div className="text-center mb-8">
                  <h1 className="text-2xl font-black uppercase tracking-[0.15em] font-sans border-y py-3 border-slate-100">Prontuário de Registro Acadêmico</h1>
               </div>

               {/* DADOS - GRID OTIMIZADO PARA PÁGINA ÚNICA */}
               <div className="flex-1 space-y-6">
                  <section className="space-y-4">
                     <h3 className="text-[11px] font-black uppercase font-sans border-l-4 border-slate-900 pl-4 tracking-widest italic bg-slate-50 py-1.5">I. Dados de Identificação</h3>
                     <div className="grid grid-cols-2 gap-y-4 gap-x-10 px-4 text-xs italic">
                        <div><p className="text-[8px] font-bold font-sans uppercase text-slate-400">Nome Civil</p><p className="font-bold border-b border-slate-100 pb-0.5">{selectedStudent.displayName}</p></div>
                        <div><p className="text-[8px] font-bold font-sans uppercase text-slate-400">CPF</p><p className="font-bold border-b border-slate-100 pb-0.5">{selectedStudent.cpf || '---'}</p></div>
                        <div><p className="text-[8px] font-bold font-sans uppercase text-slate-400">Nascimento</p><p className="font-bold border-b border-slate-100 pb-0.5">{selectedStudent.nascimento ? new Date(selectedStudent.nascimento).toLocaleDateString('pt-BR') : '---'}</p></div>
                        <div><p className="text-[8px] font-bold font-sans uppercase text-slate-400">WhatsApp</p><p className="font-bold border-b border-slate-100 pb-0.5">{selectedStudent.telefone || '---'}</p></div>
                        <div className="col-span-2"><p className="text-[8px] font-bold font-sans uppercase text-slate-400">Residência</p><p className="font-bold border-b border-slate-100 pb-0.5 truncate">{selectedStudent.endereco?.rua}, {selectedStudent.endereco?.numero} - {selectedStudent.endereco?.cidade}/{selectedStudent.endereco?.uf}</p></div>
                     </div>
                  </section>

                  <section className="space-y-4">
                     <h3 className="text-[11px] font-black uppercase font-sans border-l-4 border-slate-900 pl-4 tracking-widest italic bg-slate-50 py-1.5">II. Vínculo Institucional</h3>
                     <div className="grid grid-cols-2 gap-y-4 gap-x-10 px-4 text-xs italic">
                        <div><p className="text-[8px] font-bold font-sans uppercase text-slate-400">Matriz de Ingresso</p><p className="font-bold border-b border-slate-100 pb-0.5 text-indigo-900">{courses.find(c => c.id === selectedStudent.cursoInicial)?.nome || 'Pendente'}</p></div>
                        <div><p className="text-[8px] font-bold font-sans uppercase text-slate-400">Login Oficial</p><p className="font-bold border-b border-slate-100 pb-0.5 lowercase">{selectedStudent.email}</p></div>
                        <div><p className="text-[8px] font-bold font-sans uppercase text-slate-400">Status Operacional</p><p className="font-bold border-b border-slate-100 pb-0.5 uppercase">{selectedStudent.status}</p></div>
                        <div><p className="text-[8px] font-bold font-sans uppercase text-slate-400">Data Matrícula</p><p className="font-bold border-b border-slate-100 pb-0.5">{selectedStudent.createdAt?.seconds ? new Date(selectedStudent.createdAt.seconds * 1000).toLocaleDateString('pt-BR') : 'Recent'}</p></div>
                     </div>
                  </section>

                  <div className="text-center pt-4">
                     <p className="text-[9px] text-slate-400 font-sans italic">Documento emitido via sistema central de gestão acadêmica EAD EB-AD.</p>
