                           <div className="w-full border-t border-slate-900"></div>
                        </div>
                        <p className="text-[9px] font-black uppercase font-sans tracking-tighter leading-none italic">Secretaria Acadêmica Geral</p>
                        <p className="text-[7px] font-bold uppercase font-sans text-slate-400 mt-0.5">{signatures.secretaria?.nome || 'Titular'}</p>
                     </div>
                     <div className="flex flex-col items-center">
                        <div className="h-16 flex flex-col items-center justify-end mb-1">
                           {signatures.diretor?.signatureUrl && <img src={signatures.diretor.signatureUrl} className="max-h-12 grayscale" />}
                           <div className="w-full border-t border-slate-900"></div>
                        </div>
                        <p className="text-[9px] font-black uppercase font-sans tracking-tighter leading-none italic">Diretoria Executiva</p>
                        <p className="text-[7px] font-bold uppercase font-sans text-slate-400 mt-0.5">{signatures.diretor?.nome || 'Titular'}</p>
                     </div>
                  </div>
