          <div className="text-center"><h2 className="text-lg font-black uppercase italic tracking-tighter leading-none">Fluxo de Auto-Matrícula</h2><p className="text-[8px] font-bold text-slate-400 uppercase tracking-widest mt-1">Disciplina: {selectedCourse.nome}</p></div>
          <div className="w-20"></div>
        </header>
        <div className="flex-1 overflow-y-auto bg-slate-50 py-12 px-6">
          <form onSubmit={handleFinalizeEnroll} className="max-w-4xl mx-auto bg-white rounded-[3rem] p-12 shadow-2xl space-y-12 border border-slate-100">
             <div className="grid grid-cols-1 lg:grid-cols-4 gap-12">
                <div className="lg:col-span-1 flex flex-col items-center gap-4">
                   <div onClick={() => fileInputRef.current?.click()} className="w-40 h-40 bg-slate-50 border-2 border-dashed border-slate-200 flex items-center justify-center cursor-pointer overflow-hidden rounded-3xl group hover:border-indigo-400">
                      {enrollForm.fotoUrl ? <img src={enrollForm.fotoUrl} className="w-full h-full object-cover" /> : <div className="text-center opacity-30"><Camera size={32} className="mx-auto"/><span className="text-[8px] font-black uppercase mt-2 block">Sua Foto</span></div>}
                   </div>
                   <input type="file" ref={fileInputRef} className="hidden" accept="image/*" onChange={handleFileUpload} />
                </div>
                <div className="lg:col-span-3 grid grid-cols-1 md:grid-cols-2 gap-6">
                   <div className="space-y-1"><label className="text-[9px] font-black text-slate-400 uppercase ml-2">Nome Completo</label><input required value={enrollForm.nome} onChange={e => setEnrollForm({...enrollForm, nome: e.target.value})} className="w-full p-4 bg-slate-50 border-none rounded-2xl text-xs font-bold shadow-inner outline-none focus:ring-1 focus:ring-indigo-600" /></div>
                   <div className="space-y-1"><label className="text-[9px] font-black text-slate-400 uppercase ml-2">WhatsApp</label><input required value={enrollForm.telefone} onChange={e => setEnrollForm({...enrollForm, telefone: e.target.value})} className="w-full p-4 bg-slate-50 border-none rounded-2xl text-xs font-bold shadow-inner outline-none focus:ring-1 focus:ring-indigo-600" placeholder="(00) 00000-0000" /></div>
                   <div className="space-y-1"><label className="text-[9px] font-black text-slate-400 uppercase ml-2">E-mail Pessoal</label><input type="email" required value={enrollForm.emailPessoal} onChange={e => setEnrollForm({...enrollForm, emailPessoal: e.target.value})} className="w-full p-4 bg-slate-50 border-none rounded-2xl text-xs font-bold shadow-inner outline-none focus:ring-1 focus:ring-indigo-600" /></div>
                   <div className="space-y-1"><label className="text-[9px] font-black text-slate-400 uppercase ml-2">Crie sua Senha</label><input type="password" required value={enrollForm.senha} onChange={e => setEnrollForm({...enrollForm, senha: e.target.value})} className="w-full p-4 bg-slate-50 border-none rounded-2xl text-xs font-bold shadow-inner outline-none focus:ring-1 focus:ring-indigo-600" /></div>
                   <div className="space-y-1"><label className="text-[9px] font-black text-slate-400 uppercase ml-2">CPF</label><input required value={enrollForm.cpf} onChange={e => setEnrollForm({...enrollForm, cpf: e.target.value})} className="w-full p-4 bg-slate-50 border-none rounded-2xl text-xs font-bold shadow-inner outline-none focus:ring-1 focus:ring-indigo-600" /></div>
                   <div className="space-y-1"><label className="text-[9px] font-black text-slate-400 uppercase ml-2">Nascimento</label><input type="date" required value={enrollForm.nascimento} onChange={e => setEnrollForm({...enrollForm, nascimento: e.target.value})} className="w-full p-4 bg-slate-50 border-none rounded-2xl text-xs font-bold shadow-inner outline-none focus:ring-1 focus:ring-indigo-600" /></div>
                </div>
             </div>
             <div className="space-y-6 pt-6 border-t border-slate-100">
                <h4 className="text-[10px] font-black uppercase text-indigo-600 italic flex items-center gap-2 tracking-widest"><MapPin size={16}/> Localidade de Domicílio</h4>
                <div className="grid grid-cols-1 md:grid-cols-6 gap-4">
                   <div className="md:col-span-1 space-y-1"><label className="text-[8px] font-bold text-slate-400 uppercase ml-1">CEP</label><input required value={enrollForm.endereco.cep} onChange={e => setEnrollForm({...enrollForm, endereco: {...enrollForm.endereco, cep: e.target.value}})} className="w-full p-3 bg-slate-50 border-none rounded-xl text-[10px] font-bold shadow-inner" placeholder="00000-000" /></div>
                   <div className="md:col-span-4 space-y-1"><label className="text-[8px] font-bold text-slate-400 uppercase ml-1">Logradouro / Rua</label><input required value={enrollForm.endereco.rua} onChange={e => setEnrollForm({...enrollForm, endereco: {...enrollForm.endereco, rua: e.target.value}})} className="w-full p-3 bg-slate-50 border-none rounded-xl text-[10px] font-bold shadow-inner" /></div>
                   <div className="md:col-span-1 space-y-1"><label className="text-[8px] font-bold text-slate-400 uppercase ml-1">Nº</label><input required value={enrollForm.endereco.numero} onChange={e => setEnrollForm({...enrollForm, endereco: {...enrollForm.endereco, numero: e.target.value}})} className="w-full p-3 bg-slate-50 border-none rounded-xl text-[10px] font-bold shadow-inner" placeholder="S/N" /></div>
                   <div className="md:col-span-2 space-y-1"><label className="text-[8px] font-bold text-slate-400 uppercase ml-1">Bairro</label><input required value={enrollForm.endereco.bairro} onChange={e => setEnrollForm({...enrollForm, endereco: {...enrollForm.endereco, bairro: e.target.value}})} className="w-full p-3 bg-slate-50 border-none rounded-xl text-[10px] font-bold shadow-inner" /></div>
                   <div className="md:col-span-3 space-y-1"><label className="text-[8px] font-bold text-slate-400 uppercase ml-1">Cidade</label><input required value={enrollForm.endereco.cidade} onChange={e => setEnrollForm({...enrollForm, endereco: {...enrollForm.endereco, cidade: e.target.value}})} className="w-full p-3 bg-slate-50 border-none rounded-xl text-[10px] font-bold shadow-inner" /></div>
                   <div className="md:col-span-1 space-y-1"><label className="text-[8px] font-bold text-slate-400 uppercase ml-1">UF</label><input required value={enrollForm.endereco.uf} onChange={e => setEnrollForm({...enrollForm, endereco: {...enrollForm.endereco, uf: e.target.value.toUpperCase()}})} maxLength={2} className="w-full p-3 bg-slate-50 border-none rounded-xl text-[10px] font-black shadow-inner uppercase" /></div>
                </div>
             </div>
             {error && <div className="p-4 bg-rose-50 text-rose-600 text-[10px] font-black uppercase rounded-2xl">{error}</div>}
             <button type="submit" disabled={loading} className="w-full py-6 bg-slate-900 text-white rounded-[2rem] text-[11px] font-black uppercase italic tracking-[0.4em] shadow-2xl hover:bg-indigo-600 transition-all flex items-center justify-center gap-3 active:scale-[0.98]">
               {loading ? <RefreshCw className="animate-spin" size={20}/> : <><ShieldCheck size={20}/> Concluir Auto-Matrícula</>}
             </button>
          </form>
        </div>
      </div>
    );
  }

  if (viewMode === 'success_notice') {
    return (
      <div className="min-h-screen bg-slate-950 flex items-center justify-center p-6 text-center">
         <div className="max-w-md w-full bg-white rounded-[3rem] p-12 shadow-[0_50px_100px_rgba(0,0,0,0.5)] space-y-10 animate-in zoom-in-95">
            <div className="w-24 h-24 bg-emerald-50 text-emerald-600 rounded-[2.5rem] flex items-center justify-center mx-auto shadow-inner"><CheckCircle2 size={48}/></div>
            <div className="space-y-4">
              <h2 className="text-3xl font-black text-slate-900 uppercase italic tracking-tighter leading-none">Matrícula Master Registrada!</h2>
              <p className="text-slate-400 text-xs font-medium italic">Seu perfil está aguardando ativação final da secretaria acadêmica.</p>
            </div>
            <div className="p-8 bg-indigo-50/50 rounded-[2.5rem] border border-indigo-100 space-y-4">
               <p className="text-[9px] font-black uppercase text-indigo-400 tracking-widest">Login Acadêmico Automático</p>
               <p className="text-sm font-black text-indigo-600 italic select-all underline">{generatedEmail}</p>
            </div>
            <button onClick={() => setViewMode('login')} className="w-full py-5 bg-slate-900 text-white rounded-2xl text-[10px] font-black uppercase italic tracking-widest hover:bg-indigo-600 transition-all shadow-xl">Entrar na Sala de Aula</button>
         </div>
      </div>
    );
  }

  return (
    <div className="min-h-screen bg-slate-950 flex items-center justify-center p-6">
       <div className="max-w-md w-full bg-white rounded-[3rem] p-12 border border-white/10 shadow-[0_50px_100px_rgba(0,0,0,0.5)] space-y-8 text-center animate-in zoom-in-95">
          <div className="w-20 h-20 bg-indigo-600 text-white rounded-[2rem] flex items-center justify-center mx-auto shadow-2xl animate-pulse"><Lock size={40}/></div>
          <div className="space-y-1">
             <h2 className="text-2xl font-black uppercase italic tracking-tighter text-slate-900 leading-none">Acesso Acadêmico</h2>
             <p className="text-[10px] font-bold text-slate-400 uppercase tracking-widest italic">EB-EAD Sala Virtual</p>
          </div>
          {error && <div className="p-4 bg-rose-50 text-rose-600 text-[10px] font-black uppercase border border-rose-100 rounded-2xl flex items-center gap-3"><Info size={16}/> {error}</div>}
          <form onSubmit={handleLogin} className="space-y-4">
             <div className="space-y-1 text-left"><label className="text-[9px] font-black uppercase text-slate-400 ml-4 italic">Login E-mail</label><input type="email" required value={email} onChange={e => setEmail(e.target.value)} className="w-full p-4 bg-slate-50 border-none rounded-2xl text-xs font-bold shadow-inner outline-none focus:ring-1 focus:ring-indigo-600" /></div>
             <div className="space-y-1 text-left"><label className="text-[9px] font-black uppercase text-slate-400 ml-4 italic">Senha Secreta</label><input type="password" required value={password} onChange={e => setPassword(e.target.value)} className="w-full p-4 bg-slate-50 border-none rounded-2xl text-xs font-bold shadow-inner outline-none focus:ring-1 focus:ring-indigo-600" /></div>
             <button type="submit" disabled={loading} className="w-full py-5 bg-slate-900 text-white rounded-2xl text-[10px] font-black uppercase italic tracking-[0.3em] shadow-2xl hover:bg-indigo-600 transition-all">{loading ? 'Validando...' : 'Iniciar Sessão Digital'}</button>
          </form>
          <div className="pt-6 border-t border-slate-50 flex flex-col gap-3">
             <button onClick={() => setViewMode('landing')} className="text-[9px] font-black uppercase text-slate-300 hover:text-indigo-600 transition-colors italic">Ver Matriz de Cursos</button>
             <button onClick={() => setIsAdminMode(!isAdminMode)} className="text-[9px] font-black uppercase text-slate-400 italic underline">{isAdminMode ? 'Voltar p/ Aluno' : 'Governança Institucional'}</button>
          </div>
       </div>
    </div>
  );
};

export default LoginView;

import React, { useState, useEffect, useRef } from 'react';
import { signInWithEmailAndPassword, createUserWithEmailAndPassword, signOut } from "https://www.gstatic.com/firebasejs/10.7.1/firebase-auth.js";
import { collection, query, where, onSnapshot, doc, setDoc, getDoc, serverTimestamp, getDocs } from "https://www.gstatic.com/firebasejs/10.7.1/firebase-firestore.js";
import { auth, db } from '../firebase';
import { Lock, GraduationCap, ArrowRight, BookOpen, Star, Camera, MapPin, Key, ChevronLeft, Info, ImageIcon, Users, Zap, ShieldCheck, MessageCircle, Play, Flame, RefreshCw, CheckCircle2, Quote, Activity, Award, LogIn } from 'lucide-react';

type ViewMode = 'landing' | 'login' | 'enroll_form' | 'success_notice';

const LoginView: React.FC = () => {
  const [viewMode, setViewMode] = useState<ViewMode>('landing');
  const [email, setEmail] = useState('');
  const [password, setPassword] = useState('');
  const [error, setError] = useState('');
  const [loading, setLoading] = useState(false);
  const [isAdminMode, setIsAdminMode] = useState(false);

  const [courses, setCourses] = useState<any[]>([]);
  const [selectedCourse, setSelectedCourse] = useState<any>(null);
  const [generatedEmail, setGeneratedEmail] = useState('');
  const [realStats, setRealStats] = useState({ students: 0, classes: 0, rating: '0.0' });
  const [realFeedbacks, setRealFeedbacks] = useState<any[]>([]);

  const [enrollForm, setEnrollForm] = useState({
    nome: '', emailPessoal: '', senha: '', cpf: '', nascimento: '', telefone: '', fotoUrl: '',
    endereco: { cep: '', rua: '', numero: '', bairro: '', cidade: '', uf: '' }
  });

  const fileInputRef = useRef<HTMLInputElement>(null);

  useEffect(() => {
    // Sincronização de Cursos
    const unsubC = onSnapshot(query(collection(db, 'cursos'), where('status', '==', 'ativo')), (snap) => {
      setCourses(snap.docs.map(d => ({ id: d.id, ...d.data() })));
    });

    // Sincronização de Estatísticas Reais
    const unsubS = onSnapshot(query(collection(db, 'users'), where('role', '==', 'aluno')), (snap) => {
      setRealStats(prev => ({ ...prev, students: snap.size }));
    });

    // Sincronização de Feedbacks Reais
    const unsubF = onSnapshot(collection(db, 'feedbacks'), (snap) => {
      const data = snap.docs.map(d => d.data());
      setRealFeedbacks(data.slice(0, 3));
      if (data.length > 0) {
        const avg = data.reduce((acc, curr) => acc + (curr.rating || 0), 0) / data.length;
        setRealStats(prev => ({ ...prev, rating: avg.toFixed(1) }));
      }
    });

    return () => { unsubC(); unsubS(); unsubF(); };
  }, []);

  useEffect(() => {
    const cep = enrollForm.endereco.cep.replace(/\D/g, '');
    if (cep.length === 8) {
      fetch(`https://viacep.com.br/ws/${cep}/json/`)
        .then(res => res.json())
        .then(data => {
          if (!data.erro) {
            setEnrollForm(prev => ({
              ...prev,
              endereco: { ...prev.endereco, rua: data.logradouro, bairro: data.bairro, cidade: data.localidade, uf: data.uf }
            }));
          }
        });
    }
  }, [enrollForm.endereco.cep]);

  const handleLogin = async (e: React.FormEvent) => {
    e.preventDefault();
    setLoading(true);
    setError('');
    try {
      const userCredential = await signInWithEmailAndPassword(auth, email.trim().toLowerCase(), password);
      const userDoc = await getDoc(doc(db, 'users', userCredential.user.uid));

      if (userDoc.exists()) {
        const userData = userDoc.data();
        // Se for admin mode mas o user for aluno, barra. 
        // Se for login normal (aluno), App.tsx cuidará do roteamento.
        if (isAdminMode && userData.role === 'aluno') {
          await signOut(auth);
          setError('Acesso administrativo negado.');
          setLoading(false);
          return;
        }
      } else {
        // Se o usuário existe no Auth mas não no Firestore (migração ou erro de criação manual)
        // Criamos o perfil básico para não quebrar o login
        const emailLower = email.toLowerCase();
        const role = emailLower.includes('@ead.com') ? 'aluno' : 'diretor';
        await setDoc(doc(db, 'users', userCredential.user.uid), {
          uid: userCredential.user.uid,
          email: emailLower,
          displayName: userCredential.user.displayName || 'Usuário Migrado',
          role: role,
          status: 'ativo',
          createdAt: serverTimestamp()
        });
      }
    } catch (err: any) {
      setError('Credenciais inválidas ou erro de conexão.');
      setLoading(false);
    }
  };

  const generateAcademicEmail = async (fullName: string) => {
    const names = fullName.trim().toLowerCase().split(' ');
    const firstName = names[0];
    const lastName = names.length > 1 ? names[names.length - 1] : '';
    let baseEmail = `${firstName}@ead.com`;
    const q = query(collection(db, 'users'), where('email', '==', baseEmail));
    const snap = await getDocs(q);
    if (!snap.empty && lastName) {
      baseEmail = `${firstName}.${lastName}@ead.com`;
    }
    return baseEmail;
  };

  const handleFinalizeEnroll = async (e: React.FormEvent) => {
    e.preventDefault();
    setLoading(true);
    setError('');
    try {
      const academicoEmail = await generateAcademicEmail(enrollForm.nome);
      const userCredential = await createUserWithEmailAndPassword(auth, academicoEmail, enrollForm.senha);
      const uid = userCredential.user.uid;
      const academicId = `MAT-${new Date().getFullYear()}-${Math.random().toString(36).substring(2, 7).toUpperCase()}`;
      const authHash = Math.random().toString(36).substring(2, 12).toUpperCase() + "-" + Date.now().toString().slice(-4);

      const payload = {
        uid,
        displayName: enrollForm.nome,
        nome: enrollForm.nome,
        email: academicoEmail,
        emailPessoal: enrollForm.emailPessoal.toLowerCase(),
        cpf: enrollForm.cpf,
        nascimento: enrollForm.nascimento,
        telefone: enrollForm.telefone,
        photoURL: enrollForm.fotoUrl,
        endereco: enrollForm.endereco,
        role: 'aluno',
        status: 'ativo', // Alterado para ativo para garantir sincronização imediata
        cursoInicial: selectedCourse.id,
        academicId,
        authHash,
        createdAt: serverTimestamp(),
        progress: 0
      };

      await setDoc(doc(db, 'users', uid), payload);
      setGeneratedEmail(academicoEmail);
      setViewMode('success_notice');
      setLoading(false);
    } catch (err: any) {
      setError('Falha no registro: ' + (err.code === 'auth/email-already-in-use' ? 'Nome indisponível.' : 'Erro Firestore.'));
      setLoading(false);
    }
  };

  const handleFileUpload = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (file) {
      const reader = new FileReader();
      reader.onload = (ev) => setEnrollForm({...enrollForm, fotoUrl: ev.target?.result as string});
      reader.readAsDataURL(file);
    }
  };

  if (viewMode === 'landing') {
    return (
      <div className="min-h-screen bg-white font-sans text-slate-900 overflow-x-hidden">
        <div className="relative min-h-screen flex flex-col">
          <div className="absolute inset-0 z-0">
            <img src="https://images.unsplash.com/photo-1519791883288-dc8bd696e667?auto=format&fit=crop&w=1920&q=80" className="w-full h-full object-cover brightness-[0.2]" alt="Background Sacred study" />
            <div className="absolute inset-0 bg-gradient-to-b from-indigo-900/30 via-transparent to-white"></div>
          </div>

          <header className="relative z-10 h-24 px-8 flex items-center justify-between max-w-7xl mx-auto w-full">
            <div className="flex items-center gap-3">
              <div className="bg-indigo-600 p-2.5 rounded-2xl text-white shadow-2xl"><BookOpen size={28} /></div>
              <div className="flex flex-col">
                <span className="font-black text-white text-2xl uppercase italic tracking-tighter leading-none">Escola Bíblica AD</span>
                <span className="text-[10px] font-bold text-indigo-400 uppercase tracking-widest italic mt-1">EAD Teológico Master</span>
              </div>
            </div>
            <div className="hidden md:flex items-center gap-4">
              <button onClick={() => setViewMode('login')} className="px-8 py-3 bg-white/10 backdrop-blur-md text-white border border-white/20 rounded-full text-[11px] font-black uppercase italic hover:bg-white hover:text-slate-900 transition-all">Acessar Sala de Aula</button>
              <a href="#cursos" className="px-8 py-3 bg-indigo-600 text-white rounded-full text-[11px] font-black uppercase italic shadow-2xl hover:bg-indigo-500 transition-all">Matricule-se Já</a>
            </div>
          </header>

          <main className="relative z-10 flex-1 flex flex-col items-center justify-center text-center px-6 py-20 max-w-5xl mx-auto">
            <div className="inline-flex items-center gap-2 px-6 py-2 bg-indigo-600/30 backdrop-blur-xl rounded-full border border-indigo-400/30 text-indigo-400 text-[11px] font-black uppercase tracking-[0.4em] mb-10">
              <Zap size={16} fill="currentColor" className="text-yellow-400" /> Inscrições 2026 Abertas
            </div>
            <h1 className="text-7xl md:text-9xl font-black text-white uppercase italic tracking-tighter leading-[0.82] mb-10 drop-shadow-2xl">Ensino <br/> <span className="text-indigo-500">Virtual</span></h1>
            <p className="text-slate-300 text-xl md:text-2xl font-medium italic max-w-3xl leading-relaxed mb-16 drop-shadow-lg">A maior rede de capacitação teológica do país, sincronizada em tempo real.</p>
            <div className="flex flex-col sm:flex-row gap-6 w-full max-w-lg">
              <a href="#comunidade" className="flex-1 py-6 bg-indigo-600 text-white rounded-[2rem] text-xs font-black uppercase italic tracking-[0.3em] shadow-2xl hover:bg-indigo-700 transition-all flex items-center justify-center gap-3">Explorar Experiência <ArrowRight size={20}/></a>
            </div>
          </main>
        </div>

        {/* COMUNIDADE - DADOS REAIS */}
        <section id="comunidade" className="py-32 bg-slate-50 relative overflow-hidden">
          <div className="max-w-7xl mx-auto px-6 grid grid-cols-1 lg:grid-cols-2 gap-20 items-center">
            <div className="space-y-12">
               <div className="space-y-4">
                  <h2 className="text-5xl font-black uppercase italic tracking-tighter text-slate-900 leading-none">Voz da <br/> <span className="text-indigo-600">Comunidade</span></h2>
                  <p className="text-slate-400 text-sm font-bold uppercase tracking-[0.4em] italic">Relatos extraídos da plataforma</p>
               </div>

               <div className="space-y-8">
                  {realFeedbacks.length > 0 ? realFeedbacks.map((f, i) => (
                    <div key={i} className="bg-white p-10 rounded-[3rem] shadow-xl border border-slate-100 relative group">
                       <Quote className="absolute top-8 right-8 text-indigo-100 group-hover:text-indigo-600 transition-colors" size={60} />
                       <div className="flex gap-1 mb-6 text-amber-400">
                          {Array.from({length: f.rating || 5}).map((_, j) => <Star key={j} size={16} fill="currentColor"/>)}
                       </div>
                       <p className="text-lg font-medium italic text-slate-600 leading-relaxed mb-8">"{f.comment}"</p>
                       <div className="flex items-center gap-4">
                          <div className="w-14 h-14 bg-indigo-100 rounded-2xl flex items-center justify-center font-black text-indigo-600">{(f.userName || 'U').charAt(0)}</div>
                          <div><p className="font-black text-slate-900 uppercase italic tracking-tight">{f.userName || 'Aluno Anônimo'}</p><p className="text-[10px] font-bold text-slate-400 uppercase italic">Participante Real</p></div>
                       </div>
                    </div>
                  )) : (
                    <p className="text-slate-400 font-bold uppercase italic text-xs">Aguardando novos relatos da comunidade...</p>
                  )}
               </div>
            </div>

            <div className="bg-slate-900 p-16 rounded-[4rem] text-white shadow-2xl relative overflow-hidden group">
               <div className="relative z-10 space-y-12">
                  <div className="space-y-2">
                     <h3 className="text-4xl font-black uppercase italic tracking-tighter">Impacto Real</h3>
                     <p className="text-indigo-400 text-[10px] font-bold uppercase tracking-[0.4em] italic">Métricas de Sincronização Live</p>
