                   <div className="md:col-span-3 space-y-1"><label className="text-[8px] font-bold text-slate-400 uppercase ml-1">Cidade</label><input required value={enrollForm.endereco.cidade} onChange={e => setEnrollForm({...enrollForm, endereco: {...enrollForm.endereco, cidade: e.target.value}})} className="w-full p-3 bg-slate-50 border-none rounded-xl text-[10px] font-bold shadow-inner" /></div>
                   <div className="md:col-span-1 space-y-1"><label className="text-[8px] font-bold text-slate-400 uppercase ml-1">UF</label><input required value={enrollForm.endereco.uf} onChange={e => setEnrollForm({...enrollForm, endereco: {...enrollForm.endereco, uf: e.target.value.toUpperCase()}})} maxLength={2} className="w-full p-3 bg-slate-50 border-none rounded-xl text-[10px] font-black shadow-inner uppercase" /></div>
                </div>
             </div>
             {error && <div className="p-4 bg-rose-50 text-rose-600 text-[10px] font-black uppercase rounded-2xl">{error}</div>}
             <button type="submit" disabled={loading} className="w-full py-6 bg-slate-900 text-white rounded-[2rem] text-[11px] font-black uppercase italic tracking-[0.4em] shadow-2xl hover:bg-indigo-600 transition-all flex items-center justify-center gap-3 active:scale-[0.98]">
               {loading ? <RefreshCw className="animate-spin" size={20}/> : <><ShieldCheck size={20}/> Concluir Auto-Matrícula Master</>}
             </button>
          </form>
        </div>
      </div>
    );
  }

  if (viewMode === 'success_notice') {
    return (
      <div className="min-h-screen bg-slate-950 flex items-center justify-center p-6 text-center">
         <div className="max-w-md w-full bg-white rounded-[3rem] p-12 shadow-[0_50px_100px_rgba(0,0,0,0.5)] space-y-10 animate-in zoom-in-95">
            <div className="w-24 h-24 bg-emerald-50 text-emerald-600 rounded-[2.5rem] flex items-center justify-center mx-auto shadow-inner"><CheckCircle2 size={48}/></div>
            <div className="space-y-4">
              <h2 className="text-3xl font-black text-slate-900 uppercase italic tracking-tighter leading-none">Matrícula Registrada!</h2>
              <p className="text-slate-400 text-xs font-medium italic">Sincronização com o Firestore concluída com sucesso.</p>
            </div>
            <div className="p-8 bg-indigo-50/50 rounded-[2.5rem] border border-indigo-100 space-y-4">
               <p className="text-[9px] font-black uppercase text-indigo-400 tracking-widest">E-mail Acadêmico Master</p>
               <p className="text-sm font-black text-indigo-600 italic select-all underline">{generatedEmail}</p>
            </div>
            <button onClick={() => setViewMode('login')} className="w-full py-5 bg-slate-900 text-white rounded-2xl text-[10px] font-black uppercase italic tracking-widest hover:bg-indigo-600 transition-all shadow-xl">Entrar na Sala de Aula</button>
         </div>
      </div>
    );
  }

  return (
    <div className="min-h-screen bg-slate-950 flex items-center justify-center p-6 relative">
       <div className="absolute inset-0 z-0">
          <img src="https://images.unsplash.com/photo-1501290830387-99bc439ca623?auto=format&fit=crop&w=1920&q=80" className="w-full h-full object-cover opacity-20" alt="Login Background" />
       </div>
       <div className="relative z-10 w-full max-w-5xl bg-white rounded-[4rem] shadow-[0_100px_200px_rgba(0,0,0,0.8)] overflow-hidden animate-in zoom-in-95 flex flex-col">
          <div className="p-10 border-b border-slate-50 flex items-center justify-between bg-slate-50/30">
             <div className="flex items-center gap-4">
                <div className="w-14 h-14 bg-indigo-600 text-white rounded-2xl flex items-center justify-center shadow-xl shadow-indigo-600/20"><Lock size={32}/></div>
                <div>
                   <h2 className="text-2xl font-black uppercase italic tracking-tighter text-slate-900 leading-none">Login de Acesso</h2>
                   <p className="text-[10px] font-bold text-slate-400 uppercase tracking-widest italic mt-1.5">Sincronização Acadêmica Global EB-AD</p>
                </div>
             </div>
             <button onClick={() => setViewMode('landing')} className="p-3 hover:bg-slate-100 rounded-full transition-all text-slate-400"><X size={24}/></button>
          </div>
          <div className="flex flex-col lg:flex-row flex-1">
             <div className="lg:w-1/2 p-12 space-y-8 bg-white">
                <div className="space-y-1">
                   <h3 className="text-3xl font-black text-slate-900 uppercase italic tracking-tighter">Login <span className="text-indigo-600">Sênior</span></h3>
                   <p className="text-slate-400 text-xs font-medium italic">Insira suas credenciais acadêmicas oficiais.</p>
                </div>
                {error && <div className="p-4 bg-rose-50 text-rose-600 text-[10px] font-black uppercase border border-rose-100 rounded-2xl flex items-center gap-3"><Info size={16}/> {error}</div>}
                <form onSubmit={handleLogin} className="space-y-6">
                   <div className="space-y-1.5"><label className="text-[9px] font-black uppercase text-slate-400 ml-4 italic">Login E-mail Acadêmico</label><input type="email" required value={email} onChange={e => setEmail(e.target.value)} className="w-full p-5 bg-slate-50 border-none rounded-3xl text-sm font-bold shadow-inner outline-none focus:ring-1 focus:ring-indigo-600 transition-all" /></div>
                   <div className="space-y-1.5"><label className="text-[9px] font-black uppercase text-slate-400 ml-4 italic">Senha Secreta</label><input type="password" required value={password} onChange={e => setPassword(e.target.value)} className="w-full p-5 bg-slate-50 border-none rounded-3xl text-sm font-bold shadow-inner outline-none focus:ring-1 focus:ring-indigo-600 transition-all" /></div>
                   <div className="flex items-center justify-between px-4">
                      <label className="flex items-center gap-2 cursor-pointer group"><input type="checkbox" className="w-4 h-4 rounded border-slate-200 text-indigo-600 focus:ring-indigo-600" /><span className="text-[10px] font-bold text-slate-400 uppercase italic">Lembrar Conexão</span></label>
                      <button type="button" className="text-[10px] font-black uppercase text-indigo-600 italic hover:underline">Recuperar Senha</button>
                   </div>
                </form>
             </div>
             <div className="lg:w-1/2 bg-slate-50 p-12 flex flex-col justify-center gap-6 border-l border-slate-100">
                <button onClick={handleLogin} disabled={loading} className="w-full py-7 bg-slate-900 text-white rounded-[2.5rem] text-xs font-black uppercase italic tracking-[0.4em] shadow-2xl hover:bg-indigo-600 transition-all flex items-center justify-center gap-4 group">
                  {loading ? <RefreshCw className="animate-spin" size={24}/> : <><LogIn size={24} className="group-hover:translate-x-2 transition-transform"/> Acessar Sala de Aula</>}
                </button>
                <div className="relative py-4 flex items-center justify-center"><div className="absolute inset-0 flex items-center"><div className="w-full border-t border-slate-200"></div></div><span className="relative px-6 bg-slate-50 text-[9px] font-black text-slate-300 uppercase italic">Ainda não é aluno?</span></div>
                <button onClick={() => setViewMode('landing')} className="w-full py-6 bg-white border border-slate-200 text-slate-900 rounded-[2rem] text-[10px] font-black uppercase italic tracking-widest hover:bg-slate-100 hover:border-indigo-600 transition-all flex items-center justify-center gap-3">
                   <GraduationCap size={20}/> Quero me Matricular Agora
                </button>
             </div>
          </div>
          <div className="p-8 bg-slate-900/5 backdrop-blur-sm border-t border-slate-50 flex items-center justify-center">
             <button onClick={() => setIsAdminMode(!isAdminMode)} className="text-[8px] font-black uppercase text-slate-400 italic tracking-[0.6em] hover:text-indigo-600 transition-colors flex items-center gap-3">
               <ShieldCheck size={14} className={isAdminMode ? 'text-indigo-600' : ''}/> {isAdminMode ? 'Sair do Ambiente de Governança' : 'Acesso Restrito: Painel de Governança'}
             </button>
          </div>
       </div>
    </div>
  );
};

export default LoginView;

import React from 'react';

export type UserRole = 'diretor' | 'professor' | 'aluno';

export interface User {
  uid: string;
  email: string | null;
  displayName: string;
  role: UserRole;
  photoURL?: string;
  signatureUrl?: string;
  // Added to fix type errors and support admin/login sync
  status?: string;
  password?: string;
}

export interface ScheduledClass {
  id: string;
