      // O LoginView verificará este campo se o login com a senha do Auth falhar.
      if (formData.senhaNova) {
        payload.password = formData.senhaNova;
      }

      await setDoc(doc(db, 'users', uid), payload, { merge: true });

      setIsRegisterModalOpen(false);
      setSelectedStudent(null);
      alert("Prontuário e senha atualizados no banco mestre!");
    } catch (err) {
      console.error(err);
      alert("Erro ao gravar dados.");
