                    <td className="px-6 py-4 text-center"><span className={`px-3 py-1 font-black uppercase italic text-[8px] border ${s.status === 'ativo' ? 'bg-emerald-50 text-emerald-700 border-emerald-100' : 'bg-rose-50 text-rose-700 border-rose-100'}`}>{s.status}</span></td>
                    <td className="px-6 py-4 text-center flex justify-center gap-1">
                        <button onClick={() => { setSelectedStudent(s); setIsProntuarioOpen(true); }} className="p-2 border border-slate-200 hover:bg-slate-900 hover:text-white transition-all"><Eye size={14}/></button>
                        <button onClick={() => { setSelectedStudent(s); setFormData({ nome: s.displayName, emailPessoal: (s as any).emailPessoal || '', emailAcademico: s.email || '', telefone: (s as any).telefone || '', cursoId: (s as any).cursoInicial || '', status: s.status || 'ativo', cpf: (s as any).cpf || '', nascimento: (s as any).nascimento || '', fotoUrl: (s as any).photoURL || '', senhaNova: '', endereco: (s as any).endereco || {cep:'', rua:'', numero:'', bairro:'', cidade:'', uf:''} }); setIsRegisterModalOpen(true); }} className="p-2 border border-slate-200 hover:bg-slate-900 hover:text-white transition-all"><Edit3 size={14}/></button>
                        <button onClick={async () => { if(confirm('Remover?')) await deleteDoc(doc(db, 'users', s.uid)); }} className="p-2 border border-slate-200 hover:bg-rose-600 hover:text-white transition-all"><Trash2 size={14}/></button>
