                        <button onClick={() => { setSelectedStudent(s); setFormData({ nome: s.displayName, emailPessoal: (s as any).emailPessoal || '', emailAcademico: s.email || '', telefone: (s as any).telefone || '', cursoId: (s as any).cursoInicial || '', status: s.status || 'ativo', cpf: (s as any).cpf || '', nascimento: (s as any).nascimento || '', fotoUrl: (s as any).photoURL || '', senhaNova: '', endereco: (s as any).endereco || {cep:'', rua:'', numero:'', bairro:'', cidade:'', uf:''} }); setIsRegisterModalOpen(true); }} className="p-2 border border-slate-200 hover:bg-slate-900 hover:text-white transition-all text-slate-400"><Edit3 size={14}/></button>
                        <button onClick={async () => { if(confirm('Remover?')) await deleteDoc(doc(db, 'users', s.uid)); }} className="p-2 border border-slate-200 hover:bg-rose-600 hover:text-white transition-all text-slate-400"><Trash2 size={14}/></button>
