import React, { useState, useEffect, useRef } from 'react';
import { signInWithEmailAndPassword, createUserWithEmailAndPassword, signOut } from "https://www.gstatic.com/firebasejs/10.7.1/firebase-auth.js";
import { collection, query, where, onSnapshot, doc, setDoc, getDoc, serverTimestamp, getDocs, addDoc, orderBy } from "https://www.gstatic.com/firebasejs/10.7.1/firebase-firestore.js";
import { auth, db } from '../firebase';
import { Lock, GraduationCap, ArrowRight, BookOpen, Star, Camera, MapPin, Key, ChevronLeft, Info, ImageIcon, Users, Zap, ShieldCheck, MessageCircle, Play, Flame, RefreshCw, CheckCircle2, Quote, Activity, Award, LogIn, X, Send } from 'lucide-react';

type ViewMode = 'landing' | 'login' | 'enroll_form' | 'success_notice' | 'password_recovery';

const LoginView: React.FC = () => {
  const [viewMode, setViewMode] = useState<ViewMode>('landing');
  const [email, setEmail] = useState('');
  const [password, setPassword] = useState('');
  const [error, setError] = useState('');
  const [loading, setLoading] = useState(false);
  const [isAdminMode, setIsAdminMode] = useState(false);

  // Chat Recovery States
  const [recoveryName, setRecoveryName] = useState('');
  const [recoveryEmail, setRecoveryEmail] = useState('');
  const [activeProtocol, setActiveProtocol] = useState<string | null>(null);
  const [ticketId, setTicketId] = useState<string | null>(null);
  const [chatMessage, setChatMessage] = useState('');
  const [messages, setMessages] = useState<any[]>([]);
  const chatEndRef = useRef<HTMLDivElement>(null);

  const [courses, setCourses] = useState<any[]>([]);
  const [selectedCourse, setSelectedCourse] = useState<any>(null);
  const [generatedEmail, setGeneratedEmail] = useState('');
  const [realStats, setRealStats] = useState({ students: 0, classes: 0, rating: '0.0' });
  const [realFeedbacks, setRealFeedbacks] = useState<any[]>([]);

  const [enrollForm, setEnrollForm] = useState({
    nome: '', emailPessoal: '', password: '', cpf: '', nascimento: '', telefone: '', fotoUrl: '',
    endereco: { cep: '', rua: '', numero: '', bairro: '', cidade: '', uf: '' }
  });

  const fileInputRef = useRef<HTMLInputElement>(null);

  useEffect(() => {
    const unsubC = onSnapshot(query(collection(db, 'cursos'), where('status', '==', 'ativo')), (snap) => {
      setCourses(snap.docs.map(d => ({ id: d.id, ...d.data() })));
    });
    const unsubS = onSnapshot(query(collection(db, 'users'), where('role', '==', 'aluno')), (snap) => {
      setRealStats(prev => ({ ...prev, students: snap.size }));
    });
    const unsubF = onSnapshot(collection(db, 'feedbacks'), (snap) => {
      const data = snap.docs.map(d => d.data());
      setRealFeedbacks(data.slice(0, 3));
      if (data.length > 0) {
        const avg = data.reduce((acc, curr) => acc + (curr.rating || 0), 0) / data.length;
        setRealStats(prev => ({ ...prev, rating: avg.toFixed(1) }));
      }
    });
    return () => { unsubC(); unsubS(); unsubF(); };
  }, []);

  useEffect(() => {
    if (!ticketId) return;
    const unsub = onSnapshot(query(collection(db, `tickets/${ticketId}/messages`), orderBy('timestamp', 'asc')), (snap) => {
      setMessages(snap.docs.map(d => d.data()));
      setTimeout(() => chatEndRef.current?.scrollIntoView({ behavior: 'smooth' }), 100);
    });
    return () => unsub();
  }, [ticketId]);

  const handleLogin = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!email || !password) {
      setError('Preencha todos os campos.');
      return;
    }
    setLoading(true);
    setError('');
    const emailLower = email.trim().toLowerCase();

    try {
      const userCredential = await signInWithEmailAndPassword(auth, emailLower, password);
      const userDoc = await getDoc(doc(db, 'users', userCredential.user.uid));

      if (userDoc.exists()) {
        const userData = userDoc.data();
        if (isAdminMode && userData.role === 'aluno') {
          await signOut(auth);
          setError('Acesso administrativo negado.');
          setLoading(false);
          return;
        }
      }
    } catch (err: any) {
      setError('E-mail ou senha incorretos. Caso tenha esquecido, use a Recuperação de Senha.');
      setLoading(false);
    }
  };

  const startRecoveryTicket = async (e: React.FormEvent) => {
    e.preventDefault();
    setLoading(true);
    const protocol = 'REC-' + Math.random().toString(36).substring(2, 9).toUpperCase();
    const payload = {
      protocolo: protocol,
      user: recoveryName,
      email: recoveryEmail,
      type: 'Recuperação de Senha',
      status: 'Pendente',
      createdAt: serverTimestamp(),
      lastUpdate: serverTimestamp(),
      lastMessage: 'Solicitação de nova senha iniciada.'
    };
    const docRef = await addDoc(collection(db, 'tickets'), payload);
    setTicketId(docRef.id);
    setActiveProtocol(protocol);
    setLoading(false);
  };

  const sendChatMessage = async () => {
    if (!chatMessage.trim() || !ticketId) return;
    await addDoc(collection(db, `tickets/${ticketId}/messages`), {
      text: chatMessage,
      sender: 'Aluno',
      timestamp: serverTimestamp()
    });
    setChatMessage('');
  };

  const generateAcademicEmail = async (fullName: string) => {
    const names = fullName.trim().toLowerCase().split(' ');
    const firstName = names[0];
    const lastName = names.length > 1 ? names[names.length - 1] : '';
    let baseEmail = `${firstName}@ead.com`;
    const q = query(collection(db, 'users'), where('email', '==', baseEmail));
    const snap = await getDocs(q);
    if (!snap.empty && lastName) {
      baseEmail = `${firstName}.${lastName}@ead.com`;
    }
    return baseEmail;
  };

  const handleFinalizeEnroll = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!selectedCourse) return;
    setLoading(true);
    setError('');
    try {
      const academicoEmail = await generateAcademicEmail(enrollForm.nome);
      const userCredential = await createUserWithEmailAndPassword(auth, academicoEmail, enrollForm.password);
      const uid = userCredential.user.uid;
      const academicId = `MAT-${new Date().getFullYear()}-${Math.random().toString(36).substring(2, 7).toUpperCase()}`;
      const authHash = Math.random().toString(36).substring(2, 12).toUpperCase() + "-" + Date.now().toString().slice(-4);

      const payload = {
        uid,
        displayName: enrollForm.nome,
        nome: enrollForm.nome,
        email: academicoEmail,
        emailPessoal: enrollForm.emailPessoal.toLowerCase(),
        password: enrollForm.password, 
        cpf: enrollForm.cpf,
        nascimento: enrollForm.nascimento,
        telefone: enrollForm.telefone,
        photoURL: enrollForm.fotoUrl,
        endereco: enrollForm.endereco,
        role: 'aluno',
        status: 'ativo',
        cursoInicial: selectedCourse.id,
        academicId,
        authHash,
        createdAt: serverTimestamp(),
        progress: 0
      };

      await setDoc(doc(db, 'users', uid), payload);
      setGeneratedEmail(academicoEmail);
      setViewMode('success_notice');
      setLoading(false);
    } catch (err: any) {
      setError('Falha na inscrição: ' + (err.code === 'auth/email-already-in-use' ? 'Erro de duplicidade.' : 'Verifique sua conexão.'));
      setLoading(false);
    }
  };

  const handleFileUpload = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (file) {
      const reader = new FileReader();
      reader.onload = (ev) => setEnrollForm({...enrollForm, fotoUrl: ev.target?.result as string});
      reader.readAsDataURL(file);
    }
  };

  if (viewMode === 'password_recovery') {
    return (
      <div className="min-h-screen bg-slate-950 flex items-center justify-center p-6 relative">
        <div className="absolute inset-0 z-0 opacity-20">
          <img src="https://images.unsplash.com/photo-1454165833767-027ffea9e61b?auto=format&fit=crop&w=1920&q=80" className="w-full h-full object-cover" />
        </div>
        <div className="relative z-10 w-full max-w-4xl bg-white rounded-[3rem] shadow-2xl overflow-hidden flex flex-col md:flex-row h-[600px] animate-in zoom-in-95 duration-500">
           {!activeProtocol ? (
             <div className="flex-1 p-12 flex flex-col justify-center space-y-8">
