                </div>
                {error && <div className="p-4 bg-rose-50 text-rose-600 text-[10px] font-black uppercase border border-rose-100 rounded-2xl flex items-center gap-3"><Info size={16}/> {error}</div>}
                <form onSubmit={handleLogin} className="space-y-6">
                   <div className="space-y-1.5"><label className="text-[9px] font-black uppercase text-slate-400 ml-4 italic">Login E-mail Acadêmico</label><input type="email" required value={email} onChange={e => setEmail(e.target.value)} className="w-full p-5 bg-slate-50 border-none rounded-3xl text-sm font-bold shadow-inner outline-none focus:ring-1 focus:ring-indigo-600 transition-all text-slate-900" /></div>
                   <div className="space-y-1.5"><label className="text-[9px] font-black uppercase text-slate-400 ml-4 italic">Senha Secreta</label><input type="password" required value={password} onChange={e => setPassword(e.target.value)} className="w-full p-5 bg-slate-50 border-none rounded-3xl text-sm font-bold shadow-inner outline-none focus:ring-1 focus:ring-indigo-600 transition-all text-slate-900" /></div>
                   <div className="flex items-center justify-between px-4">
                      <label className="flex items-center gap-2 cursor-pointer group"><input type="checkbox" className="w-4 h-4 rounded border-slate-200 text-indigo-600 focus:ring-indigo-600" /><span className="text-[10px] font-bold text-slate-400 uppercase italic">Lembrar Conexão</span></label>
                      <button onClick={() => setViewMode('password_recovery')} type="button" className="text-[10px] font-black uppercase text-indigo-600 italic hover:underline">Recuperar Senha</button>
                   </div>
                </form>
             </div>
             <div className="lg:w-1/2 bg-slate-50 p-12 flex flex-col justify-center gap-6 border-l border-slate-100">
                <button onClick={handleLogin} disabled={loading} className="w-full py-7 bg-slate-900 text-white rounded-[2.5rem] text-xs font-black uppercase italic tracking-[0.4em] shadow-2xl hover:bg-indigo-600 transition-all flex items-center justify-center gap-4 group">
                  {loading ? <RefreshCw className="animate-spin" size={24}/> : <><LogIn size={24} className="group-hover:translate-x-2 transition-transform"/> Acessar Sala de Aula</>}
                </button>
                <div className="relative py-4 flex items-center justify-center"><div className="absolute inset-0 flex items-center"><div className="w-full border-t border-slate-200"></div></div><span className="relative px-6 bg-slate-50 text-[9px] font-black text-slate-300 uppercase italic">Ainda não é aluno?</span></div>
                <button onClick={() => setViewMode('landing')} className="w-full py-6 bg-white border border-slate-200 text-slate-900 rounded-[2rem] text-[10px] font-black uppercase italic tracking-widest hover:bg-slate-100 hover:border-indigo-600 transition-all flex items-center justify-center gap-3">
                   <GraduationCap size={20}/> Quero me Matricular Agora
                </button>
             </div>
          </div>
          <div className="p-8 bg-slate-900/5 backdrop-blur-sm border-t border-slate-50 flex items-center justify-center">
             <button onClick={() => setIsAdminMode(!isAdminMode)} className="text-[8px] font-black uppercase text-slate-400 italic tracking-[0.6em] hover:text-indigo-600 transition-colors flex items-center gap-3">
               <ShieldCheck size={14} className={isAdminMode ? 'text-indigo-600' : ''}/> {isAdminMode ? 'Sair do Ambiente de Governança' : 'Acesso Restrito: Painel de Governança'}
             </button>
          </div>
       </div>
    </div>
  );
};

