const SettingsView: React.FC = () => {
  const [activeTab, setActiveTab] = useState<SettingsTab>('geral');
  const [loading, setLoading] = useState(true);
  const [isSaving, setIsSaving] = useState(false);
  const fileInputRef = useRef<HTMLInputElement>(null);

  const [staff, setStaff] = useState<any[]>([]);
  const [isMemberModalOpen, setIsMemberModalOpen] = useState(false);
  const [isViewModalOpen, setIsViewModalOpen] = useState(false);
  const [selectedMember, setSelectedMember] = useState<any>(null);

  const [memberForm, setMemberForm] = useState({
    nome: '', email: '', documento: '', telefone: '',
    cargo: 'professor' as RoleClassification,
    status: 'ativo', fotoUrl: '', password: '',
    endereco: { cep: '', rua: '', numero: '', bairro: '', cidade: '', uf: '' },
    formacoes: [] as Formacao[],
    experiencias: [] as Experiencia[],
    biografia: ''
  });

  const [governanceLogs, setGovernanceLogs] = useState<any[]>([]);

  const [schoolConfig, setSchoolConfig] = useState({
    schoolName: 'Escola Bíblica EAD',
    primaryColor: '#4f46e5',
    secondaryColor: '#0f172a',
    academicYear: '2026',
    cnpj: '',
    enderecoFisico: '',
    telefoneInstitucional: '',
    emailSuporte: '',
    missao: ''
  });

  const [securityConfig, setSecurityConfig] = useState({
    mfaRequired: false,
    sessionTimeout: '24h',
    allowPublicRegistration: false,
    passwordComplexity: 'medium'
  });

  useEffect(() => {
    const unsubConfig = onSnapshot(doc(db, 'system_settings', 'main_config'), (docSnap) => {
      if (docSnap.exists()) {
        const data = docSnap.data();
        if (data.schoolConfig) setSchoolConfig(prev => ({ ...prev, ...data.schoolConfig }));
        if (data.securityConfig) setSecurityConfig(prev => ({ ...prev, ...data.securityConfig }));
      }
      setLoading(false);
    });

    const unsubStaff = onSnapshot(query(collection(db, 'users'), where('role', 'in', ['diretor', 'vice_diretor', 'coordenador', 'secretaria', 'professor', 'apoio', 'ti'])), (snap) => {
      setStaff(snap.docs.map(d => ({ id: d.id, ...d.data() })));
    });

    const unsubLogs = onSnapshot(query(collection(db, 'system_logs'), orderBy('timestamp', 'desc'), limit(10)), (snap) => {
      setGovernanceLogs(snap.docs.map(d => ({ id: d.id, ...d.data() })));
    });

    return () => { unsubConfig(); unsubStaff(); unsubLogs(); };
  }, []);

  const compressImage = (base64: string): Promise<string> => {
    return new Promise((resolve) => {
      const img = new Image();
      img.src = base64;
      img.onload = () => {
        const canvas = document.createElement('canvas');
        const MAX_WIDTH = 300;
        const scale = MAX_WIDTH / img.width;
        canvas.width = MAX_WIDTH;
        canvas.height = img.height * scale;
        const ctx = canvas.getContext('2d');
        ctx?.drawImage(img, 0, 0, canvas.width, canvas.height);
        resolve(canvas.toDataURL('image/jpeg', 0.7));
      };
    });
  };

  const handleFileUpload = async (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (file) {
      const reader = new FileReader();
      reader.onloadend = async () => {
        const compressed = await compressImage(reader.result as string);
        setMemberForm({ ...memberForm, fotoUrl: compressed });
      };
      reader.readAsDataURL(file);
    }
  };

  const handleSaveSystemConfig = async () => {
    setIsSaving(true);
    try {
      await setDoc(doc(db, 'system_settings', 'main_config'), {
        schoolConfig: { ...schoolConfig },
        securityConfig: { ...securityConfig },
        updatedAt: serverTimestamp()
      }, { merge: true });

      await addDoc(collection(db, 'system_logs'), {
        action: `Alteração de Configurações Institucionais`,
        user: auth.currentUser?.email || 'Admin',
        timestamp: serverTimestamp()
      });

      alert("Configurações do sistema atualizadas e auditadas!");
    } catch (err) {
      alert("Erro ao salvar configurações.");
    } finally {
      setIsSaving(false);
    }
  };

  const handleDeleteMember = async (id: string, name: string) => {
    if (confirm(`Remover permanentemente ${name} e revogar acesso?`)) {
      try {
        await deleteDoc(doc(db, 'users', id));
        // Note: Client SDK cannot delete User from Auth easily without cloud functions.
        // We rely on checking the DB document existence during login.
        await addDoc(collection(db, 'system_logs'), {
          action: `Exclusão de Membro: ${name}`,
          user: auth.currentUser?.email || 'Admin',
          timestamp: serverTimestamp()
        });
      } catch (err) { alert("Erro na exclusão."); }
    }
  };

  const handleSaveMember = async (e: React.FormEvent) => {
    e.preventDefault();
    setIsSaving(true);
    try {
      let uid = selectedMember?.id;

      // Criação de Usuário no Auth (Se for novo)
      if (!selectedMember) {
        if (!memberForm.password) {
          alert("Senha é obrigatória para novos membros.");
          setIsSaving(false);
          return;
        }
        // TRUQUE DO APP SECUNDÁRIO: Criar usuário sem deslogar o admin
        const secondaryApp = initializeApp(firebaseConfig, "Secondary");
        const secondaryAuth = getAuth(secondaryApp);
        try {
          const userCredential = await createUserWithEmailAndPassword(secondaryAuth, memberForm.email, memberForm.password);
          uid = userCredential.user.uid;
          await secondaryAuth.signOut(); // Limpa a sessão secundária
        } catch (authErr: any) {
          if (authErr.code === 'auth/email-already-in-use') {
             alert("Este e-mail já possui um acesso Auth. O registro será vinculado ao UID existente se possível, ou verifique duplicidade.");
             // Em um cenário real, precisaríamos buscar o UID pelo e-mail, o que requer Admin SDK.
             // Aqui, vamos falhar para segurança ou assumir erro.
             setIsSaving(false);
             return;
          }
          throw authErr;
        }
      }

      const payload: any = {
        uid: uid,
        nome: memberForm.nome,
        displayName: memberForm.nome,
        email: memberForm.email.toLowerCase().trim(),
        documento: memberForm.documento,
        telefone: memberForm.telefone,
        role: memberForm.cargo,
        status: memberForm.status,
        photoURL: memberForm.fotoUrl,
        endereco: memberForm.endereco,
        formacoes: memberForm.formacoes,
        experiencias: memberForm.experiencias,
        biografia: memberForm.biografia,
        updatedAt: serverTimestamp()
      };

      if (!selectedMember) {
        payload.createdAt = serverTimestamp();
        payload.staffId = `STF-${Math.random().toString(36).substr(2, 5).toUpperCase()}`;
        payload.password = memberForm.password; 
        await setDoc(doc(db, 'users', uid), payload); // setDoc com UID do Auth
      } else {
        if (memberForm.password) payload.password = memberForm.password;
        await updateDoc(doc(db, 'users', uid), payload);
      }

      await addDoc(collection(db, 'system_logs'), {
        action: selectedMember ? `Editou membro: ${memberForm.nome}` : `Cadastrou novo membro: ${memberForm.nome}`,
        user: auth.currentUser?.email || 'Admin',
        timestamp: serverTimestamp()
      });

      setIsMemberModalOpen(false);
      setSelectedMember(null);
      alert("Membro cadastrado com acesso ao sistema garantido!");
    } catch (err: any) {
      console.error(err);
      alert("Erro ao processar dados: " + err.message);
    } finally {
      setIsSaving(false);
    }
  };

  if (loading) return <div className="h-screen flex items-center justify-center bg-slate-50"><RefreshCw className="animate-spin text-indigo-600" /></div>;

  return (
    <div className="max-w-7xl mx-auto space-y-6 pb-20 px-4">
      {/* Header and UI Code remains same as provided previously, just ensured handleSaveMember logic above is used */}
      <header className="flex flex-col md:flex-row md:items-center justify-between gap-4">
        <div>
          <h1 className="text-2xl font-bold text-slate-900 tracking-tight uppercase italic">Configurações</h1>
          <p className="text-slate-500 text-xs font-medium uppercase tracking-widest">Governança e Identidade Institucional</p>
        </div>
        <div className="flex bg-white p-1 rounded-xl border border-slate-200 shadow-sm">
          {[
            { id: 'geral', label: 'Institucional', icon: <Building size={14}/> },
            { id: 'equipe', label: 'Equipe', icon: <Users size={14}/> },
            { id: 'seguranca', label: 'Segurança', icon: <ShieldCheck size={14}/> },
            { id: 'infra', label: 'Logs', icon: <Activity size={14}/> }
          ].map(tab => (
            <button
              key={tab.id}
              onClick={() => setActiveTab(tab.id as SettingsTab)}
              className={`flex items-center gap-2 px-4 py-2 rounded-lg text-[10px] font-bold uppercase transition-all ${
                activeTab === tab.id ? 'bg-slate-900 text-white shadow-md' : 'text-slate-400 hover:text-slate-900'
              }`}
            >
              {tab.icon} {tab.label}
            </button>
          ))}
        </div>
      </header>

      {activeTab === 'geral' && (
        <div className="grid grid-cols-1 lg:grid-cols-3 gap-6 animate-in fade-in slide-in-from-bottom-2">
          {/* Institutional Settings Form (Same as before) */}
          <div className="lg:col-span-2 space-y-6">
            <div className="bg-white p-8 rounded-[2rem] border border-slate-200 shadow-sm space-y-8">
              <div className="flex items-center gap-3 border-b pb-4">
                <div className="p-2.5 bg-indigo-50 text-indigo-600 rounded-xl"><Globe size={18}/></div>
                <h3 className="font-black text-slate-900 uppercase italic text-sm">Identidade e Credibilidade</h3>
              </div>
              <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
                <div className="space-y-1.5"><label className="text-[10px] font-bold text-slate-400 uppercase">Nome Institucional</label><input value={schoolConfig.schoolName} onChange={e => setSchoolConfig({...schoolConfig, schoolName: e.target.value})} className="w-full p-3 bg-slate-50 border border-slate-100 rounded-xl text-sm font-bold outline-none focus:ring-2 focus:ring-indigo-500" /></div>
                <div className="space-y-1.5"><label className="text-[10px] font-bold text-slate-400 uppercase">CNPJ</label><input value={schoolConfig.cnpj} onChange={e => setSchoolConfig({...schoolConfig, cnpj: e.target.value})} className="w-full p-3 bg-slate-50 border border-slate-100 rounded-xl text-sm font-bold outline-none focus:ring-2 focus:ring-indigo-500" /></div>
                <div className="space-y-1.5"><label className="text-[10px] font-bold text-slate-400 uppercase">Telefone</label><input value={schoolConfig.telefoneInstitucional} onChange={e => setSchoolConfig({...schoolConfig, telefoneInstitucional: e.target.value})} className="w-full p-3 bg-slate-50 border border-slate-100 rounded-xl text-sm font-bold outline-none focus:ring-2 focus:ring-indigo-500" /></div>
                <div className="space-y-1.5"><label className="text-[10px] font-bold text-slate-400 uppercase">E-mail Suporte</label><input value={schoolConfig.emailSuporte} onChange={e => setSchoolConfig({...schoolConfig, emailSuporte: e.target.value})} className="w-full p-3 bg-slate-50 border border-slate-100 rounded-xl text-sm font-bold outline-none focus:ring-2 focus:ring-indigo-500" /></div>
                <div className="md:col-span-2 space-y-1.5"><label className="text-[10px] font-bold text-slate-400 uppercase">Endereço</label><input value={schoolConfig.enderecoFisico} onChange={e => setSchoolConfig({...schoolConfig, enderecoFisico: e.target.value})} className="w-full pl-3 pr-3 py-3 bg-slate-50 border border-slate-100 rounded-xl text-sm font-bold outline-none focus:ring-2 focus:ring-indigo-500" /></div>
                <div className="md:col-span-2 space-y-1.5"><label className="text-[10px] font-bold text-slate-400 uppercase">Missão</label><textarea value={schoolConfig.missao} onChange={e => setSchoolConfig({...schoolConfig, missao: e.target.value})} className="w-full p-4 bg-slate-50 border border-slate-100 rounded-xl text-sm font-medium italic outline-none focus:ring-2 focus:ring-indigo-500 h-24 resize-none" /></div>
              </div>
              <div className="pt-4 border-t border-slate-50">
                <button onClick={handleSaveSystemConfig} disabled={isSaving} className="bg-slate-900 text-white px-8 py-3.5 rounded-xl text-[10px] font-black uppercase hover:bg-indigo-600 transition-all shadow-lg flex items-center gap-2">
                  {isSaving ? <RefreshCw className="animate-spin" size={14}/> : <Save size={14}/>} Gravar Dados Institucionais
                </button>
              </div>
            </div>
          </div>
          {/* Side panels for Academic Year & Identity */}
          <div className="space-y-6">
             <div className="bg-white p-8 rounded-[2rem] border border-slate-200 shadow-sm space-y-6">
               <h3 className="font-black text-slate-900 uppercase italic text-sm border-b pb-4">Ano Letivo</h3>
               <div className="space-y-1.5"><label className="text-[10px] font-bold text-slate-400 uppercase">Ciclo Ativo</label><input value={schoolConfig.academicYear} onChange={e => setSchoolConfig({...schoolConfig, academicYear: e.target.value})} className="w-full p-3 bg-slate-50 border border-slate-100 rounded-xl text-sm font-bold outline-none focus:ring-2 focus:ring-indigo-500" /></div>
             </div>
             <div className="bg-white p-8 rounded-[2rem] border border-slate-200 shadow-sm space-y-6">
                <h3 className="font-black text-slate-900 uppercase italic text-sm border-b pb-4 text-center">Identidade Visual</h3>
                <div className="space-y-4">
                   <div className="flex items-center justify-between p-4 bg-slate-50 rounded-2xl border border-slate-100"><span className="text-[10px] font-bold text-slate-500 uppercase">Cor Primária</span><input type="color" value={schoolConfig.primaryColor} onChange={e => setSchoolConfig({...schoolConfig, primaryColor: e.target.value})} className="h-10 w-16 rounded-lg border-none cursor-pointer shadow-sm" /></div>
                   <div className="flex items-center justify-between p-4 bg-slate-50 rounded-2xl border border-slate-100"><span className="text-[10px] font-bold text-slate-500 uppercase">Cor Secundária</span><input type="color" value={schoolConfig.secondaryColor} onChange={e => setSchoolConfig({...schoolConfig, secondaryColor: e.target.value})} className="h-10 w-16 rounded-lg border-none cursor-pointer shadow-sm" /></div>
                </div>
             </div>
          </div>
        </div>
      )}

      {activeTab === 'equipe' && (
        <div className="space-y-4 animate-in fade-in">
          <div className="bg-white p-5 rounded-2xl border border-slate-200 flex justify-between items-center shadow-sm">
            <h3 className="font-black text-slate-800 uppercase italic text-sm">Corpo Docente e Administrativo</h3>
            <button 
              onClick={() => {
                setSelectedMember(null);
                setMemberForm({
                  nome: '', email: '', documento: '', telefone: '', cargo: 'professor', status: 'ativo', fotoUrl: '', password: '',
                  endereco: { cep: '', rua: '', numero: '', bairro: '', cidade: '', uf: '' },
                  formacoes: [], experiencias: [], biografia: ''
                });
                setIsMemberModalOpen(true);
              }}
              className="bg-indigo-600 text-white px-5 py-2.5 rounded-xl text-[10px] font-black uppercase flex items-center gap-2 hover:bg-indigo-700 transition-all shadow-lg"
            >
              <Plus size={16}/> Credenciar Profissional
            </button>
          </div>

          <div className="bg-white rounded-2xl border border-slate-200 overflow-hidden shadow-sm">
            <table className="w-full text-left border-collapse">
              <thead className="bg-slate-50 border-b border-slate-100">
                <tr><th className="px-6 py-4 text-[9px] font-black uppercase text-slate-400">Profissional</th><th className="px-6 py-4 text-[9px] font-black uppercase text-slate-400">Cargo</th><th className="px-6 py-4 text-[9px] font-black uppercase text-slate-400">Login</th><th className="px-6 py-4 text-[9px] font-black uppercase text-slate-400">Status</th><th className="px-6 py-4 text-[9px] font-black uppercase text-slate-400 text-right">Gestão</th></tr>
              </thead>
              <tbody className="divide-y divide-slate-50">
                {staff.map(m => (
                  <tr key={m.id} className="hover:bg-slate-50/50 transition-colors group">
                    <td className="px-6 py-4"><div className="flex items-center gap-3"><div className="w-10 h-10 rounded-full bg-slate-100 overflow-hidden border-2 border-white shadow-sm shrink-0">{m.photoURL ? <img src={m.photoURL} className="w-full h-full object-cover" /> : <UserIcon className="m-auto text-slate-300 mt-2" size={24}/>}</div><div><p className="text-xs font-black text-slate-900 uppercase italic tracking-tight">{m.nome}</p><p className="text-[9px] text-slate-400 font-mono tracking-tighter">REF: {m.staffId || 'MASTER'}</p></div></div></td>
                    <td className="px-6 py-4"><span className="text-[9px] font-black uppercase bg-indigo-50 px-2.5 py-1 rounded-lg text-indigo-600 border border-indigo-100 italic">{m.role?.replace('_', ' ')}</span></td>
                    <td className="px-6 py-4"><p className="text-[11px] font-bold text-slate-600">{m.email}</p></td>
                    <td className="px-6 py-4"><div className="flex items-center gap-1.5"><span className={`w-1.5 h-1.5 rounded-full ${m.status === 'ativo' ? 'bg-emerald-500' : 'bg-rose-500'}`}></span><span className="text-[10px] font-bold text-slate-500 uppercase">{m.status === 'ativo' ? 'Ativo' : 'Inativo'}</span></div></td>
                    <td className="px-6 py-4 text-right"><div className="flex justify-end gap-2"><button onClick={() => { setSelectedMember(m); setIsViewModalOpen(true); }} className="p-2 text-slate-300 hover:text-indigo-600 transition-all"><Eye size={18}/></button><button onClick={() => { setSelectedMember(m); setMemberForm({ nome: m.nome||'', email: m.email||'', documento: m.documento||'', telefone: m.telefone||'', cargo: m.role||'professor', status: m.status||'ativo', fotoUrl: m.photoURL||'', password: '', endereco: m.endereco||{cep:'', rua:'', numero:'', bairro:'', cidade:'', uf:''}, formacoes: m.formacoes||[], experiencias: m.experiencias||[], biografia: m.biografia||'' }); setIsMemberModalOpen(true); }} className="p-2 text-slate-300 hover:text-amber-600 transition-all"><Edit3 size={18}/></button><button onClick={() => handleDeleteMember(m.id, m.nome)} className="p-2 text-slate-100 hover:text-rose-600 transition-all"><Trash2 size={18}/></button></div></td>
                  </tr>
                ))}
              </tbody>
            </table>
          </div>
        </div>
      )}

      {/* Member Modal (kept largely same, just ensuring form submission triggers handleSaveMember) */}
      {isMemberModalOpen && (
        <div className="fixed inset-0 z-[1000] bg-slate-950/60 backdrop-blur-sm flex items-center justify-center p-4">
          <div className="bg-white w-full max-w-5xl h-[90vh] rounded-[2.5rem] shadow-2xl flex flex-col overflow-hidden animate-in zoom-in-95">
            <header className="p-6 border-b border-slate-100 flex justify-between items-center bg-slate-50/50">
              <div className="flex items-center gap-3"><div className="p-2 bg-indigo-600 text-white rounded-xl shadow-lg"><Users size={20}/></div><h2 className="text-lg font-black text-slate-900 uppercase italic tracking-tighter">{selectedMember ? 'Revisar Prontuário' : 'Novo Credenciamento'}</h2></div>
              <button onClick={() => setIsMemberModalOpen(false)} className="p-2 hover:bg-rose-50 text-slate-400 rounded-full transition-all"><X size={20}/></button>
            </header>
            <form onSubmit={handleSaveMember} className="flex-1 overflow-y-auto p-8 custom-scrollbar space-y-12">
               {/* Same form fields as previous SettingsView... */}
               <div className="grid grid-cols-1 lg:grid-cols-4 gap-10">
                <div className="lg:col-span-1 flex flex-col items-center gap-4">
                  <div onClick={() => fileInputRef.current?.click()} className="w-44 h-44 rounded-[2rem] bg-slate-50 border-2 border-dashed border-slate-200 flex items-center justify-center overflow-hidden cursor-pointer hover:border-indigo-400 hover:bg-indigo-50/50 transition-all relative group shadow-inner">
                    {memberForm.fotoUrl ? <img src={memberForm.fotoUrl} className="w-full h-full object-cover" /> : <div className="text-center opacity-30"><Camera size={40} className="mx-auto" /><span className="text-[9px] font-black uppercase mt-2 block">Upload Identidade</span></div>}
                  </div>
                  <input type="file" ref={fileInputRef} className="hidden" accept="image/*" onChange={handleFileUpload} />
                </div>
                <div className="lg:col-span-3 grid grid-cols-1 sm:grid-cols-2 gap-5">
                  <div className="space-y-1.5"><label className="text-[10px] font-black text-slate-400 uppercase ml-1">Nome Completo</label><input required value={memberForm.nome} onChange={e => setMemberForm({...memberForm, nome: e.target.value})} className="w-full p-3 bg-slate-50 border border-slate-100 rounded-xl text-sm font-bold outline-none focus:ring-2 focus:ring-indigo-500" /></div>
                  <div className="space-y-1.5"><label className="text-[10px] font-black text-slate-400 uppercase ml-1">Cargo</label><select value={memberForm.cargo} onChange={e => setMemberForm({...memberForm, cargo: e.target.value as RoleClassification})} className="w-full p-3 bg-slate-50 border border-slate-100 rounded-xl text-[11px] font-black uppercase italic outline-none focus:ring-2 focus:ring-indigo-500 cursor-pointer shadow-inner"><option value="professor">Professor Docente</option><option value="coordenador">Coordenador Pedagógico</option><option value="secretaria">Secretaria Geral</option><option value="vice_diretor">Vice-Direção</option><option value="diretor">Diretoria Executiva</option><option value="ti">Gestão TI</option></select></div>
                  <div className="space-y-1.5"><label className="text-[10px] font-black text-slate-400 uppercase ml-1">E-mail</label><input type="email" required value={memberForm.email} onChange={e => setMemberForm({...memberForm, email: e.target.value})} className="w-full p-3 bg-slate-50 border border-slate-100 rounded-xl text-sm font-bold outline-none focus:ring-2 focus:ring-indigo-500" /></div>
                  <div className="space-y-1.5"><label className="text-[10px] font-black text-slate-400 uppercase ml-1">Senha</label><input type="password" required={!selectedMember} value={memberForm.password} onChange={e => setMemberForm({...memberForm, password: e.target.value})} className="w-full p-3 bg-slate-50 border border-slate-100 rounded-xl text-sm font-mono outline-none focus:ring-2 focus:ring-indigo-500" placeholder="Mínimo 6 caracteres" /></div>
                  <div className="space-y-1.5"><label className="text-[10px] font-black text-slate-400 uppercase ml-1">Documento</label><input required value={memberForm.documento} onChange={e => setMemberForm({...memberForm, documento: e.target.value})} className="w-full p-3 bg-slate-50 border border-slate-100 rounded-xl text-sm font-bold outline-none focus:ring-2 focus:ring-indigo-500" /></div>
                  <div className="space-y-1.5"><label className="text-[10px] font-black text-slate-400 uppercase ml-1">WhatsApp</label><input required value={memberForm.telefone} onChange={e => setMemberForm({...memberForm, telefone: e.target.value})} className="w-full p-3 bg-slate-50 border border-slate-100 rounded-xl text-sm font-bold outline-none focus:ring-2 focus:ring-indigo-500" /></div>
                </div>
              </div>
            </form>
            <footer className="p-8 border-t border-slate-100 bg-slate-50/80 flex justify-end gap-3 shadow-2xl">
              <button onClick={() => setIsMemberModalOpen(false)} className="px-8 py-3.5 text-slate-400 font-black text-[10px] uppercase hover:bg-slate-200 rounded-xl transition-all">Descartar</button>
              <button onClick={handleSaveMember} disabled={isSaving} className="bg-slate-900 text-white px-12 py-3.5 rounded-xl text-[10px] font-black uppercase shadow-xl hover:bg-indigo-600 transition-all disabled:opacity-50 flex items-center gap-2">
                {isSaving ? <RefreshCw className="animate-spin" size={14}/> : <Save size={14}/>} {selectedMember ? 'Efetivar Alterações' : 'Concluir Credenciamento'}
              </button>
            </footer>
          </div>
        </div>
      )}
      {/* Other tabs (Security, Logs) omitted for brevity as they remain unchanged except for context */}
    </div>
  );
};

export default SettingsView;

import React, { useState, useEffect, useMemo, useRef } from 'react';
import { 
  collection, query, onSnapshot, addDoc, updateDoc, 
  doc, serverTimestamp, orderBy, where, deleteDoc, getDoc, getDocs
} from "https://www.gstatic.com/firebasejs/10.7.1/firebase-firestore.js";
import { db, auth } from '../firebase';
import { User } from '../types';
import { 
  Ticket as TicketIcon, AlertCircle, Clock, MessageSquare, Search, Plus, X, FolderOpen, FileText, Download, UserCheck, ShieldAlert, FileSignature, Save, PenTool, UserX, Check, ArrowRightLeft, Fingerprint, Star, Send, Folder, Archive, CheckCircle2, ChevronRight, FileDown, Phone, Printer, MoreVertical, RotateCcw
} from 'lucide-react';
import SignaturePad from '../components/SignaturePad';

interface SecretariatViewProps { user: User; }
type SecretariatTab = 'atendimento' | 'chat' | 'arquivos' | 'operacional';
type OperationalSubView = 'main' | 'declaracao' | 'validacao' | 'transferencia' | 'assinatura' | 'ficha';
type ChatFilter = 'abertos' | 'finalizados' | 'arquivados';

const SecretariatView: React.FC<SecretariatViewProps> = ({ user }) => {
  const [activeTab, setActiveTab] = useState<SecretariatTab>('atendimento');
  const [opSubView, setOpSubView] = useState<OperationalSubView>('main');
  const [chatFilter, setChatFilter] = useState<ChatFilter>('abertos');
  const [tickets, setTickets] = useState<any[]>([]);
  const [files, setFiles] = useState<any[]>([]);
  const [students, setStudents] = useState<any[]>([]);
  const [courses, setCourses] = useState<any[]>([]);
  const [searchTerm, setSearchTerm] = useState('');
  const [selectedTicketId, setSelectedTicketId] = useState<string | null>(null);
  const [chatHistory, setChatHistory] = useState<any[]>([]);
  const [chatMessage, setChatMessage] = useState('');
  const [isSignModalOpen, setIsSignModalOpen] = useState(false);
  const [secSignature, setSecSignature] = useState<string | null>(null);

  // New States for Protocol Modal
  const [isNewProtocolOpen, setIsNewProtocolOpen] = useState(false);
  const [newProtocolForm, setNewProtocolForm] = useState({ name: '', channel: 'Balcão', notes: '' });

  // Operational Modals States
  const [selectedStudentForOp, setSelectedStudentForOp] = useState<string>('');
  const [targetCourseId, setTargetCourseId] = useState<string>('');
  const [declarationText, setDeclarationText] = useState('');

  const [currentPath, setCurrentPath] = useState<string[]>([]);
  const chatEndRef = useRef<HTMLDivElement>(null);

  useEffect(() => {
    const unsubT = onSnapshot(query(collection(db, 'tickets'), orderBy('createdAt', 'desc')), s => setTickets(s.docs.map(d => ({ id: d.id, ...d.data() }))));
    const unsubF = onSnapshot(collection(db, 'secretaria_arquivos'), s => setFiles(s.docs.map(d => ({ id: d.id, ...d.data() }))));
    const unsubS = onSnapshot(query(collection(db, 'users'), where('role', '==', 'aluno')), s => setStudents(s.docs.map(d => ({ uid: d.id, ...d.data() }))));
    const unsubC = onSnapshot(collection(db, 'cursos'), s => setCourses(s.docs.map(d => ({ id: d.id, ...d.data() }))));
    getDoc(doc(db, 'users', user.uid)).then(d => d.exists() && setSecSignature(d.data().signatureUrl));
    return () => { unsubT(); unsubF(); unsubS(); unsubC(); };
  }, [user.uid]);

  useEffect(() => {
    if (!selectedTicketId) return;
    const unsubChat = onSnapshot(query(collection(db, `tickets/${selectedTicketId}/messages`), orderBy('timestamp', 'asc')), (snap) => {
      setChatHistory(snap.docs.map(d => d.data()));
      setTimeout(() => chatEndRef.current?.scrollIntoView({ behavior: 'smooth' }), 100);
    });
    return () => unsubChat();
  }, [selectedTicketId]);

  const stats = useMemo(() => {
    const pendingVal = students.filter(s => s.status === 'aguardando_validacao' || s.status === 'pendente').length;
    return {
      abertos: tickets.filter(t => t.status === 'Pendente').length,
      finalizados: tickets.filter(t => t.status === 'Finalizado').length,
      arquivados: tickets.filter(t => t.status === 'Arquivado').length,
      pendentesVal: pendingVal,
      totalGed: files.length
    };
  }, [tickets, students, files]);

  const handleSendMessage = async () => {
    if (!selectedTicketId || !chatMessage.trim()) return;
    const msg = { text: chatMessage, sender: 'Secretaria', timestamp: serverTimestamp() };
    await addDoc(collection(db, `tickets/${selectedTicketId}/messages`), msg);
    await updateDoc(doc(db, 'tickets', selectedTicketId), { lastMessage: chatMessage, lastUpdate: serverTimestamp() });
    setChatMessage('');
  };

  const handleCreateProtocol = async () => {
    if (!newProtocolForm.name) return;
    const protocol = 'PROT-' + Math.random().toString(36).substring(2, 9).toUpperCase();
    await addDoc(collection(db, 'tickets'), {
      protocolo: protocol,
      user: newProtocolForm.name,
      email: 'Atendimento Local',
      type: newProtocolForm.channel,
      status: 'Pendente',
      createdAt: serverTimestamp(),
      lastUpdate: serverTimestamp(),
      lastMessage: newProtocolForm.notes || 'Início de atendimento.'
    });
    setIsNewProtocolOpen(false);
    setNewProtocolForm({ name: '', channel: 'Balcão', notes: '' });
    alert(`Protocolo ${protocol} gerado com sucesso!`);
  };

  const generateDeclaration = () => {
    if (!selectedStudentForOp) return;
    const s = students.find(u => u.uid === selectedStudentForOp);
    const c = courses.find(course => course.id === s?.cursoInicial);
    const text = `
      DECLARAÇÃO DE MATRÍCULA

      Declaramos para os devidos fins que o(a) aluno(a) ${s?.displayName.toUpperCase()},
      inscrito(a) sob o CPF ${s?.cpf || '___.___.___-__'}, encontra-se regularmente 
      matriculado(a) no curso de ${c?.nome.toUpperCase() || 'TEOLOGIA'}, nesta instituição de ensino.

      Status Acadêmico: ${s?.status.toUpperCase()}
      Data de Emissão: ${new Date().toLocaleDateString('pt-BR')}

      __________________________________
      Secretaria Acadêmica - EBD EAD
    `;
    setDeclarationText(text);
  };

  const handleTransfer = async () => {
    if (!selectedStudentForOp || !targetCourseId) return;
    if (confirm('Confirmar transferência de curso?')) {
      await updateDoc(doc(db, 'users', selectedStudentForOp), { cursoInicial: targetCourseId });
      alert('Transferência realizada com sucesso.');
      setOpSubView('main');
    }
  };

  const filteredTickets = tickets.filter(t => {
    const matchSearch = t.protocolo?.toLowerCase().includes(searchTerm.toLowerCase()) || t.user?.toLowerCase().includes(searchTerm.toLowerCase());
    if (activeTab === 'atendimento') return matchSearch && t.status === 'Pendente';
    if (activeTab === 'chat') {
       if (chatFilter === 'abertos') return matchSearch && (t.status === 'Em Atendimento' || t.status === 'Pendente');
       if (chatFilter === 'finalizados') return matchSearch && t.status === 'Finalizado';
       if (chatFilter === 'arquivados') return matchSearch && t.status === 'Arquivado';
    }
    return matchSearch;
  });

  const renderOperational = () => {
    switch(opSubView) {
      case 'validacao':
        const pending = students.filter(s => s.status === 'aguardando_validacao' || s.status === 'pendente');
        return (
          <div className="bg-white border border-slate-300 animate-in zoom-in-98 shadow-lg rounded-2xl overflow-hidden">
             <div className="p-6 bg-slate-900 text-white flex justify-between items-center">
                <h3 className="text-sm font-bold uppercase italic flex items-center gap-2"><UserCheck size={18}/> Validação de Novas Matrículas</h3>
                <button onClick={() => setOpSubView('main')}><X size={20}/></button>
             </div>
             <table className="w-full text-left border-collapse">
                <thead className="bg-slate-50 border-b border-slate-300 text-[10px] font-bold uppercase">
                   <tr><th className="px-6 py-4">Aluno</th><th className="px-6 py-4">Curso Escolhido</th><th className="px-6 py-4 text-center">Gestão</th></tr>
                </thead>
                <tbody className="text-xs">
                   {pending.length === 0 ? <tr><td colSpan={3} className="p-10 text-center text-slate-400 italic font-bold">Todas as matrículas estão em dia.</td></tr> : pending.map(s => (
                     <tr key={s.uid} className="border-b border-slate-200 hover:bg-slate-50">
                        <td className="px-6 py-4 font-bold uppercase">{s.displayName}</td>
                        <td className="px-6 py-4 font-bold text-indigo-600 uppercase">{courses.find(c=>c.id===s.cursoInicial)?.nome || 'Não definido'}</td>
                        <td className="px-6 py-4 flex gap-3 justify-center">
                           <button onClick={async () => await updateDoc(doc(db, 'users', s.uid), {status: 'ativo'})} className="px-4 py-2 bg-emerald-600 text-white text-[10px] font-black uppercase rounded-lg hover:bg-emerald-700 transition-all shadow-md">Aprovar Acesso</button>
                           <button onClick={async () => await deleteDoc(doc(db, 'users', s.uid))} className="p-2 border border-red-200 text-red-600 hover:bg-red-50 rounded-lg"><UserX size={16}/></button>
                        </td>
                     </tr>
                   ))}
                </tbody>
             </table>
          </div>
        );
      case 'declaracao':
        return (
          <div className="bg-white border border-slate-300 shadow-xl rounded-2xl p-8 max-w-2xl mx-auto space-y-6">
             <div className="flex justify-between items-center border-b pb-4">
                <h3 className="text-lg font-black uppercase text-slate-900 italic">Emissor de Declarações</h3>
                <button onClick={() => setOpSubView('main')} className="text-slate-400 hover:text-rose-500"><X size={24}/></button>
             </div>
             <div className="flex gap-4">
               <select value={selectedStudentForOp} onChange={e => setSelectedStudentForOp(e.target.value)} className="flex-1 p-3 border border-slate-300 rounded-xl text-xs font-bold uppercase outline-none focus:border-indigo-600">
                 <option value="">Selecione o Aluno...</option>
                 {students.map(s => <option key={s.uid} value={s.uid}>{s.displayName}</option>)}
               </select>
               <button onClick={generateDeclaration} className="px-6 py-3 bg-indigo-600 text-white rounded-xl text-[10px] font-black uppercase hover:bg-indigo-700">Gerar</button>
             </div>
             {declarationText && (
               <div className="bg-slate-50 p-8 border border-slate-200 rounded-xl font-serif text-sm leading-relaxed whitespace-pre-wrap shadow-inner text-slate-800">
                 {declarationText}
               </div>
             )}
             {declarationText && (
               <div className="flex justify-end">
                 <button onClick={() => window.print()} className="flex items-center gap-2 px-8 py-3 bg-slate-900 text-white rounded-xl text-[10px] font-black uppercase hover:bg-slate-800"><Printer size={16}/> Imprimir Documento</button>
               </div>
             )}
          </div>
        );
      case 'transferencia':
        return (
          <div className="bg-white border border-slate-300 shadow-xl rounded-2xl p-8 max-w-lg mx-auto space-y-6">
             <div className="flex justify-between items-center border-b pb-4">
                <h3 className="text-lg font-black uppercase text-slate-900 italic">Transferência de Curso</h3>
                <button onClick={() => setOpSubView('main')} className="text-slate-400 hover:text-rose-500"><X size={24}/></button>
             </div>
             <div className="space-y-4">
                <div>
                  <label className="text-[10px] font-bold text-slate-400 uppercase">Aluno</label>
                  <select value={selectedStudentForOp} onChange={e => setSelectedStudentForOp(e.target.value)} className="w-full p-3 border border-slate-300 rounded-xl text-xs font-bold uppercase mt-1">
                    <option value="">Selecione...</option>
                    {students.map(s => <option key={s.uid} value={s.uid}>{s.displayName}</option>)}
                  </select>
                </div>
                <div>
                  <label className="text-[10px] font-bold text-slate-400 uppercase">Novo Curso de Destino</label>
                  <select value={targetCourseId} onChange={e => setTargetCourseId(e.target.value)} className="w-full p-3 border border-slate-300 rounded-xl text-xs font-bold uppercase mt-1">
                    <option value="">Selecione...</option>
                    {courses.map(c => <option key={c.id} value={c.id}>{c.nome}</option>)}
                  </select>
                </div>
                <button onClick={handleTransfer} className="w-full py-4 bg-indigo-600 text-white rounded-xl text-[10px] font-black uppercase hover:bg-indigo-700 shadow-lg mt-4">Confirmar Transferência</button>
             </div>
          </div>
        );
      case 'ficha':
        return (
          <div className="bg-white border border-slate-300 shadow-xl rounded-2xl p-8 max-w-lg mx-auto space-y-6 text-center">
             <div className="flex justify-between items-center border-b pb-4">
                <h3 className="text-lg font-black uppercase text-slate-900 italic">Ficha Cadastral</h3>
                <button onClick={() => setOpSubView('main')} className="text-slate-400 hover:text-rose-500"><X size={24}/></button>
             </div>
             <p className="text-sm text-slate-500 italic">Selecione um aluno para visualizar a ficha completa (Redireciona para Prontuário).</p>
             <select onChange={e => { if(e.target.value) alert("Funcionalidade integrada na aba 'Alunos'. Por favor, acesse o menu 'Alunos' para ver a ficha completa."); }} className="w-full p-3 border border-slate-300 rounded-xl text-xs font-bold uppercase mt-1">
               <option value="">Selecione o Aluno...</option>
               {students.map(s => <option key={s.uid} value={s.uid}>{s.displayName}</option>)}
             </select>
          </div>
        );
      case 'assinatura':
        return (
          <div className="max-w-md mx-auto bg-white border border-slate-300 p-8 text-center space-y-6 rounded-2xl shadow-xl">
             <div className="w-16 h-16 bg-slate-100 rounded-full flex items-center justify-center mx-auto text-slate-400"><Fingerprint size={32}/></div>
             <h3 className="font-bold uppercase italic">Assinatura Digital do Secretário</h3>
             <div className="p-4 border-2 border-dashed border-slate-300 bg-slate-50 min-h-[120px] flex items-center justify-center rounded-xl">
                {secSignature ? <img src={secSignature} className="max-h-24 grayscale" /> : <p className="text-[10px] text-slate-300 uppercase font-bold">Nenhuma assinatura registrada</p>}
             </div>
             <button onClick={() => setIsSignModalOpen(true)} className="w-full py-3 bg-slate-900 text-white text-[10px] font-bold uppercase italic rounded-xl hover:bg-slate-800 transition-all">Coletar Nova Assinatura</button>
             <button onClick={() => setOpSubView('main')} className="text-[10px] text-slate-400 underline uppercase font-bold">Voltar</button>
          </div>
        );
      default:
        return (
          <div className="grid grid-cols-2 md:grid-cols-5 gap-4">
             <button onClick={() => setOpSubView('declaracao')} className="bg-white p-8 border border-slate-200 rounded-2xl flex flex-col items-center gap-4 hover:border-indigo-400 hover:shadow-xl transition-all group">
                <div className="text-slate-300 group-hover:text-indigo-600 transition-colors"><FileText size={32}/></div>
                <span className="text-[10px] font-black uppercase text-slate-700 tracking-wider">Declaração</span>
             </button>
             <button onClick={() => setOpSubView('validacao')} className="bg-white p-8 border border-slate-200 rounded-2xl flex flex-col items-center gap-4 hover:border-indigo-400 hover:shadow-xl transition-all group relative">
                <div className="text-slate-300 group-hover:text-indigo-600 transition-colors"><UserCheck size={32}/></div>
                <span className="text-[10px] font-black uppercase text-slate-700 tracking-wider">Validar Aluno</span>
                {stats.pendentesVal > 0 && <span className="absolute top-3 right-3 bg-red-600 text-white text-[9px] w-6 h-6 flex items-center justify-center font-black rounded-full shadow-lg border-2 border-white">{stats.pendentesVal}</span>}
             </button>
             <button onClick={() => setOpSubView('ficha')} className="bg-white p-8 border border-slate-200 rounded-2xl flex flex-col items-center gap-4 hover:border-indigo-400 hover:shadow-xl transition-all group">
                <div className="text-slate-300 group-hover:text-indigo-600 transition-colors"><FileSignature size={32}/></div>
                <span className="text-[10px] font-black uppercase text-slate-700 tracking-wider">Ficha Aluno</span>
             </button>
             <button onClick={() => setOpSubView('transferencia')} className="bg-white p-8 border border-slate-200 rounded-2xl flex flex-col items-center gap-4 hover:border-indigo-400 hover:shadow-xl transition-all group">
                <div className="text-slate-300 group-hover:text-indigo-600 transition-colors"><ArrowRightLeft size={32}/></div>
                <span className="text-[10px] font-black uppercase text-slate-700 tracking-wider">Transferências</span>
             </button>
             <button onClick={() => setOpSubView('assinatura')} className="bg-white p-8 border border-slate-200 rounded-2xl flex flex-col items-center gap-4 hover:border-indigo-400 hover:shadow-xl transition-all group">
                <div className="text-slate-300 group-hover:text-indigo-600 transition-colors"><Fingerprint size={32}/></div>
                <span className="text-[10px] font-black uppercase text-slate-700 tracking-wider">Assinatura Sec.</span>
             </button>
          </div>
        );
    }
  };

  return (
    <div className="space-y-6 animate-in fade-in h-full max-w-full overflow-hidden text-slate-900 pb-20">
      <header className="flex flex-col md:flex-row justify-between items-center bg-white p-6 rounded-[2rem] border border-slate-200 shadow-sm gap-4">
        <div className="flex items-center gap-4">
           <div className="p-3 bg-indigo-600 text-white rounded-2xl shadow-lg shadow-indigo-200"><MessageSquare size={24}/></div>
           <div>
             <h1 className="text-xl font-black uppercase italic tracking-tighter text-slate-900 leading-none">EBD EAD - Secretaria Virtual</h1>
             <p className="text-[9px] text-indigo-500 font-black uppercase tracking-[0.3em] mt-1">Central de Operações v3.0</p>
           </div>
        </div>
        <div className="flex bg-slate-100 p-1.5 rounded-xl border border-slate-200">
           {(['atendimento', 'chat', 'arquivos', 'operacional'] as any).map((t:any) => (
             <button key={t} onClick={() => { setActiveTab(t); setOpSubView('main'); setSelectedTicketId(null); }} className={`px-6 py-2.5 rounded-lg text-[10px] font-black uppercase transition-all ${activeTab === t ? 'bg-white text-indigo-600 shadow-md' : 'text-slate-400 hover:text-slate-600'}`}>{t}</button>
           ))}
        </div>
      </header>

      {/* KPI INDICATORS */}
      <div className="grid grid-cols-2 md:grid-cols-4 gap-4">
         <div className="bg-white p-5 rounded-2xl border border-slate-200 shadow-sm flex flex-col justify-between h-24 hover:border-amber-400 transition-all group cursor-pointer" onClick={() => {setActiveTab('atendimento'); setChatFilter('abertos');}}>
            <p className="text-[9px] font-black text-slate-400 uppercase tracking-widest flex items-center gap-2"><TicketIcon size={12}/> Pendentes</p>
            <p className="text-3xl font-black text-amber-500 group-hover:scale-110 transition-transform origin-left">{stats.abertos}</p>
         </div>
         <div className="bg-white p-5 rounded-2xl border border-slate-200 shadow-sm flex flex-col justify-between h-24 hover:border-indigo-400 transition-all group cursor-pointer" onClick={() => {setActiveTab('chat'); setChatFilter('abertos');}}>
            <p className="text-[9px] font-black text-slate-400 uppercase tracking-widest flex items-center gap-2"><MessageSquare size={12}/> Em Chat</p>
            <p className="text-3xl font-black text-indigo-600 group-hover:scale-110 transition-transform origin-left">{tickets.filter(t => t.status === 'Em Atendimento').length}</p>
         </div>
         <div className="bg-white p-5 rounded-2xl border border-slate-200 shadow-sm flex flex-col justify-between h-24 hover:border-red-400 transition-all group cursor-pointer" onClick={() => {setActiveTab('operacional'); setOpSubView('validacao');}}>
            <p className="text-[9px] font-black text-slate-400 uppercase tracking-widest flex items-center gap-2"><UserCheck size={12}/> Validar Matrículas</p>
            <p className="text-3xl font-black text-rose-500 group-hover:scale-110 transition-transform origin-left">{stats.pendentesVal}</p>
         </div>
         <div className="bg-white p-5 rounded-2xl border border-slate-200 shadow-sm flex flex-col justify-between h-24 hover:border-emerald-400 transition-all group">
            <p className="text-[9px] font-black text-slate-400 uppercase tracking-widest flex items-center gap-2"><FolderOpen size={12}/> Arquivos GED</p>
            <p className="text-3xl font-black text-emerald-500 group-hover:scale-110 transition-transform origin-left">{stats.totalGed}</p>
         </div>
      </div>

      <main className="flex-1 min-h-[600px] overflow-hidden">
         {activeTab === 'operacional' && renderOperational()}

         {activeTab === 'atendimento' && (
           <div className="bg-white rounded-[2rem] border border-slate-200 overflow-hidden h-full flex flex-col shadow-sm">
              <div className="p-6 border-b border-slate-100 flex justify-between items-center bg-slate-50/50">
                 <h3 className="font-black text-xs uppercase italic flex items-center gap-2 text-slate-700 tracking-widest">Fila de Protocolos</h3>
                 <div className="flex gap-4">
                    <div className="relative"><Search className="absolute left-3 top-1/2 -translate-y-1/2 text-slate-300" size={14}/><input value={searchTerm} onChange={e => setSearchTerm(e.target.value)} placeholder="Buscar Protocolo..." className="pl-9 pr-4 py-2.5 border border-slate-200 rounded-xl text-xs w-64 outline-none focus:border-indigo-500 font-bold bg-white shadow-sm" /></div>
                    <button onClick={() => setIsNewProtocolOpen(true)} className="bg-slate-900 text-white px-5 py-2.5 rounded-xl text-[9px] font-black uppercase hover:bg-indigo-600 transition-all shadow-lg flex items-center gap-2"><Plus size={14}/> Novo Atendimento</button>
                 </div>
              </div>
              <div className="flex-1 overflow-auto custom-scrollbar p-2">
                 <table className="w-full text-left border-collapse">
                    <thead className="bg-white text-[9px] font-black uppercase text-slate-400 tracking-widest border-b border-slate-100 sticky top-0 z-10">
                       <tr><th className="px-6 py-4">Protocolo</th><th className="px-6 py-4">Solicitante</th><th className="px-6 py-4">Canal</th><th className="px-6 py-4">Data</th><th className="px-6 py-4 text-center">Ação</th></tr>
                    </thead>
                    <tbody className="text-xs font-medium text-slate-600">
                       {filteredTickets.length === 0 ? <tr><td colSpan={5} className="p-20 text-center text-slate-300 uppercase italic font-bold">Nenhum ticket pendente na fila.</td></tr> : filteredTickets.map(t => (
                         <tr key={t.id} className="border-b border-slate-50 hover:bg-indigo-50/30 transition-colors group">
                            <td className="px-6 py-4 font-mono font-black text-indigo-600">{t.protocolo}</td>
                            <td className="px-6 py-4 font-bold text-slate-900 uppercase">{t.user}</td>
                            <td className="px-6 py-4"><span className="px-3 py-1 bg-slate-100 rounded-lg text-[9px] font-black uppercase text-slate-500">{t.type}</span></td>
                            <td className="px-6 py-4 text-[10px] text-slate-400 font-bold">{t.createdAt?.seconds ? new Date(t.createdAt.seconds*1000).toLocaleDateString() : 'Hoje'}</td>
                            <td className="px-6 py-4 text-center"><button onClick={async () => { await updateDoc(doc(db, 'tickets', t.id), {status: 'Em Atendimento'}); setSelectedTicketId(t.id); setActiveTab('chat'); setChatFilter('abertos'); }} className="px-4 py-2 bg-indigo-600 text-white font-black uppercase text-[8px] rounded-lg hover:bg-indigo-700 shadow-md">Atender</button></td>
                         </tr>
                       ))}
                    </tbody>
                 </table>
              </div>
           </div>
         )}

         {activeTab === 'chat' && (
           <div className="grid grid-cols-12 gap-6 h-[700px]">
              <div className="col-span-4 bg-white rounded-[2rem] border border-slate-200 flex flex-col overflow-hidden shadow-sm">
                 <div className="flex p-2 bg-slate-50 border-b border-slate-100">
                    {['abertos', 'finalizados', 'arquivados'].map((f:any) => (
                      <button key={f} onClick={() => setChatFilter(f)} className={`flex-1 py-3 text-[9px] font-black uppercase transition-all rounded-xl ${chatFilter === f ? 'bg-white text-indigo-600 shadow-sm' : 'text-slate-400 hover:text-slate-600'}`}>{f}</button>
                    ))}
                 </div>
                 <div className="flex-1 overflow-y-auto custom-scrollbar">
                    {filteredTickets.map(t => (
                      <div key={t.id} onClick={() => setSelectedTicketId(t.id)} className={`p-5 border-b border-slate-50 cursor-pointer transition-all ${selectedTicketId === t.id ? 'bg-indigo-50 border-r-4 border-r-indigo-600' : 'hover:bg-slate-50'}`}>
                         <div className="flex justify-between items-start mb-1">
                            <p className="text-xs font-black uppercase text-slate-900 leading-none">{t.user}</p>
                            <span className="text-[8px] font-bold text-slate-300">{t.lastUpdate?.seconds ? new Date(t.lastUpdate.seconds * 1000).toLocaleTimeString([], {hour: '2-digit', minute:'2-digit'}) : ''}</span>
                         </div>
                         <p className="text-[9px] text-indigo-500 font-mono font-bold mt-1 tracking-tight">#{t.protocolo}</p>
                         <p className="text-[10px] text-slate-400 mt-2 font-medium truncate italic">"{t.lastMessage || 'Inicie o atendimento...'}"</p>
                      </div>
                    ))}
                 </div>
              </div>

              <div className="col-span-8 bg-white rounded-[2rem] border border-slate-200 flex flex-col relative overflow-hidden shadow-xl">
                 {selectedTicketId ? (
                   <>
                     <div className="p-6 bg-slate-50 border-b border-slate-100 flex justify-between items-center">
                        <div className="flex items-center gap-4">
                           <div className="w-12 h-12 bg-indigo-600 text-white rounded-2xl flex items-center justify-center font-black text-lg italic shadow-lg">{(filteredTickets.find(t=>t.id===selectedTicketId)?.user||'U').charAt(0)}</div>
                           <div>
                              <h4 className="text-sm font-black uppercase text-slate-900 italic tracking-tight">{filteredTickets.find(t=>t.id===selectedTicketId)?.user}</h4>
                              <p className="text-[10px] text-slate-400 font-bold uppercase tracking-widest mt-0.5">Protocolo: <span className="text-indigo-600">{filteredTickets.find(t=>t.id===selectedTicketId)?.protocolo}</span></p>
                           </div>
                        </div>
                        <div className="flex gap-2">
                           <button onClick={async () => { await updateDoc(doc(db, 'tickets', selectedTicketId), {status: 'Em Atendimento'}); setChatFilter('abertos'); }} className="p-2.5 bg-white border border-slate-200 rounded-xl hover:bg-indigo-50 hover:text-indigo-600 transition-all" title="Assumir / Reabrir"><RotateCcw size={16}/></button>
                           <button onClick={async () => { await updateDoc(doc(db, 'tickets', selectedTicketId), {status: 'Finalizado'}); setSelectedTicketId(null); }} className="p-2.5 bg-white border border-slate-200 rounded-xl hover:bg-emerald-50 hover:text-emerald-600 transition-all" title="Finalizar"><CheckCircle2 size={16}/></button>
                           <button onClick={async () => { await updateDoc(doc(db, 'tickets', selectedTicketId), {status: 'Arquivado'}); setSelectedTicketId(null); }} className="p-2.5 bg-white border border-slate-200 rounded-xl hover:bg-amber-50 hover:text-amber-600 transition-all" title="Arquivar"><Archive size={16}/></button>
                           <button onClick={async () => { if(confirm('Excluir ticket permanentemente?')) { await deleteDoc(doc(db, 'tickets', selectedTicketId)); setSelectedTicketId(null); }}} className="p-2.5 bg-white border border-slate-200 rounded-xl hover:bg-rose-50 hover:text-rose-600 transition-all" title="Excluir"><Trash2 size={16}/></button>
                        </div>
                     </div>

                     <div className="flex-1 overflow-y-auto p-8 space-y-6 bg-slate-50/30 custom-scrollbar">
                        {chatHistory.map((m, i) => (
                          <div key={i} className={`flex flex-col ${m.sender === 'Secretaria' ? 'items-end' : 'items-start'} animate-in slide-in-from-bottom-2`}>
                             <div className={`max-w-[70%] p-4 text-[11px] font-medium leading-relaxed shadow-sm ${m.sender === 'Secretaria' ? 'bg-slate-900 text-white rounded-2xl rounded-tr-sm' : 'bg-white border border-slate-200 text-slate-600 rounded-2xl rounded-tl-sm'}`}>
                                 {m.text}
                             </div>
                             <span className="text-[8px] font-black text-slate-300 uppercase mt-1.5 px-1 tracking-widest">{m.sender} • {m.timestamp?.seconds ? new Date(m.timestamp.seconds * 1000).toLocaleTimeString([], {hour: '2-digit', minute:'2-digit'}) : '...'}</span>
                          </div>
                        ))}
                        <div ref={chatEndRef} />
                     </div>

                     <div className="p-6 border-t border-slate-100 bg-white flex gap-3 items-center">
                        <input value={chatMessage} onChange={e => setChatMessage(e.target.value)} onKeyDown={e => e.key === 'Enter' && handleSendMessage()} placeholder="Digite uma resposta..." className="flex-1 bg-slate-50 border-none rounded-xl px-5 py-4 text-xs font-bold text-slate-700 outline-none focus:ring-2 focus:ring-indigo-500 transition-all" />
                        <button onClick={handleSendMessage} className="p-4 bg-indigo-600 text-white rounded-xl shadow-lg hover:bg-indigo-700 transition-all hover:scale-105 active:scale-95"><Send size={18}/></button>
                     </div>
                   </>
                 ) : (
                   <div className="flex-1 flex flex-col items-center justify-center opacity-30 text-center gap-4 p-10">
                      <div className="w-24 h-24 bg-slate-100 rounded-full flex items-center justify-center"><MessageSquare size={40} className="text-slate-400"/></div>
                      <div>
                        <h4 className="text-lg font-black uppercase text-slate-900 tracking-tighter italic">Nenhuma conversa selecionada</h4>
                        <p className="text-[10px] font-bold uppercase tracking-[0.2em] text-slate-500 mt-2">Selecione um protocolo na lista ao lado.</p>
                      </div>
                   </div>
                 )}
              </div>
           </div>
         )}

         {activeTab === 'arquivos' && (
            <div className="bg-white border border-slate-200 rounded-[2rem] h-full flex flex-col shadow-sm overflow-hidden">
               <div className="p-6 bg-slate-50 border-b border-slate-200 flex justify-between items-center">
                  <div className="flex items-center gap-4">
                     <button onClick={() => setCurrentPath([])} className="text-[10px] font-black uppercase italic hover:underline text-slate-500 hover:text-indigo-600 flex items-center gap-2"><FolderOpen size={14}/> Raiz</button>
                     {currentPath.map((p, i) => (
                       <React.Fragment key={i}><ChevronRight size={14} className="text-slate-300" /><button className="text-[10px] font-black uppercase italic text-indigo-500 bg-indigo-50 px-2 py-1 rounded">{p}</button></React.Fragment>
                     ))}
                  </div>
                  <button className="px-5 py-2.5 bg-slate-900 text-white rounded-xl text-[9px] font-black uppercase flex items-center gap-2 hover:bg-indigo-600 transition-all shadow-lg"><Plus size={14}/> Novo Diretório</button>
               </div>
               <div className="p-8 grid grid-cols-2 md:grid-cols-4 lg:grid-cols-6 gap-6 overflow-y-auto">
                  {currentPath.length === 0 ? (
                     <>
                        {['Matrículas', 'Declarações', 'Financeiro', 'Históricos', 'Contratos', 'Boletins'].map(folder => (
                          <button key={folder} onClick={() => setCurrentPath([folder])} className="aspect-square bg-slate-50 border border-slate-200 rounded-3xl flex flex-col items-center justify-center gap-4 hover:border-indigo-400 hover:shadow-xl hover:bg-white transition-all group">
                             <div className="w-16 h-16 bg-white rounded-2xl flex items-center justify-center shadow-sm group-hover:bg-indigo-50 transition-colors"><Folder size={32} className="text-slate-300 group-hover:text-indigo-500 transition-colors" /></div>
                             <span className="text-[10px] font-black uppercase text-slate-600 tracking-wider group-hover:text-indigo-600">{folder}</span>
                          </button>
                        ))}
                     </>
                  ) : (
                     files.filter(f => f.folder === currentPath[0]).length === 0 ? (
                        <div className="col-span-full py-32 text-center text-slate-300 italic uppercase font-black text-xs tracking-widest border-4 border-dashed rounded-[3rem]">Diretório Vazio.</div>
                     ) : files.filter(f => f.folder === currentPath[0]).map(f => (
                        <div key={f.id} className="aspect-square bg-white border border-slate-200 rounded-3xl flex flex-col items-center justify-center gap-4 relative group hover:shadow-xl transition-all">
                           <FileText size={40} className="text-indigo-200 group-hover:text-indigo-600 transition-colors" />
                           <span className="text-[9px] font-bold uppercase text-slate-900 leading-tight text-center px-4 line-clamp-2">{f.title}</span>
                           <div className="absolute inset-0 bg-slate-900/90 rounded-3xl flex flex-col items-center justify-center opacity-0 group-hover:opacity-100 transition-opacity gap-2">
                              <button className="px-4 py-2 bg-white text-slate-900 rounded-lg text-[8px] font-black uppercase flex items-center gap-2 hover:bg-indigo-50"><FileDown size={12}/> Baixar</button>
                              <button className="px-4 py-2 text-rose-400 text-[8px] font-black uppercase hover:text-rose-200 flex items-center gap-2"><Trash2 size={12}/> Excluir</button>
                           </div>
                        </div>
                     ))
                  )}
               </div>
            </div>
         )}
      </main>

      {/* MODAL NOVO PROTOCOLO */}
      {isNewProtocolOpen && (
        <div className="fixed inset-0 z-[3000] bg-slate-950/80 backdrop-blur-sm flex items-center justify-center p-4 animate-in zoom-in-95">
           <div className="bg-white w-full max-w-md rounded-[2.5rem] p-10 space-y-6 shadow-2xl">
              <div className="flex justify-between items-center">
                 <h3 className="text-xl font-black uppercase italic text-slate-900 tracking-tighter">Abrir Protocolo</h3>
                 <button onClick={() => setIsNewProtocolOpen(false)} className="p-2 bg-slate-100 rounded-full hover:bg-slate-200"><X size={20}/></button>
              </div>
              <div className="space-y-4">
                 <div className="space-y-1.5"><label className="text-[9px] font-black uppercase text-slate-400 ml-2">Nome do Solicitante</label><input value={newProtocolForm.name} onChange={e => setNewProtocolForm({...newProtocolForm, name: e.target.value})} className="w-full p-4 bg-slate-50 border-none rounded-2xl text-xs font-bold outline-none focus:ring-2 focus:ring-indigo-500" placeholder="Nome Completo..." /></div>
                 <div className="space-y-1.5"><label className="text-[9px] font-black uppercase text-slate-400 ml-2">Canal de Origem</label><select value={newProtocolForm.channel} onChange={e => setNewProtocolForm({...newProtocolForm, channel: e.target.value})} className="w-full p-4 bg-slate-50 border-none rounded-2xl text-xs font-bold outline-none focus:ring-2 focus:ring-indigo-500 cursor-pointer"><option value="Balcão">Balcão (Presencial)</option><option value="Telefone">Telefone</option><option value="WhatsApp">WhatsApp</option><option value="E-mail">E-mail</option></select></div>
                 <div className="space-y-1.5"><label className="text-[9px] font-black uppercase text-slate-400 ml-2">Descrição Inicial</label><textarea value={newProtocolForm.notes} onChange={e => setNewProtocolForm({...newProtocolForm, notes: e.target.value})} className="w-full p-4 bg-slate-50 border-none rounded-2xl text-xs font-medium outline-none focus:ring-2 focus:ring-indigo-500 h-24 resize-none" placeholder="Motivo do contato..." /></div>
                 <button onClick={handleCreateProtocol} className="w-full py-4 bg-indigo-600 text-white rounded-2xl text-[10px] font-black uppercase shadow-xl hover:bg-indigo-700 transition-all">Gerar Ticket</button>
              </div>
           </div>
        </div>
      )}

      {isSignModalOpen && <SignaturePad title="Certificação Digital do Secretário" onCancel={() => setIsSignModalOpen(false)} onSave={async b => { await updateDoc(doc(db, 'users', user.uid), {signatureUrl: b}); setSecSignature(b); setIsSignModalOpen(false); alert('Assinatura Registrada!'); }} />}
    </div>
  );
};

export default SecretariatView;

import React, { useState, useEffect, useMemo, useRef } from 'react';
import { 
  collection, query, onSnapshot, addDoc, updateDoc, 
  doc, serverTimestamp, orderBy, where, deleteDoc, getDoc, getDocs
} from "https://www.gstatic.com/firebasejs/10.7.1/firebase-firestore.js";
import { db, auth } from '../firebase';
import { User } from '../types';
import { 
  Ticket as TicketIcon, AlertCircle, Clock, MessageSquare, Search, Plus, X, FolderOpen, FileText, Download, UserCheck, ShieldAlert, FileSignature, Save, PenTool, UserX, Check, ArrowRightLeft, Fingerprint, Star, Send, Folder, Archive, CheckCircle2, ChevronRight, FileDown, Phone, Printer, MoreVertical, RotateCcw, Trash2
} from 'lucide-react';
import SignaturePad from '../components/SignaturePad';

interface SecretariatViewProps { user: User; }
type SecretariatTab = 'atendimento' | 'chat' | 'arquivos' | 'operacional';
type OperationalSubView = 'main' | 'declaracao' | 'validacao' | 'transferencia' | 'assinatura' | 'ficha';
type ChatFilter = 'abertos' | 'finalizados' | 'arquivados';

const SecretariatView: React.FC<SecretariatViewProps> = ({ user }) => {
  const [activeTab, setActiveTab] = useState<SecretariatTab>('atendimento');
  const [opSubView, setOpSubView] = useState<OperationalSubView>('main');
  const [chatFilter, setChatFilter] = useState<ChatFilter>('abertos');
  const [tickets, setTickets] = useState<any[]>([]);
  const [files, setFiles] = useState<any[]>([]);
  const [students, setStudents] = useState<any[]>([]);
  const [courses, setCourses] = useState<any[]>([]);
  const [searchTerm, setSearchTerm] = useState('');
  const [selectedTicketId, setSelectedTicketId] = useState<string | null>(null);
  const [chatHistory, setChatHistory] = useState<any[]>([]);
  const [chatMessage, setChatMessage] = useState('');
  const [isSignModalOpen, setIsSignModalOpen] = useState(false);
  const [secSignature, setSecSignature] = useState<string | null>(null);

  // New States for Protocol Modal
  const [isNewProtocolOpen, setIsNewProtocolOpen] = useState(false);
  const [newProtocolForm, setNewProtocolForm] = useState({ name: '', channel: 'Balcão', notes: '' });

  // Operational Modals States
  const [selectedStudentForOp, setSelectedStudentForOp] = useState<string>('');
  const [targetCourseId, setTargetCourseId] = useState<string>('');
  const [declarationText, setDeclarationText] = useState('');

  const [currentPath, setCurrentPath] = useState<string[]>([]);
  const chatEndRef = useRef<HTMLDivElement>(null);

  useEffect(() => {
    const unsubT = onSnapshot(query(collection(db, 'tickets'), orderBy('createdAt', 'desc')), s => setTickets(s.docs.map(d => ({ id: d.id, ...d.data() }))));
    const unsubF = onSnapshot(collection(db, 'secretaria_arquivos'), s => setFiles(s.docs.map(d => ({ id: d.id, ...d.data() }))));
    const unsubS = onSnapshot(query(collection(db, 'users'), where('role', '==', 'aluno')), s => setStudents(s.docs.map(d => ({ uid: d.id, ...d.data() }))));
    const unsubC = onSnapshot(collection(db, 'cursos'), s => setCourses(s.docs.map(d => ({ id: d.id, ...d.data() }))));
    getDoc(doc(db, 'users', user.uid)).then(d => d.exists() && setSecSignature(d.data().signatureUrl));
    return () => { unsubT(); unsubF(); unsubS(); unsubC(); };
  }, [user.uid]);

  useEffect(() => {
    if (!selectedTicketId) return;
    const unsubChat = onSnapshot(query(collection(db, `tickets/${selectedTicketId}/messages`), orderBy('timestamp', 'asc')), (snap) => {
      setChatHistory(snap.docs.map(d => d.data()));
      setTimeout(() => chatEndRef.current?.scrollIntoView({ behavior: 'smooth' }), 100);
    });
    return () => unsubChat();
  }, [selectedTicketId]);

  const stats = useMemo(() => {
    const pendingVal = students.filter(s => s.status === 'aguardando_validacao' || s.status === 'pendente').length;
    return {
      abertos: tickets.filter(t => t.status === 'Pendente').length,
      finalizados: tickets.filter(t => t.status === 'Finalizado').length,
      arquivados: tickets.filter(t => t.status === 'Arquivado').length,
      pendentesVal: pendingVal,
      totalGed: files.length
    };
  }, [tickets, students, files]);

  const handleSendMessage = async () => {
    if (!selectedTicketId || !chatMessage.trim()) return;
    const msg = { text: chatMessage, sender: 'Secretaria', timestamp: serverTimestamp() };
    await addDoc(collection(db, `tickets/${selectedTicketId}/messages`), msg);
    await updateDoc(doc(db, 'tickets', selectedTicketId), { lastMessage: chatMessage, lastUpdate: serverTimestamp() });
    setChatMessage('');
  };

  const handleCreateProtocol = async () => {
    if (!newProtocolForm.name) return;
    const protocol = 'PROT-' + Math.random().toString(36).substring(2, 9).toUpperCase();
    await addDoc(collection(db, 'tickets'), {
      protocolo: protocol,
      user: newProtocolForm.name,
      email: 'Atendimento Local',
      type: newProtocolForm.channel,
      status: 'Pendente',
      createdAt: serverTimestamp(),
      lastUpdate: serverTimestamp(),
      lastMessage: newProtocolForm.notes || 'Início de atendimento.'
    });
    setIsNewProtocolOpen(false);
    setNewProtocolForm({ name: '', channel: 'Balcão', notes: '' });
    alert(`Protocolo ${protocol} gerado com sucesso!`);
  };

  const generateDeclaration = () => {
    if (!selectedStudentForOp) return;
    const s = students.find(u => u.uid === selectedStudentForOp);
    const c = courses.find(course => course.id === s?.cursoInicial);
    const text = `
      DECLARAÇÃO DE MATRÍCULA

      Declaramos para os devidos fins que o(a) aluno(a) ${s?.displayName.toUpperCase()},
      inscrito(a) sob o CPF ${s?.cpf || '___.___.___-__'}, encontra-se regularmente 
      matriculado(a) no curso de ${c?.nome.toUpperCase() || 'TEOLOGIA'}, nesta instituição de ensino.

      Status Acadêmico: ${s?.status.toUpperCase()}
      Data de Emissão: ${new Date().toLocaleDateString('pt-BR')}

      __________________________________
      Secretaria Acadêmica - EBD EAD
    `;
    setDeclarationText(text);
  };

  const handleTransfer = async () => {
    if (!selectedStudentForOp || !targetCourseId) return;
    if (confirm('Confirmar transferência de curso?')) {
      await updateDoc(doc(db, 'users', selectedStudentForOp), { cursoInicial: targetCourseId });
      alert('Transferência realizada com sucesso.');
      setOpSubView('main');
    }
  };

  const filteredTickets = tickets.filter(t => {
    const matchSearch = t.protocolo?.toLowerCase().includes(searchTerm.toLowerCase()) || t.user?.toLowerCase().includes(searchTerm.toLowerCase());
    if (activeTab === 'atendimento') return matchSearch && t.status === 'Pendente';
    if (activeTab === 'chat') {
       if (chatFilter === 'abertos') return matchSearch && (t.status === 'Em Atendimento' || t.status === 'Pendente');
       if (chatFilter === 'finalizados') return matchSearch && t.status === 'Finalizado';
       if (chatFilter === 'arquivados') return matchSearch && t.status === 'Arquivado';
    }
    return matchSearch;
  });

  const renderOperational = () => {
    switch(opSubView) {
      case 'validacao':
        const pending = students.filter(s => s.status === 'aguardando_validacao' || s.status === 'pendente');
        return (
          <div className="bg-white border border-slate-300 animate-in zoom-in-98 shadow-lg rounded-2xl overflow-hidden">
             <div className="p-6 bg-slate-900 text-white flex justify-between items-center">
                <h3 className="text-sm font-bold uppercase italic flex items-center gap-2"><UserCheck size={18}/> Validação de Novas Matrículas</h3>
                <button onClick={() => setOpSubView('main')}><X size={20}/></button>
             </div>
             <table className="w-full text-left border-collapse">
                <thead className="bg-slate-50 border-b border-slate-300 text-[10px] font-bold uppercase">
                   <tr><th className="px-6 py-4">Aluno</th><th className="px-6 py-4">Curso Escolhido</th><th className="px-6 py-4 text-center">Gestão</th></tr>
                </thead>
                <tbody className="text-xs">
                   {pending.length === 0 ? <tr><td colSpan={3} className="p-10 text-center text-slate-400 italic font-bold">Todas as matrículas estão em dia.</td></tr> : pending.map(s => (
                     <tr key={s.uid} className="border-b border-slate-200 hover:bg-slate-50">
                        <td className="px-6 py-4 font-bold uppercase">{s.displayName}</td>
                        <td className="px-6 py-4 font-bold text-indigo-600 uppercase">{courses.find(c=>c.id===s.cursoInicial)?.nome || 'Não definido'}</td>
                        <td className="px-6 py-4 flex gap-3 justify-center">
                           <button onClick={async () => await updateDoc(doc(db, 'users', s.uid), {status: 'ativo'})} className="px-4 py-2 bg-emerald-600 text-white text-[10px] font-black uppercase rounded-lg hover:bg-emerald-700 transition-all shadow-md">Aprovar Acesso</button>
                           <button onClick={async () => await deleteDoc(doc(db, 'users', s.uid))} className="p-2 border border-red-200 text-red-600 hover:bg-red-50 rounded-lg"><UserX size={16}/></button>
                        </td>
                     </tr>
                   ))}
                </tbody>
             </table>
          </div>
        );
      case 'declaracao':
        return (
          <div className="bg-white border border-slate-300 shadow-xl rounded-2xl p-8 max-w-2xl mx-auto space-y-6">
             <div className="flex justify-between items-center border-b pb-4">
                <h3 className="text-lg font-black uppercase text-slate-900 italic">Emissor de Declarações</h3>
                <button onClick={() => setOpSubView('main')} className="text-slate-400 hover:text-rose-500"><X size={24}/></button>
             </div>
             <div className="flex gap-4">
               <select value={selectedStudentForOp} onChange={e => setSelectedStudentForOp(e.target.value)} className="flex-1 p-3 border border-slate-300 rounded-xl text-xs font-bold uppercase outline-none focus:border-indigo-600">
                 <option value="">Selecione o Aluno...</option>
                 {students.map(s => <option key={s.uid} value={s.uid}>{s.displayName}</option>)}
               </select>
               <button onClick={generateDeclaration} className="px-6 py-3 bg-indigo-600 text-white rounded-xl text-[10px] font-black uppercase hover:bg-indigo-700">Gerar</button>
             </div>
             {declarationText && (
               <div className="bg-slate-50 p-8 border border-slate-200 rounded-xl font-serif text-sm leading-relaxed whitespace-pre-wrap shadow-inner text-slate-800">
                 {declarationText}
               </div>
             )}
             {declarationText && (
               <div className="flex justify-end">
                 <button onClick={() => window.print()} className="flex items-center gap-2 px-8 py-3 bg-slate-900 text-white rounded-xl text-[10px] font-black uppercase hover:bg-slate-800"><Printer size={16}/> Imprimir Documento</button>
               </div>
             )}
          </div>
        );
      case 'transferencia':
        return (
          <div className="bg-white border border-slate-300 shadow-xl rounded-2xl p-8 max-w-lg mx-auto space-y-6">
             <div className="flex justify-between items-center border-b pb-4">
                <h3 className="text-lg font-black uppercase text-slate-900 italic">Transferência de Curso</h3>
                <button onClick={() => setOpSubView('main')} className="text-slate-400 hover:text-rose-500"><X size={24}/></button>
             </div>
             <div className="space-y-4">
                <div>
                  <label className="text-[10px] font-bold text-slate-400 uppercase">Aluno</label>
                  <select value={selectedStudentForOp} onChange={e => setSelectedStudentForOp(e.target.value)} className="w-full p-3 border border-slate-300 rounded-xl text-xs font-bold uppercase mt-1">
                    <option value="">Selecione...</option>
                    {students.map(s => <option key={s.uid} value={s.uid}>{s.displayName}</option>)}
                  </select>
                </div>
                <div>
                  <label className="text-[10px] font-bold text-slate-400 uppercase">Novo Curso de Destino</label>
                  <select value={targetCourseId} onChange={e => setTargetCourseId(e.target.value)} className="w-full p-3 border border-slate-300 rounded-xl text-xs font-bold uppercase mt-1">
                    <option value="">Selecione...</option>
                    {courses.map(c => <option key={c.id} value={c.id}>{c.nome}</option>)}
                  </select>
                </div>
