                                 {m.text}
                             </div>
                             <span className="text-[8px] font-black text-slate-300 uppercase mt-1.5 px-1 tracking-widest">{m.sender} • {m.timestamp?.seconds ? new Date(m.timestamp.seconds * 1000).toLocaleTimeString([], {hour: '2-digit', minute:'2-digit'}) : '...'}</span>
                          </div>
