                       <React.Fragment key={i}><ChevronRight size={14} className="text-slate-300" /><button className="text-[10px] font-black uppercase italic text-indigo-500 bg-indigo-50 px-2 py-1 rounded">{p}</button></React.Fragment>
                     ))}
