                  <button className="px-5 py-2.5 bg-slate-900 text-white rounded-xl text-[9px] font-black uppercase flex items-center gap-2 hover:bg-indigo-600 transition-all shadow-lg"><Plus size={14}/> Novo Diretório</button>
               </div>
               <div className="p-8 grid grid-cols-2 md:grid-cols-4 lg:grid-cols-6 gap-6 overflow-y-auto">
                  {currentPath.length === 0 ? (
                     <>
                        {['Matrículas', 'Declarações', 'Financeiro', 'Históricos', 'Contratos', 'Boletins'].map(folder => (
                          <button key={folder} onClick={() => setCurrentPath([folder])} className="aspect-square bg-slate-50 border border-slate-200 rounded-3xl flex flex-col items-center justify-center gap-4 hover:border-indigo-400 hover:shadow-xl hover:bg-white transition-all group">
                             <div className="w-16 h-16 bg-white rounded-2xl flex items-center justify-center shadow-sm group-hover:bg-indigo-50 transition-colors"><Folder size={32} className="text-slate-300 group-hover:text-indigo-500 transition-colors" /></div>
                             <span className="text-[10px] font-black uppercase text-slate-600 tracking-wider group-hover:text-indigo-600">{folder}</span>
                          </button>
                        ))}
                     </>
                  ) : (
                     files.filter(f => f.folder === currentPath[0]).length === 0 ? (
                        <div className="col-span-full py-32 text-center text-slate-300 italic uppercase font-black text-xs tracking-widest border-4 border-dashed rounded-[3rem]">Diretório Vazio.</div>
                     ) : files.filter(f => f.folder === currentPath[0]).map(f => (
                        <div key={f.id} className="aspect-square bg-white border border-slate-200 rounded-3xl flex flex-col items-center justify-center gap-4 relative group hover:shadow-xl transition-all">
                           <FileText size={40} className="text-indigo-200 group-hover:text-indigo-600 transition-colors" />
                           <span className="text-[9px] font-bold uppercase text-slate-900 leading-tight text-center px-4 line-clamp-2">{f.title}</span>
                           <div className="absolute inset-0 bg-slate-900/90 rounded-3xl flex flex-col items-center justify-center opacity-0 group-hover:opacity-100 transition-opacity gap-2">
                              <button className="px-4 py-2 bg-white text-slate-900 rounded-lg text-[8px] font-black uppercase flex items-center gap-2 hover:bg-indigo-50"><FileDown size={12}/> Baixar</button>
                              <button className="px-4 py-2 text-rose-400 text-[8px] font-black uppercase hover:text-rose-200 flex items-center gap-2"><Trash2 size={12}/> Excluir</button>
                           </div>
                        </div>
                     ))
                  )}
               </div>
            </div>
         )}
      </main>

      {/* MODAL NOVO PROTOCOLO */}
      {isNewProtocolOpen && (
        <div className="fixed inset-0 z-[3000] bg-slate-950/80 backdrop-blur-sm flex items-center justify-center p-4 animate-in zoom-in-95">
           <div className="bg-white w-full max-w-md rounded-[2.5rem] p-10 space-y-6 shadow-2xl">
              <div className="flex justify-between items-center">
                 <h3 className="text-xl font-black uppercase italic text-slate-900 tracking-tighter">Abrir Protocolo</h3>
                 <button onClick={() => setIsNewProtocolOpen(false)} className="p-2 bg-slate-100 rounded-full hover:bg-slate-200"><X size={20}/></button>
              </div>
              <div className="space-y-4">
                 <div className="space-y-1.5"><label className="text-[9px] font-black uppercase text-slate-400 ml-2">Nome do Solicitante</label><input value={newProtocolForm.name} onChange={e => setNewProtocolForm({...newProtocolForm, name: e.target.value})} className="w-full p-4 bg-slate-50 border-none rounded-2xl text-xs font-bold outline-none focus:ring-2 focus:ring-indigo-500" placeholder="Nome Completo..." /></div>
                 <div className="space-y-1.5"><label className="text-[9px] font-black uppercase text-slate-400 ml-2">Canal de Origem</label><select value={newProtocolForm.channel} onChange={e => setNewProtocolForm({...newProtocolForm, channel: e.target.value})} className="w-full p-4 bg-slate-50 border-none rounded-2xl text-xs font-bold outline-none focus:ring-2 focus:ring-indigo-500 cursor-pointer"><option value="Balcão">Balcão (Presencial)</option><option value="Telefone">Telefone</option><option value="WhatsApp">WhatsApp</option><option value="E-mail">E-mail</option></select></div>
                 <div className="space-y-1.5"><label className="text-[9px] font-black uppercase text-slate-400 ml-2">Descrição Inicial</label><textarea value={newProtocolForm.notes} onChange={e => setNewProtocolForm({...newProtocolForm, notes: e.target.value})} className="w-full p-4 bg-slate-50 border-none rounded-2xl text-xs font-medium outline-none focus:ring-2 focus:ring-indigo-500 h-24 resize-none" placeholder="Motivo do contato..." /></div>
                 <button onClick={handleCreateProtocol} className="w-full py-4 bg-indigo-600 text-white rounded-2xl text-[10px] font-black uppercase shadow-xl hover:bg-indigo-700 transition-all">Gerar Ticket</button>
              </div>
           </div>
        </div>
      )}

      {isSignModalOpen && <SignaturePad title="Certificação Digital do Secretário" onCancel={() => setIsSignModalOpen(false)} onSave={async b => { await updateDoc(doc(db, 'users', user.uid), {signatureUrl: b}); setSecSignature(b); setIsSignModalOpen(false); alert('Assinatura Registrada!'); }} />}
    </div>
  );
};

export default SecretariatView;

