import { User } from '../types';
import { 
  Ticket as TicketIcon, AlertCircle, Clock, MessageSquare, Search, Plus, X, FolderOpen, FileText, Download, UserCheck, ShieldAlert, FileSignature, Save, PenTool, UserX, Check, ArrowRightLeft, Fingerprint, Star, Send, Folder, Archive, CheckCircle2, ChevronRight, FileDown, Phone, Printer, MoreVertical, RotateCcw, Trash2, QrCode, ShieldCheck
} from 'lucide-react';
import SignaturePad from '../components/SignaturePad';

interface SecretariatViewProps { user: User; }
type SecretariatTab = 'atendimento' | 'chat' | 'arquivos' | 'operacional';
type OperationalSubView = 'main' | 'declaracao' | 'validacao' | 'transferencia' | 'assinatura' | 'ficha';
type ChatFilter = 'abertos' | 'finalizados' | 'arquivados';

const SecretariatView: React.FC<SecretariatViewProps> = ({ user }) => {
  const [activeTab, setActiveTab] = useState<SecretariatTab>('atendimento');
  const [opSubView, setOpSubView] = useState<OperationalSubView>('main');
  const [chatFilter, setChatFilter] = useState<ChatFilter>('abertos');
  const [tickets, setTickets] = useState<any[]>([]);
  const [files, setFiles] = useState<any[]>([]);
  const [students, setStudents] = useState<any[]>([]);
  const [courses, setCourses] = useState<any[]>([]);
  const [searchTerm, setSearchTerm] = useState('');
  const [selectedTicketId, setSelectedTicketId] = useState<string | null>(null);
  const [chatHistory, setChatHistory] = useState<any[]>([]);
  const [chatMessage, setChatMessage] = useState('');
  const [isSignModalOpen, setIsSignModalOpen] = useState(false);
  const [secSignature, setSecSignature] = useState<string | null>(null);

  // Assinaturas Institucionais
  const [directorSignature, setDirectorSignature] = useState<string | null>(null);
  const [secretarySignature, setSecretarySignature] = useState<string | null>(null);

  // New States for Protocol Modal
  const [isNewProtocolOpen, setIsNewProtocolOpen] = useState(false);
  const [newProtocolForm, setNewProtocolForm] = useState({ name: '', channel: 'Balcão', notes: '' });

  // Operational Modals States
  const [selectedStudentForOp, setSelectedStudentForOp] = useState<string>('');
  const [targetCourseId, setTargetCourseId] = useState<string>('');

  // Estado para os dados da declaração gerada
  const [declarationData, setDeclarationData] = useState<any | null>(null);

  const [currentPath, setCurrentPath] = useState<string[]>([]);
  const chatEndRef = useRef<HTMLDivElement>(null);

  useEffect(() => {
    const unsubT = onSnapshot(query(collection(db, 'tickets'), orderBy('createdAt', 'desc')), s => setTickets(s.docs.map(d => ({ id: d.id, ...d.data() }))));
    const unsubF = onSnapshot(collection(db, 'secretaria_arquivos'), s => setFiles(s.docs.map(d => ({ id: d.id, ...d.data() }))));
    const unsubS = onSnapshot(query(collection(db, 'users'), where('role', '==', 'aluno')), s => setStudents(s.docs.map(d => ({ uid: d.id, ...d.data() }))));
    const unsubC = onSnapshot(collection(db, 'cursos'), s => setCourses(s.docs.map(d => ({ id: d.id, ...d.data() }))));
    getDoc(doc(db, 'users', user.uid)).then(d => d.exists() && setSecSignature(d.data().signatureUrl));

    // Buscar assinaturas do Diretor e da Secretaria para documentos
    const fetchSignatures = async () => {
        const qDir = query(collection(db, 'users'), where('role', '==', 'diretor'));
        const qSec = query(collection(db, 'users'), where('role', '==', 'secretaria'));

        const snapDir = await getDocs(qDir);
        const snapSec = await getDocs(qSec);

        if (!snapDir.empty) setDirectorSignature(snapDir.docs[0].data().signatureUrl);
        if (!snapSec.empty) setSecretarySignature(snapSec.docs[0].data().signatureUrl);
    };
    fetchSignatures();

    return () => { unsubT(); unsubF(); unsubS(); unsubC(); };
  }, [user.uid]);

  useEffect(() => {
    if (!selectedTicketId) return;
    const unsubChat = onSnapshot(query(collection(db, `tickets/${selectedTicketId}/messages`), orderBy('timestamp', 'asc')), (snap) => {
      setChatHistory(snap.docs.map(d => d.data()));
      setTimeout(() => chatEndRef.current?.scrollIntoView({ behavior: 'smooth' }), 100);
    });
    return () => unsubChat();
  }, [selectedTicketId]);

  const stats = useMemo(() => {
    const pendingVal = students.filter(s => s.status === 'aguardando_validacao' || s.status === 'pendente').length;
    return {
      abertos: tickets.filter(t => t.status === 'Pendente').length,
      finalizados: tickets.filter(t => t.status === 'Finalizado').length,
      arquivados: tickets.filter(t => t.status === 'Arquivado').length,
      pendentesVal: pendingVal,
      totalGed: files.length
    };
  }, [tickets, students, files]);

  const handleSendMessage = async () => {
    if (!selectedTicketId || !chatMessage.trim()) return;
    const msg = { text: chatMessage, sender: 'Secretaria', timestamp: serverTimestamp() };
    await addDoc(collection(db, `tickets/${selectedTicketId}/messages`), msg);
    await updateDoc(doc(db, 'tickets', selectedTicketId), { lastMessage: chatMessage, lastUpdate: serverTimestamp() });
    setChatMessage('');
  };

  const handleCreateProtocol = async () => {
    if (!newProtocolForm.name) return;
    const protocol = 'PROT-' + Math.random().toString(36).substring(2, 9).toUpperCase();
    await addDoc(collection(db, 'tickets'), {
      protocolo: protocol,
      user: newProtocolForm.name,
      email: 'Atendimento Local',
      type: newProtocolForm.channel,
      status: 'Pendente',
      createdAt: serverTimestamp(),
      lastUpdate: serverTimestamp(),
      lastMessage: newProtocolForm.notes || 'Início de atendimento.'
    });
    setIsNewProtocolOpen(false);
    setNewProtocolForm({ name: '', channel: 'Balcão', notes: '' });
    alert(`Protocolo ${protocol} gerado com sucesso!`);
  };

  const generateDeclaration = () => {
    if (!selectedStudentForOp) return;
    const s = students.find(u => u.uid === selectedStudentForOp);
    const c = courses.find(course => course.id === s?.cursoInicial);

    // Gerar Código de Validação Único
    const uniqueHash = Math.random().toString(36).substring(2, 15).toUpperCase() + "-" + Date.now().toString().slice(-6);

    setDeclarationData({
        studentName: s?.displayName.toUpperCase(),
        cpf: s?.cpf || 'Não Informado',
        courseName: c?.nome.toUpperCase() || 'TEOLOGIA SISTEMÁTICA',
        status: s?.status.toUpperCase(),
        enrollmentDate: s?.createdAt?.seconds ? new Date(s.createdAt.seconds * 1000).toLocaleDateString('pt-BR') : new Date().toLocaleDateString('pt-BR'),
        today: new Date().toLocaleDateString('pt-BR', { day: 'numeric', month: 'long', year: 'numeric' }),
        hash: uniqueHash,
        directorSig: directorSignature,
        secretarySig: secretarySignature || secSignature // Fallback para a assinatura do usuário atual se for secretaria
    });
  };

  const handleTransfer = async () => {
    if (!selectedStudentForOp || !targetCourseId) return;
    if (confirm('Confirmar transferência de curso?')) {
      await updateDoc(doc(db, 'users', selectedStudentForOp), { cursoInicial: targetCourseId });
      alert('Transferência realizada com sucesso.');
      setOpSubView('main');
    }
  };

  const filteredTickets = tickets.filter(t => {
    const matchSearch = t.protocolo?.toLowerCase().includes(searchTerm.toLowerCase()) || t.user?.toLowerCase().includes(searchTerm.toLowerCase());
    if (activeTab === 'atendimento') return matchSearch && t.status === 'Pendente';
    if (activeTab === 'chat') {
       if (chatFilter === 'abertos') return matchSearch && (t.status === 'Em Atendimento' || t.status === 'Pendente');
       if (chatFilter === 'finalizados') return matchSearch && t.status === 'Finalizado';
       if (chatFilter === 'arquivados') return matchSearch && t.status === 'Arquivado';
    }
    return matchSearch;
  });

  const renderOperational = () => {
    switch(opSubView) {
      case 'validacao':
        const pending = students.filter(s => s.status === 'aguardando_validacao' || s.status === 'pendente');
        return (
          <div className="bg-white border border-slate-300 animate-in zoom-in-98 shadow-lg rounded-2xl overflow-hidden">
             <div className="p-6 bg-slate-900 text-white flex justify-between items-center">
                <h3 className="text-sm font-bold uppercase italic flex items-center gap-2"><UserCheck size={18}/> Validação de Novas Matrículas</h3>
                <button onClick={() => setOpSubView('main')}><X size={20}/></button>
             </div>
             <table className="w-full text-left border-collapse">
                <thead className="bg-slate-50 border-b border-slate-300 text-[10px] font-bold uppercase">
                   <tr><th className="px-6 py-4">Aluno</th><th className="px-6 py-4">Curso Escolhido</th><th className="px-6 py-4 text-center">Gestão</th></tr>
                </thead>
                <tbody className="text-xs">
                   {pending.length === 0 ? <tr><td colSpan={3} className="p-10 text-center text-slate-400 italic font-bold">Todas as matrículas estão em dia.</td></tr> : pending.map(s => (
                     <tr key={s.uid} className="border-b border-slate-200 hover:bg-slate-50">
                        <td className="px-6 py-4 font-bold uppercase">{s.displayName}</td>
                        <td className="px-6 py-4 font-bold text-indigo-600 uppercase">{courses.find(c=>c.id===s.cursoInicial)?.nome || 'Não definido'}</td>
                        <td className="px-6 py-4 flex gap-3 justify-center">
                           <button onClick={async () => await updateDoc(doc(db, 'users', s.uid), {status: 'ativo'})} className="px-4 py-2 bg-emerald-600 text-white text-[10px] font-black uppercase rounded-lg hover:bg-emerald-700 transition-all shadow-md">Aprovar Acesso</button>
                           <button onClick={async () => await deleteDoc(doc(db, 'users', s.uid))} className="p-2 border border-red-200 text-red-600 hover:bg-red-50 rounded-lg"><UserX size={16}/></button>
                        </td>
                     </tr>
                   ))}
                </tbody>
             </table>
          </div>
        );
      case 'declaracao':
        return (
          <div className="bg-white border border-slate-300 shadow-xl rounded-2xl max-w-4xl mx-auto flex flex-col h-[85vh]">
             {/* Header do Modal (Não sai na impressão) */}
             <div className="flex justify-between items-center p-6 border-b border-slate-200 bg-slate-50 rounded-t-2xl print:hidden">
                <h3 className="text-lg font-black uppercase text-slate-900 italic">Emissor de Documentos Oficiais</h3>
                <button onClick={() => { setOpSubView('main'); setDeclarationData(null); }} className="text-slate-400 hover:text-rose-500"><X size={24}/></button>
             </div>

             {/* Controles (Não sai na impressão) */}
             <div className="p-6 border-b border-slate-100 flex gap-4 print:hidden bg-white">
               <select value={selectedStudentForOp} onChange={e => setSelectedStudentForOp(e.target.value)} className="flex-1 p-3 border border-slate-300 rounded-xl text-xs font-bold uppercase outline-none focus:border-indigo-600">
                 <option value="">Selecione o Aluno para Emitir...</option>
                 {students.map(s => <option key={s.uid} value={s.uid}>{s.displayName}</option>)}
               </select>
               <button onClick={generateDeclaration} className="px-6 py-3 bg-indigo-600 text-white rounded-xl text-[10px] font-black uppercase hover:bg-indigo-700 shadow-lg">Gerar Documento</button>
               {declarationData && <button onClick={() => window.print()} className="flex items-center gap-2 px-6 py-3 bg-slate-900 text-white rounded-xl text-[10px] font-black uppercase hover:bg-slate-800 shadow-lg"><Printer size={16}/> Imprimir / PDF</button>}
             </div>

             {/* Área de Visualização / Impressão */}
             <div className="flex-1 overflow-y-auto bg-slate-100 p-8 print:p-0 print:bg-white print:overflow-visible">
               {declarationData ? (
                 <div id="print-area" className="bg-white shadow-2xl mx-auto w-[210mm] min-h-[297mm] p-[20mm] relative text-black print:shadow-none print:w-full print:h-full">
                    {/* Cabeçalho */}
                    <div className="text-center border-b-2 border-slate-900 pb-6 mb-8">
                       <div className="flex items-center justify-center gap-3 mb-4">
                          <ShieldCheck size={48} className="text-slate-900"/>
                          <div className="text-left">
                             <h1 className="text-2xl font-serif font-bold uppercase tracking-widest text-slate-900 leading-none">Escola Bíblica EAD</h1>
                             <p className="text-[10px] font-sans font-bold uppercase tracking-[0.4em] text-slate-500 mt-1">Excelência em Ensino Teológico</p>
                          </div>
                       </div>
                       <p className="text-xs font-serif italic text-slate-600">CNPJ: 00.000.000/0001-00 | Credenciamento MEC/Cultura nº 12345</p>
                       <p className="text-xs font-serif italic text-slate-600">Av. das Nações, 1000 - Centro - São Paulo/SP</p>
                    </div>

                    {/* Título */}
                    <div className="my-12 text-center">
                       <h2 className="text-3xl font-serif font-bold uppercase tracking-[0.2em] underline decoration-double underline-offset-4">Declaração de Matrícula</h2>
                    </div>

                    {/* Corpo do Texto */}
                    <div className="font-serif text-lg leading-loose text-justify space-y-8 px-4">
                       <p>
                          Declaramos, para os devidos fins de direito e a quem possa interessar, que o(a) aluno(a) 
                          <span className="font-bold uppercase"> {declarationData.studentName}</span>, portador(a) do CPF nº <span className="font-bold">{declarationData.cpf}</span>, 
                          encontra-se regularmente matriculado(a) no curso de <span className="font-bold uppercase">{declarationData.courseName}</span> nesta instituição de ensino.
                       </p>
                       <p>
                          Atestamos ainda que o referido discente possui situação acadêmica atual classificada como 
                          <span className="font-bold uppercase"> "{declarationData.status}"</span>, tendo iniciado suas atividades letivas na data de {declarationData.enrollmentDate}.
                       </p>
                       <p>
                          Esta declaração tem validade de 30 (trinta) dias a partir da data de sua emissão e pode ser verificada digitalmente através do código de autenticação impresso no rodapé deste documento.
                       </p>
                    </div>

                    {/* Data e Local */}
                    <div className="mt-16 text-right font-serif text-lg px-4">
                       <p>São Paulo, {declarationData.today}.</p>
                    </div>

                    {/* Assinaturas */}
                    <div className="mt-24 grid grid-cols-2 gap-10">
                       <div className="flex flex-col items-center justify-end h-32">
                          {declarationData.secretarySig ? <img src={declarationData.secretarySig} className="h-20 object-contain mb-[-10px] mix-blend-multiply" /> : <div className="h-16"></div>}
                          <div className="w-full border-t border-slate-900"></div>
                          <p className="font-bold text-sm uppercase mt-2">Secretaria Acadêmica</p>
                       </div>
                       <div className="flex flex-col items-center justify-end h-32">
                          {declarationData.directorSig ? <img src={declarationData.directorSig} className="h-20 object-contain mb-[-10px] mix-blend-multiply" /> : <div className="h-16"></div>}
                          <div className="w-full border-t border-slate-900"></div>
                          <p className="font-bold text-sm uppercase mt-2">Diretoria Executiva</p>
                       </div>
                    </div>

                    {/* Rodapé de Validação */}
                    <div className="absolute bottom-[15mm] left-[20mm] right-[20mm] border-t border-slate-300 pt-4 flex items-center justify-between">
                       <div className="space-y-1">
                          <p className="text-[9px] font-sans font-bold uppercase text-slate-500">Documento assinado digitalmente com validade nacional.</p>
                          <p className="text-[9px] font-sans text-slate-400">Verifique a autenticidade deste documento informando o código abaixo na secretaria virtual.</p>
                          <p className="text-xs font-mono font-bold text-slate-800 bg-slate-100 px-2 py-1 inline-block border border-slate-200 mt-1">HASH: {declarationData.hash}</p>
                       </div>
                       <div className="text-right">
                          <QrCode size={48} className="text-slate-800 ml-auto"/>
                          <p className="text-[7px] font-black uppercase text-slate-400 mt-1 tracking-widest">EBD DIGITAL VALIDATION</p>
                       </div>
                    </div>
                 </div>
               ) : (
                 <div className="h-full flex flex-col items-center justify-center text-slate-300 gap-4">
                    <FileText size={64} />
                    <p className="text-xs font-black uppercase tracking-widest">Selecione um aluno e clique em Gerar</p>
                 </div>
               )}
             </div>
             <style>{`
                @media print {
                  @page { size: A4; margin: 0; }
                  body * { visibility: hidden; }
                  #print-area, #print-area * { visibility: visible; }
                  #print-area { position: absolute; left: 0; top: 0; width: 100%; margin: 0; padding: 20mm; box-shadow: none; }
                  .print\\:hidden { display: none !important; }
                }
             `}</style>
          </div>
        );
      case 'transferencia':
        return (
          <div className="bg-white border border-slate-300 shadow-xl rounded-2xl p-8 max-w-lg mx-auto space-y-6">
             <div className="flex justify-between items-center border-b pb-4">
                <h3 className="text-lg font-black uppercase text-slate-900 italic">Transferência de Curso</h3>
                <button onClick={() => setOpSubView('main')} className="text-slate-400 hover:text-rose-500"><X size={24}/></button>
             </div>
             <div className="space-y-4">
                <div>
                  <label className="text-[10px] font-bold text-slate-400 uppercase">Aluno</label>
                  <select value={selectedStudentForOp} onChange={e => setSelectedStudentForOp(e.target.value)} className="w-full p-3 border border-slate-300 rounded-xl text-xs font-bold uppercase mt-1">
                    <option value="">Selecione...</option>
                    {students.map(s => <option key={s.uid} value={s.uid}>{s.displayName}</option>)}
                  </select>
                </div>
                <div>
                  <label className="text-[10px] font-bold text-slate-400 uppercase">Novo Curso de Destino</label>
                  <select value={targetCourseId} onChange={e => setTargetCourseId(e.target.value)} className="w-full p-3 border border-slate-300 rounded-xl text-xs font-bold uppercase mt-1">
                    <option value="">Selecione...</option>
                    {courses.map(c => <option key={c.id} value={c.id}>{c.nome}</option>)}
                  </select>
                </div>
                <button onClick={handleTransfer} className="w-full py-4 bg-indigo-600 text-white rounded-xl text-[10px] font-black uppercase hover:bg-indigo-700 shadow-lg mt-4">Confirmar Transferência</button>
             </div>
          </div>
        );
      case 'ficha':
        return (
          <div className="bg-white border border-slate-300 shadow-xl rounded-2xl p-8 max-w-lg mx-auto space-y-6 text-center">
             <div className="flex justify-between items-center border-b pb-4">
                <h3 className="text-lg font-black uppercase text-slate-900 italic">Ficha Cadastral</h3>
                <button onClick={() => setOpSubView('main')} className="text-slate-400 hover:text-rose-500"><X size={24}/></button>
             </div>
             <p className="text-sm text-slate-500 italic">Selecione um aluno para visualizar a ficha completa (Redireciona para Prontuário).</p>
             <select onChange={e => { if(e.target.value) alert("Funcionalidade integrada na aba 'Alunos'. Por favor, acesse o menu 'Alunos' para ver a ficha completa."); }} className="w-full p-3 border border-slate-300 rounded-xl text-xs font-bold uppercase mt-1">
               <option value="">Selecione o Aluno...</option>
               {students.map(s => <option key={s.uid} value={s.uid}>{s.displayName}</option>)}
             </select>
          </div>
        );
      case 'assinatura':
        return (
          <div className="max-w-md mx-auto bg-white border border-slate-300 p-8 text-center space-y-6 rounded-2xl shadow-xl">
             <div className="w-16 h-16 bg-slate-100 rounded-full flex items-center justify-center mx-auto text-slate-400"><Fingerprint size={32}/></div>
             <h3 className="font-bold uppercase italic">Assinatura Digital do Secretário</h3>
             <div className="p-4 border-2 border-dashed border-slate-300 bg-slate-50 min-h-[120px] flex items-center justify-center rounded-xl">
                {secSignature ? <img src={secSignature} className="max-h-24 grayscale" /> : <p className="text-[10px] text-slate-300 uppercase font-bold">Nenhuma assinatura registrada</p>}
             </div>
             <button onClick={() => setIsSignModalOpen(true)} className="w-full py-3 bg-slate-900 text-white text-[10px] font-bold uppercase italic rounded-xl hover:bg-slate-800 transition-all">Coletar Nova Assinatura</button>
             <button onClick={() => setOpSubView('main')} className="text-[10px] text-slate-400 underline uppercase font-bold">Voltar</button>
          </div>
        );
      default:
        return (
          <div className="grid grid-cols-2 md:grid-cols-5 gap-4">
             <button onClick={() => setOpSubView('declaracao')} className="bg-white p-8 border border-slate-200 rounded-2xl flex flex-col items-center gap-4 hover:border-indigo-400 hover:shadow-xl transition-all group">
                <div className="text-slate-300 group-hover:text-indigo-600 transition-colors"><FileText size={32}/></div>
                <span className="text-[10px] font-black uppercase text-slate-700 tracking-wider">Declaração</span>
             </button>
             <button onClick={() => setOpSubView('validacao')} className="bg-white p-8 border border-slate-200 rounded-2xl flex flex-col items-center gap-4 hover:border-indigo-400 hover:shadow-xl transition-all group relative">
                <div className="text-slate-300 group-hover:text-indigo-600 transition-colors"><UserCheck size={32}/></div>
                <span className="text-[10px] font-black uppercase text-slate-700 tracking-wider">Validar Aluno</span>
                {stats.pendentesVal > 0 && <span className="absolute top-3 right-3 bg-red-600 text-white text-[9px] w-6 h-6 flex items-center justify-center font-black rounded-full shadow-lg border-2 border-white">{stats.pendentesVal}</span>}
             </button>
             <button onClick={() => setOpSubView('ficha')} className="bg-white p-8 border border-slate-200 rounded-2xl flex flex-col items-center gap-4 hover:border-indigo-400 hover:shadow-xl transition-all group">
                <div className="text-slate-300 group-hover:text-indigo-600 transition-colors"><FileSignature size={32}/></div>
                <span className="text-[10px] font-black uppercase text-slate-700 tracking-wider">Ficha Aluno</span>
             </button>
             <button onClick={() => setOpSubView('transferencia')} className="bg-white p-8 border border-slate-200 rounded-2xl flex flex-col items-center gap-4 hover:border-indigo-400 hover:shadow-xl transition-all group">
                <div className="text-slate-300 group-hover:text-indigo-600 transition-colors"><ArrowRightLeft size={32}/></div>
                <span className="text-[10px] font-black uppercase text-slate-700 tracking-wider">Transferências</span>
             </button>
             <button onClick={() => setOpSubView('assinatura')} className="bg-white p-8 border border-slate-200 rounded-2xl flex flex-col items-center gap-4 hover:border-indigo-400 hover:shadow-xl transition-all group">
                <div className="text-slate-300 group-hover:text-indigo-600 transition-colors"><Fingerprint size={32}/></div>
                <span className="text-[10px] font-black uppercase text-slate-700 tracking-wider">Assinatura Sec.</span>
             </button>
          </div>
        );
    }
  };

  return (
    <div className="space-y-6 animate-in fade-in h-full max-w-full overflow-hidden text-slate-900 pb-20">
      <header className="flex flex-col md:flex-row justify-between items-center bg-white p-6 rounded-[2rem] border border-slate-200 shadow-sm gap-4">
        <div className="flex items-center gap-4">
           <div className="p-3 bg-indigo-600 text-white rounded-2xl shadow-lg shadow-indigo-200"><MessageSquare size={24}/></div>
           <div>
             <h1 className="text-xl font-black uppercase italic tracking-tighter text-slate-900 leading-none">EBD EAD - Secretaria Virtual</h1>
             <p className="text-[9px] text-indigo-500 font-black uppercase tracking-[0.3em] mt-1">Central de Operações v3.0</p>
           </div>
        </div>
        <div className="flex bg-slate-100 p-1.5 rounded-xl border border-slate-200">
           {(['atendimento', 'chat', 'arquivos', 'operacional'] as any).map((t:any) => (
