import React, { useState, useEffect } from 'react';
import { collection, query, where, onSnapshot, doc, getDoc, updateDoc, serverTimestamp, orderBy, addDoc } from "https://www.gstatic.com/firebasejs/10.7.1/firebase-firestore.js";
import { auth, db } from '../firebase';
import { Course, User, Module, Lesson } from '../types';
import { BookOpen, PlayCircle, Award, ArrowLeft, GraduationCap, Zap, Bell, Menu, X, LogOut, Home, LifeBuoy, ScrollText, Smartphone, ShieldAlert, Star, Play, Settings, FileText, CheckCircle2, PenTool, Lock } from 'lucide-react';
import SignaturePad from '../components/SignaturePad';

interface StudentViewProps { user: User; }
type StudentSubView = 'dashboard' | 'classroom' | 'library' | 'certificates' | 'support';

const StudentView: React.FC<StudentViewProps> = ({ user }) => {
  const [activeSubView, setActiveSubView] = useState<StudentSubView>('dashboard');
  const [enrolledCourse, setEnrolledCourse] = useState<Course | null>(null);
  const [modules, setModules] = useState<Module[]>([]);
  const [activeLesson, setActiveLesson] = useState<Lesson | null>(null);
  const [loading, setLoading] = useState(true);
  const [isSidebarOpen, setIsSidebarOpen] = useState(true);

  // Contract States
  const [showContractModal, setShowContractModal] = useState(false);
  const [isSigning, setIsSigning] = useState(false);
  const [termsAccepted, setTermsAccepted] = useState(false);
  const [contractSignature, setContractSignature] = useState<string | null>(null);
  const [isSignPadOpen, setIsSignPadOpen] = useState(false);

  useEffect(() => {
    const fetchProfile = async () => {
      setLoading(true);
      try {
        const userDoc = await getDoc(doc(db, 'users', user.uid));
        if (userDoc.exists()) {
          const userData = userDoc.data();

          // Verificação de Contrato
          if (!userData.contractSigned) {
            setShowContractModal(true);
          }

          // Auditoria: Alunos administrativos usam 'cursoInicial', captados podem usar similar.
          const cId = userData.cursoInicial || userData.cursoId;

          if (cId) {
            const courseDoc = await getDoc(doc(db, 'cursos', cId));
            if (courseDoc.exists()) {
              setEnrolledCourse({ id: courseDoc.id, ...courseDoc.data() } as Course);
            }
          }
        }
      } catch (error) {
        console.error("Erro na auditoria de acesso do aluno:", error);
      }
      setLoading(false);
    };
    fetchProfile();
  }, [user.uid]);

  const handleStartLesson = () => {
    if (!enrolledCourse) return;
    onSnapshot(query(collection(db, 'modulos'), where('courseId', '==', enrolledCourse.id)), snap => {
      const mods = snap.docs.map(d => ({ id: d.id, ...d.data() } as Module)).sort((a,b) => (a.order||0)-(b.order||0));
      setModules(mods);
      if (mods.length > 0 && mods[0].lessons?.length > 0) setActiveLesson(mods[0].lessons[0]);
      setActiveSubView('classroom');
    });
  };

  const handleFinishContract = async () => {
    if (!termsAccepted || !contractSignature) return;
    setIsSigning(true);
    try {
      // 1. Atualizar perfil do usuário
      await updateDoc(doc(db, 'users', user.uid), {
        contractSigned: true,
        contractSignedAt: serverTimestamp(),
        signatureUrl: contractSignature
      });

      // 2. Gerar registro de arquivo na Secretaria (Simulação de PDF)
