import React, { useState, useEffect, useRef } from 'react';
import { signInWithEmailAndPassword, createUserWithEmailAndPassword, signOut } from "https://www.gstatic.com/firebasejs/10.7.1/firebase-auth.js";
import { collection, query, where, onSnapshot, doc, setDoc, getDoc, serverTimestamp, getDocs, addDoc, orderBy, updateDoc } from "https://www.gstatic.com/firebasejs/10.7.1/firebase-firestore.js";
import { auth, db } from '../firebase';
import { Lock, GraduationCap, ArrowRight, BookOpen, Star, Camera, MapPin, Key, ChevronLeft, Info, ImageIcon, Users, Zap, ShieldCheck, MessageCircle, Play, Flame, RefreshCw, CheckCircle2, Quote, Activity, Award, LogIn, X, Send, Phone, Clock, AlertTriangle, ThumbsUp, ThumbsDown, MessageSquare } from 'lucide-react';

type ViewMode = 'landing' | 'login' | 'enroll_form' | 'success_notice' | 'password_recovery' | 'evaluation';

const LoginView: React.FC = () => {
  const [viewMode, setViewMode] = useState<ViewMode>('landing');
  const [email, setEmail] = useState('');
  const [password, setPassword] = useState('');
  const [error, setError] = useState('');
  const [loading, setLoading] = useState(false);
  const [isAdminMode, setIsAdminMode] = useState(false);

  // Chat Recovery States
  const [recoveryName, setRecoveryName] = useState('');
  const [recoveryEmail, setRecoveryEmail] = useState('');
  const [activeProtocol, setActiveProtocol] = useState<string | null>(null);
  const [ticketId, setTicketId] = useState<string | null>(null);
  const [chatMessage, setChatMessage] = useState('');
  const [messages, setMessages] = useState<any[]>([]);
  const [recoveryTimer, setRecoveryTimer] = useState(300); // 5 minutes
  const [showWhatsAppRedirect, setShowWhatsAppRedirect] = useState(false);
  const chatEndRef = useRef<HTMLDivElement>(null);

  // Evaluation States
  const [rating, setRating] = useState(0);
  const [solved, setSolved] = useState<boolean | null>(null);
  const [waitEvaluation, setWaitEvaluation] = useState('');

  const [courses, setCourses] = useState<any[]>([]);
  const [selectedCourse, setSelectedCourse] = useState<any>(null);
  const [generatedEmail, setGeneratedEmail] = useState('');
  const [realStats, setRealStats] = useState({ students: 0, classes: 0, rating: '0.0' });
  const [realFeedbacks, setRealFeedbacks] = useState<any[]>([]);

  const [enrollForm, setEnrollForm] = useState({
    nome: '', emailPessoal: '', password: '', cpf: '', nascimento: '', telefone: '', fotoUrl: '',
    endereco: { cep: '', rua: '', numero: '', bairro: '', cidade: '', uf: '' }
  });

  const fileInputRef = useRef<HTMLInputElement>(null);

  useEffect(() => {
    const unsubC = onSnapshot(query(collection(db, 'cursos'), where('status', '==', 'ativo')), (snap) => {
      setCourses(snap.docs.map(d => ({ id: d.id, ...d.data() })));
    });
    const unsubS = onSnapshot(query(collection(db, 'users'), where('role', '==', 'aluno')), (snap) => {
      setRealStats(prev => ({ ...prev, students: snap.size }));
    });
    const unsubF = onSnapshot(collection(db, 'feedbacks'), (snap) => {
      const data = snap.docs.map(d => d.data());
      setRealFeedbacks(data.slice(0, 3));
      if (data.length > 0) {
        const avg = data.reduce((acc, curr) => acc + (curr.rating || 0), 0) / data.length;
        setRealStats(prev => ({ ...prev, rating: avg.toFixed(1) }));
      }
    });
    return () => { unsubC(); unsubS(); unsubF(); };
  }, []);

  useEffect(() => {
    if (!ticketId) return;
    const unsub = onSnapshot(query(collection(db, `tickets/${ticketId}/messages`), orderBy('timestamp', 'asc')), (snap) => {
      const msgs = snap.docs.map(d => d.data());
      setMessages(msgs);

      const hasStaffResponded = msgs.some(m => m.sender === 'Secretaria');
      if (hasStaffResponded) {
        setShowWhatsAppRedirect(false);
      }

      setTimeout(() => chatEndRef.current?.scrollIntoView({ behavior: 'smooth' }), 100);
    });
    return () => unsub();
  }, [ticketId]);

  // Support Timer Logic (5 Minutes)
  useEffect(() => {
    let timer: any;
    if (activeProtocol && recoveryTimer > 0 && !showWhatsAppRedirect && viewMode === 'password_recovery') {
      timer = setInterval(() => {
        setRecoveryTimer(prev => {
          if (prev <= 1) {
            clearInterval(timer);
            handleTimeout();
            return 0;
          }
          return prev - 1;
        });
      }, 1000);
    }
    return () => clearInterval(timer);
  }, [activeProtocol, recoveryTimer, showWhatsAppRedirect, messages, viewMode]);

  const handleTimeout = async () => {
    const hasResponse = messages.some(m => m.sender === 'Secretaria');
    if (!hasResponse && ticketId) {
      setShowWhatsAppRedirect(true);
      // Auto-archive in Firestore with Tag
      await updateDoc(doc(db, 'tickets', ticketId), {
        status: 'Finalizado',
        archivedReason: 'expirado',
        lastUpdate: serverTimestamp(),
        lastMessage: 'Atendimento encerrado por tempo limite de espera.'
      });
    }
  };

  const formatTimer = (seconds: number) => {
    const m = Math.floor(seconds / 60);
    const s = seconds % 60;
    return `${m}:${s.toString().padStart(2, '0')}`;
  };

  const handleLogin = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!email || !password) {
      setError('Preencha todos os campos.');
      return;
    }
    setLoading(true);
    setError('');
    const emailLower = email.trim().toLowerCase();

    try {
      const userCredential = await signInWithEmailAndPassword(auth, emailLower, password);
      const userDoc = await getDoc(doc(db, 'users', userCredential.user.uid));

      if (userDoc.exists()) {
        const userData = userDoc.data();
        if (isAdminMode && userData.role === 'aluno') {
          await signOut(auth);
          setError('Acesso administrativo negado.');
          setLoading(false);
          return;
        }
      }
    } catch (err: any) {
      setError('E-mail ou senha incorretos.');
      setLoading(false);
    }
  };

