                   <div className="flex items-center gap-4">
                      <div className="p-2 bg-indigo-600 rounded-xl"><MessageCircle size={20}/></div>
                      <div>
                        <h3 className="text-sm font-black uppercase italic tracking-tighter">Atendimento EB-EAD</h3>
