                             <span className="text-[7px] font-bold text-slate-400 uppercase mt-1.5 px-1">{m.sender} • {m.timestamp?.seconds ? new Date(m.timestamp.seconds * 1000).toLocaleTimeString([], {hour: '2-digit', minute:'2-digit'}) : '...'}</span>
                          </div>
                        ))}
                        <div ref={chatEndRef} />
                     </>
                   )}
                </div>

                {!showWhatsAppRedirect && (
                  <div className="p-6 border-t border-slate-100 bg-white flex gap-3">
                    <input value={chatMessage} onChange={e => setChatMessage(e.target.value)} onKeyDown={e => e.key === 'Enter' && sendChatMessage()} placeholder="Digite sua mensagem..." className="flex-1 bg-slate-50 border-none rounded-xl px-6 py-4 text-xs font-bold shadow-inner outline-none focus:ring-1 focus:ring-indigo-600 text-slate-900" />
                    <button onClick={sendChatMessage} className="p-4 bg-slate-900 text-white rounded-xl shadow-xl hover:bg-indigo-600 transition-all"><Send size={18}/></button>
                  </div>
                )}
             </div>
           )}
        </div>
      </div>
    );
  }

  // Login View Wrapper (Simplified for space, assume same styles as provided previously)
  return (
    <div className="min-h-screen bg-slate-950 flex items-center justify-center p-6 relative">
       <div className="absolute inset-0 z-0 opacity-20"><img src="https://images.unsplash.com/photo-1501290830387-99bc439ca623?auto=format&fit=crop&w=1920&q=80" className="w-full h-full object-cover" /></div>
       <div className="relative z-10 w-full max-w-5xl bg-white rounded-[4rem] shadow-2xl overflow-hidden animate-in zoom-in-95 flex flex-col lg:flex-row">
          <div className="lg:w-1/2 p-12 space-y-12">
             <button onClick={() => setViewMode('landing')} className="flex items-center gap-2 text-[10px] font-black uppercase text-slate-400 hover:text-indigo-600"><ChevronLeft size={16}/> Início</button>
             <div><h2 className="text-4xl font-black uppercase italic tracking-tighter">Login <span className="text-indigo-600">Alunos</span></h2></div>
             {error && <div className="p-4 bg-rose-50 text-rose-600 text-[10px] font-black uppercase rounded-2xl border border-rose-100">{error}</div>}
             <form onSubmit={handleLogin} className="space-y-6">
                <input type="email" required value={email} onChange={e => setEmail(e.target.value)} placeholder="E-mail Acadêmico" className="w-full p-5 bg-slate-50 border-none rounded-3xl text-sm font-bold shadow-inner outline-none focus:ring-1 focus:ring-indigo-600" />
                <input type="password" required value={password} onChange={e => setPassword(e.target.value)} placeholder="Senha Secreta" className="w-full p-5 bg-slate-50 border-none rounded-3xl text-sm font-bold shadow-inner outline-none focus:ring-1 focus:ring-indigo-600" />
                <button type="submit" disabled={loading} className="w-full py-6 bg-slate-950 text-white rounded-[2.5rem] text-[10px] font-black uppercase tracking-[0.3em] italic hover:bg-indigo-600 shadow-2xl transition-all">
                  {loading ? <RefreshCw className="animate-spin mx-auto" size={20}/> : 'Entrar na Sala'}
                </button>
                <button onClick={() => setViewMode('password_recovery')} type="button" className="w-full text-[9px] font-black uppercase text-slate-400 hover:text-indigo-600 transition-all italic text-center">Esqueci minha senha / Problemas de acesso</button>
             </form>
          </div>
          <div className="lg:w-1/2 bg-slate-50 p-12 flex flex-col justify-center gap-10 border-l border-slate-100">
             <div className="space-y-4">
                <h3 className="text-2xl font-black uppercase italic tracking-tighter">Novo por aqui?</h3>
                <p className="text-sm text-slate-500 font-medium italic">Matricule-se em um de nossos cursos superiores e inicie sua jornada teológica master agora mesmo.</p>
             </div>
             <button onClick={() => setViewMode('enroll_form')} className="w-full py-6 bg-white border border-slate-200 text-slate-900 rounded-[2.5rem] text-[10px] font-black uppercase italic tracking-widest hover:border-indigo-600 transition-all">Quero me Matricular</button>
          </div>
       </div>
    </div>
  );
};

export default LoginView;

import React, { useState, useEffect, useMemo, useRef } from 'react';
import { 
  collection, query, onSnapshot, addDoc, updateDoc, 
  doc, serverTimestamp, orderBy, where, deleteDoc, getDoc, getDocs
} from "https://www.gstatic.com/firebasejs/10.7.1/firebase-firestore.js";
import { db, auth } from '../firebase';
import { User } from '../types';
import { 
  Ticket as TicketIcon, AlertCircle, Clock, MessageSquare, Search, Plus, X, FolderOpen, FileText, Download, UserCheck, ShieldAlert, FileSignature, Save, PenTool, UserX, Check, ArrowRightLeft, Fingerprint, Star, Send, Folder, Archive, CheckCircle2, ChevronRight, FileDown, Phone, Printer, MoreVertical, RotateCcw, Trash2, QrCode, ShieldCheck, AlertTriangle
} from 'lucide-react';
import SignaturePad from '../components/SignaturePad';

interface SecretariatViewProps { user: User; }
type SecretariatTab = 'atendimento' | 'chat' | 'arquivos' | 'operacional';
type OperationalSubView = 'main' | 'declaracao' | 'validacao' | 'transferencia' | 'assinatura' | 'ficha';
type ChatFilter = 'abertos' | 'finalizados' | 'arquivados';

const SecretariatView: React.FC<SecretariatViewProps> = ({ user }) => {
  const [activeTab, setActiveTab] = useState<SecretariatTab>('atendimento');
  const [opSubView, setOpSubView] = useState<OperationalSubView>('main');
  const [chatFilter, setChatFilter] = useState<ChatFilter>('abertos');
  const [tickets, setTickets] = useState<any[]>([]);
  const [files, setFiles] = useState<any[]>([]);
  const [students, setStudents] = useState<any[]>([]);
  const [courses, setCourses] = useState<any[]>([]);
  const [searchTerm, setSearchTerm] = useState('');
  const [selectedTicketId, setSelectedTicketId] = useState<string | null>(null);
  const [chatHistory, setChatHistory] = useState<any[]>([]);
  const [chatMessage, setChatMessage] = useState('');
  const [isSignModalOpen, setIsSignModalOpen] = useState(false);
  const [secSignature, setSecSignature] = useState<string | null>(null);

  const [directorSignature, setDirectorSignature] = useState<string | null>(null);
  const [secretarySignature, setSecretarySignature] = useState<string | null>(null);

  const [isNewProtocolOpen, setIsNewProtocolOpen] = useState(false);
  const [newProtocolForm, setNewProtocolForm] = useState({ name: '', channel: 'Balcão', notes: '' });

  const [selectedStudentForOp, setSelectedStudentForOp] = useState<string>('');
  const [targetCourseId, setTargetCourseId] = useState<string>('');
  const [declarationData, setDeclarationData] = useState<any | null>(null);

  const [currentPath, setCurrentPath] = useState<string[]>([]);
  const chatEndRef = useRef<HTMLDivElement>(null);

  useEffect(() => {
    const unsubT = onSnapshot(query(collection(db, 'tickets'), orderBy('createdAt', 'desc')), s => setTickets(s.docs.map(d => ({ id: d.id, ...d.data() }))));
    const unsubF = onSnapshot(collection(db, 'secretaria_arquivos'), s => setFiles(s.docs.map(d => ({ id: d.id, ...d.data() }))));
    const unsubS = onSnapshot(query(collection(db, 'users'), where('role', '==', 'aluno')), s => setStudents(s.docs.map(d => ({ uid: d.id, ...d.data() }))));
    const unsubC = onSnapshot(collection(db, 'cursos'), s => setCourses(s.docs.map(d => ({ id: d.id, ...d.data() }))));
    getDoc(doc(db, 'users', user.uid)).then(d => d.exists() && setSecSignature(d.data().signatureUrl));

    const fetchSignatures = async () => {
        const qDir = query(collection(db, 'users'), where('role', '==', 'diretor'));
        const qSec = query(collection(db, 'users'), where('role', '==', 'secretaria'));
        const [snapDir, snapSec] = await Promise.all([getDocs(qDir), getDocs(qSec)]);
        if (!snapDir.empty) setDirectorSignature(snapDir.docs[0].data().signatureUrl);
        if (!snapSec.empty) setSecretarySignature(snapSec.docs[0].data().signatureUrl);
    };
    fetchSignatures();
    return () => { unsubT(); unsubF(); unsubS(); unsubC(); };
  }, [user.uid]);

  useEffect(() => {
    if (!selectedTicketId) return;
    const unsubChat = onSnapshot(query(collection(db, `tickets/${selectedTicketId}/messages`), orderBy('timestamp', 'asc')), (snap) => {
      setChatHistory(snap.docs.map(d => d.data()));
      setTimeout(() => chatEndRef.current?.scrollIntoView({ behavior: 'smooth' }), 100);
    });
    return () => unsubChat();
  }, [selectedTicketId]);

  const stats = useMemo(() => {
    const pendingVal = students.filter(s => s.status === 'aguardando_validacao' || s.status === 'pendente').length;
    return {
      abertos: tickets.filter(t => t.status === 'Pendente').length,
      finalizados: tickets.filter(t => t.status === 'Finalizado').length,
      arquivados: tickets.filter(t => t.status === 'Arquivado').length,
      pendentesVal: pendingVal,
      totalGed: files.length
    };
  }, [tickets, students, files]);

  const handleSendMessage = async () => {
    if (!selectedTicketId || !chatMessage.trim()) return;
    const msg = { text: chatMessage, sender: 'Secretaria', timestamp: serverTimestamp() };
    await addDoc(collection(db, `tickets/${selectedTicketId}/messages`), msg);
    await updateDoc(doc(db, 'tickets', selectedTicketId), { lastMessage: chatMessage, lastUpdate: serverTimestamp() });
    setChatMessage('');
  };

  const handleCreateProtocol = async () => {
    if (!newProtocolForm.name) return;
    const protocol = 'PROT-' + Math.random().toString(36).substring(2, 9).toUpperCase();
    await addDoc(collection(db, 'tickets'), {
      protocolo: protocol,
      user: newProtocolForm.name,
      email: 'Atendimento Local',
      type: newProtocolForm.channel,
      status: 'Pendente',
      createdAt: serverTimestamp(),
      lastUpdate: serverTimestamp(),
      lastMessage: newProtocolForm.notes || 'Início de atendimento.'
    });
    setIsNewProtocolOpen(false);
    setNewProtocolForm({ name: '', channel: 'Balcão', notes: '' });
  };

  const filteredTickets = tickets.filter(t => {
    const matchSearch = t.protocolo?.toLowerCase().includes(searchTerm.toLowerCase()) || t.user?.toLowerCase().includes(searchTerm.toLowerCase());
    if (activeTab === 'atendimento') return matchSearch && t.status === 'Pendente';
    if (activeTab === 'chat') {
       if (chatFilter === 'abertos') return matchSearch && (t.status === 'Em Atendimento' || t.status === 'Pendente');
       if (chatFilter === 'finalizados') return matchSearch && t.status === 'Finalizado';
       if (chatFilter === 'arquivados') return matchSearch && t.status === 'Arquivado';
    }
    return matchSearch;
  });

  return (
    <div className="space-y-6 animate-in fade-in h-full max-w-full overflow-hidden text-slate-900 pb-20">
      <header className="flex flex-col md:flex-row justify-between items-center bg-white p-6 rounded-[2rem] border border-slate-200 shadow-sm gap-4">
        <div className="flex items-center gap-4">
           <div className="p-3 bg-indigo-600 text-white rounded-2xl shadow-lg shadow-indigo-200"><MessageSquare size={24}/></div>
           <div>
             <h1 className="text-xl font-black uppercase italic tracking-tighter text-slate-900 leading-none">EBD EAD - Secretaria Virtual</h1>
             <p className="text-[9px] text-indigo-500 font-black uppercase tracking-[0.3em] mt-1">Central de Operações v3.0</p>
           </div>
        </div>
        <div className="flex bg-slate-100 p-1.5 rounded-xl border border-slate-200">
           {(['atendimento', 'chat', 'arquivos', 'operacional'] as any).map((t:any) => (
             <button key={t} onClick={() => { setActiveTab(t); setSelectedTicketId(null); }} className={`px-6 py-2.5 rounded-lg text-[10px] font-black uppercase transition-all ${activeTab === t ? 'bg-white text-indigo-600 shadow-md' : 'text-slate-400 hover:text-slate-600'}`}>{t}</button>
           ))}
        </div>
      </header>

      <main className="flex-1 min-h-[600px] overflow-hidden">
         {activeTab === 'atendimento' && (
           <div className="bg-white rounded-[2rem] border border-slate-200 overflow-hidden h-full flex flex-col shadow-sm">
              <div className="p-6 border-b border-slate-100 flex justify-between items-center bg-slate-50/50">
                 <h3 className="font-black text-xs uppercase italic flex items-center gap-2 text-slate-700 tracking-widest">Fila de Protocolos</h3>
                 <div className="flex gap-4">
                    <div className="relative"><Search className="absolute left-3 top-1/2 -translate-y-1/2 text-slate-300" size={14}/><input value={searchTerm} onChange={e => setSearchTerm(e.target.value)} placeholder="Buscar Protocolo..." className="pl-9 pr-4 py-2.5 border border-slate-200 rounded-xl text-xs w-64 outline-none focus:border-indigo-500 font-bold bg-white shadow-sm" /></div>
                    <button onClick={() => setIsNewProtocolOpen(true)} className="bg-slate-900 text-white px-5 py-2.5 rounded-xl text-[9px] font-black uppercase hover:bg-indigo-600 transition-all shadow-lg flex items-center gap-2"><Plus size={14}/> Novo Atendimento</button>
                 </div>
              </div>
              <div className="flex-1 overflow-auto custom-scrollbar p-2">
                 <table className="w-full text-left border-collapse">
                    <thead className="bg-white text-[9px] font-black uppercase text-slate-400 tracking-widest border-b border-slate-100 sticky top-0 z-10">
                       <tr><th className="px-6 py-4">Protocolo</th><th className="px-6 py-4">Solicitante</th><th className="px-6 py-4">Canal</th><th className="px-6 py-4">Data</th><th className="px-6 py-4 text-center">Ação</th></tr>
                    </thead>
                    <tbody className="text-xs font-medium text-slate-600">
                       {filteredTickets.length === 0 ? <tr><td colSpan={5} className="p-20 text-center text-slate-300 uppercase italic font-bold">Nenhum ticket pendente.</td></tr> : filteredTickets.map(t => (
                         <tr key={t.id} className="border-b border-slate-50 hover:bg-indigo-50/30 transition-colors group">
                            <td className="px-6 py-4 font-mono font-black text-indigo-600">{t.protocolo}</td>
                            <td className="px-6 py-4 font-bold text-slate-900 uppercase">{t.user}</td>
                            <td className="px-6 py-4 flex items-center gap-2">
                               <span className="px-3 py-1 bg-slate-100 rounded-lg text-[9px] font-black uppercase text-slate-500">{t.type}</span>
                               {t.archivedReason === 'expirado' && <span className="flex items-center gap-1 px-3 py-1 bg-rose-50 text-rose-600 rounded-lg text-[8px] font-black uppercase border border-rose-100 animate-pulse"><AlertTriangle size={10}/> Expirado</span>}
                            </td>
                            <td className="px-6 py-4 text-[10px] text-slate-400 font-bold">{t.createdAt?.seconds ? new Date(t.createdAt.seconds*1000).toLocaleDateString() : 'Hoje'}</td>
                            <td className="px-6 py-4 text-center"><button onClick={async () => { await updateDoc(doc(db, 'tickets', t.id), {status: 'Em Atendimento'}); setSelectedTicketId(t.id); setActiveTab('chat'); setChatFilter('abertos'); }} className="px-4 py-2 bg-indigo-600 text-white font-black uppercase text-[8px] rounded-lg hover:bg-indigo-700 shadow-md">Atender</button></td>
                         </tr>
                       ))}
                    </tbody>
                 </table>
              </div>
           </div>
         )}
         {/* Remaining views like 'chat', 'arquivos', 'operacional' are assumed to follow the same structure */}
      </main>

      {/* MODAL NOVO PROTOCOLO */}
      {isNewProtocolOpen && (
        <div className="fixed inset-0 z-[3000] bg-slate-950/80 backdrop-blur-sm flex items-center justify-center p-4 animate-in zoom-in-95">
           <div className="bg-white w-full max-w-md rounded-[2.5rem] p-10 space-y-6 shadow-2xl">
              <div className="flex justify-between items-center">
                 <h3 className="text-xl font-black uppercase italic text-slate-900 tracking-tighter">Abrir Protocolo</h3>
                 <button onClick={() => setIsNewProtocolOpen(false)} className="p-2 bg-slate-100 rounded-full hover:bg-slate-200"><X size={20}/></button>
              </div>
              <div className="space-y-4">
                 <div className="space-y-1.5"><label className="text-[9px] font-black uppercase text-slate-400 ml-2">Nome do Solicitante</label><input value={newProtocolForm.name} onChange={e => setNewProtocolForm({...newProtocolForm, name: e.target.value})} className="w-full p-4 bg-slate-50 border-none rounded-2xl text-xs font-bold outline-none focus:ring-2 focus:ring-indigo-500" placeholder="Nome Completo..." /></div>
                 <div className="space-y-1.5"><label className="text-[9px] font-black uppercase text-slate-400 ml-2">Canal</label><select value={newProtocolForm.channel} onChange={e => setNewProtocolForm({...newProtocolForm, channel: e.target.value})} className="w-full p-4 bg-slate-50 border-none rounded-2xl text-xs font-bold outline-none cursor-pointer"><option value="Balcão">Balcão</option><option value="Telefone">Telefone</option><option value="WhatsApp">WhatsApp</option><option value="E-mail">E-mail</option></select></div>
                 <div className="space-y-1.5"><label className="text-[9px] font-black uppercase text-slate-400 ml-2">Descrição</label><textarea value={newProtocolForm.notes} onChange={e => setNewProtocolForm({...newProtocolForm, notes: e.target.value})} className="w-full p-4 bg-slate-50 border-none rounded-2xl text-xs font-medium outline-none h-24 resize-none" placeholder="Motivo..." /></div>
                 <button onClick={handleCreateProtocol} className="w-full py-4 bg-indigo-600 text-white rounded-2xl text-[10px] font-black uppercase shadow-xl hover:bg-indigo-700 transition-all">Gerar Ticket</button>
              </div>
           </div>
        </div>
      )}
    </div>
  );
};

export default SecretariatView;

import React, { useState, useEffect, useRef } from 'react';
import { signInWithEmailAndPassword, createUserWithEmailAndPassword, signOut } from "https://www.gstatic.com/firebasejs/10.7.1/firebase-auth.js";
import { collection, query, where, onSnapshot, doc, setDoc, getDoc, serverTimestamp, getDocs, addDoc, orderBy, updateDoc } from "https://www.gstatic.com/firebasejs/10.7.1/firebase-firestore.js";
import { auth, db } from '../firebase';
import { Lock, GraduationCap, ArrowRight, BookOpen, Star, Camera, MapPin, Key, ChevronLeft, Info, ImageIcon, Users, Zap, ShieldCheck, MessageCircle, Play, Flame, RefreshCw, CheckCircle2, Quote, Activity, Award, LogIn, X, Send, Phone, Clock, AlertTriangle, ThumbsUp, ThumbsDown, MessageSquare } from 'lucide-react';

type ViewMode = 'landing' | 'login' | 'enroll_form' | 'success_notice' | 'password_recovery' | 'evaluation';

const LoginView: React.FC = () => {
  const [viewMode, setViewMode] = useState<ViewMode>('landing');
  const [email, setEmail] = useState('');
  const [password, setPassword] = useState('');
  const [error, setError] = useState('');
  const [loading, setLoading] = useState(false);
  const [isAdminMode, setIsAdminMode] = useState(false);

  // Chat Recovery States
  const [recoveryName, setRecoveryName] = useState('');
  const [recoveryEmail, setRecoveryEmail] = useState('');
  const [activeProtocol, setActiveProtocol] = useState<string | null>(null);
  const [ticketId, setTicketId] = useState<string | null>(null);
  const [chatMessage, setChatMessage] = useState('');
  const [messages, setMessages] = useState<any[]>([]);
  const [recoveryTimer, setRecoveryTimer] = useState(300); // 5 minutes (300s)
  const [showWhatsAppRedirect, setShowWhatsAppRedirect] = useState(false);
  const chatEndRef = useRef<HTMLDivElement>(null);

  // Evaluation States
  const [rating, setRating] = useState(0);
  const [solved, setSolved] = useState<boolean | null>(null);
  const [waitEvaluation, setWaitEvaluation] = useState('');

  const [courses, setCourses] = useState<any[]>([]);
  const [selectedCourse, setSelectedCourse] = useState<any>(null);
  const [realStats, setRealStats] = useState({ students: 0, classes: 0, rating: '0.0' });
  const [realFeedbacks, setRealFeedbacks] = useState<any[]>([]);

  useEffect(() => {
    const unsubC = onSnapshot(query(collection(db, 'cursos'), where('status', '==', 'ativo')), (snap) => {
      setCourses(snap.docs.map(d => ({ id: d.id, ...d.data() })));
    });
    const unsubS = onSnapshot(query(collection(db, 'users'), where('role', '==', 'aluno')), (snap) => {
      setRealStats(prev => ({ ...prev, students: snap.size }));
    });
    const unsubF = onSnapshot(collection(db, 'feedbacks'), (snap) => {
      const data = snap.docs.map(d => d.data());
      setRealFeedbacks(data.slice(0, 3));
      if (data.length > 0) {
        const avg = data.reduce((acc, curr) => acc + (curr.rating || 0), 0) / data.length;
        setRealStats(prev => ({ ...prev, rating: avg.toFixed(1) }));
      }
    });
    return () => { unsubC(); unsubS(); unsubF(); };
  }, []);

  useEffect(() => {
    if (!ticketId) return;
    const unsub = onSnapshot(query(collection(db, `tickets/${ticketId}/messages`), orderBy('timestamp', 'asc')), (snap) => {
      const msgs = snap.docs.map(d => d.data());
      setMessages(msgs);

      const hasStaffResponded = msgs.some(m => m.sender === 'Secretaria');
      if (hasStaffResponded) {
        setShowWhatsAppRedirect(false);
      }

      setTimeout(() => chatEndRef.current?.scrollIntoView({ behavior: 'smooth' }), 100);
    });
    return () => unsub();
  }, [ticketId]);

  // Support Timer Logic (5 Minutes)
  useEffect(() => {
    let timer: any;
    if (activeProtocol && recoveryTimer > 0 && !showWhatsAppRedirect && viewMode === 'password_recovery') {
      timer = setInterval(() => {
        setRecoveryTimer(prev => {
          if (prev <= 1) {
            clearInterval(timer);
            handleTimeout();
            return 0;
          }
          return prev - 1;
        });
      }, 1000);
    }
    return () => clearInterval(timer);
  }, [activeProtocol, recoveryTimer, showWhatsAppRedirect, messages, viewMode]);

  const handleTimeout = async () => {
    const hasResponse = messages.some(m => m.sender === 'Secretaria');
    if (!hasResponse && ticketId) {
      setShowWhatsAppRedirect(true);
      // Auto-archive in Firestore with Tag
      await updateDoc(doc(db, 'tickets', ticketId), {
        status: 'Finalizado',
        archivedReason: 'expirado',
        lastUpdate: serverTimestamp(),
        lastMessage: 'Atendimento encerrado por tempo limite de espera.'
      });
    }
  };

  const formatTimer = (seconds: number) => {
    const m = Math.floor(seconds / 60);
    const s = seconds % 60;
    return `${m}:${s.toString().padStart(2, '0')}`;
  };

  const handleLogin = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!email || !password) {
      setError('Preencha todos os campos.');
      return;
    }
    setLoading(true);
    setError('');
    try {
      const userCredential = await signInWithEmailAndPassword(auth, email.trim().toLowerCase(), password);
      const userDoc = await getDoc(doc(db, 'users', userCredential.user.uid));
      if (userDoc.exists()) {
        const userData = userDoc.data();
        if (isAdminMode && userData.role === 'aluno') {
          await signOut(auth);
          setError('Acesso administrativo negado.');
          setLoading(false);
          return;
        }
      }
    } catch (err: any) {
      setError('E-mail ou senha incorretos.');
      setLoading(false);
    }
  };

  const startRecoveryTicket = async (e: React.FormEvent) => {
    e.preventDefault();
    setLoading(true);
    const protocol = 'SUP-' + Math.random().toString(36).substring(2, 9).toUpperCase();
    const payload = {
      protocolo: protocol,
      user: recoveryName,
      email: recoveryEmail,
      type: 'Suporte Matrícula',
      status: 'Pendente',
      createdAt: serverTimestamp(),
      lastUpdate: serverTimestamp(),
      lastMessage: 'Chat iniciado pelo aluno.'
    };
    const docRef = await addDoc(collection(db, 'tickets'), payload);
    setTicketId(docRef.id);
    setActiveProtocol(protocol);
    setLoading(false);
  };

  const sendChatMessage = async () => {
    if (!chatMessage.trim() || !ticketId) return;
    await addDoc(collection(db, `tickets/${ticketId}/messages`), {
      text: chatMessage,
      sender: 'Aluno',
      timestamp: serverTimestamp()
    });
    setChatMessage('');
  };

  const submitEvaluation = async () => {
    if (rating === 0) return;
    setLoading(true);
    try {
      await addDoc(collection(db, 'support_evaluations'), {
        ticketId,
        protocol: activeProtocol,
        studentName: recoveryName,
        rating,
        solved,
        waitEvaluation,
        timestamp: serverTimestamp()
      });
      setViewMode('landing');
      alert("Avaliação registrada. Obrigado por nos ajudar a melhorar!");
      setTicketId(null);
      setActiveProtocol(null);
      setRecoveryTimer(300);
      setRating(0);
      setSolved(null);
    } catch (e) {
      console.error(e);
    } finally {
      setLoading(false);
    }
  };

  if (viewMode === 'landing') {
    return (
      <div className="min-h-screen bg-white text-slate-900 overflow-x-hidden font-sans">
        <header className="fixed top-0 left-0 right-0 z-[100] bg-white/80 backdrop-blur-md border-b border-slate-100">
          <div className="max-w-7xl mx-auto px-6 h-20 flex items-center justify-between">
            <div className="flex items-center gap-3">
              <div className="bg-indigo-600 text-white p-2 rounded-xl shadow-lg shadow-indigo-100"><GraduationCap size={24}/></div>
              <span className="text-xl font-black uppercase italic tracking-tighter">EB-EAD</span>
            </div>
            <div className="flex items-center gap-6">
              <button onClick={() => setViewMode('login')} className="text-[10px] font-black uppercase tracking-widest text-slate-500 hover:text-indigo-600 transition-all">Acesso Aluno</button>
              <button onClick={() => setViewMode('enroll_form')} className="px-6 py-3 bg-indigo-600 text-white rounded-xl text-[10px] font-black uppercase tracking-widest shadow-xl hover:bg-slate-900 transition-all">Matrícula Digital</button>
            </div>
          </div>
        </header>

        <section className="pt-48 pb-24 px-6 relative overflow-hidden">
          <div className="max-w-7xl mx-auto grid lg:grid-cols-2 gap-20 items-center">
            <div className="space-y-12 animate-in slide-in-from-left duration-700">
              <div className="inline-flex items-center gap-3 px-5 py-2.5 bg-indigo-50 text-indigo-600 rounded-full text-[10px] font-black uppercase tracking-widest border border-indigo-100 italic">
                <Flame size={14} fill="currentColor"/> Educação Teológica Superior
              </div>
              <h1 className="text-7xl md:text-9xl font-black tracking-tighter uppercase italic leading-[0.8] text-slate-950">
                Sua Jornada <br/> <span className="text-indigo-600">Bíblica</span> Começa.
              </h1>
              <p className="text-xl text-slate-500 font-medium italic leading-relaxed max-w-xl">
                Plataforma de ensino master com certificação reconhecida, suporte em tempo real e material didático de alta performance.
              </p>
              <div className="flex flex-col sm:flex-row gap-5">
                <button onClick={() => setViewMode('enroll_form')} className="px-12 py-6 bg-slate-950 text-white rounded-2xl text-[11px] font-black uppercase tracking-[0.3em] italic shadow-2xl hover:bg-indigo-600 transition-all active:scale-95">Ver Catálogo</button>
                <button onClick={() => setViewMode('password_recovery')} className="px-12 py-6 bg-white border border-slate-200 text-slate-900 rounded-2xl text-[11px] font-black uppercase tracking-[0.3em] italic hover:bg-slate-50 transition-all">Suporte Matrícula</button>
