            <div className="relative animate-in zoom-in duration-1000">
              <div className="aspect-square bg-slate-100 rounded-[5rem] overflow-hidden shadow-[0_50px_100px_rgba(0,0,0,0.1)] relative border-8 border-white">
                <img src="https://images.unsplash.com/photo-1501290830387-99bc439ca623?auto=format&fit=crop&w=1200&q=80" className="w-full h-full object-cover grayscale hover:grayscale-0 transition-all duration-1000" />
                <div className="absolute inset-0 bg-indigo-600/5 mix-blend-multiply"></div>
              </div>
              <div className="absolute -bottom-10 -left-10 bg-white p-10 rounded-[3rem] shadow-2xl border border-slate-100 animate-bounce-slow">
                <p className="text-5xl font-black text-indigo-600 tabular-nums">+{realStats.students}</p>
                <p className="text-[10px] font-black uppercase tracking-widest text-slate-400 mt-2">Alunos Ativos</p>
              </div>
            </div>
          </div>
        </section>

        <section className="py-32 bg-slate-50 border-y border-slate-100">
          <div className="max-w-7xl mx-auto px-6 space-y-24">
            <div className="flex flex-col md:flex-row justify-between items-end gap-6">
              <h2 className="text-5xl font-black uppercase italic tracking-tighter leading-none">Disciplinas <br/><span className="text-indigo-600">Disponíveis</span></h2>
              <button className="text-[10px] font-black uppercase tracking-[0.3em] text-slate-400 hover:text-indigo-600 transition-colors">Visualizar Matriz Completa</button>
            </div>
            <div className="grid md:grid-cols-3 gap-10">
              {courses.slice(0, 3).map(c => (
                <div key={c.id} className="bg-white rounded-[3.5rem] p-5 border border-slate-200 group hover:shadow-2xl transition-all duration-500 flex flex-col h-full">
                  <div className="aspect-video rounded-[2.5rem] overflow-hidden mb-8 relative shadow-lg">
                    <img src={c.capaUrl} className="w-full h-full object-cover group-hover:scale-110 transition-transform duration-1000" />
                    <div className="absolute top-4 left-4 bg-white/90 backdrop-blur-md px-4 py-1.5 rounded-full text-[8px] font-black uppercase tracking-widest text-indigo-600 italic">{c.categoria}</div>
                  </div>
                  <div className="px-4 pb-8 flex-1 flex flex-col justify-between">
                    <div>
                      <h3 className="text-2xl font-black uppercase italic tracking-tighter leading-tight mb-4 group-hover:text-indigo-600 transition-colors">{c.nome}</h3>
                      <p className="text-xs text-slate-500 font-medium italic leading-relaxed line-clamp-3">{c.descricao || 'Excelência e profundidade teológica.'}</p>
                    </div>
                    <button onClick={() => { setSelectedCourse(c); setViewMode('enroll_form'); }} className="w-full mt-10 py-5 bg-slate-950 text-white rounded-2xl text-[10px] font-black uppercase tracking-[0.2em] italic hover:bg-indigo-600 transition-all">Iniciar Matrícula</button>
                  </div>
                </div>
              ))}
            </div>
          </div>
        </section>
      </div>
    );
  }

  if (viewMode === 'evaluation') {
    return (
      <div className="min-h-screen bg-slate-950 flex items-center justify-center p-6 font-sans">
        <div className="w-full max-w-xl bg-white rounded-[4rem] p-16 shadow-2xl text-center space-y-12 animate-in zoom-in-95 duration-500">
          <div className="p-5 bg-indigo-50 text-indigo-600 rounded-[2.5rem] w-fit mx-auto border border-indigo-100 shadow-inner"><Star size={48} className="animate-pulse"/></div>
          <div className="space-y-4">
            <h2 className="text-4xl font-black uppercase italic tracking-tighter leading-none text-slate-900">Como foi seu suporte?</h2>
            <p className="text-xs text-slate-400 font-medium italic uppercase tracking-widest">Sua opinião ajuda a secretaria a evoluir.</p>
          </div>

          <div className="space-y-10">
            <div className="space-y-6">
              <p className="text-[10px] font-black uppercase tracking-[0.3em] text-slate-500 italic">Avaliação do Atendimento</p>
              <div className="flex justify-center gap-4">
                {[1, 2, 3, 4, 5].map(s => (
                  <button key={s} onClick={() => setRating(s)} className={`w-14 h-14 rounded-2xl flex items-center justify-center transition-all shadow-xl active:scale-90 ${rating >= s ? 'bg-indigo-600 text-white' : 'bg-slate-50 text-slate-300 border border-slate-100'}`}>
                    <Star size={28} fill={rating >= s ? 'currentColor' : 'none'}/>
                  </button>
                ))}
              </div>
