                <option value="">Selecione...</option>
                <option value="imediato">Atendimento Imediato</option>
                <option value="aceitavel">Tempo Aceitável</option>
                <option value="demorado">Muito Demorado</option>
              </select>
            </div>

            <button onClick={submitEvaluation} disabled={rating === 0 || loading} className="w-full py-6 bg-slate-900 text-white rounded-[2rem] text-[11px] font-black uppercase tracking-[0.4em] italic hover:bg-indigo-600 shadow-2xl transition-all disabled:opacity-50">
              {loading ? <RefreshCw className="animate-spin mx-auto" size={20}/> : 'Finalizar Feedback Master'}
            </button>
          </div>
        </div>
      </div>
    );
  }

  if (viewMode === 'password_recovery') {
    return (
      <div className="min-h-screen bg-slate-950 flex items-center justify-center p-6 relative font-sans overflow-hidden">
        <div className="absolute inset-0 z-0 opacity-10 blur-sm scale-110">
          <img src="https://images.unsplash.com/photo-1454165833767-027ffea9e61b?auto=format&fit=crop&w=1920&q=80" className="w-full h-full object-cover" />
        </div>
        <div className="relative z-10 w-full max-w-4xl bg-white rounded-[4rem] shadow-2xl overflow-hidden flex flex-col md:flex-row h-[700px] animate-in zoom-in-95 duration-500">
