                <form onSubmit={startRecoveryTicket} className="space-y-6">
                   <div className="space-y-2"><label className="text-[9px] font-black uppercase text-slate-400 ml-5 italic tracking-widest">Nome Completo</label><input required value={recoveryName} onChange={e => setRecoveryName(e.target.value)} className="w-full p-5 bg-slate-50 border-none rounded-3xl text-sm font-bold outline-none focus:ring-2 focus:ring-indigo-600 shadow-inner" placeholder="Seu nome..." /></div>
                   <div className="space-y-2"><label className="text-[9px] font-black uppercase text-slate-400 ml-5 italic tracking-widest">E-mail para Contato</label><input required type="email" value={recoveryEmail} onChange={e => setRecoveryEmail(e.target.value)} className="w-full p-5 bg-slate-50 border-none rounded-3xl text-sm font-bold outline-none focus:ring-2 focus:ring-indigo-600 shadow-inner" placeholder="email@exemplo.com" /></div>
                   <button type="submit" disabled={loading} className="w-full py-6 bg-slate-950 text-white rounded-[2.5rem] text-[10px] font-black uppercase tracking-[0.3em] italic hover:bg-indigo-600 transition-all shadow-2xl">
                      {loading ? <RefreshCw className="animate-spin mx-auto" size={20}/> : 'Iniciar Chamado de Suporte'}
                   </button>
                </form>
             </div>
           ) : (
             <div className="flex-1 flex flex-col h-full overflow-hidden relative">
                <header className="p-8 bg-slate-900 text-white flex justify-between items-center shrink-0">
                   <div className="flex items-center gap-5">
                      <div className="p-3 bg-indigo-600 rounded-2xl shadow-xl shadow-indigo-900/40"><MessageSquare size={24}/></div>
                      <div>
                        <h3 className="text-sm font-black uppercase italic tracking-tighter">Atendimento EB-EAD</h3>
                        <p className="text-[9px] text-indigo-400 font-bold uppercase tracking-widest mt-1 italic">Protocolo: {activeProtocol}</p>
                      </div>
                   </div>
                   {!showWhatsAppRedirect && (
                     <div className="flex items-center gap-3 px-4 py-2 bg-white/10 rounded-full border border-white/5 shadow-inner">
                        <Clock size={14} className="text-indigo-400 animate-pulse"/>
                        <span className="text-[11px] font-black text-white tabular-nums tracking-widest">{formatTimer(recoveryTimer)}</span>
