      </header>

      <main className="flex-1 min-h-[600px] overflow-hidden">
         {activeTab === 'atendimento' && (
           <div className="bg-white rounded-[2.5rem] border border-slate-200 overflow-hidden h-full flex flex-col shadow-sm">
              <div className="p-8 border-b border-slate-100 flex justify-between items-center bg-slate-50/50">
                 <h3 className="font-black text-xs uppercase italic flex items-center gap-3 text-slate-700 tracking-widest leading-none">Fila de Protocolos Prioritários</h3>
                 <div className="flex gap-4">
                    <div className="relative"><Search className="absolute left-4 top-1/2 -translate-y-1/2 text-slate-300" size={16}/><input value={searchTerm} onChange={e => setSearchTerm(e.target.value)} placeholder="Pesquisar..." className="pl-11 pr-4 py-3 border border-slate-100 rounded-xl text-xs w-64 outline-none focus:ring-1 focus:ring-indigo-600 font-bold bg-white shadow-inner" /></div>
                    <button onClick={() => setIsNewProtocolOpen(true)} className="bg-slate-950 text-white px-6 py-3 rounded-xl text-[9px] font-black uppercase italic tracking-widest hover:bg-indigo-600 transition-all shadow-xl flex items-center gap-2"><Plus size={16}/> Abrir Protocolo</button>
                 </div>
              </div>
              <div className="flex-1 overflow-auto custom-scrollbar p-4">
                 <table className="w-full text-left border-collapse">
                    <thead className="bg-white text-[9px] font-black uppercase text-slate-400 tracking-[0.2em] border-b border-slate-100 italic">
                       <tr><th className="px-6 py-4">Protocolo</th><th className="px-6 py-4">Solicitante</th><th className="px-6 py-4">Status / Canal</th><th className="px-6 py-4">Data</th><th className="px-6 py-4 text-center">Gestão</th></tr>
                    </thead>
                    <tbody className="text-xs font-medium text-slate-600">
                       {filteredTickets.length === 0 ? <tr><td colSpan={5} className="p-24 text-center text-slate-300 uppercase italic font-black text-xs tracking-widest">Nenhum chamado pendente no banco.</td></tr> : filteredTickets.map(t => (
                         <tr key={t.id} className="border-b border-slate-50 hover:bg-indigo-50/30 transition-all group">
                            <td className="px-6 py-5 font-mono font-black text-indigo-600 italic">{t.protocolo}</td>
                            <td className="px-6 py-5 font-black text-slate-900 uppercase italic">{t.user}</td>
                            <td className="px-6 py-5 flex flex-wrap gap-2 items-center">
                               <span className={`px-3 py-1 rounded-lg text-[9px] font-black uppercase italic border ${t.status === 'Pendente' ? 'bg-amber-50 text-amber-600 border-amber-100' : 'bg-indigo-50 text-indigo-600 border-indigo-100'}`}>{t.status}</span>
                               <span className="px-3 py-1 bg-slate-50 border border-slate-100 rounded-lg text-[8px] font-black uppercase text-slate-400">{t.type}</span>
                               {t.archivedReason === 'expirado' && <span className="flex items-center gap-1.5 px-3 py-1 bg-rose-50 text-rose-600 rounded-lg text-[8px] font-black uppercase border border-rose-100 animate-pulse italic"><AlertTriangle size={10}/> Atendimento Expirado</span>}
                            </td>
                            <td className="px-6 py-5 text-[10px] text-slate-400 font-bold uppercase italic">{t.lastUpdate?.seconds ? new Date(t.lastUpdate.seconds*1000).toLocaleDateString() : 'Agora'}</td>
                            <td className="px-6 py-5 text-center"><button onClick={async () => { await updateDoc(doc(db, 'tickets', t.id), {status: 'Em Atendimento'}); setSelectedTicketId(t.id); setActiveTab('chat'); setChatFilter('abertos'); }} className="px-6 py-2.5 bg-slate-950 text-white font-black uppercase italic text-[9px] rounded-xl hover:bg-indigo-600 shadow-xl tracking-widest transition-all active:scale-95">Atender</button></td>
                         </tr>
                       ))}
                    </tbody>
                 </table>
              </div>
           </div>
         )}
         {/* Outras abas (chat, arquivos, operacional) permanecem com sua lógica base */}
      </main>

      {/* MODAL NOVO PROTOCOLO */}
      {isNewProtocolOpen && (
        <div className="fixed inset-0 z-[3000] bg-slate-950/80 backdrop-blur-md flex items-center justify-center p-4 animate-in zoom-in-95">
           <div className="bg-white w-full max-w-md rounded-[3rem] p-12 space-y-8 shadow-2xl">
              <div className="flex justify-between items-center">
                 <h3 className="text-2xl font-black uppercase italic text-slate-900 tracking-tighter leading-none">Novo Chamado</h3>
                 <button onClick={() => setIsNewProtocolOpen(false)} className="p-3 bg-slate-50 rounded-full hover:bg-rose-50 hover:text-rose-600 transition-all"><X size={20}/></button>
              </div>
              <div className="space-y-6">
                 <div className="space-y-2"><label className="text-[9px] font-black uppercase text-slate-400 ml-3 italic tracking-widest">Solicitante</label><input value={newProtocolForm.name} onChange={e => setNewProtocolForm({...newProtocolForm, name: e.target.value})} className="w-full p-4 bg-slate-50 border border-slate-100 rounded-2xl text-xs font-bold outline-none focus:ring-2 focus:ring-indigo-600 shadow-inner" placeholder="Nome do Aluno..." /></div>
                 <div className="space-y-2"><label className="text-[9px] font-black uppercase text-slate-400 ml-3 italic tracking-widest">Canal de Entrada</label><select value={newProtocolForm.channel} onChange={e => setNewProtocolForm({...newProtocolForm, channel: e.target.value})} className="w-full p-4 bg-slate-50 border border-slate-100 rounded-2xl text-[10px] font-black uppercase italic outline-none cursor-pointer shadow-inner"><option value="Balcão">Balcão Presencial</option><option value="WhatsApp">WhatsApp</option><option value="E-mail">E-mail</option></select></div>
                 <div className="space-y-2"><label className="text-[9px] font-black uppercase text-slate-400 ml-3 italic tracking-widest">Relato Inicial</label><textarea value={newProtocolForm.notes} onChange={e => setNewProtocolForm({...newProtocolForm, notes: e.target.value})} className="w-full p-5 bg-slate-50 border border-slate-100 rounded-2xl text-xs font-medium italic outline-none h-28 resize-none shadow-inner" placeholder="O que o aluno precisa?" /></div>
                 <button onClick={handleCreateProtocol} className="w-full py-5 bg-slate-950 text-white rounded-[1.5rem] text-[10px] font-black uppercase italic tracking-[0.2em] shadow-2xl hover:bg-indigo-600 transition-all active:scale-95">Confirmar e Abrir</button>
              </div>
