import React, { useState, useEffect, useRef } from 'react';
import { signInWithEmailAndPassword, signOut } from "https://www.gstatic.com/firebasejs/10.7.1/firebase-auth.js";
import { collection, query, where, onSnapshot, doc, getDoc, serverTimestamp, addDoc, orderBy, updateDoc } from "https://www.gstatic.com/firebasejs/10.7.1/firebase-firestore.js";
import { auth, db } from '../firebase';
import { GraduationCap, BookOpen, Star, ChevronLeft, MessageCircle, Flame, RefreshCw, Send, Phone, Clock, AlertTriangle, ThumbsUp, ThumbsDown } from 'lucide-react';

type ViewMode = 'landing' | 'login' | 'enroll_form' | 'password_recovery' | 'evaluation';

const LoginView: React.FC = () => {
  const [viewMode, setViewMode] = useState<ViewMode>('landing');
  const [email, setEmail] = useState('');
  const [password, setPassword] = useState('');
  const [error, setError] = useState('');
  const [loading, setLoading] = useState(false);
  const [isAdminMode, setIsAdminMode] = useState(false);

  // Chat Recovery States
  const [recoveryName, setRecoveryName] = useState('');
  const [recoveryEmail, setRecoveryEmail] = useState('');
  const [activeProtocol, setActiveProtocol] = useState<string | null>(null);
  const [ticketId, setTicketId] = useState<string | null>(null);
  const [chatMessage, setChatMessage] = useState('');
  const [messages, setMessages] = useState<any[]>([]);
  const [recoveryTimer, setRecoveryTimer] = useState(300); // 5 minutes (300s)
  const [showWhatsAppRedirect, setShowWhatsAppRedirect] = useState(false);
  const chatEndRef = useRef<HTMLDivElement>(null);

  // Evaluation States
  const [rating, setRating] = useState(0);
  const [solved, setSolved] = useState<boolean | null>(null);
  const [waitEvaluation, setWaitEvaluation] = useState('');

  const [courses, setCourses] = useState<any[]>([]);
  const [realStats, setRealStats] = useState({ students: 0, classes: 0, rating: '0.0' });

  // Load Data
  useEffect(() => {
    const unsubC = onSnapshot(query(collection(db, 'cursos'), where('status', '==', 'ativo')), (snap) => {
      setCourses(snap.docs.map(d => ({ id: d.id, ...d.data() })));
    });
    const unsubS = onSnapshot(query(collection(db, 'users'), where('role', '==', 'aluno')), (snap) => {
      setRealStats(prev => ({ ...prev, students: snap.size }));
    });
    return () => { unsubC(); unsubS(); };
  }, []);

  // Chat Messages Listener with Data Sanitization (Prevents Circular Reference error)
  useEffect(() => {
    if (!ticketId) return;
    const unsub = onSnapshot(query(collection(db, `tickets/${ticketId}/messages`), orderBy('timestamp', 'asc')), (snap) => {
      const msgs = snap.docs.map(d => {
        const data = d.data();
        return {
          ...data,
          // Convert Timestamp to millis for safe serialization/logging
          timestamp: data.timestamp?.toMillis ? { seconds: data.timestamp.seconds } : data.timestamp
        };
      });
      setMessages(msgs);

      const hasStaffResponded = msgs.some(m => m.sender === 'Secretaria');
      if (hasStaffResponded) {
        setShowWhatsAppRedirect(false);
      }

      setTimeout(() => chatEndRef.current?.scrollIntoView({ behavior: 'smooth' }), 100);
    });
    return () => unsub();
  }, [ticketId]);

  // Support Timer Logic (5 Minutes)
  useEffect(() => {
    let timer: any;
    if (activeProtocol && recoveryTimer > 0 && !showWhatsAppRedirect && viewMode === 'password_recovery') {
      timer = setInterval(() => {
        setRecoveryTimer(prev => prev - 1);
      }, 1000);
    }
    return () => clearInterval(timer);
  }, [activeProtocol, recoveryTimer, showWhatsAppRedirect, viewMode]);

  // Handle Timeout when timer hits 0
  useEffect(() => {
    if (recoveryTimer === 0 && !showWhatsAppRedirect && activeProtocol) {
      handleTimeout();
    }
  }, [recoveryTimer]);

  const handleTimeout = async () => {
    const hasResponse = messages.some(m => m.sender === 'Secretaria');
    if (!hasResponse && ticketId) {
      setShowWhatsAppRedirect(true);
      try {
        await updateDoc(doc(db, 'tickets', ticketId), {
          status: 'Finalizado',
          archivedReason: 'expirado',
          lastUpdate: serverTimestamp(),
          lastMessage: 'Atendimento encerrado por tempo limite de espera.'
        });
      } catch (e) {
        console.error("Erro ao arquivar ticket expirado");
      }
    }
  };

  const formatTimer = (seconds: number) => {
    const m = Math.floor(seconds / 60);
    const s = seconds % 60;
    return `${m}:${s.toString().padStart(2, '0')}`;
  };

  const handleLogin = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!email || !password) {
      setError('Preencha todos os campos.');
      return;
    }
    setLoading(true);
    setError('');
    try {
      const userCredential = await signInWithEmailAndPassword(auth, email.trim().toLowerCase(), password);
      const userDoc = await getDoc(doc(db, 'users', userCredential.user.uid));
      if (userDoc.exists()) {
        const userData = userDoc.data();
        if (isAdminMode && userData.role === 'aluno') {
          await signOut(auth);
          setError('Acesso administrativo negado.');
          setLoading(false);
          return;
        }
      }
    } catch (err: any) {
      setError('E-mail ou senha incorretos.');
      setLoading(false);
    }
  };

  const startRecoveryTicket = async (e: React.FormEvent) => {
    e.preventDefault();
    setLoading(true);
    const protocol = 'SUP-' + Math.random().toString(36).substring(2, 9).toUpperCase();
    const payload = {
      protocolo: protocol,
      user: recoveryName,
      email: recoveryEmail,
      type: 'Suporte Matrícula',
      status: 'Pendente',
      createdAt: serverTimestamp(),
      lastUpdate: serverTimestamp(),
      lastMessage: 'Chat iniciado pelo aluno.'
    };
    try {
      const docRef = await addDoc(collection(db, 'tickets'), payload);
      setTicketId(docRef.id);
      setActiveProtocol(protocol);
    } catch (err) {
      console.error("Erro ao iniciar suporte");
    } finally {
      setLoading(false);
    }
  };

  const sendChatMessage = async () => {
    if (!chatMessage.trim() || !ticketId) return;
    try {
      await addDoc(collection(db, `tickets/${ticketId}/messages`), {
        text: chatMessage,
        sender: 'Aluno',
        timestamp: serverTimestamp()
      });
      setChatMessage('');
    } catch (e) {
      console.error("Erro ao enviar mensagem");
    }
  };

  const submitEvaluation = async () => {
    if (rating === 0) return;
    setLoading(true);
    try {
      await addDoc(collection(db, 'support_evaluations'), {
        ticketId,
        protocol: activeProtocol,
        studentName: recoveryName,
        rating,
        solved,
        waitEvaluation,
        timestamp: serverTimestamp()
      });
      setViewMode('landing');
      alert("Avaliação registrada com sucesso!");
      setTicketId(null);
      setActiveProtocol(null);
      setRecoveryTimer(300);
      setRating(0);
      setSolved(null);
    } catch (e) {
      console.error("Erro ao salvar avaliação");
    } finally {
      setLoading(false);
    }
  };

  if (viewMode === 'landing') {
    return (
      <div className="min-h-screen bg-white text-slate-900 overflow-x-hidden font-sans">
        <header className="fixed top-0 left-0 right-0 z-[100] bg-white/80 backdrop-blur-md border-b border-slate-100">
          <div className="max-w-7xl mx-auto px-6 h-20 flex items-center justify-between">
            <div className="flex items-center gap-3">
              <div className="bg-indigo-600 text-white p-2 rounded-xl shadow-lg shadow-indigo-100"><GraduationCap size={24}/></div>
              <span className="text-xl font-black uppercase italic tracking-tighter">EB-EAD</span>
            </div>
            <div className="flex items-center gap-6">
              <button onClick={() => setViewMode('login')} className="text-[10px] font-black uppercase tracking-widest text-slate-500 hover:text-indigo-600 transition-all">Acesso Aluno</button>
              <button onClick={() => setViewMode('enroll_form')} className="px-6 py-3 bg-indigo-600 text-white rounded-xl text-[10px] font-black uppercase tracking-widest shadow-xl hover:bg-slate-900 transition-all">Matrícula Digital</button>
            </div>
          </div>
        </header>

        <section className="pt-48 pb-24 px-6 relative overflow-hidden">
          <div className="max-w-7xl mx-auto grid lg:grid-cols-2 gap-20 items-center">
            <div className="space-y-12 animate-in slide-in-from-left duration-700">
              <div className="inline-flex items-center gap-3 px-5 py-2.5 bg-indigo-50 text-indigo-600 rounded-full text-[10px] font-black uppercase tracking-widest border border-indigo-100 italic">
                <Flame size={14} fill="currentColor"/> Educação Teológica Superior
              </div>
              <h1 className="text-7xl md:text-9xl font-black tracking-tighter uppercase italic leading-[0.8] text-slate-950">
                O Futuro da <br/> <span className="text-indigo-600">Teologia</span>.
              </h1>
              <p className="text-xl text-slate-500 font-medium italic leading-relaxed max-w-xl">
                Plataforma exclusiva de ensino bíblico com certificação master, suporte em tempo real e material didático auditado.
              </p>
              <div className="flex flex-col sm:flex-row gap-5">
                <button onClick={() => setViewMode('enroll_form')} className="px-12 py-6 bg-slate-950 text-white rounded-2xl text-[11px] font-black uppercase tracking-[0.3em] italic shadow-2xl hover:bg-indigo-600 transition-all active:scale-95">Ver Catálogo</button>
                <button onClick={() => setViewMode('password_recovery')} className="px-12 py-6 bg-white border border-slate-200 text-slate-900 rounded-2xl text-[11px] font-black uppercase tracking-[0.3em] italic hover:bg-slate-50 transition-all">Falar com Secretaria</button>
              </div>
            </div>
            <div className="relative animate-in zoom-in duration-1000">
              <div className="aspect-square bg-slate-100 rounded-[5rem] overflow-hidden shadow-2xl relative border-8 border-white">
                <img src="https://images.unsplash.com/photo-1501290830387-99bc439ca623?auto=format&fit=crop&w=1200&q=80" className="w-full h-full object-cover grayscale" />
              </div>
              <div className="absolute -bottom-10 -left-10 bg-white p-10 rounded-[3rem] shadow-2xl border border-slate-100">
                <p className="text-5xl font-black text-indigo-600">+{realStats.students}</p>
