            <div className="grid md:grid-cols-3 gap-10">
              {courses.slice(0, 3).map(c => (
                <div key={c.id} className="bg-white rounded-[3.5rem] p-5 border border-slate-200 shadow-sm hover:shadow-2xl transition-all flex flex-col h-full group">
                  <div className="aspect-video rounded-[2.5rem] overflow-hidden mb-8 relative">
                    <img src={c.capaUrl} className="w-full h-full object-cover group-hover:scale-110 transition-transform duration-1000" />
                  </div>
                  <div className="px-4 pb-8 flex-1 flex flex-col justify-between">
                    <div>
                      <h3 className="text-2xl font-black uppercase italic tracking-tighter leading-tight mb-4">{c.nome}</h3>
                      <p className="text-xs text-slate-500 font-medium italic line-clamp-3">{c.descricao}</p>
                    </div>
                    <button onClick={() => setViewMode('enroll_form')} className="w-full mt-10 py-5 bg-slate-950 text-white rounded-2xl text-[10px] font-black uppercase tracking-[0.2em] italic hover:bg-indigo-600 transition-all">Iniciar Matrícula</button>
                  </div>
                </div>
              ))}
            </div>
          </div>
        </section>
      </div>
    );
  }

  if (viewMode === 'evaluation') {
    return (
      <div className="min-h-screen bg-slate-950 flex items-center justify-center p-6 font-sans">
        <div className="w-full max-w-xl bg-white rounded-[4rem] p-16 shadow-2xl text-center space-y-12 animate-in zoom-in-95 duration-500">
          <div className="p-5 bg-indigo-50 text-indigo-600 rounded-[2.5rem] w-fit mx-auto border border-indigo-100 shadow-inner"><Star size={48} className="animate-pulse"/></div>
          <h2 className="text-4xl font-black uppercase italic tracking-tighter leading-none text-slate-900">Avalie seu Atendimento</h2>
          <div className="space-y-10">
            <div className="space-y-6">
              <p className="text-[10px] font-black uppercase tracking-[0.3em] text-slate-500 italic">O que achou do atendimento?</p>
              <div className="flex justify-center gap-4">
                {[1, 2, 3, 4, 5].map(s => (
                  <button key={s} onClick={() => setRating(s)} className={`w-14 h-14 rounded-2xl flex items-center justify-center transition-all ${rating >= s ? 'bg-indigo-600 text-white' : 'bg-slate-50 text-slate-300'}`}>
                    <Star size={28} fill={rating >= s ? 'currentColor' : 'none'}/>
                  </button>
                ))}
              </div>
            </div>
            <div className="space-y-6">
              <p className="text-[10px] font-black uppercase tracking-[0.3em] text-slate-500 italic">Problema resolvido?</p>
              <div className="flex justify-center gap-5">
                <button onClick={() => setSolved(true)} className={`px-10 py-5 rounded-2xl flex items-center gap-3 text-[10px] font-black uppercase transition-all ${solved === true ? 'bg-emerald-600 text-white' : 'bg-slate-50 text-slate-400'}`}><ThumbsUp size={18}/> Sim</button>
                <button onClick={() => setSolved(false)} className={`px-10 py-5 rounded-2xl flex items-center gap-3 text-[10px] font-black uppercase transition-all ${solved === false ? 'bg-rose-600 text-white' : 'bg-slate-50 text-slate-400'}`}><ThumbsDown size={18}/> Não</button>
              </div>
            </div>
            <button onClick={submitEvaluation} disabled={rating === 0 || loading} className="w-full py-6 bg-slate-900 text-white rounded-[2rem] text-[11px] font-black uppercase tracking-[0.4em] italic hover:bg-indigo-600 shadow-2xl transition-all">
              {loading ? <RefreshCw className="animate-spin mx-auto" size={20}/> : 'Finalizar Avaliação'}
            </button>
          </div>
        </div>
      </div>
    );
  }

  if (viewMode === 'password_recovery') {
    return (
      <div className="min-h-screen bg-slate-950 flex items-center justify-center p-6 relative font-sans">
        <div className="relative z-10 w-full max-w-4xl bg-white rounded-[4rem] shadow-2xl overflow-hidden flex flex-col md:flex-row h-[700px] animate-in zoom-in-95 duration-500">
           {!activeProtocol ? (
             <div className="flex-1 p-16 flex flex-col justify-center space-y-12">
                <button onClick={() => setViewMode('landing')} className="flex items-center gap-3 text-[10px] font-black uppercase text-slate-400 hover:text-indigo-600 transition-all italic"><ChevronLeft size={16}/> Retornar</button>
                <h2 className="text-4xl font-black text-slate-900 uppercase italic tracking-tighter leading-none">Suporte Matrícula</h2>
                <form onSubmit={startRecoveryTicket} className="space-y-6">
                   <div className="space-y-2"><label className="text-[9px] font-black uppercase text-slate-400 ml-5 italic tracking-widest">Nome Completo</label><input required value={recoveryName} onChange={e => setRecoveryName(e.target.value)} className="w-full p-5 bg-slate-50 border-none rounded-3xl text-sm font-bold shadow-inner" placeholder="Seu nome..." /></div>
                   <div className="space-y-2"><label className="text-[9px] font-black uppercase text-slate-400 ml-5 italic tracking-widest">E-mail</label><input required type="email" value={recoveryEmail} onChange={e => setRecoveryEmail(e.target.value)} className="w-full p-5 bg-slate-50 border-none rounded-3xl text-sm font-bold shadow-inner" /></div>
                   <button type="submit" disabled={loading} className="w-full py-6 bg-slate-950 text-white rounded-[2.5rem] text-[10px] font-black uppercase tracking-[0.3em] italic hover:bg-indigo-600 shadow-2xl">
                      {loading ? <RefreshCw className="animate-spin mx-auto" size={20}/> : 'Falar com Secretaria'}
                   </button>
                </form>
             </div>
           ) : (
             <div className="flex-1 flex flex-col h-full overflow-hidden relative">
                <header className="p-8 bg-slate-900 text-white flex justify-between items-center shrink-0">
                   <div className="flex items-center gap-5">
                      <div className="p-3 bg-indigo-600 rounded-2xl"><MessageCircle size={24}/></div>
                      <div>
                        <h3 className="text-sm font-black uppercase italic tracking-tighter">Atendimento EB-EAD</h3>
                        <p className="text-[9px] text-indigo-400 font-bold uppercase tracking-widest mt-1">Prot: {activeProtocol}</p>
                      </div>
                   </div>
                   {!showWhatsAppRedirect && (
                     <div className="flex items-center gap-3 px-4 py-2 bg-white/10 rounded-full border border-white/5">
                        <Clock size={14} className="text-indigo-400 animate-pulse"/>
                        <span className="text-[11px] font-black text-white tabular-nums">{formatTimer(recoveryTimer)}</span>
                     </div>
                   )}
                   <button onClick={() => setViewMode('evaluation')} className="px-5 py-2.5 bg-rose-600/10 hover:bg-rose-600 rounded-xl text-[9px] font-black uppercase transition-all">Sair</button>
                </header>

                <div className="flex-1 overflow-y-auto p-8 space-y-6 bg-slate-50 shadow-inner custom-scrollbar relative">
                   {showWhatsAppRedirect ? (
                     <div className="absolute inset-0 z-50 bg-white/95 backdrop-blur-xl flex flex-col items-center justify-center p-12 text-center animate-in fade-in">
                        <div className="w-24 h-24 bg-rose-50 text-rose-500 rounded-[3rem] flex items-center justify-center mb-10 border border-rose-100 animate-bounce-slow">
                          <AlertTriangle size={48} />
                        </div>
                        <h4 className="text-3xl font-black text-slate-900 uppercase italic tracking-tighter leading-none">Alta Demanda</h4>
                        <p className="text-xs text-slate-500 font-medium italic mt-6 leading-relaxed max-w-sm">Nossos atendentes estão ocupados. Migramos sua solicitação para nosso WhatsApp Prioritário.</p>
                        <a 
                          href={`https://wa.me/5511999999999?text=Olá, sou ${recoveryName}. Ticket ${activeProtocol}.`}
                          target="_blank"
                          onClick={() => setViewMode('evaluation')}
                          className="mt-12 px-12 py-6 bg-emerald-600 text-white rounded-[2.5rem] text-[10px] font-black uppercase tracking-[0.3em] shadow-2xl flex items-center gap-4"
                        >
                          <Phone size={20}/> Suporte Prioritário
                        </a>
                     </div>
                   ) : (
                     <>
                        {messages.length === 0 && (
                          <div className="p-8 bg-indigo-50 border border-indigo-100 rounded-3xl text-[10px] font-black uppercase text-indigo-700 italic text-center animate-pulse">
                            Aguardando resposta da secretaria...
                          </div>
                        )}
                        {messages.map((m, i) => (
                          <div key={i} className={`flex flex-col ${m.sender === 'Aluno' ? 'items-end' : 'items-start'} animate-in slide-in-from-bottom-3`}>
                             <div className={`max-w-[80%] p-5 rounded-[2rem] text-xs font-medium italic shadow-lg ${m.sender === 'Aluno' ? 'bg-indigo-600 text-white rounded-tr-none' : 'bg-white border border-slate-200 text-slate-900 rounded-tl-none'}`}>
                               {m.text}
                             </div>
                             <span className="text-[8px] font-bold text-slate-400 uppercase mt-2 px-3 italic">{m.sender}</span>
                          </div>
                        ))}
                        <div ref={chatEndRef} />
                     </>
                   )}
                </div>

                {!showWhatsAppRedirect && (
                  <div className="p-8 border-t border-slate-100 bg-white flex gap-4">
                    <input value={chatMessage} onChange={e => setChatMessage(e.target.value)} onKeyDown={e => e.key === 'Enter' && sendChatMessage()} placeholder="Descreva sua solicitação..." className="flex-1 bg-slate-50 border-none rounded-2xl px-8 py-5 text-xs font-bold outline-none italic" />
                    <button onClick={sendChatMessage} className="p-5 bg-slate-900 text-white rounded-2xl shadow-2xl hover:bg-indigo-600 transition-all active:scale-95"><Send size={24}/></button>
                  </div>
                )}
             </div>
           )}
        </div>
      </div>
    );
  }

  return (
    <div className="min-h-screen bg-slate-950 flex items-center justify-center p-6 relative font-sans">
       <div className="relative z-10 w-full max-w-5xl bg-white rounded-[5rem] shadow-2xl overflow-hidden animate-in zoom-in-95 flex flex-col lg:flex-row h-full lg:h-[750px]">
          <div className="lg:w-1/2 p-16 space-y-16 flex flex-col justify-center">
             <button onClick={() => setViewMode('landing')} className="flex items-center gap-3 text-[10px] font-black uppercase text-slate-400 hover:text-indigo-600 transition-all italic"><ChevronLeft size={16}/> Retornar</button>
             <h2 className="text-5xl font-black uppercase italic tracking-tighter leading-none">Login <span className="text-indigo-600">Alunos</span></h2>
             {error && <div className="p-5 bg-rose-50 text-rose-600 text-[10px] font-black uppercase rounded-3xl border border-rose-100 italic">{error}</div>}
             <form onSubmit={handleLogin} className="space-y-6">
                <input type="email" required value={email} onChange={e => setEmail(e.target.value)} placeholder="E-mail Acadêmico" className="w-full p-6 bg-slate-50 border-none rounded-[2rem] text-sm font-bold shadow-inner italic" />
                <input type="password" required value={password} onChange={e => setPassword(e.target.value)} placeholder="Senha Secreta" className="w-full p-6 bg-slate-50 border-none rounded-[2rem] text-sm font-bold shadow-inner italic" />
                <button type="submit" disabled={loading} className="w-full py-7 bg-slate-950 text-white rounded-[2.5rem] text-[11px] font-black uppercase tracking-[0.4em] italic hover:bg-indigo-600 transition-all">
                  {loading ? <RefreshCw className="animate-spin mx-auto" size={24}/> : 'Ingressar na Sala'}
                </button>
                <button onClick={() => setViewMode('password_recovery')} type="button" className="w-full text-[9px] font-black uppercase text-slate-400 hover:text-indigo-600 transition-all italic text-center">Esqueci minha senha / Suporte</button>
             </form>
          </div>
          <div className="lg:w-1/2 bg-slate-50 p-16 flex flex-col justify-center gap-12 border-l border-slate-100">
             <h3 className="text-3xl font-black uppercase italic tracking-tighter leading-none">Expandir seu Conhecimento?</h3>
