             <button onClick={() => setViewMode('enroll_form')} className="w-full py-7 bg-white border border-slate-200 text-slate-900 rounded-[2.5rem] text-[11px] font-black uppercase italic tracking-[0.3em] hover:border-indigo-600 transition-all shadow-xl">Novo Cadastro</button>
          </div>
       </div>
    </div>
  );
};

export default LoginView;

import React, { useState, useEffect, useMemo, useRef } from 'react';
import { 
  collection, query, onSnapshot, addDoc, updateDoc, 
  doc, serverTimestamp, orderBy, where, getDoc, getDocs
} from "https://www.gstatic.com/firebasejs/10.7.1/firebase-firestore.js";
import { db } from '../firebase';
import { User } from '../types';
import { 
  MessageSquare, Search, Plus, X, Eye, Edit3, Trash2, AlertTriangle
} from 'lucide-react';

interface SecretariatViewProps { user: User; }
type SecretariatTab = 'atendimento' | 'chat' | 'arquivos' | 'operacional';
type ChatFilter = 'abertos' | 'finalizados' | 'arquivados';

const SecretariatView: React.FC<SecretariatViewProps> = ({ user }) => {
  const [activeTab, setActiveTab] = useState<SecretariatTab>('atendimento');
  const [chatFilter, setChatFilter] = useState<ChatFilter>('abertos');
  const [tickets, setTickets] = useState<any[]>([]);
  const [students, setStudents] = useState<any[]>([]);
  const [searchTerm, setSearchTerm] = useState('');
  const [selectedTicketId, setSelectedTicketId] = useState<string | null>(null);
  const [chatHistory, setChatHistory] = useState<any[]>([]);
  const [chatMessage, setChatMessage] = useState('');

  const [isNewProtocolOpen, setIsNewProtocolOpen] = useState(false);
  const [newProtocolForm, setNewProtocolForm] = useState({ name: '', channel: 'Balcão', notes: '' });

  const chatEndRef = useRef<HTMLDivElement>(null);

  // Tickets Listener with Sanitization
  useEffect(() => {
    const unsubT = onSnapshot(query(collection(db, 'tickets'), orderBy('lastUpdate', 'desc')), s => {
      setTickets(s.docs.map(d => {
        const data = d.data();
        return {
          id: d.id,
          ...data,
          lastUpdate: data.lastUpdate?.toMillis ? { seconds: data.lastUpdate.seconds } : data.lastUpdate
        };
      }));
    });
    const unsubS = onSnapshot(query(collection(db, 'users'), where('role', '==', 'aluno')), s => setStudents(s.docs.map(d => ({ uid: d.id, ...d.data() }))));
    return () => { unsubT(); unsubS(); };
  }, []);

  // Chat History Listener
  useEffect(() => {
    if (!selectedTicketId) return;
    const unsubChat = onSnapshot(query(collection(db, `tickets/${selectedTicketId}/messages`), orderBy('timestamp', 'asc')), (snap) => {
      setChatHistory(snap.docs.map(d => d.data()));
      setTimeout(() => chatEndRef.current?.scrollIntoView({ behavior: 'smooth' }), 100);
    });
    return () => unsubChat();
  }, [selectedTicketId]);

  const handleSendMessage = async () => {
    if (!selectedTicketId || !chatMessage.trim()) return;
    const msg = { text: chatMessage, sender: 'Secretaria', timestamp: serverTimestamp() };
    try {
      await addDoc(collection(db, `tickets/${selectedTicketId}/messages`), msg);
      await updateDoc(doc(db, 'tickets', selectedTicketId), { 
        lastMessage: chatMessage, 
        lastUpdate: serverTimestamp(),
        status: 'Em Atendimento'
      });
      setChatMessage('');
    } catch (e) {
      console.error("Erro ao enviar resposta");
    }
  };

  const handleCreateProtocol = async () => {
    if (!newProtocolForm.name) return;
    const protocol = 'PROT-' + Math.random().toString(36).substring(2, 9).toUpperCase();
    try {
      await addDoc(collection(db, 'tickets'), {
        protocolo: protocol,
        user: newProtocolForm.name,
        email: 'Atendimento Local',
        type: newProtocolForm.channel,
        status: 'Pendente',
        createdAt: serverTimestamp(),
        lastUpdate: serverTimestamp(),
        lastMessage: newProtocolForm.notes || 'Início de atendimento.'
      });
      setIsNewProtocolOpen(false);
      setNewProtocolForm({ name: '', channel: 'Balcão', notes: '' });
    } catch (e) {
      console.error("Erro ao criar protocolo");
    }
  };

  const filteredTickets = tickets.filter(t => {
    const matchSearch = t.protocolo?.toLowerCase().includes(searchTerm.toLowerCase()) || t.user?.toLowerCase().includes(searchTerm.toLowerCase());
    if (activeTab === 'atendimento') return matchSearch && t.status === 'Pendente';
    if (activeTab === 'chat') {
       if (chatFilter === 'abertos') return matchSearch && (t.status === 'Em Atendimento' || t.status === 'Pendente');
       if (chatFilter === 'finalizados') return matchSearch && t.status === 'Finalizado';
       if (chatFilter === 'arquivados') return matchSearch && t.status === 'Arquivado';
    }
    return matchSearch;
  });

  return (
    <div className="space-y-6 animate-in fade-in h-full max-w-full overflow-hidden text-slate-900 pb-20 font-sans">
      <header className="flex flex-col md:flex-row justify-between items-center bg-white p-6 rounded-[2.5rem] border border-slate-200 shadow-sm gap-4">
        <div className="flex items-center gap-4">
           <div className="p-3 bg-indigo-600 text-white rounded-2xl shadow-xl shadow-indigo-100"><MessageSquare size={24}/></div>
           <div>
             <h1 className="text-xl font-black uppercase italic tracking-tighter text-slate-900 leading-none">Secretaria Virtual</h1>
             <p className="text-[9px] text-indigo-500 font-black uppercase tracking-[0.3em] mt-2">Central Master v4.2</p>
           </div>
        </div>
        <div className="flex bg-slate-50 p-1.5 rounded-2xl border border-slate-100 shadow-inner">
           {(['atendimento', 'chat', 'arquivos', 'operacional'] as any).map((t:any) => (
             <button key={t} onClick={() => { setActiveTab(t); setSelectedTicketId(null); }} className={`px-6 py-2.5 rounded-xl text-[10px] font-black uppercase italic tracking-widest transition-all ${activeTab === t ? 'bg-white text-indigo-600 shadow-md border border-slate-100' : 'text-slate-400 hover:text-slate-600'}`}>{t}</button>
           ))}
        </div>
      </header>

      <main className="flex-1 min-h-[600px] overflow-hidden">
         {activeTab === 'atendimento' && (
           <div className="bg-white rounded-[2.5rem] border border-slate-200 overflow-hidden h-full flex flex-col shadow-sm">
              <div className="p-8 border-b border-slate-100 flex justify-between items-center bg-slate-50/50">
                 <h3 className="font-black text-xs uppercase italic flex items-center gap-3 text-slate-700 tracking-widest leading-none">Fila de Protocolos Prioritários</h3>
                 <div className="flex gap-4">
                    <div className="relative"><Search className="absolute left-4 top-1/2 -translate-y-1/2 text-slate-300" size={16}/><input value={searchTerm} onChange={e => setSearchTerm(e.target.value)} placeholder="Pesquisar..." className="pl-11 pr-4 py-3 border border-slate-100 rounded-xl text-xs w-64 outline-none focus:ring-1 focus:ring-indigo-600 font-bold bg-white shadow-inner" /></div>
                    <button onClick={() => setIsNewProtocolOpen(true)} className="bg-slate-950 text-white px-6 py-3 rounded-xl text-[9px] font-black uppercase italic tracking-widest hover:bg-indigo-600 transition-all shadow-xl flex items-center gap-2"><Plus size={16}/> Abrir Protocolo</button>
                 </div>
              </div>
              <div className="flex-1 overflow-auto custom-scrollbar p-4">
                 <table className="w-full text-left border-collapse">
                    <thead className="bg-white text-[9px] font-black uppercase text-slate-400 tracking-[0.2em] border-b border-slate-100 italic">
                       <tr><th className="px-6 py-4">Protocolo</th><th className="px-6 py-4">Solicitante</th><th className="px-6 py-4">Status / Canal</th><th className="px-6 py-4 text-center">Gestão</th></tr>
                    </thead>
                    <tbody className="text-xs font-medium text-slate-600">
                       {filteredTickets.length === 0 ? <tr><td colSpan={4} className="p-24 text-center text-slate-300 uppercase italic font-black text-xs tracking-widest">Nenhum chamado pendente no banco.</td></tr> : filteredTickets.map(t => (
                         <tr key={t.id} className="border-b border-slate-50 hover:bg-indigo-50/30 transition-all group">
                            <td className="px-6 py-5 font-mono font-black text-indigo-600 italic">{t.protocolo}</td>
                            <td className="px-6 py-5 font-black text-slate-900 uppercase italic">{t.user}</td>
                            <td className="px-6 py-5 flex flex-wrap gap-2 items-center">
                               <span className={`px-3 py-1 rounded-lg text-[9px] font-black uppercase italic border ${t.status === 'Pendente' ? 'bg-amber-50 text-amber-600 border-amber-100' : 'bg-indigo-50 text-indigo-600 border-indigo-100'}`}>{t.status}</span>
                               <span className="px-3 py-1 bg-slate-50 border border-slate-100 rounded-lg text-[8px] font-black uppercase text-slate-400">{t.type}</span>
                               {t.archivedReason === 'expirado' && <span className="flex items-center gap-1.5 px-3 py-1 bg-rose-50 text-rose-600 rounded-lg text-[8px] font-black uppercase border border-rose-100 animate-pulse italic"><AlertTriangle size={10}/> Atendimento Expirado</span>}
                            </td>
                            <td className="px-6 py-5 text-center"><button onClick={async () => { await updateDoc(doc(db, 'tickets', t.id), {status: 'Em Atendimento'}); setSelectedTicketId(t.id); setActiveTab('chat'); setChatFilter('abertos'); }} className="px-6 py-2.5 bg-slate-950 text-white font-black uppercase italic text-[9px] rounded-xl hover:bg-indigo-600 shadow-xl tracking-widest transition-all active:scale-95">Atender</button></td>
                         </tr>
                       ))}
                    </tbody>
                 </table>
              </div>
           </div>
         )}
      </main>

      {/* MODAL NOVO PROTOCOLO */}
      {isNewProtocolOpen && (
        <div className="fixed inset-0 z-[3000] bg-slate-950/80 backdrop-blur-md flex items-center justify-center p-4 animate-in zoom-in-95">
           <div className="bg-white w-full max-w-md rounded-[3rem] p-12 space-y-8 shadow-2xl">
              <div className="flex justify-between items-center">
                 <h3 className="text-2xl font-black uppercase italic text-slate-900 tracking-tighter leading-none">Novo Chamado</h3>
                 <button onClick={() => setIsNewProtocolOpen(false)} className="p-3 bg-slate-50 rounded-full hover:bg-rose-50 hover:text-rose-600 transition-all"><X size={20}/></button>
              </div>
              <div className="space-y-6">
                 <div className="space-y-2"><label className="text-[9px] font-black uppercase text-slate-400 ml-3 italic tracking-widest">Solicitante</label><input value={newProtocolForm.name} onChange={e => setNewProtocolForm({...newProtocolForm, name: e.target.value})} className="w-full p-4 bg-slate-50 border border-slate-100 rounded-2xl text-xs font-bold outline-none focus:ring-2 focus:ring-indigo-600 shadow-inner" placeholder="Nome do Aluno..." /></div>
                 <div className="space-y-2"><label className="text-[9px] font-black uppercase text-slate-400 ml-3 italic tracking-widest">Canal de Entrada</label><select value={newProtocolForm.channel} onChange={e => setNewProtocolForm({...newProtocolForm, channel: e.target.value})} className="w-full p-4 bg-slate-50 border border-slate-100 rounded-2xl text-[10px] font-black uppercase italic outline-none cursor-pointer shadow-inner"><option value="Balcão">Balcão Presencial</option><option value="WhatsApp">WhatsApp</option><option value="E-mail">E-mail</option></select></div>
                 <div className="space-y-2"><label className="text-[9px] font-black uppercase text-slate-400 ml-3 italic tracking-widest">Relato Inicial</label><textarea value={newProtocolForm.notes} onChange={e => setNewProtocolForm({...newProtocolForm, notes: e.target.value})} className="w-full p-5 bg-slate-50 border border-slate-100 rounded-2xl text-xs font-medium italic outline-none h-28 resize-none shadow-inner" placeholder="O que o aluno precisa?" /></div>
                 <button onClick={handleCreateProtocol} className="w-full py-5 bg-slate-950 text-white rounded-[1.5rem] text-[10px] font-black uppercase italic tracking-[0.2em] shadow-2xl hover:bg-indigo-600 transition-all active:scale-95">Confirmar e Abrir</button>
              </div>
           </div>
        </div>
      )}
    </div>
  );
};

export default SecretariatView;

import React, { useState, useEffect, useMemo, useRef } from 'react';
import { 
  collection, query, onSnapshot, addDoc, updateDoc, 
  doc, serverTimestamp, orderBy, where, deleteDoc, getDoc, getDocs
} from "https://www.gstatic.com/firebasejs/10.7.1/firebase-firestore.js";
import { db, auth } from '../firebase';
import { User } from '../types';
import { 
  Ticket as TicketIcon, AlertCircle, Clock, MessageSquare, Search, Plus, X, FolderOpen, FileText, Download, UserCheck, ShieldAlert, FileSignature, Save, PenTool, UserX, Check, ArrowRightLeft, Fingerprint, Star, Send, Folder, Archive, CheckCircle2, ChevronRight, FileDown, Trash2, RotateCcw, MoreVertical, Layout
} from 'lucide-react';
import SignaturePad from '../components/SignaturePad';

interface SecretariatViewProps { user: User; }
type SecretariatTab = 'atendimento' | 'chat' | 'arquivos' | 'operacional';
type OperationalSubView = 'main' | 'transferencia' | 'validacao' | 'assinatura';
type ChatFilter = 'abertos' | 'finalizados' | 'arquivados';

const SecretariatView: React.FC<SecretariatViewProps> = ({ user }) => {
  const [activeTab, setActiveTab] = useState<SecretariatTab>('atendimento');
  const [opSubView, setOpSubView] = useState<OperationalSubView>('main');
  const [chatFilter, setChatFilter] = useState<ChatFilter>('abertos');
  const [tickets, setTickets] = useState<any[]>([]);
  const [files, setFiles] = useState<any[]>([]);
  const [students, setStudents] = useState<any[]>([]);
  const [courses, setCourses] = useState<any[]>([]);
  const [searchTerm, setSearchTerm] = useState('');
  const [selectedTicketId, setSelectedTicketId] = useState<string | null>(null);
  const [chatHistory, setChatHistory] = useState<any[]>([]);
  const [chatMessage, setChatMessage] = useState('');
  const [isSignModalOpen, setIsSignModalOpen] = useState(false);
  const [secSignature, setSecSignature] = useState<string | null>(null);

  // Transfer Form State
  const [transferForm, setTransferForm] = useState({ studentId: '', targetCourseId: '', reason: '' });

  const chatEndRef = useRef<HTMLDivElement>(null);

  useEffect(() => {
    const unsubT = onSnapshot(query(collection(db, 'tickets'), orderBy('createdAt', 'desc')), s => setTickets(s.docs.map(d => ({ id: d.id, ...d.data() }))));
    const unsubF = onSnapshot(collection(db, 'secretaria_arquivos'), s => setFiles(s.docs.map(d => ({ id: d.id, ...d.data() }))));
    const unsubS = onSnapshot(query(collection(db, 'users'), where('role', '==', 'aluno')), s => setStudents(s.docs.map(d => ({ uid: d.id, ...d.data() }))));
    const unsubC = onSnapshot(collection(db, 'cursos'), s => setCourses(s.docs.map(d => ({ id: d.id, ...d.data() }))));
    getDoc(doc(db, 'users', user.uid)).then(d => d.exists() && setSecSignature(d.data().signatureUrl));
    return () => { unsubT(); unsubF(); unsubS(); unsubC(); };
  }, [user.uid]);

  useEffect(() => {
    if (!selectedTicketId) return;
    const unsubChat = onSnapshot(query(collection(db, `tickets/${selectedTicketId}/messages`), orderBy('timestamp', 'asc')), (snap) => {
      setChatHistory(snap.docs.map(d => d.data()));
      setTimeout(() => chatEndRef.current?.scrollIntoView({ behavior: 'smooth' }), 100);
    });
    return () => unsubChat();
  }, [selectedTicketId]);

  const stats = useMemo(() => ({
    abertos: tickets.filter(t => t.status === 'Pendente' || t.status === 'Em Atendimento').length,
    finalizados: tickets.filter(t => t.status === 'Finalizado').length,
    pendentesVal: students.filter(s => s.status === 'aguardando_validacao').length,
    totalGed: files.length
  }), [tickets, students, files]);

  const handleSendMessage = async () => {
    if (!selectedTicketId || !chatMessage.trim()) return;
    const msg = { text: chatMessage, sender: 'Secretaria', timestamp: serverTimestamp() };
    await addDoc(collection(db, `tickets/${selectedTicketId}/messages`), msg);
    await updateDoc(doc(db, 'tickets', selectedTicketId), { lastMessage: chatMessage, lastUpdate: serverTimestamp(), status: 'Em Atendimento' });
    setChatMessage('');
  };

  const handleDownload = (url: string, filename: string) => {
    if (!url) return;
    const link = document.createElement('a');
    link.href = url;
    link.target = '_blank';
    link.download = filename;
    document.body.appendChild(link);
    link.click();
    document.body.removeChild(link);
  };

  const handleExecuteTransfer = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!transferForm.studentId || !transferForm.targetCourseId) return;

    try {
      await updateDoc(doc(db, 'users', transferForm.studentId), {
        cursoInicial: transferForm.targetCourseId,
        transferHistory: serverTimestamp(),
        lastTransferReason: transferForm.reason
      });
      alert('Transferência acadêmica realizada com sucesso!');
      setOpSubView('main');
      setTransferForm({ studentId: '', targetCourseId: '', reason: '' });
    } catch (err) {
      alert('Erro na transferência.');
    }
  };

  const filteredTickets = tickets.filter(t => {
    const matchSearch = t.protocolo?.toLowerCase().includes(searchTerm.toLowerCase()) || t.user?.toLowerCase().includes(searchTerm.toLowerCase());
    if (activeTab === 'atendimento') return matchSearch && t.status === 'Pendente';
    if (activeTab === 'chat') {
       if (chatFilter === 'abertos') return matchSearch && (t.status === 'Em Atendimento' || t.status === 'Pendente');
       if (chatFilter === 'finalizados') return matchSearch && t.status === 'Finalizado';
       if (chatFilter === 'arquivados') return matchSearch && t.status === 'Arquivado';
    }
    return matchSearch;
  });

  const renderOperational = () => {
    switch(opSubView) {
      case 'transferencia':
        return (
          <div className="bg-white border border-slate-200 rounded-[2rem] shadow-xl overflow-hidden animate-in zoom-in-95 max-w-2xl mx-auto">
             <div className="p-8 bg-slate-900 text-white flex justify-between items-center">
                <div className="flex items-center gap-4">
                   <div className="p-3 bg-indigo-600 rounded-2xl"><ArrowRightLeft size={24}/></div>
                   <h3 className="text-sm font-black uppercase italic tracking-tighter">Formulário de Transferência de Curso</h3>
                </div>
                <button onClick={() => setOpSubView('main')} className="p-2 hover:bg-white/10 rounded-full"><X size={20}/></button>
             </div>
             <form onSubmit={handleExecuteTransfer} className="p-10 space-y-8">
                <div className="space-y-2">
                   <label className="text-[10px] font-black uppercase text-slate-400 ml-4 italic">Selecionar Aluno Ativo</label>
                   <select required value={transferForm.studentId} onChange={e => setTransferForm({...transferForm, studentId: e.target.value})} className="w-full p-4 bg-slate-50 border-none rounded-2xl font-bold text-sm outline-none focus:ring-2 focus:ring-indigo-600">
                      <option value="">Buscar aluno...</option>
                      {students.map(s => <option key={s.uid} value={s.uid}>{s.displayName} ({s.academicId})</option>)}
                   </select>
                </div>
                <div className="space-y-2">
                   <label className="text-[10px] font-black uppercase text-slate-400 ml-4 italic">Nova Disciplina de Destino</label>
                   <select required value={transferForm.targetCourseId} onChange={e => setTransferForm({...transferForm, targetCourseId: e.target.value})} className="w-full p-4 bg-slate-50 border-none rounded-2xl font-bold text-sm outline-none focus:ring-2 focus:ring-indigo-600">
                      <option value="">Selecionar novo curso...</option>
                      {courses.map(c => <option key={c.id} value={c.id}>{c.nome}</option>)}
                   </select>
                </div>
                <div className="space-y-2">
                   <label className="text-[10px] font-black uppercase text-slate-400 ml-4 italic">Motivo da Movimentação</label>
                   <textarea value={transferForm.reason} onChange={e => setTransferForm({...transferForm, reason: e.target.value})} className="w-full p-6 bg-slate-50 border-none rounded-[2rem] h-32 text-sm font-medium italic outline-none focus:ring-2 focus:ring-indigo-600" placeholder="Justificativa administrativa..."></textarea>
                </div>
                <button type="submit" className="w-full py-6 bg-slate-950 text-white rounded-[2rem] text-[10px] font-black uppercase italic tracking-[0.3em] shadow-2xl hover:bg-indigo-600 transition-all">Confirmar Transferência</button>
             </form>
          </div>
        );
      case 'validacao':
        const pending = students.filter(s => s.status === 'aguardando_validacao');
        return (
          <div className="bg-white border border-slate-200 rounded-[2.5rem] shadow-xl overflow-hidden animate-in slide-in-from-bottom-5">
             <div className="p-6 bg-indigo-600 text-white flex justify-between items-center">
                <h3 className="text-xs font-black uppercase italic flex items-center gap-3 tracking-widest"><UserCheck size={20}/> Auditoria de Matrículas</h3>
                <button onClick={() => setOpSubView('main')} className="p-2 hover:bg-white/10 rounded-full"><X size={20}/></button>
             </div>
             <div className="overflow-x-auto">
               <table className="w-full text-left">
                  <thead className="bg-slate-50 border-b border-slate-100 text-[9px] font-black uppercase text-slate-400 italic">
                     <tr><th className="px-8 py-4">Aluno Captado</th><th className="px-8 py-4">Cadeira Escolhida</th><th className="px-8 py-4 text-center">Ações de Gestão</th></tr>
                  </thead>
                  <tbody className="text-xs">
                     {pending.length === 0 ? <tr><td colSpan={3} className="p-20 text-center text-slate-300 italic font-black uppercase tracking-widest">Sem pendências no momento.</td></tr> : pending.map(s => (
                       <tr key={s.uid} className="border-b border-slate-50 hover:bg-slate-50 transition-colors">
                          <td className="px-8 py-5 font-black text-slate-900 uppercase italic">{s.displayName}</td>
                          <td className="px-8 py-5 font-bold text-indigo-600 uppercase">{courses.find(c=>c.id===s.cursoInicial)?.nome}</td>
                          <td className="px-8 py-5 flex justify-center gap-3">
                             <button onClick={async () => await updateDoc(doc(db, 'users', s.uid), {status: 'ativo'})} className="px-6 py-2.5 bg-emerald-600 text-white text-[9px] font-black uppercase italic rounded-xl shadow-lg hover:bg-emerald-700 transition-all">Deferir</button>
                             <button onClick={async () => { if(confirm('Indeferir matrícula?')) await deleteDoc(doc(db, 'users', s.uid)); }} className="p-2.5 text-rose-500 hover:bg-rose-50 rounded-xl transition-all border border-transparent hover:border-rose-100"><UserX size={18}/></button>
                          </td>
                       </tr>
                     ))}
                  </tbody>
               </table>
             </div>
          </div>
        );
      case 'assinatura':
        return (
          <div className="max-w-md mx-auto bg-white border border-slate-200 rounded-[3rem] p-10 text-center space-y-8 shadow-2xl animate-in zoom-in-95">
             <div className="w-20 h-20 bg-indigo-50 rounded-[2rem] flex items-center justify-center mx-auto text-indigo-600 shadow-inner border border-indigo-100"><Fingerprint size={40}/></div>
             <div>
                <h3 className="font-black uppercase italic text-slate-900 tracking-tighter text-xl">Validação Digital</h3>
                <p className="text-[10px] text-slate-400 font-medium italic mt-2 uppercase tracking-widest">Sua assinatura oficial EB-AD</p>
             </div>
             <div className="p-6 border-2 border-dashed border-slate-100 bg-slate-50/50 rounded-[2rem] min-h-[120px] flex items-center justify-center shadow-inner">
                {secSignature ? <img src={secSignature} className="max-h-24 grayscale" /> : <p className="text-[10px] text-slate-300 font-black uppercase italic tracking-widest">Não vinculada</p>}
             </div>
             <button onClick={() => setIsSignModalOpen(true)} className="w-full py-5 bg-slate-950 text-white rounded-2xl text-[10px] font-black uppercase italic tracking-[0.2em] shadow-xl hover:bg-indigo-600 transition-all">Registrar Nova Assinatura</button>
             <button onClick={() => setOpSubView('main')} className="text-[9px] text-slate-400 font-black uppercase italic underline hover:text-indigo-600 transition-colors">Retornar ao Painel</button>
          </div>
        );
      default:
        return (
          <div className="grid grid-cols-1 md:grid-cols-4 gap-6 animate-in fade-in">
             <button onClick={() => alert('Abrir Gerador de Declaração Acadêmica')} className="bg-white p-10 rounded-[2.5rem] border border-slate-200 flex flex-col items-center gap-6 hover:shadow-2xl hover:border-indigo-400 transition-all group">
                <div className="p-5 bg-slate-50 text-slate-400 rounded-2xl group-hover:bg-indigo-50 group-hover:text-indigo-600 transition-all shadow-inner"><FileText size={32}/></div>
                <span className="text-[11px] font-black uppercase text-slate-900 italic tracking-widest">Gerar Declaração</span>
             </button>
             <button onClick={() => setOpSubView('validacao')} className="bg-white p-10 rounded-[2.5rem] border border-slate-200 flex flex-col items-center gap-6 hover:shadow-2xl hover:border-indigo-400 transition-all group relative">
                <div className="p-5 bg-slate-50 text-slate-400 rounded-2xl group-hover:bg-indigo-50 group-hover:text-indigo-600 transition-all shadow-inner"><UserCheck size={32}/></div>
                <span className="text-[11px] font-black uppercase text-slate-900 italic tracking-widest">Auditar Matrículas</span>
                {stats.pendentesVal > 0 && <span className="absolute top-6 right-6 bg-rose-600 text-white text-[9px] font-black w-7 h-7 flex items-center justify-center rounded-full shadow-lg animate-pulse">{stats.pendentesVal}</span>}
             </button>
             <button onClick={() => setOpSubView('transferencia')} className="bg-white p-10 rounded-[2.5rem] border border-slate-200 flex flex-col items-center gap-6 hover:shadow-2xl hover:border-indigo-400 transition-all group">
                <div className="p-5 bg-slate-50 text-slate-400 rounded-2xl group-hover:bg-indigo-50 group-hover:text-indigo-600 transition-all shadow-inner"><ArrowRightLeft size={32}/></div>
                <span className="text-[11px] font-black uppercase text-slate-900 italic tracking-widest">Transferências</span>
             </button>
             <button onClick={() => setOpSubView('assinatura')} className="bg-white p-10 rounded-[2.5rem] border border-slate-200 flex flex-col items-center gap-6 hover:shadow-2xl hover:border-indigo-400 transition-all group">
                <div className="p-5 bg-slate-50 text-slate-400 rounded-2xl group-hover:bg-indigo-50 group-hover:text-indigo-600 transition-all shadow-inner"><Fingerprint size={32}/></div>
                <span className="text-[11px] font-black uppercase text-slate-900 italic tracking-widest">Assinatura Digital</span>
             </button>
          </div>
        );
    }
  };

  return (
    <div className="space-y-6 animate-in fade-in h-full max-w-full overflow-hidden pb-20">
      <header className="flex flex-col md:flex-row justify-between items-center bg-slate-900 p-8 rounded-[3rem] text-white gap-6 shadow-2xl border border-white/5">
        <div className="flex items-center gap-5">
           <div className="p-4 bg-indigo-600 text-white rounded-2xl shadow-xl shadow-indigo-900/40"><Layout size={32}/></div>
           <div>
             <h1 className="text-2xl font-black uppercase italic tracking-tighter leading-none">Secretaria Master EB-AD</h1>
             <p className="text-[10px] text-indigo-400 font-bold uppercase tracking-[0.4em] mt-2 italic">Governança Acadêmica v4.0</p>
           </div>
        </div>
        <div className="flex bg-slate-800/50 p-1.5 rounded-2xl border border-white/5 backdrop-blur-md">
           {(['atendimento', 'chat', 'arquivos', 'operacional'] as any).map((t:any) => (
             <button key={t} onClick={() => { setActiveTab(t); setOpSubView('main'); setSelectedTicketId(null); }} className={`px-8 py-3 rounded-xl text-[10px] font-black uppercase italic tracking-widest transition-all ${activeTab === t ? 'bg-white text-slate-950 shadow-xl' : 'text-slate-500 hover:text-white hover:bg-white/5'}`}>{t}</button>
           ))}
        </div>
      </header>

      {/* KPI DASHBOARD */}
      <div className="grid grid-cols-2 md:grid-cols-4 gap-4">
         {[
           { label: 'Aguardando', value: stats.abertos, color: 'border-l-amber-500', icon: <Clock size={16}/> },
           { label: 'Finalizados', value: stats.finalizados, color: 'border-l-indigo-600', icon: <CheckCircle2 size={16}/> },
           { label: 'Matrículas', value: stats.pendentesVal, color: 'border-l-rose-600', icon: <UserCheck size={16}/> },
