              </div>
            </div>
            <button onClick={() => setIsRegisterModalOpen(false)} className="p-4 bg-white/5 rounded-full hover:bg-rose-600 transition-all"><X size={28}/></button>
          </header>

          <div className="bg-white pb-40">
            <form onSubmit={handleSave} className="max-w-6xl mx-auto py-20 px-10 space-y-20">
