                   <span className="text-4xl font-black text-slate-100 italic select-none">01</span>
                   <h3 className="text-xs font-black uppercase italic tracking-[0.2em] text-slate-800">Prontuário de Identificação</h3>
                </div>
                <div className="grid grid-cols-1 lg:grid-cols-4 gap-16">
                   <div className="lg:col-span-1 flex flex-col items-center gap-6">
                      <div onClick={() => fileInputRef.current?.click()} className="w-56 h-56 bg-slate-50 border-4 border-dashed border-slate-200 flex items-center justify-center cursor-pointer overflow-hidden relative group rounded-[3rem] shadow-inner hover:border-indigo-400 transition-all">
                        {formData.fotoUrl ? <img src={formData.fotoUrl} className="w-full h-full object-cover" /> : <div className="text-center p-8 opacity-20"><Camera size={48} className="mx-auto mb-3 text-indigo-600"/><span className="text-[9px] font-black uppercase tracking-widest italic">Capturar Foto</span></div>}
                      </div>
                      <input type="file" ref={fileInputRef} className="hidden" accept="image/*" onChange={(e) => {
                        const reader = new FileReader();
                        reader.onload = (ev) => setFormData({...formData, fotoUrl: ev.target?.result as string});
                        reader.readAsDataURL(e.target.files![0]);
                      }} />
