                   <div className="lg:col-span-3 grid grid-cols-1 sm:grid-cols-2 gap-x-12 gap-y-8 text-slate-900">
                      <div className="space-y-2"><label className="text-[10px] font-black uppercase text-slate-400 italic ml-2">Nome Completo</label><input required value={formData.nome} onChange={e => setFormData({...formData, nome: e.target.value})} className="w-full bg-slate-50 border-none rounded-2xl p-5 text-sm font-bold shadow-inner outline-none focus:ring-2 focus:ring-indigo-600" /></div>
                      <div className="space-y-2"><label className="text-[10px] font-black uppercase text-slate-400 italic ml-2">WhatsApp Oficial</label><input required value={formData.telefone} onChange={e => setFormData({...formData, telefone: e.target.value})} className="w-full bg-slate-50 border-none rounded-2xl p-5 text-sm font-bold shadow-inner outline-none focus:ring-2 focus:ring-indigo-600" placeholder="(00) 00000-0000" /></div>
                      <div className="space-y-2"><label className="text-[10px] font-black uppercase text-slate-400 italic ml-2">Documento CPF</label><input required value={formData.cpf} onChange={e => setFormData({...formData, cpf: e.target.value})} className="w-full bg-slate-50 border-none rounded-2xl p-5 text-sm font-bold shadow-inner outline-none focus:ring-2 focus:ring-indigo-600" /></div>
