          </header>
          <div className="bg-white border border-slate-200 p-6 rounded-[2.5rem] flex flex-col md:flex-row items-center gap-4 shadow-sm">
            <div className="relative flex-1 w-full"><Search size={18} className="absolute left-5 top-1/2 -translate-y-1/2 text-slate-400" /><input value={searchTerm} onChange={e => setSearchTerm(e.target.value)} placeholder="Pesquisar por nome, matrícula ou login..." className="w-full pl-14 pr-6 py-4 bg-slate-50 border-none rounded-2xl text-xs font-bold shadow-inner outline-none focus:ring-1 focus:ring-indigo-600 italic transition-all" /></div>
          </div>
          <div className="bg-white border border-slate-200 rounded-[3rem] overflow-hidden shadow-xl">
            <table className="w-full text-left border-collapse text-slate-900">
              <thead className="bg-slate-50 border-b border-slate-100 text-[10px] font-black uppercase text-slate-400 italic tracking-widest">
                <tr><th className="px-8 py-5">Matrícula</th><th className="px-8 py-5">Nome do Aluno</th><th className="px-8 py-5">Login Acadêmico</th><th className="px-8 py-5 text-center">Status</th><th className="px-8 py-5 text-center">Ações</th></tr>
              </thead>
              <tbody className="text-xs">
                {filtered.map(s => (
                  <tr key={s.uid} className="border-b border-slate-50 hover:bg-indigo-50/20 transition-all group">
