                    <td className="px-8 py-6 text-center flex justify-center gap-2">
                        <button className="p-3 bg-slate-50 text-slate-400 hover:text-indigo-600 hover:bg-white rounded-xl transition-all shadow-sm"><Eye size={16}/></button>
