                             <span className="text-[8px] font-black text-slate-400 uppercase mt-2 px-4 tracking-widest italic">{m.sender} • {m.timestamp?.seconds ? new Date(m.timestamp.seconds*1000).toLocaleTimeString([], {hour:'2-digit', minute:'2-digit'}) : 'Agora'}</span>
                          </div>
                        ))}
                        <div ref={chatEndRef} />
                     </div>

                     <div className="p-8 border-t border-slate-100 bg-white shadow-2xl">
                        <div className="flex items-center gap-4 bg-slate-50 p-2 rounded-[2.5rem] border border-slate-100 shadow-inner">
