                           <button onClick={handleSendMessage} className="p-5 bg-slate-950 text-white rounded-full shadow-2xl hover:bg-indigo-600 transition-all active:scale-95"><Send size={24}/></button>
                        </div>
                     </div>
                   </>
                 ) : (
                   <div className="flex-1 flex flex-col items-center justify-center opacity-10 text-center gap-6 select-none grayscale">
                      <MessageSquare size={150}/>
                      <h2 className="text-2xl font-black uppercase italic tracking-[1em]">MESSENGER</h2>
                   </div>
                 )}
              </div>
           </div>
         )}

         {activeTab === 'arquivos' && (
            <div className="bg-white border border-slate-200 rounded-[3rem] h-full flex flex-col overflow-hidden shadow-sm">
