      {isSignModalOpen && <SignaturePad title="Certificação Digital do Secretário" onCancel={() => setIsSignModalOpen(false)} onSave={async b => { await updateDoc(doc(db, 'users', user.uid), {signatureUrl: b}); setSecSignature(b); setIsSignModalOpen(false); alert('Selo Digital Master Atualizado!'); }} />}
