export default SecretariatView;

import React, { useState, useEffect, useMemo, useRef } from 'react';
import { 
  collection, query, onSnapshot, addDoc, updateDoc, 
  doc, serverTimestamp, orderBy, where, deleteDoc, getDoc, getDocs
} from "https://www.gstatic.com/firebasejs/10.7.1/firebase-firestore.js";
import { db } from '../firebase';
import { User } from '../types';
import { 
  MessageSquare, Search, Plus, X, Folder, FileText, Download, 
  Trash2, RotateCcw, Archive, CheckCircle2, FileDown, Paperclip, 
  ImageIcon, Printer, UserCheck, ArrowRightLeft, Database, Clock
} from 'lucide-react';
import { jsPDF } from 'jspdf';
import html2canvas from 'html2canvas';

interface SecretariatViewProps { user: User; }
type SecretariatTab = 'atendimento' | 'chat' | 'arquivos' | 'operacional';
type ChatFilter = 'abertos' | 'finalizados' | 'arquivados';

const SecretariatView: React.FC<SecretariatViewProps> = ({ user }) => {
  const [activeTab, setActiveTab] = useState<SecretariatTab>('atendimento');
  const [chatFilter, setChatFilter] = useState<ChatFilter>('abertos');
  const [tickets, setTickets] = useState<any[]>([]);
  const [files, setFiles] = useState<any[]>([]);
  const [students, setStudents] = useState<any[]>([]);
  const [courses, setCourses] = useState<any[]>([]);
  const [searchTerm, setSearchTerm] = useState('');
  const [selectedTicketId, setSelectedTicketId] = useState<string | null>(null);
  const [chatHistory, setChatHistory] = useState<any[]>([]);
  const [chatMessage, setChatMessage] = useState('');

  const [currentFolder, setCurrentFolder] = useState<string | null>(null);
  const [isGeneratingDoc, setIsGeneratingDoc] = useState(false);
  const [selectedStudentForDoc, setSelectedStudentForDoc] = useState<string>('');

  const [signatures, setSignatures] = useState({ director: '', secretary: '' });

  const chatEndRef = useRef<HTMLDivElement>(null);
  const fileInputRef = useRef<HTMLInputElement>(null);
  const docRef = useRef<HTMLDivElement>(null);

  useEffect(() => {
    const unsubT = onSnapshot(query(collection(db, 'tickets'), orderBy('lastUpdate', 'desc')), s => {
      setTickets(s.docs.map(d => ({ id: d.id, ...d.data() })));
    });
    const unsubF = onSnapshot(collection(db, 'secretaria_arquivos'), s => setFiles(s.docs.map(d => ({ id: d.id, ...d.data() }))));
    const unsubS = onSnapshot(query(collection(db, 'users'), where('role', '==', 'aluno')), s => setStudents(s.docs.map(d => ({ uid: d.id, ...d.data() }))));
    const unsubC = onSnapshot(collection(db, 'cursos'), s => setCourses(s.docs.map(d => ({ id: d.id, ...d.data() }))));

    // Fetch Signatures
    getDocs(query(collection(db, 'users'), where('role', 'in', ['diretor', 'secretaria']))).then(snap => {
      const sigs = { director: '', secretary: '' };
      snap.docs.forEach(d => {
        const data = d.data();
        if (data.role === 'diretor') sigs.director = data.signatureUrl;
        if (data.role === 'secretaria') sigs.secretary = data.signatureUrl;
      });
      setSignatures(sigs);
    });

    return () => { unsubT(); unsubF(); unsubS(); unsubC(); };
  }, []);

  useEffect(() => {
    if (!selectedTicketId) return;
    const unsubChat = onSnapshot(query(collection(db, `tickets/${selectedTicketId}/messages`), orderBy('timestamp', 'asc')), (snap) => {
      setChatHistory(snap.docs.map(d => d.data()));
      setTimeout(() => chatEndRef.current?.scrollIntoView({ behavior: 'smooth' }), 100);
    });
    return () => unsubChat();
  }, [selectedTicketId]);

  const handleSendMessage = async (attachment?: { url: string, name: string, type: string }) => {
    if (!selectedTicketId || (!chatMessage.trim() && !attachment)) return;
    const msg = { 
      text: chatMessage, 
      sender: 'Secretaria', 
      timestamp: serverTimestamp(),
      attachment: attachment || null
    };
    await addDoc(collection(db, `tickets/${selectedTicketId}/messages`), msg);
    await updateDoc(doc(db, 'tickets', selectedTicketId), { 
      lastMessage: attachment ? `[Arquivo: ${attachment.name}]` : chatMessage, 
      lastUpdate: serverTimestamp() 
    });
    setChatMessage('');
  };

  const handleFileUpload = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (file) {
      const reader = new FileReader();
      reader.onload = (ev) => {
        handleSendMessage({
          url: ev.target?.result as string,
          name: file.name,
          type: file.type
        });
      };
      reader.readAsDataURL(file);
    }
  };

  const generatePDF = async (title: string) => {
    if (!docRef.current) return;
    setIsGeneratingDoc(true);
    const canvas = await html2canvas(docRef.current, { scale: 2 });
    const imgData = canvas.toDataURL('image/png');
    const pdf = new jsPDF('p', 'mm', 'a4');
    const imgProps = pdf.getImageProperties(imgData);
    const pdfWidth = pdf.internal.pageSize.getWidth();
    const pdfHeight = (imgProps.height * pdfWidth) / imgProps.width;
    pdf.addImage(imgData, 'PNG', 0, 0, pdfWidth, pdfHeight);
    pdf.save(`${title.toLowerCase().replace(/\s/g, '_')}_${Date.now()}.pdf`);
    setIsGeneratingDoc(false);
  };

  const filteredTickets = tickets.filter(t => {
    const matchSearch = t.protocolo?.toLowerCase().includes(searchTerm.toLowerCase()) || t.user?.toLowerCase().includes(searchTerm.toLowerCase());
    if (activeTab === 'atendimento') return matchSearch && t.status === 'Aguardando Atendente';
    if (activeTab === 'chat') {
       if (chatFilter === 'abertos') return matchSearch && (t.status === 'Em Atendimento' || t.status === 'Aguardando Atendente');
       if (chatFilter === 'finalizados') return matchSearch && t.status === 'Finalizado';
       if (chatFilter === 'arquivados') return matchSearch && t.status === 'Arquivado';
    }
    return matchSearch;
  });

  const gedFiles = currentFolder ? files.filter(f => f.category === currentFolder) : [];

  return (
    <div className="space-y-4 animate-in fade-in h-full text-[11px] font-medium tracking-tight">
      <header className="flex justify-between items-center bg-white border border-slate-200 p-4 rounded-none shadow-sm">
        <div className="flex items-center gap-3">
           <div className="p-2 bg-slate-900 text-white"><Database size={16}/></div>
           <h1 className="font-black uppercase tracking-tighter text-sm">Secretaria Master EB-AD</h1>
        </div>
        <div className="flex border border-slate-100 bg-slate-50 p-1">
           {(['atendimento', 'chat', 'arquivos', 'operacional'] as any).map((t:any) => (
