import React, { useState, useEffect, useRef } from 'react';
import { signInWithEmailAndPassword, signOut } from "https://www.gstatic.com/firebasejs/10.7.1/firebase-auth.js";
import { collection, query, where, onSnapshot, doc, setDoc, getDoc, serverTimestamp, getDocs, addDoc, orderBy } from "https://www.gstatic.com/firebasejs/10.7.1/firebase-firestore.js";
import { auth, db } from '../firebase';
import { Lock, BookOpen, Star, ChevronLeft, MessageCircle, Send, Plus, X, Phone, ThumbsUp, ThumbsDown, Info, ShieldCheck, RefreshCw } from 'lucide-react';

type ViewMode = 'landing' | 'login' | 'support_chat' | 'evaluation';

const LoginView: React.FC = () => {
  const [viewMode, setViewMode] = useState<ViewMode>('landing');
  const [email, setEmail] = useState('');
  const [password, setPassword] = useState('');
  const [loading, setLoading] = useState(false);

  // Chat States
  const [ticketId, setTicketId] = useState<string | null>(null);
  const [messages, setMessages] = useState<any[]>([]);
  const [chatMessage, setChatMessage] = useState('');
  const [botStep, setBotStep] = useState<'welcome' | 'human'>('welcome');

  // Evaluation States
  const [rating, setRating] = useState(0);
  const [feedbackText, setFeedbackText] = useState('');

  const chatEndRef = useRef<HTMLDivElement>(null);

  useEffect(() => {
    if (!ticketId) return;
    const unsub = onSnapshot(query(collection(db, `tickets/${ticketId}/messages`), orderBy('timestamp', 'asc')), (snap) => {
      const msgs = snap.docs.map(d => d.data());
      setMessages(msgs);
      setTimeout(() => chatEndRef.current?.scrollIntoView({ behavior: 'smooth' }), 100);

      // Monitor completion to trigger evaluation
      const ticketRef = doc(db, 'tickets', ticketId);
      getDoc(ticketRef).then(docSnap => {
        if (docSnap.data()?.status === 'Finalizado') setViewMode('evaluation');
      });
    });
    return () => unsub();
  }, [ticketId]);

  const handleLogin = async (e: React.FormEvent) => {
    e.preventDefault();
    setLoading(true);
    try {
      await signInWithEmailAndPassword(auth, email.trim().toLowerCase(), password);
    } catch (err) {
      alert("Credenciais inválidas.");
      setLoading(false);
    }
  };

  const startSupport = async (option?: string) => {
    const protocol = 'SUP-' + Math.random().toString(36).substring(2, 9).toUpperCase();
    const payload = {
      protocolo: protocol,
      user: 'Visitante/Aluno',
      status: 'Aguardando Atendente',
      lastUpdate: serverTimestamp(),
      createdAt: serverTimestamp(),
      type: 'Suporte Online'
    };
    const docRef = await addDoc(collection(db, 'tickets'), payload);
    setTicketId(docRef.id);

    // Bot First message
    await addDoc(collection(db, `tickets/${docRef.id}/messages`), {
      text: "Olá! Sou o assistente virtual EB-AD. Como posso ajudar agora?",
      sender: "Robô",
      timestamp: serverTimestamp()
    });

    if (option) {
      await addDoc(collection(db, `tickets/${docRef.id}/messages`), {
        text: `Desejo ajuda com: ${option}`,
        sender: "Aluno",
        timestamp: serverTimestamp()
      });
    }

    setViewMode('support_chat');
  };

  const sendMessage = async () => {
    if (!chatMessage.trim() || !ticketId) return;
    await addDoc(collection(db, `tickets/${ticketId}/messages`), {
      text: chatMessage,
      sender: "Aluno",
      timestamp: serverTimestamp()
    });
    setChatMessage('');
  };

  const submitEvaluation = async () => {
    if (!rating) return;
    await addDoc(collection(db, 'evaluations'), {
      ticketId,
      rating,
      comment: feedbackText,
      timestamp: serverTimestamp()
    });
    setViewMode('landing');
    setTicketId(null);
    alert("Obrigado pelo seu feedback acadêmico!");
  };

  if (viewMode === 'landing') {
    return (
      <div className="min-h-screen bg-slate-900 text-white font-sans flex flex-col tracking-tighter uppercase italic">
        <header className="p-6 border-b border-white/5 flex justify-between items-center">
           <div className="flex items-center gap-3"><div className="bg-indigo-600 p-2 font-black">EB-AD</div><h1 className="text-sm font-black">Escola Bíblica EAD</h1></div>
           <button onClick={() => setViewMode('login')} className="px-6 py-2 bg-white text-slate-950 font-black text-[10px]">Acessar Sistema</button>
        </header>
        <main className="flex-1 flex flex-col items-center justify-center p-8 text-center">
           <h2 className="text-6xl md:text-8xl font-black leading-none mb-6">Formação <br/> <span className="text-indigo-500">Integral</span></h2>
