                        {formData.fotoUrl ? <img src={formData.fotoUrl} className="w-full h-full object-cover" /> : <div className="text-center p-4 opacity-30"><Camera size={24} className="mx-auto mb-1"/><span className="text-[7px] font-black uppercase tracking-widest italic">Capturar Foto</span></div>}
                      </div>
                      <input type="file" ref={fileInputRef} className="hidden" accept="image/*" onChange={(e) => {
                        const reader = new FileReader();
                        reader.onload = (ev) => setFormData({...formData, fotoUrl: ev.target?.result as string});
                        reader.readAsDataURL(e.target.files![0]);
                      }} />
                   </div>
                   <div className="md:col-span-3 grid grid-cols-1 sm:grid-cols-2 gap-4 text-slate-900">
                      <div className="space-y-1"><label className="text-[8px] font-black uppercase text-slate-400 italic ml-1">Nome Completo</label><input required value={formData.nome} onChange={e => setFormData({...formData, nome: e.target.value})} className="w-full bg-slate-50 border border-slate-300 rounded-none p-2 text-[10px] font-bold outline-none" /></div>
                      <div className="space-y-1"><label className="text-[8px] font-black uppercase text-slate-400 italic ml-1">WhatsApp</label><input required value={formData.telefone} onChange={e => setFormData({...formData, telefone: e.target.value})} className="w-full bg-slate-50 border border-slate-300 rounded-none p-2 text-[10px] font-bold outline-none" /></div>
                      <div className="space-y-1"><label className="text-[8px] font-black uppercase text-slate-400 italic ml-1">Documento CPF</label><input required value={formData.cpf} onChange={e => setFormData({...formData, cpf: e.target.value})} className="w-full bg-slate-50 border border-slate-300 rounded-none p-2 text-[10px] font-bold outline-none" /></div>
                      <div className="space-y-1"><label className="text-[8px] font-black uppercase text-slate-400 italic ml-1">Data Nascimento</label><input required type="date" value={formData.nascimento} onChange={e => setFormData({...formData, nascimento: e.target.value})} className="w-full bg-slate-50 border border-slate-300 rounded-none p-2 text-[10px] font-bold outline-none" /></div>
                   </div>
                </div>
              </section>

              <section className="space-y-4">
