                        {cepLoading && <RefreshCw className="absolute right-2 top-1/2 -translate-y-1/2 animate-spin text-indigo-600" size={12}/>}
                      </div>
                   </div>
                   <div className="md:col-span-3 space-y-1"><label className="text-[8px] font-black uppercase text-slate-400 italic ml-1">Rua / Logradouro</label><input required value={formData.endereco.rua} onChange={e => setFormData({...formData, endereco: {...formData.endereco, rua: e.target.value}})} className="w-full bg-slate-50 border border-slate-300 rounded-none p-2 text-[10px] font-bold outline-none" /></div>
