                   <div className="md:col-span-2 space-y-1"><label className="text-[8px] font-black uppercase text-slate-400 italic ml-1">Bairro</label><input required value={formData.endereco.bairro} onChange={e => setFormData({...formData, endereco: {...formData.endereco, bairro: e.target.value}})} className="w-full bg-slate-50 border border-slate-300 rounded-none p-2 text-[10px] font-bold outline-none" /></div>
                   <div className="md:col-span-3 space-y-1"><label className="text-[8px] font-black uppercase text-slate-400 italic ml-1">Cidade</label><input required value={formData.endereco.cidade} onChange={e => setFormData({...formData, endereco: {...formData.endereco, cidade: e.target.value}})} className="w-full bg-slate-50 border border-slate-300 rounded-none p-2 text-[10px] font-bold outline-none" /></div>
                   <div className="md:col-span-1 space-y-1"><label className="text-[8px] font-black uppercase text-slate-400 italic ml-1">UF</label><input required maxLength={2} value={formData.endereco.uf} onChange={e => setFormData({...formData, endereco: {...formData.endereco, uf: e.target.value.toUpperCase()}})} className="w-full bg-slate-50 border border-slate-300 rounded-none p-2 text-[10px] font-black text-center" /></div>
                </div>
              </section>

              <section className="space-y-4">
                <div className="flex items-center gap-2 border-l-2 border-indigo-600 pl-4">
