                      <div className="space-y-1"><label className="text-[8px] font-black uppercase text-rose-500 italic ml-2">Senha Sincronização</label><input type="password" required={!selectedStudent} value={formData.senhaNova} onChange={e => setFormData({...formData, senhaNova: e.target.value})} className="w-full bg-rose-50 border border-rose-200 p-2 text-[10px] font-bold outline-none" placeholder="Definir..." /></div>
