                      <div className="space-y-1"><label className="text-[8px] font-black uppercase text-slate-400 italic ml-2">Backup Pessoal</label><input type="email" required value={formData.emailPessoal} onChange={e => setFormData({...formData, emailPessoal: e.target.value})} className="w-full bg-slate-50 border border-slate-300 rounded-none p-2 text-[10px] font-bold outline-none" /></div>
                   </div>
                </div>
              </section>

              <div className="flex flex-col md:flex-row items-center justify-center gap-4 pt-10 border-t border-slate-200">
                <button type="button" onClick={() => setIsRegisterModalOpen(false)} className="px-10 py-3 bg-slate-100 border border-slate-300 text-slate-400 hover:text-rose-600 rounded-none font-black uppercase tracking-widest transition-all">Descartar</button>
                <button type="submit" disabled={actionLoading} className="w-full md:max-w-xs px-10 py-3 bg-slate-900 text-white text-[10px] font-black uppercase tracking-[0.2em] shadow-lg hover:bg-indigo-600 transition-all flex items-center justify-center gap-3 rounded-none active:scale-95">
