                  <td className="px-4 py-2 text-center flex justify-center gap-1.5">
                      <button onClick={() => { setSelectedStudent(s); setFormData({ nome: s.displayName, emailPessoal: (s as any).emailPessoal || '', emailAcademico: s.email || '', telefone: (s as any).telefone || '', cursoId: (s as any).cursoInicial || '', status: s.status || 'ativo', cpf: (s as any).cpf || '', nascimento: (s as any).nascimento || '', fotoUrl: (s as any).photoURL || '', senhaNova: '', endereco: (s as any).endereco || {cep:'', rua:'', numero:'', bairro:'', cidade:'', uf:''} }); setIsRegisterModalOpen(true); }} className="p-1.5 border border-slate-200 text-slate-400 hover:text-amber-600 bg-white"><Edit3 size={14}/></button>
                      <button onClick={async () => { if(confirm('Remover aluno permanente?')) await deleteDoc(doc(db, 'users', s.uid)); }} className="p-1.5 border border-slate-200 text-slate-400 hover:text-rose-600 bg-white"><Trash2 size={14}/></button>
