import React, { useState, useEffect, useRef } from 'react';
import { signInWithEmailAndPassword, signOut } from "https://www.gstatic.com/firebasejs/10.7.1/firebase-auth.js";
// Added updateDoc to firestore imports
import { collection, query, where, onSnapshot, doc, getDoc, serverTimestamp, addDoc, orderBy, updateDoc } from "https://www.gstatic.com/firebasejs/10.7.1/firebase-firestore.js";
import { auth, db } from '../firebase';
// Added Clock to lucide-react imports
import { Lock, BookOpen, Star, ChevronLeft, MessageSquare, Send, Plus, X, Phone, ThumbsUp, ThumbsDown, Info, ShieldCheck, RefreshCw, Paperclip, Clock } from 'lucide-react';

type ViewMode = 'landing' | 'login' | 'support_chat' | 'evaluation';

const LoginView: React.FC = () => {
  const [viewMode, setViewMode] = useState<ViewMode>('landing');
  const [email, setEmail] = useState('');
  const [password, setPassword] = useState('');
  const [loading, setLoading] = useState(false);

  // Chat States
  const [ticketId, setTicketId] = useState<string | null>(null);
  const [messages, setMessages] = useState<any[]>([]);
  const [chatMessage, setChatMessage] = useState('');
  const [botActive, setBotActive] = useState(true);

  // Evaluation States
  const [rating, setRating] = useState(0);
  const [speedRating, setSpeedRating] = useState(0);
  const [platformRating, setPlatformRating] = useState(0);
  const [feedbackText, setFeedbackText] = useState('');

  const chatEndRef = useRef<HTMLDivElement>(null);
  const fileInputRef = useRef<HTMLInputElement>(null);

  useEffect(() => {
    if (!ticketId) return;
    const unsub = onSnapshot(doc(db, 'tickets', ticketId), (docSnap) => {
      if (docSnap.exists() && docSnap.data().status === 'Finalizado') {
        setViewMode('evaluation');
      }
    });

    const unsubMessages = onSnapshot(query(collection(db, `tickets/${ticketId}/messages`), orderBy('timestamp', 'asc')), (snap) => {
      setMessages(snap.docs.map(d => d.data()));
      setTimeout(() => chatEndRef.current?.scrollIntoView({ behavior: 'smooth' }), 100);
    });

    return () => { unsub(); unsubMessages(); };
  }, [ticketId]);

  const handleLogin = async (e: React.FormEvent) => {
    e.preventDefault();
    setLoading(true);
    try {
      await signInWithEmailAndPassword(auth, email.trim().toLowerCase(), password);
    } catch (err) {
      alert("Credenciais inválidas.");
      setLoading(false);
    }
  };

  const startSupport = async (option?: string) => {
    const protocol = 'SUP-' + Math.random().toString(36).substring(2, 9).toUpperCase();
    const payload = {
      protocolo: protocol,
      user: 'Visitante/Aluno',
      status: 'Bot Ativo',
      lastUpdate: serverTimestamp(),
      createdAt: serverTimestamp(),
      type: 'Suporte Online'
    };
    const docRef = await addDoc(collection(db, 'tickets'), payload);
    setTicketId(docRef.id);

    // Bot Welcome message
    await addDoc(collection(db, `tickets/${docRef.id}/messages`), {
      text: "Olá! Sou o assistente EB-AD. Como posso agilizar seu atendimento hoje?",
      sender: "Robô",
      timestamp: serverTimestamp()
    });

    if (option) {
      await addDoc(collection(db, `tickets/${docRef.id}/messages`), {
        text: `Desejo ajuda com: ${option}`,
        sender: "Aluno",
        timestamp: serverTimestamp()
      });

      // Simulação de resposta do bot
      setTimeout(async () => {
        await addDoc(collection(db, `tickets/${docRef.id}/messages`), {
          text: `Entendi. Para ${option}, você pode acessar a área correspondente no painel do aluno. Se o problema persistir, clique em 'Chamar Humano'.`,
          sender: "Robô",
          timestamp: serverTimestamp()
        });
      }, 1000);
    }

    setViewMode('support_chat');
  };

  const requestHuman = async () => {
    if (!ticketId) return;
    setBotActive(false);
    // updateDoc is now imported correctly
    await updateDoc(doc(db, 'tickets', ticketId), { status: 'Aguardando Atendente' });
    await addDoc(collection(db, `tickets/${ticketId}/messages`), {
      text: "Solicitando atendimento humano... Por favor, aguarde na linha digital.",
      sender: "Robô",
      timestamp: serverTimestamp()
    });
  };

  const sendMessage = async (attachment?: { url: string, name: string, type: string }) => {
    if (!ticketId || (!chatMessage.trim() && !attachment)) return;
    await addDoc(collection(db, `tickets/${ticketId}/messages`), {
      text: chatMessage,
      sender: "Aluno",
      timestamp: serverTimestamp(),
      attachment: attachment || null
    });
    setChatMessage('');
  };

  const handleFileUpload = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (file) {
      const reader = new FileReader();
      reader.onload = (ev) => {
        sendMessage({ url: ev.target?.result as string, name: file.name, type: file.type });
      };
      reader.readAsDataURL(file);
    }
  };

  const submitEvaluation = async () => {
    if (!rating || !speedRating || !platformRating) {
      alert("Por favor, preencha todos os campos da avaliação.");
      return;
    }
    await addDoc(collection(db, 'evaluations'), {
      ticketId,
      rating,
      speedRating,
      platformRating,
      comment: feedbackText,
      timestamp: serverTimestamp(),
      userName: 'Visitante/Aluno'
    });
    setViewMode('landing');
    setTicketId(null);
    alert("Obrigado pelo feedback acadêmico!");
  };

  if (viewMode === 'landing') {
    return (
      <div className="min-h-screen bg-slate-950 text-white font-sans flex flex-col tracking-tighter uppercase italic rounded-none">
        <header className="p-4 border-b border-white/5 flex justify-between items-center bg-black/20">
           <div className="flex items-center gap-2"><div className="bg-indigo-600 p-1.5 font-black text-xs">EB-AD</div><h1 className="text-[10px] font-black tracking-widest">Escola Bíblica EAD</h1></div>
           <button onClick={() => setViewMode('login')} className="px-4 py-1.5 bg-white text-slate-950 font-black text-[9px] rounded-none">Acessar Sistema</button>
        </header>
        <main className="flex-1 flex flex-col items-center justify-center p-6 text-center">
           <h2 className="text-5xl md:text-7xl font-black leading-none mb-4">Formação <br/> <span className="text-indigo-500">Teológica</span></h2>
           <p className="text-slate-500 text-[10px] font-bold normal-case not-italic mb-10 max-w-sm tracking-widest uppercase opacity-60">Plataforma Oficial de Governança Acadêmica v4.0</p>
           <div className="grid grid-cols-1 md:grid-cols-2 gap-2 w-full max-w-md">
              <button onClick={() => startSupport()} className="py-4 border border-white/10 hover:bg-white hover:text-slate-900 transition-all font-black text-[10px] rounded-none">Suporte Digital</button>
              <button onClick={() => setViewMode('login')} className="py-4 bg-indigo-600 font-black text-[10px] rounded-none">Nova Matrícula</button>
           </div>
        </main>
      </div>
    );
  }

  if (viewMode === 'evaluation') {
    return (
      <div className="min-h-screen bg-slate-950 flex items-center justify-center p-4 text-[10px] font-black uppercase italic tracking-tighter">
         <div className="bg-white text-slate-900 w-full max-w-md p-8 space-y-6 rounded-none border border-slate-300">
            <div className="text-center space-y-1">
               <h2 className="text-xl font-black italic">Pesquisa Acadêmica</h2>
               <p className="text-slate-400 font-bold uppercase tracking-widest">Sua opinião constrói a escola</p>
            </div>

            <div className="space-y-4">
               <div className="space-y-2">
                  <p className="text-slate-500 text-center font-bold">O atendimento foi satisfatório?</p>
                  <div className="flex justify-center gap-2">
                     {[1,2,3,4,5].map(s => (
                       <button key={s} onClick={() => setRating(s)} className={`w-8 h-8 border shadow-sm rounded-none ${rating >= s ? 'bg-indigo-600 text-white border-indigo-700' : 'bg-slate-50 text-slate-300'}`}><Star size={14} fill={rating>=s?'currentColor':'none'}/></button>
                     ))}
                  </div>
               </div>
               <div className="space-y-2">
                  <p className="text-slate-500 text-center font-bold">Agilidade no atendimento?</p>
                  <div className="flex justify-center gap-2">
                     {[1,2,3,4,5].map(s => (
                       // Clock icon is now imported correctly
                       <button key={s} onClick={() => setSpeedRating(s)} className={`w-8 h-8 border shadow-sm rounded-none ${speedRating >= s ? 'bg-amber-600 text-white border-amber-700' : 'bg-slate-50 text-slate-300'}`}><Clock size={14} fill={speedRating>=s?'currentColor':'none'}/></button>
                     ))}
                  </div>
               </div>
               <div className="space-y-2">
                  <p className="text-slate-500 text-center font-bold">Qualidade da nossa plataforma?</p>
                  <div className="flex justify-center gap-2">
                     {[1,2,3,4,5].map(s => (
                       <button key={s} onClick={() => setPlatformRating(s)} className={`w-8 h-8 border shadow-sm rounded-none ${platformRating >= s ? 'bg-emerald-600 text-white border-emerald-700' : 'bg-slate-50 text-slate-300'}`}><ShieldCheck size={14} fill={platformRating>=s?'currentColor':'none'}/></button>
                     ))}
                  </div>
               </div>
            </div>

            <div className="space-y-1">
               <p className="text-slate-400 uppercase tracking-widest font-bold ml-1">Comentário / Sugestão</p>
               <textarea value={feedbackText} onChange={e => setFeedbackText(e.target.value)} placeholder="Sua mensagem aqui..." className="w-full p-3 bg-slate-50 border border-slate-300 h-20 font-bold outline-none shadow-inner resize-none text-[10px] rounded-none"></textarea>
            </div>

            <button onClick={submitEvaluation} className="w-full py-3 bg-slate-900 text-white font-black uppercase hover:bg-emerald-600 transition-colors rounded-none shadow-lg">Finalizar Avaliação Master</button>
         </div>
      </div>
    );
  }

  if (viewMode === 'support_chat') {
    return (
      <div className="min-h-screen bg-slate-950 flex items-center justify-center p-2">
        <div className="bg-white w-full max-w-3xl h-[550px] flex flex-col text-[10px] uppercase italic font-black tracking-tighter overflow-hidden rounded-none border border-slate-300">
          <header className="p-3 bg-slate-900 text-white flex justify-between items-center border-b border-white/5">
             <div className="flex items-center gap-2"><MessageCircle size={14} className="text-indigo-400"/><h3 className="font-black tracking-widest">Secretaria Online Master</h3></div>
             <button onClick={() => setViewMode('landing')} className="p-1 hover:bg-rose-600 transition-all border border-white/10 rounded-none"><X size={14}/></button>
          </header>
          <div className="flex-1 overflow-y-auto p-4 bg-slate-50/50 space-y-3 custom-scrollbar">
             {messages.map((m, i) => (
               <div key={i} className={`flex flex-col ${m.sender === 'Aluno' ? 'items-end' : 'items-start'}`}>
                  <div className={`max-w-[75%] p-2 border shadow-none rounded-none ${m.sender === 'Aluno' ? 'bg-slate-900 text-white border-slate-900' : 'bg-white text-slate-800 border-slate-300'}`}>
                     <p className="font-bold normal-case not-italic text-[10px] leading-tight italic">"{m.text}"</p>
                     {m.attachment && (
                        <div className="mt-1 border border-indigo-200/30 p-1 bg-black/5">
                          <img src={m.attachment.url} className="max-w-full grayscale brightness-90 hover:grayscale-0 transition-all" />
                          <p className="text-[7px] mt-0.5 opacity-50">{m.attachment.name}</p>
                        </div>
                     )}
                  </div>
                  <span className="text-[7px] font-black text-slate-400 mt-0.5 uppercase">{m.sender}</span>
               </div>
             ))}
             <div ref={chatEndRef} />
          </div>

          {botActive && (
            <div className="p-3 bg-white border-t border-slate-200 grid grid-cols-2 md:grid-cols-5 gap-1.5">
               {['Acesso', 'Financeiro', 'Notas', 'Diplomas', 'Outros'].map(opt => (
                 <button key={opt} onClick={() => startSupport(opt)} className="py-1.5 border border-slate-300 hover:bg-indigo-600 hover:text-white transition-all text-[8px] font-black uppercase rounded-none">{opt}</button>
               ))}
               <button onClick={requestHuman} className="col-span-full py-1.5 bg-amber-50 text-amber-700 border border-amber-300 hover:bg-amber-600 hover:text-white font-black text-[8px] uppercase mt-1 rounded-none">Chamar Humano</button>
            </div>
          )}

          <div className="p-2 border-t border-slate-200 bg-white">
             <div className="flex items-center gap-1 border border-slate-300 p-0.5 bg-slate-50 rounded-none">
                <button onClick={() => fileInputRef.current?.click()} className="p-1.5 text-slate-400 hover:text-indigo-600"><Paperclip size={16}/></button>
