                <button onClick={() => sendMessage()} className="p-1.5 bg-slate-900 text-white hover:bg-indigo-600 rounded-none transition-all"><Send size={16}/></button>
             </div>
             <input type="file" ref={fileInputRef} className="hidden" onChange={handleFileUpload} />
          </div>
        </div>
      </div>
    );
  }

  return (
    <div className="min-h-screen bg-slate-950 flex items-center justify-center p-4 uppercase font-black italic tracking-tighter">
       <div className="bg-white w-full max-sm-p-8 space-y-8 rounded-none border border-slate-300 p-8">
          <div className="flex flex-col items-center gap-3">
             <div className="p-3 bg-indigo-600 text-white rounded-none"><Lock size={24}/></div>
             <h2 className="text-xl font-black">Login Acadêmico</h2>
          </div>
          <form onSubmit={handleLogin} className="space-y-4">
             <div className="space-y-1"><label className="text-[9px] text-slate-400 font-bold ml-1">E-mail de Acesso</label><input type="email" value={email} onChange={e => setEmail(e.target.value)} className="w-full p-3 bg-slate-50 border border-slate-300 font-bold outline-none shadow-inner text-[10px] rounded-none" /></div>
