import React, { useState, useEffect, useRef } from 'react';
import { signInWithEmailAndPassword } from "https://www.gstatic.com/firebasejs/10.7.1/firebase-auth.js";
import { collection, query, onSnapshot, doc, serverTimestamp, addDoc, orderBy, updateDoc, getDoc } from "https://www.gstatic.com/firebasejs/10.7.1/firebase-firestore.js";
import { auth, db } from '../firebase';
import { Lock, Star, MessageCircle, Send, X, ShieldCheck, RefreshCw, Paperclip, Clock, GraduationCap, ChevronRight } from 'lucide-react';

type PortalMode = 'student' | 'admin';
type ViewMode = 'landing' | 'login' | 'support_chat' | 'evaluation';

const LoginView: React.FC = () => {
  const [portal, setPortal] = useState<PortalMode>('student');
  const [viewMode, setViewMode] = useState<ViewMode>('landing');
  const [email, setEmail] = useState('');
  const [password, setPassword] = useState('');
  const [loading, setLoading] = useState(false);

  const [ticketId, setTicketId] = useState<string | null>(null);
  const [messages, setMessages] = useState<any[]>([]);
  const [chatMessage, setChatMessage] = useState('');
  const [botActive, setBotActive] = useState(true);

  const [rating, setRating] = useState(0);
  const [feedbackText, setFeedbackText] = useState('');

  const chatEndRef = useRef<HTMLDivElement>(null);
  const fileInputRef = useRef<HTMLInputElement>(null);

  useEffect(() => {
    if (!ticketId) return;
    const unsub = onSnapshot(doc(db, 'tickets', ticketId), (snap) => {
      if (snap.exists() && snap.data().status === 'Finalizado') setViewMode('evaluation');
    });
    const unsubMsgs = onSnapshot(query(collection(db, `tickets/${ticketId}/messages`), orderBy('timestamp', 'asc')), (snap) => {
      setMessages(snap.docs.map(d => d.data()));
      setTimeout(() => chatEndRef.current?.scrollIntoView({ behavior: 'smooth' }), 100);
    });
    return () => { unsub(); unsubMsgs(); };
  }, [ticketId]);

  const handleLogin = async (e: React.FormEvent) => {
    e.preventDefault();
    setLoading(true);
    try {
      await signInWithEmailAndPassword(auth, email.trim().toLowerCase(), password);
    } catch (err) {
      alert("Credenciais inválidas para este portal.");
      setLoading(false);
    }
  };

  const startSupport = async (option?: string) => {
    const protocol = 'SUP-' + Math.random().toString(36).substring(2, 9).toUpperCase();
    const docRef = await addDoc(collection(db, 'tickets'), {
      protocolo: protocol,
      user: 'Visitante/Aluno',
      status: 'Bot Ativo',
      lastUpdate: serverTimestamp(),
      createdAt: serverTimestamp(),
      type: 'Suporte Online'
    });
    setTicketId(docRef.id);
    await addDoc(collection(db, `tickets/${docRef.id}/messages`), {
      text: "Olá! Sou o assistente EB-AD. Como posso ajudar?",
      sender: "Robô",
      timestamp: serverTimestamp()
    });
    setViewMode('support_chat');
  };

  const requestHuman = async () => {
    if (!ticketId) return;
    setBotActive(false);
    await updateDoc(doc(db, 'tickets', ticketId), { status: 'Aguardando Atendente' });
    await addDoc(collection(db, `tickets/${ticketId}/messages`), {
      text: "Chamando um atendente humano... Aguarde.",
      sender: "Robô",
      timestamp: serverTimestamp()
    });
  };

  const sendMessage = async (attachment?: any) => {
    if (!ticketId || (!chatMessage.trim() && !attachment)) return;
    await addDoc(collection(db, `tickets/${ticketId}/messages`), {
      text: chatMessage,
      sender: "Aluno",
      timestamp: serverTimestamp(),
      attachment: attachment || null
    });
    setChatMessage('');
  };

  // PORTAL DO ALUNO - CAPTAÇÃO ELEGANTE
  if (portal === 'student' && viewMode === 'landing') {
    return (
      <div className="min-h-screen bg-white flex flex-col font-sans overflow-x-hidden">
        <header className="p-6 flex justify-between items-center bg-white/80 backdrop-blur-md sticky top-0 z-50 border-b border-slate-100">
           <div className="flex items-center gap-3">
              <div className="bg-slate-900 text-white p-2 font-black text-xs tracking-tighter">EB-AD</div>
              <h1 className="text-sm font-black uppercase tracking-widest text-slate-900 italic">Escola Bíblica</h1>
           </div>
           <button onClick={() => setViewMode('login')} className="px-6 py-2 bg-slate-900 text-white font-black text-[10px] uppercase tracking-widest hover:bg-indigo-600 transition-all">Entrar na Sala</button>
        </header>

        <main className="flex-1 relative flex items-center justify-center">
           <div className="absolute inset-0 z-0">
              <img src="https://images.unsplash.com/photo-1523240795612-9a054b0db644?auto=format&fit=crop&q=80" className="w-full h-full object-cover brightness-[0.4] grayscale-[0.3]" />
           </div>
           <div className="relative z-10 text-center max-w-4xl px-6 space-y-8 animate-in fade-in duration-1000">
