                  <div className="flex justify-center gap-2">
                     {[1,2,3,4,5].map(s => <button key={s} onClick={() => setRating(s)} className={`w-8 h-8 border ${rating >= s ? 'bg-indigo-600 text-white' : 'bg-slate-50 text-slate-300'}`}><Star size={14} fill={rating>=s?'currentColor':'none'}/></button>)}
                  </div>
                  <textarea value={feedbackText} onChange={e => setFeedbackText(e.target.value)} placeholder="Comentário opcional..." className="w-full p-3 bg-slate-50 border border-slate-300 h-20 outline-none shadow-inner text-[10px]"></textarea>
