               <div>
                  <h2 className="text-xl font-black uppercase italic tracking-tighter">{isAdmin ? 'Acesso Administrativo' : 'Portal do Aluno'}</h2>
                  <p className="text-[9px] text-slate-400 font-bold uppercase tracking-[0.3em] mt-1">Sincronização EB-AD v4.0</p>
               </div>
