            <form onSubmit={handleLogin} className="space-y-4">
               <div className="space-y-1"><label className="text-[8px] font-black text-slate-400 uppercase tracking-widest ml-1">E-mail Corporativo</label><input type="email" value={email} onChange={e => setEmail(e.target.value)} className="w-full p-3 bg-slate-50 border border-slate-200 font-bold outline-none text-[10px]" /></div>
               <div className="space-y-1"><label className="text-[8px] font-black text-slate-400 uppercase tracking-widest ml-1">Senha de Segurança</label><input type="password" value={password} onChange={e => setPassword(e.target.value)} className="w-full p-3 bg-slate-50 border border-slate-200 font-bold outline-none text-[10px]" /></div>
               <button disabled={loading} className="w-full py-4 bg-slate-900 text-white font-black uppercase tracking-widest hover:bg-indigo-600 transition-all flex items-center justify-center gap-2">
                 {loading ? <RefreshCw className="animate-spin" size={16}/> : <><ShieldCheck size={16}/> Autenticar Acesso</>}
               </button>
               <button type="button" onClick={() => { setViewMode('landing'); setPortal('student'); }} className="w-full text-center text-slate-400 text-[8px] font-bold underline uppercase tracking-widest">Voltar para Início</button>
            </form>
         </div>
      </div>
    );
  }

  return null;
};

