import React, { useState, useEffect, useMemo, useRef } from 'react';
import { collection, query, onSnapshot, addDoc, updateDoc, doc, serverTimestamp, orderBy, where, deleteDoc, getDoc, getDocs } from "https://www.gstatic.com/firebasejs/10.7.1/firebase-firestore.js";
import { db } from '../firebase';
import { User } from '../types';
import { MessageSquare, Search, Plus, X, Folder, FileText, Download, Trash2, RotateCcw, Archive, CheckCircle2, FileDown, Paperclip, ImageIcon, Printer, UserCheck, ArrowRightLeft, Database, Clock, Fingerprint } from 'lucide-react';
import { jsPDF } from 'jspdf';
import html2canvas from 'html2canvas';

interface SecretariatViewProps { user: User; }
type SecretariatTab = 'atendimento' | 'chat' | 'arquivos' | 'operacional';
type OperationalView = 'main' | 'validacao' | 'transferencia' | 'assinatura';
type ChatFilter = 'abertos' | 'finalizados' | 'arquivados';

const SecretariatView: React.FC<SecretariatViewProps> = ({ user }) => {
  const [activeTab, setActiveTab] = useState<SecretariatTab>('atendimento');
  const [opView, setOpView] = useState<OperationalView>('main');
  const [chatFilter, setChatFilter] = useState<ChatFilter>('abertos');
  const [tickets, setTickets] = useState<any[]>([]);
  const [files, setFiles] = useState<any[]>([]);
  const [students, setStudents] = useState<any[]>([]);
  const [courses, setCourses] = useState<any[]>([]);
  const [searchTerm, setSearchTerm] = useState('');
  const [selectedTicketId, setSelectedTicketId] = useState<string | null>(null);
  const [chatHistory, setChatHistory] = useState<any[]>([]);
  const [chatMessage, setChatMessage] = useState('');
  const [currentFolder, setCurrentFolder] = useState<string | null>(null);
  const [signatures, setSignatures] = useState({ director: '', secretary: '' });

  const chatEndRef = useRef<HTMLDivElement>(null);
  const fileInputRef = useRef<HTMLInputElement>(null);

  useEffect(() => {
    const unsubT = onSnapshot(query(collection(db, 'tickets'), orderBy('lastUpdate', 'desc')), s => setTickets(s.docs.map(d => ({ id: d.id, ...d.data() }))));
    const unsubF = onSnapshot(collection(db, 'secretaria_arquivos'), s => setFiles(s.docs.map(d => ({ id: d.id, ...d.data() }))));
    const unsubS = onSnapshot(query(collection(db, 'users'), where('role', '==', 'aluno')), s => setStudents(s.docs.map(d => ({ uid: d.id, ...d.data() }))));
    const unsubC = onSnapshot(collection(db, 'cursos'), s => setCourses(s.docs.map(d => ({ id: d.id, ...d.data() }))));
    getDocs(query(collection(db, 'users'), where('role', 'in', ['diretor', 'secretaria']))).then(snap => {
      const sigs = { director: '', secretary: '' };
      snap.docs.forEach(d => {
        if (d.data().role === 'diretor') sigs.director = d.data().signatureUrl;
        if (d.data().role === 'secretaria') sigs.secretary = d.data().signatureUrl;
      });
      setSignatures(sigs);
    });
    return () => { unsubT(); unsubF(); unsubS(); unsubC(); };
  }, []);

  useEffect(() => {
    if (!selectedTicketId) return;
    const unsubChat = onSnapshot(query(collection(db, `tickets/${selectedTicketId}/messages`), orderBy('timestamp', 'asc')), (snap) => {
      setChatHistory(snap.docs.map(d => d.data()));
      setTimeout(() => chatEndRef.current?.scrollIntoView({ behavior: 'smooth' }), 100);
    });
    return () => unsubChat();
  }, [selectedTicketId]);

  const handleSendMessage = async (attachment?: any) => {
    if (!selectedTicketId || (!chatMessage.trim() && !attachment)) return;
    const msg = { text: chatMessage, sender: 'Secretaria', timestamp: serverTimestamp(), attachment: attachment || null };
    await addDoc(collection(db, `tickets/${selectedTicketId}/messages`), msg);
    await updateDoc(doc(db, 'tickets', selectedTicketId), { lastMessage: attachment ? `[Anexo: ${attachment.name}]` : chatMessage, lastUpdate: serverTimestamp() });
    setChatMessage('');
  };

  const filteredTickets = tickets.filter(t => {
    const matchSearch = t.protocolo?.toLowerCase().includes(searchTerm.toLowerCase()) || t.user?.toLowerCase().includes(searchTerm.toLowerCase());
    if (activeTab === 'atendimento') return matchSearch && t.status === 'Aguardando Atendente';
    if (activeTab === 'chat') {
       if (chatFilter === 'abertos') return matchSearch && (t.status === 'Em Atendimento' || t.status === 'Aguardando Atendente');
       if (chatFilter === 'finalizados') return matchSearch && t.status === 'Finalizado';
       if (chatFilter === 'arquivados') return matchSearch && t.status === 'Arquivado';
    }
    return matchSearch;
  });

  const pendingValCount = students.filter(s => s.status === 'aguardando_validacao').length;

  return (
    <div className="space-y-4 animate-in fade-in h-full text-[10px] font-medium tracking-tighter uppercase italic">
      <header className="flex justify-between items-center bg-white border border-slate-300 p-2 shadow-sm">
        <div className="flex items-center gap-2">
           <div className="p-1.5 bg-slate-900 text-white"><Database size={14}/></div>
           <h1 className="font-black text-xs">Secretaria Virtual Master</h1>
        </div>
        <div className="flex border border-slate-200 bg-slate-50 p-0.5">
           {(['atendimento', 'chat', 'arquivos', 'operacional'] as any).map((t:any) => (
             <button key={t} onClick={() => { setActiveTab(t); setOpView('main'); setSelectedTicketId(null); }} className={`px-4 py-1.5 font-black transition-all ${activeTab === t ? 'bg-white text-slate-950 border border-slate-200' : 'text-slate-400'}`}>{t}</button>
           ))}
        </div>
      </header>

      <main className="min-h-[500px]">
        {activeTab === 'atendimento' && (
          <div className="bg-white border border-slate-300">
            <div className="p-3 bg-slate-50 border-b border-slate-300 flex justify-between items-center">
               <span className="font-black text-slate-500">Fila Global de Chamados</span>
               <div className="relative"><Search className="absolute left-2 top-1/2 -translate-y-1/2 text-slate-300" size={12}/><input value={searchTerm} onChange={e => setSearchTerm(e.target.value)} placeholder="Pesquisar..." className="pl-7 pr-2 py-1 border border-slate-300 bg-white text-[9px] w-48 font-bold outline-none" /></div>
            </div>
            <table className="w-full text-left border-collapse">
               <thead className="bg-slate-50 text-[9px] font-black text-slate-400 border-b border-slate-300 uppercase">
                  <tr><th className="px-4 py-2 border-r border-slate-200">Protocolo</th><th className="px-4 py-2 border-r border-slate-200">Solicitante</th><th className="px-4 py-2 border-r border-slate-200">Status</th><th className="px-4 py-2 text-center">Gestão</th></tr>
               </thead>
               <tbody className="divide-y divide-slate-200 text-[10px] font-bold text-slate-700">
                  {filteredTickets.map(t => (
                    <tr key={t.id} className="hover:bg-slate-50 transition-colors">
                       <td className="px-4 py-2.5 font-mono text-indigo-600 border-r border-slate-200">{t.protocolo}</td>
                       <td className="px-4 py-2.5 border-r border-slate-200">{t.user}</td>
                       <td className="px-4 py-2.5 border-r border-slate-200"><span className="px-1.5 py-0.5 bg-amber-50 text-amber-600 border border-amber-200 text-[8px]">{t.status}</span></td>
                       <td className="px-4 py-2.5 text-center"><button onClick={async () => { await updateDoc(doc(db, 'tickets', t.id), {status: 'Em Atendimento'}); setSelectedTicketId(t.id); setActiveTab('chat'); setChatFilter('abertos'); }} className="bg-slate-900 text-white px-4 py-1 hover:bg-indigo-600 transition-all font-black text-[9px]">Assumir</button></td>
                    </tr>
                  ))}
               </tbody>
            </table>
          </div>
        )}

        {activeTab === 'operacional' && (
          <div className="space-y-4">
             {opView === 'main' && (
               <div className="grid grid-cols-1 md:grid-cols-4 gap-4">
                  <button onClick={() => setOpView('validacao')} className="bg-white p-8 border border-slate-300 text-center hover:bg-indigo-600 hover:text-white transition-all group relative">
                    <UserCheck size={32} className="mx-auto mb-3 text-slate-300 group-hover:text-white" />
                    <span className="font-black uppercase text-[10px]">Auditoria de Matrículas</span>
                    {pendingValCount > 0 && <span className="absolute top-4 right-4 bg-rose-600 text-white w-6 h-6 flex items-center justify-center font-black text-[10px]">{pendingValCount}</span>}
                  </button>
                  <button onClick={() => setOpView('transferencia')} className="bg-white p-8 border border-slate-300 text-center hover:bg-indigo-600 hover:text-white transition-all group">
                    <ArrowRightLeft size={32} className="mx-auto mb-3 text-slate-300 group-hover:text-white" />
                    <span className="font-black uppercase text-[10px]">Transferência Acadêmica</span>
                  </button>
                  <button onClick={() => alert('Gerador de Histórico em PDF')} className="bg-white p-8 border border-slate-300 text-center hover:bg-indigo-600 hover:text-white transition-all group">
                    <Printer size={32} className="mx-auto mb-3 text-slate-300 group-hover:text-white" />
                    <span className="font-black uppercase text-[10px]">Gerar Documento PDF</span>
                  </button>
                  <button onClick={() => setOpView('assinatura')} className="bg-white p-8 border border-slate-300 text-center hover:bg-indigo-600 hover:text-white transition-all group">
                    <Fingerprint size={32} className="mx-auto mb-3 text-slate-300 group-hover:text-white" />
                    <span className="font-black uppercase text-[10px]">Assinatura Digital</span>
                  </button>
               </div>
             )}

             {opView === 'validacao' && (
                <div className="bg-white border border-slate-300 overflow-hidden animate-in fade-in">
                   <header className="p-3 bg-slate-900 text-white flex justify-between items-center">
                      <span className="font-black text-[10px]">Aguardando Validação Institucional</span>
                      <button onClick={() => setOpView('main')} className="p-1 hover:bg-white/10"><X size={14}/></button>
                   </header>
                   <table className="w-full text-left">
                      <thead className="bg-slate-50 text-[9px] font-black text-slate-400 border-b border-slate-300">
                         <tr><th className="px-4 py-2 border-r border-slate-200">Aluno Captado</th><th className="px-4 py-2 border-r border-slate-200">Curso Pretendido</th><th className="px-4 py-2 text-center">Ação Operacional</th></tr>
                      </thead>
                      <tbody className="divide-y divide-slate-200 text-[10px] font-bold">
                         {students.filter(s => s.status === 'aguardando_validacao').map(s => (
                           <tr key={s.uid} className="hover:bg-slate-50">
                              <td className="px-4 py-2 border-r border-slate-200">{s.displayName}</td>
                              <td className="px-4 py-2 border-r border-slate-200 uppercase text-indigo-600 italic">Teologia Básica</td>
                              <td className="px-4 py-2 text-center flex justify-center gap-2">
                                 <button onClick={() => updateDoc(doc(db, 'users', s.uid), {status: 'ativo'})} className="px-4 py-1 bg-emerald-600 text-white font-black text-[9px]">Deferir</button>
                                 <button onClick={() => deleteDoc(doc(db, 'users', s.uid))} className="px-4 py-1 bg-rose-600 text-white font-black text-[9px]">Indeferir</button>
                              </td>
                           </tr>
                         ))}
                         {students.filter(s => s.status === 'aguardando_validacao').length === 0 && <tr><td colSpan={3} className="p-10 text-center text-slate-300 italic">Sem pendências de matrícula.</td></tr>}
                      </tbody>
                   </table>
                </div>
             )}
          </div>
        )}

        {activeTab === 'chat' && (
          <div className="grid grid-cols-12 gap-2 h-[550px]">
             <div className="col-span-3 bg-white border border-slate-300 flex flex-col overflow-hidden">
                <div className="flex border-b border-slate-300 bg-slate-50 p-0.5">
                   {(['abertos', 'finalizados', 'arquivados'] as any).map((f:any) => (
                     <button key={f} onClick={() => setChatFilter(f)} className={`flex-1 py-1.5 text-[8px] font-black uppercase ${chatFilter === f ? 'bg-white text-slate-900 border border-slate-300 shadow-sm' : 'text-slate-400'}`}>{f}</button>
                   ))}
                </div>
                <div className="flex-1 overflow-y-auto p-1 space-y-1 bg-slate-50/50">
                   {filteredTickets.map(t => (
                     <div key={t.id} onClick={() => setSelectedTicketId(t.id)} className={`p-2 border transition-all cursor-pointer relative group ${selectedTicketId === t.id ? 'bg-slate-900 text-white border-slate-800' : 'bg-white border-slate-200 hover:bg-slate-50 text-slate-900 shadow-sm'}`}>
                        <p className="font-black uppercase italic truncate text-[9px]">{t.user}</p>
                        <p className="text-[8px] truncate opacity-50 italic leading-none">{t.lastMessage || '...'}</p>
                        <div className="absolute right-1 bottom-1 flex gap-0.5 opacity-0 group-hover:opacity-100 transition-opacity">
                           {chatFilter === 'finalizados' && (
                             <>
                               <button onClick={(e) => { e.stopPropagation(); updateDoc(doc(db, 'tickets', t.id), {status: 'Em Atendimento'}); }} className="p-1 bg-indigo-50 text-indigo-600 border border-indigo-200"><RotateCcw size={10}/></button>
                               <button onClick={(e) => { e.stopPropagation(); updateDoc(doc(db, 'tickets', t.id), {status: 'Arquivado'}); }} className="p-1 bg-amber-50 text-amber-600 border border-amber-200"><Archive size={10}/></button>
                             </>
                           )}
                           {(chatFilter === 'finalizados' || chatFilter === 'arquivados') && <button onClick={(e) => { e.stopPropagation(); deleteDoc(doc(db, 'tickets', t.id)); }} className="p-1 bg-rose-50 text-rose-600 border border-rose-200"><Trash2 size={10}/></button>}
                           {chatFilter === 'arquivados' && <button onClick={(e) => { e.stopPropagation(); updateDoc(doc(db, 'tickets', t.id), {status: 'Finalizado'}); }} className="p-1 bg-indigo-50 text-indigo-600 border border-indigo-200"><RotateCcw size={10}/></button>}
                        </div>
                     </div>
                   ))}
                </div>
             </div>
             <div className="col-span-9 bg-white border border-slate-300 flex flex-col relative overflow-hidden">
                {selectedTicketId ? (
                   <>
                     <header className="px-4 py-2 border-b border-slate-300 bg-slate-50 flex justify-between items-center">
                        <div>
                           <h4 className="font-black text-slate-900 leading-none">{tickets.find(t=>t.id===selectedTicketId)?.user}</h4>
                           <span className="text-[8px] text-slate-400 font-bold uppercase mt-1">Status: {tickets.find(t=>t.id===selectedTicketId)?.status}</span>
                        </div>
                        <button onClick={async () => { await updateDoc(doc(db, 'tickets', selectedTicketId), {status: 'Finalizado'}); setSelectedTicketId(null); }} className="px-3 py-1 bg-slate-900 text-white font-black text-[9px] uppercase hover:bg-rose-600 transition-all">Finalizar Atendimento</button>
                     </header>
                     <div className="flex-1 overflow-y-auto p-4 space-y-3 bg-slate-50/50">
                        {chatHistory.map((m, i) => (
                          <div key={i} className={`flex flex-col ${m.sender === 'Secretaria' ? 'items-end' : 'items-start'}`}>
                             <div className={`max-w-[70%] p-2 border ${m.sender === 'Secretaria' ? 'bg-slate-900 text-white border-slate-800' : 'bg-white text-slate-800 border-slate-300'}`}>
                                {m.text && <p className="italic text-[10px] normal-case not-italic">"{m.text}"</p>}
                                {m.attachment && (
                                   <div className="mt-1 border border-white/10 p-1 bg-black/5 flex items-center gap-2">
                                      {m.attachment.type?.startsWith('image/') ? <ImageIcon size={14}/> : <FileText size={14}/>}
                                      <span className="text-[8px] truncate font-black">{m.attachment.name}</span>
                                      <a href={m.attachment.url} download className="p-0.5"><Download size={10}/></a>
                                   </div>
                                )}
                             </div>
                             <span className="text-[7px] font-black text-slate-400 mt-0.5">{m.sender}</span>
                          </div>
                        ))}
                        <div ref={chatEndRef} />
                     </div>
                     <div className="p-2 border-t border-slate-300 bg-white flex items-center gap-1">
                        <button onClick={() => fileInputRef.current?.click()} className="p-1.5 text-slate-400"><Paperclip size={16}/></button>
                        <input value={chatMessage} onChange={e => setChatMessage(e.target.value)} onKeyDown={e => e.key === 'Enter' && handleSendMessage()} placeholder="RESPOSTA ADMINISTRATIVA..." className="flex-1 px-3 py-1.5 outline-none font-bold bg-slate-50 border border-slate-200 text-[9px]" />
                        <button onClick={() => handleSendMessage()} className="p-1.5 bg-slate-900 text-white"><CheckCircle2 size={16}/></button>
                        <input type="file" ref={fileInputRef} className="hidden" onChange={e => { if(e.target.files?.[0]) { const reader = new FileReader(); reader.onload = (ev) => handleSendMessage({url: ev.target?.result, name: e.target.files![0].name, type: e.target.files![0].type}); reader.readAsDataURL(e.target.files![0]); } }} />
                     </div>
                   </>
                ) : (
                  <div className="flex-1 flex flex-col items-center justify-center opacity-5 grayscale"><MessageSquare size={80}/><h2 className="text-xl font-black uppercase mt-4">MESSENGER</h2></div>
                )}
             </div>
          </div>
        )}

        {activeTab === 'arquivos' && (
          <div className="bg-white border border-slate-300 min-h-[400px] flex flex-col">
             <header className="p-2 bg-slate-900 text-white flex justify-between items-center">
                <div className="flex items-center gap-2">
                   <button onClick={() => setCurrentFolder(null)} className="font-black hover:text-indigo-400 italic">GED Master</button>
                   {currentFolder && <span className="opacity-30">/ {currentFolder}</span>}
                </div>
                <button className="bg-white text-slate-900 px-3 py-1 font-black text-[9px] uppercase">Upload Manual</button>
             </header>
             <div className="p-4 grid grid-cols-2 md:grid-cols-6 gap-2">
                {!currentFolder ? (
                   ['Matrículas', 'Declarações', 'Históricos', 'Contratos', 'Termos'].map(f => (
                     <div key={f} onClick={() => setCurrentFolder(f)} className="p-4 border border-slate-200 bg-slate-50 hover:bg-white transition-all cursor-pointer text-center group">
                        <Folder size={32} className="mx-auto text-slate-200 group-hover:text-indigo-600 transition-colors mb-2" />
                        <span className="font-black text-[9px]">{f}</span>
                     </div>
                   ))
                ) : (
                   <div className="col-span-full">
                      <button onClick={() => setCurrentFolder(null)} className="mb-4 text-[9px] font-black uppercase italic flex items-center gap-1 text-slate-400 hover:text-indigo-600"><RotateCcw size={12}/> Voltar ao Início</button>
                      <div className="grid grid-cols-2 md:grid-cols-6 gap-2">
                        {files.filter(f => f.category === currentFolder).map(file => (
                          <div key={file.id} className="p-4 border border-slate-200 bg-white hover:shadow-sm transition-all text-center relative group">
                             <FileText size={32} className="mx-auto text-indigo-500 mb-2" />
                             <span className="font-bold text-[8px] line-clamp-1">{file.title}</span>
                             <div className="absolute inset-0 bg-slate-900/90 opacity-0 group-hover:opacity-100 transition-opacity flex flex-col items-center justify-center p-2 gap-1">
                                <a href={file.url} target="_blank" className="w-full py-1 bg-white text-slate-950 font-black text-[7px] uppercase">Download</a>
                                <button onClick={() => deleteDoc(doc(db, 'secretaria_arquivos', file.id))} className="w-full py-1 border border-white/30 text-white font-black text-[7px] uppercase hover:bg-rose-600">Remover</button>
                             </div>
                          </div>
                        ))}
                        {files.filter(f => f.category === currentFolder).length === 0 && <p className="col-span-full py-20 text-center text-slate-300 italic">Pasta vazia.</p>}
                      </div>
                   </div>
                )}
             </div>
          </div>
        )}
      </main>
    </div>
  );
};

export default SecretariatView;

import React, { useState, useEffect } from 'react';
import { collection, query, where, onSnapshot, doc, getDoc, serverTimestamp } from "https://www.gstatic.com/firebasejs/10.7.1/firebase-firestore.js";
import { auth, db } from '../firebase';
import { Course, User, Module, Lesson } from '../types';
import { BookOpen, PlayCircle, Award, ArrowLeft, GraduationCap, Zap, Bell, Menu, X, LogOut, Home, LifeBuoy, ScrollText, Play } from 'lucide-react';

interface StudentViewProps { user: User; }
type StudentSubView = 'dashboard' | 'classroom' | 'library' | 'certificates' | 'support';

const StudentView: React.FC<StudentViewProps> = ({ user }) => {
  const [activeSubView, setActiveSubView] = useState<StudentSubView>('dashboard');
  const [enrolledCourse, setEnrolledCourse] = useState<Course | null>(null);
  const [modules, setModules] = useState<Module[]>([]);
  const [activeLesson, setActiveLesson] = useState<Lesson | null>(null);
  const [loading, setLoading] = useState(true);
  const [isSidebarOpen, setIsSidebarOpen] = useState(true);

  useEffect(() => {
    const fetchProfile = async () => {
      setLoading(true);
      try {
        const userDoc = await getDoc(doc(db, 'users', user.uid));
        if (userDoc.exists()) {
          const userData = userDoc.data();
          const cId = userData.cursoInicial || userData.cursoId;
          if (cId) {
            const courseDoc = await getDoc(doc(db, 'cursos', cId));
            if (courseDoc.exists()) {
              setEnrolledCourse({ id: courseDoc.id, ...courseDoc.data() } as Course);
            }
          }
        }
      } catch (error) { console.error("Erro de sincronização:", error); }
      setLoading(false);
    };
    fetchProfile();
  }, [user.uid]);

  const handleStartLesson = () => {
    if (!enrolledCourse) return;
    onSnapshot(query(collection(db, 'modulos'), where('courseId', '==', enrolledCourse.id)), snap => {
      const mods = snap.docs.map(d => ({ id: d.id, ...d.data() } as Module)).sort((a,b) => (a.order||0)-(b.order||0));
      setModules(mods);
      if (mods.length > 0 && mods[0].lessons?.length > 0) setActiveLesson(mods[0].lessons[0]);
      setActiveSubView('classroom');
    });
  };

  if (loading) return <div className="h-screen bg-slate-950 flex items-center justify-center font-black uppercase italic text-white text-[10px] tracking-[0.5em] animate-pulse">Auditando Vínculos Acadêmicos...</div>;

  return (
    <div className="min-h-screen bg-white flex overflow-hidden font-sans text-[10px] font-medium tracking-tighter uppercase italic">
      {/* BACKGROUND IMAGE FOR STUDENT HUB */}
      <div className="fixed inset-0 z-0 opacity-[0.03] pointer-events-none">
        <img src="https://images.unsplash.com/photo-1523240795612-9a054b0db644?auto=format&fit=crop&q=80" className="w-full h-full object-cover" />
      </div>

      <aside className={`bg-slate-900 w-64 flex flex-col transition-all duration-300 z-50 ${isSidebarOpen ? 'ml-0' : '-ml-64'} border-r border-white/5 relative`}>
         <div className="p-6 border-b border-white/5 flex items-center gap-3">
            <div className="p-1.5 bg-indigo-600 text-white"><GraduationCap size={18}/></div>
            <div><p className="font-black text-white text-sm leading-none italic tracking-tighter">EB-AD</p><p className="text-[7px] font-bold text-indigo-400 tracking-widest mt-1">Sala de Aula Master</p></div>
         </div>
         <nav className="flex-1 p-3 space-y-1 mt-4">
            {[
              { id: 'dashboard', label: 'Home Page', icon: <Home size={14}/> },
              { id: 'library', label: 'Biblioteca', icon: <BookOpen size={14}/> },
              { id: 'certificates', label: 'Meus Diplomas', icon: <Award size={14}/> },
              { id: 'support', label: 'Suporte & Ajuda', icon: <LifeBuoy size={14}/> }
            ].map(item => (
              <button key={item.id} onClick={() => setActiveSubView(item.id as any)} className={`w-full flex items-center gap-3 px-5 py-3 transition-all ${activeSubView === item.id ? 'bg-indigo-600 text-white shadow-xl' : 'text-slate-500 hover:text-white hover:bg-white/5'}`}>{item.icon} {item.label}</button>
            ))}
         </nav>
         <div className="p-4 border-t border-white/5 bg-black/20">
            <div className="flex items-center gap-3 p-3 bg-white/5 border border-white/5">
               <div className="w-8 h-8 overflow-hidden">
                  {user.photoURL ? <img src={user.photoURL} className="w-full h-full object-cover" /> : <div className="w-full h-full bg-indigo-600 flex items-center justify-center text-white font-black">{(user.displayName||'U').charAt(0)}</div>}
               </div>
               <div className="flex-1 overflow-hidden">
                  <p className="text-[8px] font-black text-white truncate italic">{(user.displayName||'Aluno').split(' ')[0]}</p>
                  <p className="text-[6px] font-bold text-slate-500 mt-0.5 truncate uppercase">Status: Sincronizado</p>
               </div>
               <button onClick={() => auth.signOut()} className="text-rose-500 hover:scale-110 transition-transform"><LogOut size={14}/></button>
            </div>
         </div>
      </aside>

      <div className="flex-1 flex flex-col h-screen overflow-hidden relative z-10">
         <header className="h-16 bg-white/80 backdrop-blur-md border-b border-slate-100 flex items-center justify-between px-6">
            <button onClick={() => setIsSidebarOpen(!isSidebarOpen)} className="p-2 bg-slate-50 text-slate-400 hover:text-indigo-600 transition-all"><Menu size={16}/></button>
            <div className="flex items-center gap-4">
               <div className="flex items-center gap-2 px-3 py-1.5 bg-indigo-50 text-indigo-600 border border-indigo-100"><Zap size={12} fill="currentColor"/><span className="text-[8px] font-black italic uppercase">Acesso Master Digital</span></div>
               <Bell size={16} className="text-slate-300 cursor-pointer hover:text-indigo-600 transition-all"/>
            </div>
         </header>

         <main className="flex-1 overflow-y-auto p-8 bg-slate-50/50">
            {activeSubView === 'dashboard' && (
              <div className="max-w-4xl mx-auto space-y-10 animate-in fade-in">
                 <h1 className="text-4xl font-black text-slate-900 uppercase italic tracking-tighter leading-none">Sua Formação <br/> <span className="text-indigo-600">Integral EB-AD</span></h1>
                 {enrolledCourse ? (
                   <div className="bg-white border border-slate-200 shadow-xl overflow-hidden flex flex-col lg:flex-row group transition-all hover:border-indigo-400">
                      <div className="lg:w-1/2 h-64 lg:h-auto overflow-hidden relative">
                         <img src={enrolledCourse.capaUrl} className="w-full h-full object-cover group-hover:scale-110 transition-transform duration-1000 grayscale-[0.3]" />
                         <div className="absolute inset-0 bg-gradient-to-t from-slate-950 via-transparent to-transparent opacity-40"></div>
                      </div>
                      <div className="flex-1 p-10 space-y-5 flex flex-col justify-center">
                         <span className="text-[8px] font-black text-indigo-600 uppercase tracking-[0.4em] italic leading-none">{enrolledCourse.categoria}</span>
                         <h2 className="text-3xl font-black text-slate-900 uppercase italic tracking-tighter leading-none">{enrolledCourse.nome}</h2>
                         <p className="text-slate-500 italic text-[11px] leading-relaxed normal-case not-italic">{enrolledCourse.descricao || 'Excelência em teologia bíblica para o ministério cristão contemporâneo.'}</p>
                         <div className="pt-2"><div className="h-1 bg-slate-100 overflow-hidden"><div className="h-full bg-indigo-600" style={{width:'0%'}}></div></div><p className="text-[7px] font-black uppercase text-slate-400 mt-2 italic tracking-widest leading-none">Progresso: 0% Concluído</p></div>
                         <button onClick={handleStartLesson} className="w-full py-4 bg-slate-900 text-white text-[10px] font-black uppercase italic tracking-[0.3em] shadow-xl hover:bg-indigo-600 transition-all flex items-center justify-center gap-3">
                            <PlayCircle size={18}/> Ingressar na Aula
                         </button>
                      </div>
                   </div>
                 ) : (
                   <div className="bg-white p-12 text-center space-y-4 border border-slate-200 shadow-lg">
                      <Zap size={32} className="mx-auto text-indigo-400 animate-pulse"/>
                      <h3 className="text-lg font-black uppercase italic text-slate-900 leading-none">Aguardando Vinculação</h3>
                      <p className="text-[10px] text-slate-400 font-bold uppercase tracking-widest max-w-xs mx-auto leading-relaxed">Sua conta está sincronizada, mas o currículo acadêmico está em fase de auditoria final.</p>
                      <button onClick={() => window.location.reload()} className="px-6 py-2 bg-slate-100 text-slate-600 font-black uppercase text-[9px] hover:bg-indigo-600 hover:text-white transition-all">Sincronizar Agora</button>
                   </div>
                 )}
              </div>
            )}

            {activeSubView === 'classroom' && activeLesson && (
              <div className="max-w-6xl mx-auto flex flex-col lg:flex-row gap-6 animate-in slide-in-from-right duration-500">
                <div className="flex-1 space-y-4">
                  <div className="aspect-video bg-black border border-slate-300 relative group overflow-hidden shadow-2xl">
                     <div className="absolute inset-0 flex flex-col items-center justify-center text-white/20 uppercase font-black italic tracking-[1em]">
                        <Play size={80} className="mb-4 opacity-50"/>
                        Streaming Ativo
                     </div>
                  </div>
                  <div className="bg-white p-6 border border-slate-200 shadow-sm space-y-3">
                    <h3 className="text-xl font-black italic leading-none">{activeLesson.title}</h3>
                    <p className="text-[10px] text-slate-500 normal-case not-italic leading-relaxed">{activeLesson.description || 'Nenhum resumo anexado para este encontro.'}</p>
                  </div>
                </div>
                <div className="lg:w-80 space-y-2">
                  <h4 className="font-black text-slate-900 uppercase italic mb-4 tracking-widest text-[9px] border-b border-slate-200 pb-2">Matriz do Curso</h4>
                  {modules.map(m => (
                    <div key={m.id} className="space-y-1">
                      <div className="bg-slate-100 p-2 text-[8px] font-black uppercase italic text-slate-500 tracking-widest">{m.title}</div>
                      {m.lessons?.map(l => (
                        <button key={l.id} onClick={() => setActiveLesson(l)} className={`w-full text-left p-3 text-[9px] font-bold uppercase italic transition-all border ${activeLesson?.id === l.id ? 'bg-indigo-600 text-white border-indigo-700 shadow-lg' : 'bg-white text-slate-400 border-slate-100 hover:bg-slate-50'}`}>{l.title}</button>
                      ))}
                    </div>
                  ))}
                </div>
              </div>
            )}
         </main>
      </div>
    </div>
  );
};

export default StudentView;
